#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct TensorRef(String);

impl TensorRef {
    pub fn new(name: impl Into<String>) -> Result<Self> {
        let value = name.into();
        validate_name("tensor", &value)?;
        Ok(Self(value))
    }

    pub fn unchecked(name: impl Into<String>) -> Self {
        Self(name.into())
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl From<&str> for TensorRef {
    fn from(value: &str) -> Self {
        TensorRef::unchecked(value)
    }
}

impl From<String> for TensorRef {
    fn from(value: String) -> Self {
        TensorRef::unchecked(value)
    }
}

impl fmt::Display for TensorRef {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DType {
    F32,
    F16,
    Bf16,
    Fp8E4M3,
    Fp4E2M1,
    U32,
}

impl DType {
    pub fn is_float(self) -> bool {
        matches!(
            self,
            Self::F32 | Self::F16 | Self::Bf16 | Self::Fp8E4M3 | Self::Fp4E2M1
        )
    }

    pub fn storage_bits(self) -> usize {
        match self {
            Self::F32 | Self::U32 => 32,
            Self::F16 | Self::Bf16 => 16,
            Self::Fp8E4M3 => 8,
            Self::Fp4E2M1 => 4,
        }
    }

    pub fn storage_bytes_for_elements(self, elements: usize) -> Result<usize> {
        let bits = self
            .storage_bits()
            .checked_mul(elements)
            .ok_or_else(|| anyhow!("tensor storage bit count overflow"))?;
        Ok(bits.div_ceil(8))
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TensorRole {
    Token,
    Position,
    Activation,
    Weight,
    KvCache,
    Routing,
    Metadata,
    Logits,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TensorSpec {
    pub id: TensorRef,
    pub dtype: DType,
    pub shape: Vec<usize>,
    pub role: TensorRole,
    pub checkpoint_key: Option<String>,
}

impl TensorSpec {
    pub fn new(
        id: impl Into<TensorRef>,
        dtype: DType,
        shape: impl Into<Vec<usize>>,
        role: TensorRole,
    ) -> Self {
        Self {
            id: id.into(),
            dtype,
            shape: shape.into(),
            role,
            checkpoint_key: None,
        }
    }

    pub fn with_checkpoint_key(mut self, key: impl Into<String>) -> Result<Self> {
        let key = key.into();
        validate_name("checkpoint key", &key)?;
        self.checkpoint_key = Some(key);
        Ok(self)
    }

    pub fn element_count(&self) -> Result<usize> {
        element_count(&self.shape)
    }

    pub fn storage_bytes(&self) -> Result<usize> {
        self.dtype.storage_bytes_for_elements(self.element_count()?)
    }
}

