#[derive(Clone, Debug, PartialEq)]
pub enum PrimitiveOp {
    EmbeddingLookup(EmbeddingLookup),
    Linear(Linear),
    RmsNorm(RmsNorm),
    AddRmsNorm(AddRmsNorm),
    ApplyRope(ApplyRope),
    KvCacheAppend(KvCacheAppend),
    PagedAttention(PagedAttention),
    MoeRouterTopK(MoeRouterTopK),
    MoeLocalFfn(MoeLocalFfn),
    ResidualAdd(ResidualAdd),
    Collective(Collective),
    ArgmaxSample(ArgmaxSample),
}

impl PrimitiveOp {
    pub fn name(&self) -> &str {
        match self {
            Self::EmbeddingLookup(op) => &op.name,
            Self::Linear(op) => &op.name,
            Self::RmsNorm(op) => &op.name,
            Self::AddRmsNorm(op) => &op.name,
            Self::ApplyRope(op) => &op.name,
            Self::KvCacheAppend(op) => &op.name,
            Self::PagedAttention(op) => &op.name,
            Self::MoeRouterTopK(op) => &op.name,
            Self::MoeLocalFfn(op) => &op.name,
            Self::ResidualAdd(op) => &op.name,
            Self::Collective(op) => &op.name,
            Self::ArgmaxSample(op) => &op.name,
        }
    }

    pub fn kind(&self) -> PrimitiveKind {
        match self {
            Self::EmbeddingLookup(_) => PrimitiveKind::EmbeddingLookup,
            Self::Linear(_) => PrimitiveKind::Linear,
            Self::RmsNorm(_) => PrimitiveKind::RmsNorm,
            Self::AddRmsNorm(_) => PrimitiveKind::AddRmsNorm,
            Self::ApplyRope(_) => PrimitiveKind::ApplyRope,
            Self::KvCacheAppend(_) => PrimitiveKind::KvCacheAppend,
            Self::PagedAttention(_) => PrimitiveKind::PagedAttention,
            Self::MoeRouterTopK(_) => PrimitiveKind::MoeRouterTopK,
            Self::MoeLocalFfn(_) => PrimitiveKind::MoeLocalFfn,
            Self::ResidualAdd(_) => PrimitiveKind::ResidualAdd,
            Self::Collective(_) => PrimitiveKind::Collective,
            Self::ArgmaxSample(_) => PrimitiveKind::ArgmaxSample,
        }
    }
}

/// Object-safe sink used by external model definitions to build a primitive graph.
///
/// Implementors receive tensor declarations, semantic stage markers, and
/// primitive operations in source order. Model packages normally only call this
/// trait from [`ModelDefinition::define`]; they do not implement it themselves.
pub trait ModelPrimitiveApi {
    /// Declares a named tensor, including dtype, shape, role, and optional
    /// checkpoint key metadata.
    fn declare_tensor(&mut self, spec: TensorSpec) -> Result<()>;

    /// Starts a named semantic decode stage. Stages must be closed with
    /// [`ModelPrimitiveApi::end_stage`] and may not be nested.
    fn begin_stage(&mut self, name: &str, kind: ModelStageKind) -> Result<()>;

    /// Emits one typed primitive op into the current graph position.
    fn emit(&mut self, op: PrimitiveOp) -> Result<()>;

    /// Closes the current semantic stage.
    fn end_stage(&mut self) -> Result<()>;
}

/// Model-package contract for describing one decode-step graph.
///
/// A model definition should be pure metadata construction: declare tensors,
/// open semantic stages, emit typed primitives, and return. This method is
/// CPU-only and must not allocate GPU memory, load checkpoint payloads, submit
/// queues, or execute kernels.
pub trait ModelDefinition {
    /// Stable model/plugin identifier used in reports, manifests, and receipts.
    fn name(&self) -> &str;

    /// Emits the model's primitive graph into the provided API sink.
    fn define(&self, api: &mut dyn ModelPrimitiveApi) -> Result<()>;
}

#[derive(Clone, Debug, PartialEq)]
pub struct ModelPrimitiveGraph {
    pub name: String,
    pub tensors: BTreeMap<TensorRef, TensorSpec>,
    pub ops: Vec<PrimitiveOp>,
    pub stages: Vec<ModelStage>,
}

impl ModelPrimitiveGraph {
    pub fn validate(&self) -> Result<ModelPrimitiveGraphReport> {
        validate_name("graph", &self.name)?;

        let mut tensor_count = 0usize;
        for (id, spec) in &self.tensors {
            validate_name("tensor", id.as_str())?;
            if id != &spec.id {
                return Err(anyhow!(
                    "tensor map key {} does not match tensor spec id {}",
                    id,
                    spec.id
                ));
            }
            require_nonempty_shape(id.as_str(), &spec.shape)?;
            let _ = element_count(&spec.shape)?;
            if let Some(checkpoint_key) = &spec.checkpoint_key {
                validate_name("checkpoint key", checkpoint_key)?;
                if spec.role != TensorRole::Weight {
                    return Err(anyhow!(
                        "tensor {} has checkpoint key {} but role {:?}, expected Weight",
                        spec.id,
                        checkpoint_key,
                        spec.role
                    ));
                }
            }
            tensor_count += 1;
        }

        let mut op_names = BTreeSet::new();
        let mut primitive_kinds = BTreeSet::new();
        for op in &self.ops {
            validate_name("op", op.name())?;
            if !op_names.insert(op.name().to_string()) {
                return Err(anyhow!("duplicate op name {}", op.name()));
            }
            primitive_kinds.insert(op.kind());
            self.validate_op(op)?;
        }

        let stage_coverage = self.validate_stage_ranges()?;

        Ok(ModelPrimitiveGraphReport {
            tensors: tensor_count,
            ops: self.ops.len(),
            primitive_kinds: primitive_kinds.into_iter().collect(),
            stages: self.stages.len(),
            staged_ops: stage_coverage,
            unstaged_ops: self.ops.len() - stage_coverage,
        })
    }

    pub fn ops_by_kind(&self, kind: PrimitiveKind) -> usize {
        self.ops.iter().filter(|op| op.kind() == kind).count()
    }

    pub fn tensor_storage_plan(&self) -> Result<ModelTensorStoragePlan> {
        self.validate()?;
        let mut footprint = ModelTensorStorageFootprint::default();
        let mut entries = Vec::with_capacity(self.tensors.len());
        for spec in self.tensors.values() {
            let elements = spec.element_count()?;
            let storage_bytes = spec.dtype.storage_bytes_for_elements(elements)?;
            footprint.add(spec.role, storage_bytes)?;
            entries.push(TensorStoragePlanEntry {
                tensor: spec.id.clone(),
                dtype: spec.dtype,
                role: spec.role,
                elements,
                storage_bytes,
            });
        }
        Ok(ModelTensorStoragePlan { entries, footprint })
    }

    pub fn tensor_access_plan(&self) -> Result<ModelTensorAccessPlan> {
        self.validate()?;
        Ok(ModelTensorAccessPlan {
            entries: self.ops.iter().map(primitive_tensor_access).collect(),
        })
    }

    pub fn tensor_lifetime_plan(&self) -> Result<ModelTensorLifetimePlan> {
        self.validate()?;
        let storage = self.tensor_storage_plan()?;
        let access = self.tensor_access_plan()?;
        tensor_lifetime_plan_from(&storage, &access)
    }

    pub fn tensor_binding_plan(&self) -> Result<ModelTensorBindingPlan> {
        self.validate()?;
        let lifetime = self.tensor_lifetime_plan()?;
        tensor_binding_plan_from(&self.tensors, &lifetime)
    }

    pub fn primitive_execution_plan(
        &self,
        catalog: &MainarchPrimitiveLoweringCatalog,
    ) -> Result<ModelPrimitiveExecutionPlan> {
        self.validate()?;
        let access = self.tensor_access_plan()?;
        let binding = self.tensor_binding_plan()?;
        let lowering = self.lowering_plan(catalog)?;
        primitive_execution_plan_from(self, &access, &binding, &lowering)
    }

    pub fn runtime_slot_plan(
        &self,
        catalog: &MainarchPrimitiveLoweringCatalog,
    ) -> Result<ModelRuntimeSlotPlan> {
        self.validate()?;
        let binding = self.tensor_binding_plan()?;
        let execution = self.primitive_execution_plan(catalog)?;
        runtime_slot_plan_from(&binding, &execution)
    }

    pub fn runtime_dispatch_intent_plan(
        &self,
        catalog: &MainarchPrimitiveLoweringCatalog,
    ) -> Result<ModelRuntimeDispatchIntentPlan> {
        self.validate()?;
        let slots = self.runtime_slot_plan(catalog)?;
        runtime_dispatch_intent_plan_from(self, &slots)
    }

    pub fn runtime_stage_slot_plan(
        &self,
        catalog: &MainarchPrimitiveLoweringCatalog,
    ) -> Result<ModelRuntimeStageSlotPlan> {
        self.validate()?;
        let slots = self.runtime_slot_plan(catalog)?;
        runtime_stage_slot_plan_from(self, &slots)
    }

    pub fn runtime_stage_bundle_plan(
        &self,
        catalog: &MainarchPrimitiveLoweringCatalog,
    ) -> Result<ModelRuntimeStageBundlePlan> {
        self.validate()?;
        let slots = self.runtime_slot_plan(catalog)?;
        let stage_slots = runtime_stage_slot_plan_from(self, &slots)?;
        runtime_stage_bundle_plan_from(&slots, &stage_slots)
    }

    pub fn runtime_stage_dispatch_plan(
        &self,
        catalog: &MainarchPrimitiveLoweringCatalog,
    ) -> Result<ModelRuntimeStageDispatchPlan> {
        self.validate()?;
        let slots = self.runtime_slot_plan(catalog)?;
        let dispatch_intents = self.runtime_dispatch_intent_plan(catalog)?;
        let stage_slots = runtime_stage_slot_plan_from(self, &slots)?;
        runtime_stage_dispatch_plan_from(&dispatch_intents, &stage_slots)
    }

    pub fn checkpoint_binding_plan(&self) -> Result<ModelCheckpointBindingPlan> {
        self.validate()?;
        let mut entries = Vec::new();
        let mut missing_weight_tensors = Vec::new();
        let mut total_checkpoint_bytes = 0usize;
        for spec in self.tensors.values() {
            if spec.role != TensorRole::Weight {
                continue;
            }
            let elements = spec.element_count()?;
            let storage_bytes = spec.dtype.storage_bytes_for_elements(elements)?;
            if let Some(checkpoint_key) = &spec.checkpoint_key {
                total_checkpoint_bytes =
                    checked_add_bytes(total_checkpoint_bytes, storage_bytes, "checkpoint")?;
                entries.push(TensorCheckpointBinding {
                    tensor: spec.id.clone(),
                    checkpoint_key: checkpoint_key.clone(),
                    dtype: spec.dtype,
                    shape: spec.shape.clone(),
                    elements,
                    storage_bytes,
                });
            } else {
                missing_weight_tensors.push(spec.id.clone());
            }
        }
        Ok(ModelCheckpointBindingPlan {
            entries,
            missing_weight_tensors,
            total_checkpoint_bytes,
        })
    }

    pub fn stages_by_kind(&self, kind: ModelStageKind) -> usize {
        self.stages
            .iter()
            .filter(|stage| stage.kind == kind)
            .count()
    }

    pub fn stage_ops(&self, stage: &ModelStage) -> Result<&[PrimitiveOp]> {
        let end = stage
            .first_op
            .checked_add(stage.op_count)
            .ok_or_else(|| anyhow!("stage {} op range overflows", stage.name))?;
        self.ops
            .get(stage.first_op..end)
            .ok_or_else(|| anyhow!("stage {} op range is outside graph ops", stage.name))
    }

    pub fn assert_all_ops_staged(&self) -> Result<()> {
        self.validate()?;
        let mut staged = vec![false; self.ops.len()];
        for stage in &self.stages {
            for op_index in stage.op_range() {
                staged[op_index] = true;
            }
        }
        let missing = staged
            .iter()
            .enumerate()
            .filter_map(|(index, is_staged)| {
                if *is_staged {
                    None
                } else {
                    Some(self.ops[index].name().to_string())
                }
            })
            .collect::<Vec<_>>();
        if missing.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "model graph {} has {} unstaged op(s): {}",
                self.name,
                missing.len(),
                missing.join(", ")
            ))
        }
    }

    fn validate_stage_ranges(&self) -> Result<usize> {
        let mut stage_names = BTreeSet::new();
        let mut staged = vec![false; self.ops.len()];
        for stage in &self.stages {
            validate_name("stage", &stage.name)?;
            if !stage_names.insert(stage.name.clone()) {
                return Err(anyhow!("duplicate stage name {}", stage.name));
            }
            if stage.op_count == 0 {
                return Err(anyhow!("stage {} has no ops", stage.name));
            }
            let end = stage
                .first_op
                .checked_add(stage.op_count)
                .ok_or_else(|| anyhow!("stage {} op range overflows", stage.name))?;
            if end > self.ops.len() {
                return Err(anyhow!(
                    "stage {} range {}..{} exceeds graph op count {}",
                    stage.name,
                    stage.first_op,
                    end,
                    self.ops.len()
                ));
            }
            for op_index in stage.first_op..end {
                if staged[op_index] {
                    return Err(anyhow!(
                        "stage {} overlaps an earlier stage at op {} ({})",
                        stage.name,
                        op_index,
                        self.ops[op_index].name()
                    ));
                }
                staged[op_index] = true;
            }
        }
        Ok(staged.into_iter().filter(|is_staged| *is_staged).count())
    }

    fn tensor(&self, id: &TensorRef) -> Result<&TensorSpec> {
        self.tensors
            .get(id)
            .ok_or_else(|| anyhow!("tensor {} is referenced but not declared", id))
    }

    fn validate_op(&self, op: &PrimitiveOp) -> Result<()> {
        match op {
            PrimitiveOp::EmbeddingLookup(op) => self.validate_embedding_lookup(op),
            PrimitiveOp::Linear(op) => self.validate_linear(op),
            PrimitiveOp::RmsNorm(op) => self.validate_rms_norm(op),
            PrimitiveOp::AddRmsNorm(op) => self.validate_add_rms_norm(op),
            PrimitiveOp::ApplyRope(op) => self.validate_rope(op),
            PrimitiveOp::KvCacheAppend(op) => self.validate_kv_cache_append(op),
            PrimitiveOp::PagedAttention(op) => self.validate_paged_attention(op),
            PrimitiveOp::MoeRouterTopK(op) => self.validate_moe_router(op),
            PrimitiveOp::MoeLocalFfn(op) => self.validate_moe_local_ffn(op),
            PrimitiveOp::ResidualAdd(op) => self.validate_residual_add(op),
            PrimitiveOp::Collective(op) => self.validate_collective(op),
            PrimitiveOp::ArgmaxSample(op) => self.validate_argmax_sample(op),
        }
    }

    fn validate_embedding_lookup(&self, op: &EmbeddingLookup) -> Result<()> {
        require_positive(op.vocab, op.name.as_str(), "vocab")?;
        require_positive(op.hidden, op.name.as_str(), "hidden")?;
        let token = self.tensor(&op.token_ids)?;
        require_dtype(op.name.as_str(), token, DType::U32)?;
        require_shape(op.name.as_str(), token, &[1])?;
        let weight = self.tensor(&op.weight)?;
        require_float_tensor(op.name.as_str(), weight)?;
        require_shape(op.name.as_str(), weight, &[op.vocab, op.hidden])?;
        let output = self.tensor(&op.output)?;
        require_float_tensor(op.name.as_str(), output)?;
        require_shape(op.name.as_str(), output, &[op.hidden])?;
        Ok(())
    }

    fn validate_linear(&self, op: &Linear) -> Result<()> {
        require_positive(op.in_features, op.name.as_str(), "in_features")?;
        require_positive(op.out_features, op.name.as_str(), "out_features")?;
        op.parallelism.validate(op.name.as_str())?;
        let input = self.tensor(&op.input)?;
        require_float_tensor(op.name.as_str(), input)?;
        require_elements(op.name.as_str(), input, op.in_features)?;
        let weight = self.tensor(&op.weight)?;
        require_float_tensor(op.name.as_str(), weight)?;
        require_shape(op.name.as_str(), weight, &[op.out_features, op.in_features])?;
        if let Some(scale_id) = &op.scale {
            let scale = self.tensor(scale_id)?;
            require_dtype(op.name.as_str(), scale, DType::F32)?;
            require_shape(op.name.as_str(), scale, &[op.out_features])?;
        }
        let output = self.tensor(&op.output)?;
        require_float_tensor(op.name.as_str(), output)?;
        require_elements(op.name.as_str(), output, op.out_features)?;
        Ok(())
    }

    fn validate_rms_norm(&self, op: &RmsNorm) -> Result<()> {
        require_positive(op.normalized_dim, op.name.as_str(), "normalized_dim")?;
        require_positive_f32(op.eps, op.name.as_str(), "eps")?;
        let input = self.tensor(&op.input)?;
        require_float_tensor(op.name.as_str(), input)?;
        require_last_dim(op.name.as_str(), input, op.normalized_dim)?;
        let weight = self.tensor(&op.weight)?;
        require_float_tensor(op.name.as_str(), weight)?;
        require_shape(op.name.as_str(), weight, &[op.normalized_dim])?;
        let output = self.tensor(&op.output)?;
        require_float_tensor(op.name.as_str(), output)?;
        require_same_shape(op.name.as_str(), input, output)?;
        Ok(())
    }

    fn validate_add_rms_norm(&self, op: &AddRmsNorm) -> Result<()> {
        require_positive(op.normalized_dim, op.name.as_str(), "normalized_dim")?;
        require_positive_f32(op.eps, op.name.as_str(), "eps")?;
        let input = self.tensor(&op.input)?;
        let residual = self.tensor(&op.residual)?;
        let residual_output = self.tensor(&op.residual_output)?;
        let norm_output = self.tensor(&op.norm_output)?;
        for tensor in [input, residual, residual_output, norm_output] {
            require_float_tensor(op.name.as_str(), tensor)?;
        }
        require_same_shape(op.name.as_str(), input, residual)?;
        require_same_shape(op.name.as_str(), residual, residual_output)?;
        require_same_shape(op.name.as_str(), residual_output, norm_output)?;
        require_last_dim(op.name.as_str(), norm_output, op.normalized_dim)?;
        let weight = self.tensor(&op.weight)?;
        require_float_tensor(op.name.as_str(), weight)?;
        require_shape(op.name.as_str(), weight, &[op.normalized_dim])?;
        Ok(())
    }

    fn validate_rope(&self, op: &ApplyRope) -> Result<()> {
        require_attention_dims(op.name.as_str(), op.query_heads, op.kv_heads, op.head_dim)?;
        require_positive_f32(op.theta, op.name.as_str(), "theta")?;
        let query = self.tensor(&op.query)?;
        let key = self.tensor(&op.key)?;
        let query_output = self.tensor(&op.query_output)?;
        let key_output = self.tensor(&op.key_output)?;
        require_shape(op.name.as_str(), query, &[op.query_heads, op.head_dim])?;
        require_shape(op.name.as_str(), key, &[op.kv_heads, op.head_dim])?;
        require_same_shape(op.name.as_str(), query, query_output)?;
        require_same_shape(op.name.as_str(), key, key_output)?;
        let position = self.tensor(&op.position)?;
        require_dtype(op.name.as_str(), position, DType::U32)?;
        require_shape(op.name.as_str(), position, &[1])?;
        Ok(())
    }

    fn validate_kv_cache_append(&self, op: &KvCacheAppend) -> Result<()> {
        require_positive(op.max_context, op.name.as_str(), "max_context")?;
        require_positive(op.block_size, op.name.as_str(), "block_size")?;
        require_positive(op.kv_heads, op.name.as_str(), "kv_heads")?;
        require_positive(op.head_dim, op.name.as_str(), "head_dim")?;
        let key = self.tensor(&op.key)?;
        let value = self.tensor(&op.value)?;
        require_shape(op.name.as_str(), key, &[op.kv_heads, op.head_dim])?;
        require_shape(op.name.as_str(), value, &[op.kv_heads, op.head_dim])?;
        require_cache_ref(
            self,
            op.name.as_str(),
            &op.cache,
            op.max_context,
            op.kv_heads,
            op.head_dim,
            op.cache_dtype,
        )?;
        let block_table = self.tensor(&op.block_table)?;
        require_dtype(op.name.as_str(), block_table, DType::U32)?;
        require_min_elements(
            op.name.as_str(),
            block_table,
            logical_blocks(op.max_context, op.block_size)?,
        )?;
        let position = self.tensor(&op.position)?;
        require_dtype(op.name.as_str(), position, DType::U32)?;
        require_shape(op.name.as_str(), position, &[1])?;
        Ok(())
    }

    fn validate_paged_attention(&self, op: &PagedAttention) -> Result<()> {
        require_attention_dims(op.name.as_str(), op.query_heads, op.kv_heads, op.head_dim)?;
        require_positive(op.max_context, op.name.as_str(), "max_context")?;
        require_positive(op.block_size, op.name.as_str(), "block_size")?;
        let query = self.tensor(&op.query)?;
        require_shape(op.name.as_str(), query, &[op.query_heads, op.head_dim])?;
        require_cache_ref(
            self,
            op.name.as_str(),
            &op.cache,
            op.max_context,
            op.kv_heads,
            op.head_dim,
            op.cache_dtype,
        )?;
        let block_table = self.tensor(&op.block_table)?;
        require_dtype(op.name.as_str(), block_table, DType::U32)?;
        require_min_elements(
            op.name.as_str(),
            block_table,
            logical_blocks(op.max_context, op.block_size)?,
        )?;
        let seq_len = self.tensor(&op.seq_len)?;
        require_dtype(op.name.as_str(), seq_len, DType::U32)?;
        require_shape(op.name.as_str(), seq_len, &[1])?;
        let output = self.tensor(&op.output)?;
        require_float_tensor(op.name.as_str(), output)?;
        require_elements(op.name.as_str(), output, op.query_heads * op.head_dim)?;
        Ok(())
    }

    fn validate_moe_router(&self, op: &MoeRouterTopK) -> Result<()> {
        require_moe_dims(op.name.as_str(), op.hidden_dim, 1, op.experts, op.top_k)?;
        let hidden = self.tensor(&op.hidden)?;
        require_float_tensor(op.name.as_str(), hidden)?;
        require_shape(op.name.as_str(), hidden, &[op.hidden_dim])?;
        let gate = self.tensor(&op.gate_weight)?;
        require_float_tensor(op.name.as_str(), gate)?;
        require_shape(op.name.as_str(), gate, &[op.experts, op.hidden_dim])?;
        let ids = self.tensor(&op.expert_ids)?;
        require_dtype(op.name.as_str(), ids, DType::U32)?;
        require_shape(op.name.as_str(), ids, &[op.top_k])?;
        let weights = self.tensor(&op.expert_weights)?;
        require_float_tensor(op.name.as_str(), weights)?;
        require_shape(op.name.as_str(), weights, &[op.top_k])?;
        if let Some(group) = op.group {
            require_positive(group.expert_groups, op.name.as_str(), "expert_groups")?;
            require_positive(group.topk_groups, op.name.as_str(), "topk_groups")?;
            if group.topk_groups > group.expert_groups {
                return Err(anyhow!(
                    "router op {} has topk_groups {} greater than expert_groups {}",
                    op.name,
                    group.topk_groups,
                    group.expert_groups
                ));
            }
            if op.experts % group.expert_groups != 0 {
                return Err(anyhow!(
                    "router op {} has experts {} not divisible by expert_groups {}",
                    op.name,
                    op.experts,
                    group.expert_groups
                ));
            }
        }
        Ok(())
    }

    fn validate_moe_local_ffn(&self, op: &MoeLocalFfn) -> Result<()> {
        require_moe_dims(
            op.name.as_str(),
            op.hidden_dim,
            op.intermediate_dim,
            op.experts,
            op.top_k,
        )?;
        let hidden = self.tensor(&op.hidden)?;
        require_float_tensor(op.name.as_str(), hidden)?;
        require_shape(op.name.as_str(), hidden, &[op.hidden_dim])?;
        for (name, id, shape) in [
            (
                "gate_weight",
                &op.gate_weight,
                vec![op.experts, op.intermediate_dim, op.hidden_dim],
            ),
            (
                "up_weight",
                &op.up_weight,
                vec![op.experts, op.intermediate_dim, op.hidden_dim],
            ),
            (
                "down_weight",
                &op.down_weight,
                vec![op.experts, op.hidden_dim, op.intermediate_dim],
            ),
        ] {
            let weight = self.tensor(id)?;
            require_float_tensor(op.name.as_str(), weight)?;
            if weight.shape != shape {
                return Err(anyhow!(
                    "moe op {} {name} tensor {} has shape {:?}, expected {:?}",
                    op.name,
                    weight.id,
                    weight.shape,
                    shape
                ));
            }
        }
        let ids = self.tensor(&op.expert_ids)?;
        require_dtype(op.name.as_str(), ids, DType::U32)?;
        require_shape(op.name.as_str(), ids, &[op.top_k])?;
        let weights = self.tensor(&op.expert_weights)?;
        require_float_tensor(op.name.as_str(), weights)?;
        require_shape(op.name.as_str(), weights, &[op.top_k])?;
        let output = self.tensor(&op.output)?;
        require_float_tensor(op.name.as_str(), output)?;
        require_shape(op.name.as_str(), output, &[op.hidden_dim])?;
        Ok(())
    }

    fn validate_residual_add(&self, op: &ResidualAdd) -> Result<()> {
        let lhs = self.tensor(&op.lhs)?;
        let rhs = self.tensor(&op.rhs)?;
        let output = self.tensor(&op.output)?;
        require_float_tensor(op.name.as_str(), lhs)?;
        require_float_tensor(op.name.as_str(), rhs)?;
        require_float_tensor(op.name.as_str(), output)?;
        require_same_shape(op.name.as_str(), lhs, rhs)?;
        require_same_shape(op.name.as_str(), lhs, output)?;
        Ok(())
    }

    fn validate_collective(&self, op: &Collective) -> Result<()> {
        if op.group_size < 2 {
            return Err(anyhow!(
                "collective op {} has group_size {}, expected at least 2",
                op.name,
                op.group_size
            ));
        }
        let input = self.tensor(&op.input)?;
        let output = self.tensor(&op.output)?;
        require_same_shape(op.name.as_str(), input, output)?;
        if input.dtype != output.dtype {
            return Err(anyhow!(
                "collective op {} dtype mismatch: input {:?}, output {:?}",
                op.name,
                input.dtype,
                output.dtype
            ));
        }
        Ok(())
    }

    fn validate_argmax_sample(&self, op: &ArgmaxSample) -> Result<()> {
        require_positive(op.vocab, op.name.as_str(), "vocab")?;
        let logits = self.tensor(&op.logits)?;
        require_float_tensor(op.name.as_str(), logits)?;
        require_shape(op.name.as_str(), logits, &[op.vocab])?;
        let out = self.tensor(&op.output_token)?;
        require_dtype(op.name.as_str(), out, DType::U32)?;
        require_shape(op.name.as_str(), out, &[1])?;
        Ok(())
    }
}

