#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ModelTensorStorageFootprint {
    pub token_bytes: usize,
    pub position_bytes: usize,
    pub activation_bytes: usize,
    pub weight_bytes: usize,
    pub kv_cache_bytes: usize,
    pub routing_bytes: usize,
    pub metadata_bytes: usize,
    pub logits_bytes: usize,
    pub total_bytes: usize,
}

impl ModelTensorStorageFootprint {
    fn add(&mut self, role: TensorRole, bytes: usize) -> Result<()> {
        self.total_bytes = checked_add_bytes(self.total_bytes, bytes, "total")?;
        let slot = match role {
            TensorRole::Token => &mut self.token_bytes,
            TensorRole::Position => &mut self.position_bytes,
            TensorRole::Activation => &mut self.activation_bytes,
            TensorRole::Weight => &mut self.weight_bytes,
            TensorRole::KvCache => &mut self.kv_cache_bytes,
            TensorRole::Routing => &mut self.routing_bytes,
            TensorRole::Metadata => &mut self.metadata_bytes,
            TensorRole::Logits => &mut self.logits_bytes,
        };
        *slot = checked_add_bytes(*slot, bytes, "role")?;
        Ok(())
    }

    pub fn bytes_for_role(&self, role: TensorRole) -> usize {
        match role {
            TensorRole::Token => self.token_bytes,
            TensorRole::Position => self.position_bytes,
            TensorRole::Activation => self.activation_bytes,
            TensorRole::Weight => self.weight_bytes,
            TensorRole::KvCache => self.kv_cache_bytes,
            TensorRole::Routing => self.routing_bytes,
            TensorRole::Metadata => self.metadata_bytes,
            TensorRole::Logits => self.logits_bytes,
        }
    }
}

