#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TensorLifetimePlanEntry {
    pub tensor: TensorRef,
    pub dtype: DType,
    pub role: TensorRole,
    pub storage_bytes: usize,
    pub first_op_index: Option<usize>,
    pub first_op_name: Option<String>,
    pub last_op_index: Option<usize>,
    pub last_op_name: Option<String>,
    pub read_count: usize,
    pub write_count: usize,
    pub reader_ops: Vec<String>,
    pub writer_ops: Vec<String>,
}

impl TensorLifetimePlanEntry {
    pub fn is_accessed(&self) -> bool {
        self.first_op_index.is_some()
    }

    fn record_read(&mut self, op_index: usize, op_name: &str) {
        self.read_count += 1;
        self.reader_ops.push(op_name.to_string());
        self.record_access(op_index, op_name);
    }

    fn record_write(&mut self, op_index: usize, op_name: &str) {
        self.write_count += 1;
        self.writer_ops.push(op_name.to_string());
        self.record_access(op_index, op_name);
    }

    fn record_access(&mut self, op_index: usize, op_name: &str) {
        if self.first_op_index.is_none() {
            self.first_op_index = Some(op_index);
            self.first_op_name = Some(op_name.to_string());
        }
        self.last_op_index = Some(op_index);
        self.last_op_name = Some(op_name.to_string());
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelTensorLifetimePlan {
    pub entries: Vec<TensorLifetimePlanEntry>,
    pub unused_tensors: Vec<TensorRef>,
    pub total_storage_bytes: usize,
}

impl ModelTensorLifetimePlan {
    pub fn entry_for(&self, tensor: &str) -> Option<&TensorLifetimePlanEntry> {
        self.entries
            .iter()
            .find(|entry| entry.tensor.as_str() == tensor)
    }
}

fn tensor_lifetime_plan_from(
    storage: &ModelTensorStoragePlan,
    access: &ModelTensorAccessPlan,
) -> Result<ModelTensorLifetimePlan> {
    let mut entries = BTreeMap::new();
    let mut total_storage_bytes = 0usize;
    for storage_entry in &storage.entries {
        total_storage_bytes =
            checked_add_bytes(total_storage_bytes, storage_entry.storage_bytes, "lifetime")?;
        entries.insert(
            storage_entry.tensor.clone(),
            TensorLifetimePlanEntry {
                tensor: storage_entry.tensor.clone(),
                dtype: storage_entry.dtype,
                role: storage_entry.role,
                storage_bytes: storage_entry.storage_bytes,
                first_op_index: None,
                first_op_name: None,
                last_op_index: None,
                last_op_name: None,
                read_count: 0,
                write_count: 0,
                reader_ops: Vec::new(),
                writer_ops: Vec::new(),
            },
        );
    }

    for (op_index, op_access) in access.entries.iter().enumerate() {
        for tensor in &op_access.reads {
            lifetime_entry_mut(&mut entries, tensor, &op_access.op_name)?
                .record_read(op_index, &op_access.op_name);
        }
        for tensor in &op_access.writes {
            lifetime_entry_mut(&mut entries, tensor, &op_access.op_name)?
                .record_write(op_index, &op_access.op_name);
        }
    }

    let entries = entries.into_values().collect::<Vec<_>>();
    let unused_tensors = entries
        .iter()
        .filter(|entry| !entry.is_accessed())
        .map(|entry| entry.tensor.clone())
        .collect();
    Ok(ModelTensorLifetimePlan {
        entries,
        unused_tensors,
        total_storage_bytes,
    })
}

fn lifetime_entry_mut<'a>(
    entries: &'a mut BTreeMap<TensorRef, TensorLifetimePlanEntry>,
    tensor: &TensorRef,
    op_name: &str,
) -> Result<&'a mut TensorLifetimePlanEntry> {
    entries
        .get_mut(tensor)
        .ok_or_else(|| anyhow!("op {op_name} references tensor {tensor} outside storage plan"))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TensorBindingClass {
    ExternalInput,
    ExternalOutput,
    CheckpointWeight,
    PersistentState,
    Scratch,
    Unused,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TensorBindingAccess {
    ReadOnly,
    WriteOnly,
    ReadWrite,
    Unused,
}

impl TensorBindingAccess {
    fn from_counts(read_count: usize, write_count: usize) -> Self {
        match (read_count > 0, write_count > 0) {
            (true, true) => Self::ReadWrite,
            (true, false) => Self::ReadOnly,
            (false, true) => Self::WriteOnly,
            (false, false) => Self::Unused,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
