#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelPrimitiveExecutionPlan {
    pub target: &'static str,
    pub entries: Vec<PrimitiveExecutionPlanEntry>,
    pub native_gpu_ops: usize,
    pub fused_native_gpu_ops: usize,
    pub gap_ops: usize,
    pub unstaged_ops: Vec<String>,
    pub binding_issues: Vec<TensorBindingIssue>,
}

impl ModelPrimitiveExecutionPlan {
    pub fn entry_for(&self, op_name: &str) -> Option<&PrimitiveExecutionPlanEntry> {
        self.entries.iter().find(|entry| entry.op_name == op_name)
    }

    pub fn assert_static_ready(&self) -> Result<()> {
        let mut issues = Vec::new();
        if !self.binding_issues.is_empty() {
            let binding_issues = self
                .binding_issues
                .iter()
                .map(|issue| format!("{}: {}", issue.tensor, issue.message))
                .collect::<Vec<_>>();
            issues.push(format!("binding issues: {}", binding_issues.join("; ")));
        }
        if self.gap_ops > 0 {
            let gap_ops = self
                .entries
                .iter()
                .filter(|entry| entry.has_lowering_gap())
                .map(|entry| format!("{}:{:?}", entry.op_name, entry.kind))
                .collect::<Vec<_>>();
            issues.push(format!("lowering gaps: {}", gap_ops.join(", ")));
        }
        if !self.unstaged_ops.is_empty() {
            issues.push(format!("unstaged ops: {}", self.unstaged_ops.join(", ")));
        }
        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "primitive execution plan for {} is not static-ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn primitive_execution_plan_from(
    graph: &ModelPrimitiveGraph,
    access: &ModelTensorAccessPlan,
    binding: &ModelTensorBindingPlan,
    lowering: &ModelLoweringPlan,
) -> Result<ModelPrimitiveExecutionPlan> {
    let stage_slots = execution_stage_slots(graph)?;
    let mut entries = Vec::with_capacity(access.entries.len());
    let mut unstaged_ops = Vec::new();

    for (op_index, op_access) in access.entries.iter().enumerate() {
        let lowering_entry = lowering.entries.get(op_index).ok_or_else(|| {
            anyhow!(
                "primitive execution plan missing lowering row for op {} ({})",
                op_index,
                op_access.op_name
            )
        })?;
        if lowering_entry.op_name != op_access.op_name || lowering_entry.kind != op_access.kind {
            return Err(anyhow!(
                "primitive execution plan row {} mismatch: access {}:{:?}, lowering {}:{:?}",
                op_index,
                op_access.op_name,
                op_access.kind,
                lowering_entry.op_name,
                lowering_entry.kind
            ));
        }

        let stage = stage_slots[op_index];
        if stage.is_none() {
            unstaged_ops.push(op_access.op_name.clone());
        }
        entries.push(PrimitiveExecutionPlanEntry {
            op_index,
            op_name: op_access.op_name.clone(),
            kind: op_access.kind,
            stage_name: stage.map(|stage| stage.name.clone()),
            stage_kind: stage.map(|stage| stage.kind),
            route: lowering_entry.route.clone(),
            reads: primitive_execution_tensor_bindings(
                &op_access.reads,
                binding,
                &op_access.op_name,
            )?,
            writes: primitive_execution_tensor_bindings(
                &op_access.writes,
                binding,
                &op_access.op_name,
            )?,
        });
    }

    Ok(ModelPrimitiveExecutionPlan {
        target: lowering.target,
        entries,
        native_gpu_ops: lowering.native_gpu_ops,
        fused_native_gpu_ops: lowering.fused_native_gpu_ops,
        gap_ops: lowering.gap_ops,
        unstaged_ops,
        binding_issues: binding.issues.clone(),
    })
}

fn execution_stage_slots(graph: &ModelPrimitiveGraph) -> Result<Vec<Option<&ModelStage>>> {
    let mut slots = vec![None; graph.ops.len()];
    for stage in &graph.stages {
        for op_index in stage.op_range() {
            let slot = slots.get_mut(op_index).ok_or_else(|| {
                anyhow!(
                    "stage {} references op {} outside graph op count {}",
                    stage.name,
                    op_index,
                    graph.ops.len()
                )
            })?;
            *slot = Some(stage);
        }
    }
    Ok(slots)
}

fn primitive_execution_tensor_bindings(
    tensors: &[TensorRef],
    binding: &ModelTensorBindingPlan,
    op_name: &str,
) -> Result<Vec<PrimitiveExecutionTensorBinding>> {
    tensors
        .iter()
        .map(|tensor| {
            let binding_entry = binding.entry_for(tensor.as_str()).ok_or_else(|| {
                anyhow!("op {op_name} references tensor {tensor} outside binding plan")
            })?;
            Ok(PrimitiveExecutionTensorBinding::from_binding(binding_entry))
        })
        .collect()
}

