#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeSlotDevicePointerLifetimePlan {
    pub target: &'static str,
    pub slot_count: usize,
    pub tracked_slot_count: usize,
    pub bound_slot_count: usize,
    pub accessed_slot_count: usize,
    pub unused_slot_count: usize,
    pub pointer_validation_issue_count: usize,
    pub missing_slot_count: usize,
    pub lifetime_issue_count: usize,
    pub total_storage_bytes: usize,
    pub total_binding_bytes: usize,
    pub cpu_lifetime_bound_count: usize,
    pub cpu_lifetime_unbound_count: usize,
    pub complete_device_pointer_validation: bool,
    pub all_accessed_lifetimes_bound: bool,
    pub residency_proven: bool,
    pub live_execution_supported: bool,
    pub entries: Vec<RuntimeSlotDevicePointerLifetimeEntry>,
    pub issues: Vec<RuntimeSlotDevicePointerLifetimeIssue>,
}

impl ModelRuntimeSlotDevicePointerLifetimePlan {
    pub fn entry_for(&self, tensor: &str) -> Option<&RuntimeSlotDevicePointerLifetimeEntry> {
        self.entries
            .iter()
            .find(|entry| entry.tensor.as_str() == tensor)
    }

    pub fn entry_for_slot(&self, slot: usize) -> Option<&RuntimeSlotDevicePointerLifetimeEntry> {
        self.entries.iter().find(|entry| entry.slot == slot)
    }

    pub fn is_cpu_lifetime_ready(&self) -> bool {
        self.assert_cpu_lifetime_ready().is_ok()
    }

    pub fn kfd_allocation_residency_request_plan(
        &self,
        resident_gpu_ids: &[u32],
    ) -> ModelRuntimeSlotKfdAllocationResidencyRequestPlan {
        runtime_slot_kfd_allocation_residency_request_plan_from(self, resident_gpu_ids)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.entries.len() != self.tracked_slot_count {
            issues.push(format!(
                "entry count {} != tracked slot count {}",
                self.entries.len(),
                self.tracked_slot_count
            ));
        }
        if self.tracked_slot_count + self.unused_slot_count != self.slot_count {
            issues.push(format!(
                "tracked+unused slot count {} != slot count {}",
                self.tracked_slot_count + self.unused_slot_count,
                self.slot_count
            ));
        }
        let mut seen_slots = BTreeSet::new();
        let mut bound_slot_count = 0usize;
        let mut accessed_slot_count = 0usize;
        let mut total_storage_bytes = 0usize;
        let mut total_binding_bytes = 0usize;
        let mut cpu_lifetime_bound_count = 0usize;
        let mut cpu_lifetime_unbound_count = 0usize;
        let mut row_lifetime_issue_count = 0usize;
        let mut row_pointer_validation_issue_count = 0usize;

        for entry in &self.entries {
            if !seen_slots.insert(entry.slot) {
                issues.push(format!("slot {} appears more than once", entry.slot));
            }
            if entry.tensor.as_str().trim().is_empty() {
                issues.push(format!("slot {} has empty tensor name", entry.slot));
            }
            if entry.binding_present {
                bound_slot_count += 1;
                total_binding_bytes =
                    checked_add_usize(total_binding_bytes, entry.binding_bytes, "binding bytes")?;
                if entry.device_va == 0 {
                    issues.push(format!(
                        "slot {} {} has a present binding with null device VA",
                        entry.slot, entry.tensor
                    ));
                }
                let expected_end = entry.device_va.checked_add(entry.binding_bytes as u64);
                if entry.device_va_end != expected_end {
                    issues.push(format!(
                        "slot {} {} device VA end {:?} != expected {:?}",
                        entry.slot, entry.tensor, entry.device_va_end, expected_end
                    ));
                }
            } else if entry.binding_bytes != 0
                || entry.device_va != 0
                || entry.device_va_end.is_some()
            {
                issues.push(format!(
                    "slot {} {} has binding fields without a binding",
                    entry.slot, entry.tensor
                ));
            }
            total_storage_bytes =
                checked_add_usize(total_storage_bytes, entry.storage_bytes, "storage bytes")?;
            let accessed = entry.first_op_index.is_some();
            if accessed {
                accessed_slot_count += 1;
                match (entry.first_op_index, entry.last_op_index) {
                    (Some(first), Some(last)) if first <= last => {
                        let expected_live_range = last - first + 1;
                        if entry.live_range_op_count != expected_live_range {
                            issues.push(format!(
                                "slot {} {} live range {} != expected {}",
                                entry.slot,
                                entry.tensor,
                                entry.live_range_op_count,
                                expected_live_range
                            ));
                        }
                    }
                    _ => issues.push(format!(
                        "slot {} {} has incomplete or inverted lifetime indices",
                        entry.slot, entry.tensor
                    )),
                }
            } else if entry.live_range_op_count != 0 {
                issues.push(format!(
                    "slot {} {} is not accessed but has live range {}",
                    entry.slot, entry.tensor, entry.live_range_op_count
                ));
            }
            if entry.cpu_lifetime_bound {
                cpu_lifetime_bound_count += 1;
                if !accessed || !entry.binding_present {
                    issues.push(format!(
                        "slot {} {} claims a bound lifetime without access and binding",
                        entry.slot, entry.tensor
                    ));
                }
                if entry.pointer_validation_issue_count != 0 || entry.lifetime_issue_count != 0 {
                    issues.push(format!(
                        "slot {} {} claims a bound lifetime with row issues",
                        entry.slot, entry.tensor
                    ));
                }
            } else if accessed {
                cpu_lifetime_unbound_count += 1;
            }
            row_lifetime_issue_count = checked_add_usize(
                row_lifetime_issue_count,
                entry.lifetime_issue_count,
                "row lifetime issue count",
            )?;
            row_pointer_validation_issue_count = checked_add_usize(
                row_pointer_validation_issue_count,
                entry.pointer_validation_issue_count,
                "row pointer validation issue count",
            )?;
        }

        if bound_slot_count != self.bound_slot_count {
            issues.push(format!(
                "bound slot count {bound_slot_count} != plan {}",
                self.bound_slot_count
            ));
        }
        if accessed_slot_count != self.accessed_slot_count {
            issues.push(format!(
                "accessed slot count {accessed_slot_count} != plan {}",
                self.accessed_slot_count
            ));
        }
        if total_storage_bytes != self.total_storage_bytes {
            issues.push(format!(
                "total storage bytes {total_storage_bytes} != plan {}",
                self.total_storage_bytes
            ));
        }
        if total_binding_bytes != self.total_binding_bytes {
            issues.push(format!(
                "total binding bytes {total_binding_bytes} != plan {}",
                self.total_binding_bytes
            ));
        }
        if cpu_lifetime_bound_count != self.cpu_lifetime_bound_count {
            issues.push(format!(
                "CPU lifetime bound count {cpu_lifetime_bound_count} != plan {}",
                self.cpu_lifetime_bound_count
            ));
        }
        if cpu_lifetime_unbound_count != self.cpu_lifetime_unbound_count {
            issues.push(format!(
                "CPU lifetime unbound count {cpu_lifetime_unbound_count} != plan {}",
                self.cpu_lifetime_unbound_count
            ));
        }
        if row_lifetime_issue_count > self.lifetime_issue_count {
            issues.push(format!(
                "row lifetime issues {row_lifetime_issue_count} exceed plan {}",
                self.lifetime_issue_count
            ));
        }
        if row_pointer_validation_issue_count > self.pointer_validation_issue_count {
            issues.push(format!(
                "row pointer validation issues {row_pointer_validation_issue_count} exceed plan {}",
                self.pointer_validation_issue_count
            ));
        }
        let complete_device_pointer_validation =
            self.pointer_validation_issue_count == 0 && self.missing_slot_count == 0;
        if self.complete_device_pointer_validation != complete_device_pointer_validation {
            issues.push(format!(
                "complete device pointer validation {} != expected {}",
                self.complete_device_pointer_validation, complete_device_pointer_validation
            ));
        }
        let all_accessed_lifetimes_bound = self.accessed_slot_count > 0
            && self.cpu_lifetime_bound_count == self.accessed_slot_count
            && self.cpu_lifetime_unbound_count == 0;
        if self.all_accessed_lifetimes_bound != all_accessed_lifetimes_bound {
            issues.push(format!(
                "all accessed lifetimes bound {} != expected {}",
                self.all_accessed_lifetimes_bound, all_accessed_lifetimes_bound
            ));
        }
        if self.live_execution_supported != MODEL_API_CONTRACT.live_execution_supported {
            issues.push(format!(
                "live execution support {} != contract {}",
                self.live_execution_supported, MODEL_API_CONTRACT.live_execution_supported
            ));
        }
        if self.residency_proven {
            issues
                .push("device pointer lifetime plan unexpectedly proves KFD residency".to_string());
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime slot device pointer lifetime plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn assert_cpu_lifetime_ready(&self) -> Result<()> {
        self.assert_consistent()?;
        if self.complete_device_pointer_validation
            && self.all_accessed_lifetimes_bound
            && self.lifetime_issue_count == 0
        {
            return Ok(());
        }
        let mut issues = Vec::new();
        if !self.complete_device_pointer_validation {
            issues.push(format!(
                "device pointer validation incomplete: pointer issues={}, missing slots={}",
                self.pointer_validation_issue_count, self.missing_slot_count
            ));
        }
        if !self.all_accessed_lifetimes_bound {
            issues.push(format!(
                "{} accessed lifetime slot(s) are not bound",
                self.cpu_lifetime_unbound_count
            ));
        }
        if self.lifetime_issue_count > 0 {
            issues.push(format!("lifetime issues: {}", self.lifetime_issue_count));
        }
        let issue_details = self
            .issues
            .iter()
            .map(|issue| format!("slot {} {}: {}", issue.slot, issue.tensor, issue.message))
            .collect::<Vec<_>>();
        if !issue_details.is_empty() {
            issues.push(issue_details.join("; "));
        }
        Err(anyhow!(
            "runtime slot device pointer lifetime plan for {} is not CPU-lifetime-ready: {}",
            self.target,
            issues.join("; ")
        ))
    }
}

const MODEL_RUNTIME_SLOT_KFD_ALLOCATION_RESIDENCY_REQUEST_SOURCE: &str =
    "mainarch_kfd_slot_allocation_residency_request_v0";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RuntimeSlotKfdAllocationKind {
    HostVisibleGtt,
    DeviceLocalVramPreferPublicCoherent,
}

impl RuntimeSlotKfdAllocationKind {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::HostVisibleGtt => "host_visible_gtt",
            Self::DeviceLocalVramPreferPublicCoherent => "device_local_vram_prefer_public_coherent",
        }
    }

    pub fn primary_alloc_flags(self) -> u32 {
        match self {
            Self::HostVisibleGtt => {
                mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_GTT
                    | mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_WRITABLE
                    | mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_NO_SUBSTITUTE
                    | mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_COHERENT
            }
            Self::DeviceLocalVramPreferPublicCoherent => {
                mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_VRAM
                    | mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_PUBLIC
                    | mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_WRITABLE
                    | mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_NO_SUBSTITUTE
                    | mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_COHERENT
            }
        }
    }

    pub fn fallback_alloc_flags(self) -> Option<u32> {
        match self {
            Self::HostVisibleGtt => None,
            Self::DeviceLocalVramPreferPublicCoherent => Some(
                mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_VRAM
                    | mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_WRITABLE
                    | mainarch_sys::KFD_IOC_ALLOC_MEM_FLAGS_NO_SUBSTITUTE,
            ),
        }
    }
}

impl fmt::Display for RuntimeSlotKfdAllocationKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

