#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdAllocMemoryRequestIssue {
    pub slot: Option<usize>,
    pub tensor: Option<TensorRef>,
    pub message: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeKfdAllocMemoryRequestPlan {
    pub target: &'static str,
    pub request_source: &'static str,
    pub kfd_device_path: &'static str,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub allocation_gpu_id: Option<u32>,
    pub allocation_gpu_selection_policy: &'static str,
    pub slot_count: usize,
    pub allocation_request_count: usize,
    pub host_visible_gtt_request_count: usize,
    pub device_local_vram_request_count: usize,
    pub fallback_available_request_count: usize,
    pub map_to_gpu_request_count: usize,
    pub total_storage_bytes: usize,
    pub total_alloc_memory_bytes: usize,
    pub kfd_fd_bound_count: usize,
    pub vm_acquire_performed_count: usize,
    pub allocation_performed_count: usize,
    pub handle_bound_count: usize,
    pub mmap_offset_bound_count: usize,
    pub request_issue_count: usize,
    pub allocation_residency_request_ready: bool,
    pub vm_acquire_request_metadata_ready: bool,
    pub all_request_metadata_ready: bool,
    pub allocation_performed: bool,
    pub live_execution_supported: bool,
    pub entries: Vec<RuntimeKfdAllocMemoryRequestEntry>,
    pub issues: Vec<RuntimeKfdAllocMemoryRequestIssue>,
}

impl ModelRuntimeKfdAllocMemoryRequestPlan {
    pub fn entry_for(&self, tensor: &str) -> Option<&RuntimeKfdAllocMemoryRequestEntry> {
        self.entries
            .iter()
            .find(|entry| entry.tensor.as_str() == tensor)
    }

    pub fn entry_for_slot(&self, slot: usize) -> Option<&RuntimeKfdAllocMemoryRequestEntry> {
        self.entries.iter().find(|entry| entry.slot == slot)
    }

    pub fn is_kfd_alloc_memory_request_ready(&self) -> bool {
        self.assert_kfd_alloc_memory_request_ready().is_ok()
    }

    pub fn kfd_map_memory_request_plan(&self) -> ModelRuntimeKfdMapMemoryRequestPlan {
        runtime_kfd_map_memory_request_plan_from(self)
    }

    pub fn kfd_alloc_memory_result_binding_plan(
        &self,
        result_bindings: &[RuntimeKfdAllocMemoryResultBinding],
    ) -> ModelRuntimeKfdAllocMemoryResultBindingPlan {
        runtime_kfd_alloc_memory_result_binding_plan_from(self, result_bindings)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.request_source != MODEL_RUNTIME_KFD_ALLOC_MEMORY_REQUEST_SOURCE {
            issues.push(format!(
                "request source {} != {}",
                self.request_source, MODEL_RUNTIME_KFD_ALLOC_MEMORY_REQUEST_SOURCE
            ));
        }
        if self.kfd_device_path != mainarch_sys::KFD_DEVICE {
            issues.push(format!(
                "KFD device path {} != {}",
                self.kfd_device_path,
                mainarch_sys::KFD_DEVICE
            ));
        }
        if self.allocation_gpu_selection_policy
            != MODEL_RUNTIME_KFD_ALLOC_MEMORY_GPU_SELECTION_POLICY
        {
            issues.push(format!(
                "allocation GPU selection policy {} != {}",
                self.allocation_gpu_selection_policy,
                MODEL_RUNTIME_KFD_ALLOC_MEMORY_GPU_SELECTION_POLICY
            ));
        }
        if self.entries.len() != self.allocation_request_count {
            issues.push(format!(
                "entry count {} != allocation request count {}",
                self.entries.len(),
                self.allocation_request_count
            ));
        }
        let resident_gpu_ids = self
            .resident_gpu_ids
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if resident_gpu_ids.len() != self.resident_gpu_ids.len() {
            issues.push("resident GPU IDs contain duplicates".to_string());
        }
        let canonical_resident_gpu_ids = resident_gpu_ids.iter().copied().collect::<Vec<_>>();
        if canonical_resident_gpu_ids != self.resident_gpu_ids {
            issues.push("resident GPU IDs are not sorted and unique".to_string());
        }
        if self.resident_gpu_id_count != self.resident_gpu_ids.len() {
            issues.push(format!(
                "resident GPU ID count {} != IDs {}",
                self.resident_gpu_id_count,
                self.resident_gpu_ids.len()
            ));
        }
        match (
            self.resident_gpu_ids.first().copied(),
            self.allocation_gpu_id,
        ) {
            (Some(expected), Some(actual)) if expected == actual => {}
            (Some(expected), actual) => issues.push(format!(
                "allocation GPU ID {:?} != first resident GPU ID {}",
                actual, expected
            )),
            (None, Some(actual)) => issues.push(format!(
                "allocation GPU ID {} is set without resident GPU IDs",
                actual
            )),
            (None, None) => {}
        }
        if self.request_issue_count != self.issues.len() {
            issues.push(format!(
                "request issue count {} != issue rows {}",
                self.request_issue_count,
                self.issues.len()
            ));
        }
        if self.kfd_fd_bound_count != 0 {
            issues.push(format!(
                "KFD fd bound count {} != 0",
                self.kfd_fd_bound_count
            ));
        }
        if self.vm_acquire_performed_count != 0 {
            issues.push(format!(
                "VM acquire performed count {} != 0",
                self.vm_acquire_performed_count
            ));
        }
        if self.allocation_performed_count != 0 {
            issues.push(format!(
                "allocation performed count {} != 0",
                self.allocation_performed_count
            ));
        }
        if self.handle_bound_count != 0 {
            issues.push(format!(
                "allocation handle bound count {} != 0",
                self.handle_bound_count
            ));
        }
        if self.mmap_offset_bound_count != 0 {
            issues.push(format!(
                "mmap offset bound count {} != 0",
                self.mmap_offset_bound_count
            ));
        }

        let mut seen_slots = BTreeSet::new();
        let mut host_visible_gtt_request_count = 0usize;
        let mut device_local_vram_request_count = 0usize;
        let mut fallback_available_request_count = 0usize;
        let mut map_to_gpu_request_count = 0usize;
        let mut total_storage_bytes = 0usize;
        let mut total_alloc_memory_bytes = 0usize;
        let mut kfd_fd_bound_count = 0usize;
        let mut vm_acquire_performed_count = 0usize;
        let mut allocation_performed_count = 0usize;
        let mut handle_bound_count = 0usize;
        let mut mmap_offset_bound_count = 0usize;
        let mut entry_issue_count = 0usize;
        let mut entries_ready = true;

        for entry in &self.entries {
            if !seen_slots.insert(entry.slot) {
                issues.push(format!("slot {} appears more than once", entry.slot));
            }
            if entry.tensor.as_str().trim().is_empty() {
                issues.push(format!("slot {} has empty tensor name", entry.slot));
            }
            match entry.allocation_kind {
                RuntimeSlotKfdAllocationKind::HostVisibleGtt => {
                    host_visible_gtt_request_count += 1;
                }
                RuntimeSlotKfdAllocationKind::DeviceLocalVramPreferPublicCoherent => {
                    device_local_vram_request_count += 1;
                }
            }
            if entry.allocation_gpu_selection_policy != self.allocation_gpu_selection_policy {
                issues.push(format!(
                    "slot {} {} allocation GPU selection policy {} != plan {}",
                    entry.slot,
                    entry.tensor,
                    entry.allocation_gpu_selection_policy,
                    self.allocation_gpu_selection_policy
                ));
            }
            if let Some(allocation_gpu_id) = self.allocation_gpu_id {
                if entry.allocation_gpu_id != allocation_gpu_id {
                    issues.push(format!(
                        "slot {} {} allocation GPU ID {} != plan {}",
                        entry.slot, entry.tensor, entry.allocation_gpu_id, allocation_gpu_id
                    ));
                }
            }
            if entry.alloc_memory_ioctl != mainarch_sys::ioc_alloc_memory_of_gpu() as u64 {
                issues.push(format!(
                    "slot {} {} alloc-memory ioctl 0x{:x} != expected 0x{:x}",
                    entry.slot,
                    entry.tensor,
                    entry.alloc_memory_ioctl,
                    mainarch_sys::ioc_alloc_memory_of_gpu() as u64
                ));
            }
            if entry.alloc_args_va_addr == 0 {
                issues.push(format!(
                    "slot {} {} alloc args have null VA",
                    entry.slot, entry.tensor
                ));
            }
            if entry.alloc_args_size != entry.requested_bytes as u64 {
                issues.push(format!(
                    "slot {} {} alloc args size {} != requested bytes {}",
                    entry.slot, entry.tensor, entry.alloc_args_size, entry.requested_bytes
                ));
            }
            if entry.alloc_args_size < entry.storage_bytes as u64 {
                issues.push(format!(
                    "slot {} {} alloc args size {} < storage bytes {}",
                    entry.slot, entry.tensor, entry.alloc_args_size, entry.storage_bytes
                ));
            }
            if entry.alloc_args_gpu_id != entry.allocation_gpu_id {
                issues.push(format!(
                    "slot {} {} alloc args GPU ID {} != allocation GPU ID {}",
                    entry.slot, entry.tensor, entry.alloc_args_gpu_id, entry.allocation_gpu_id
                ));
            }
            if entry.alloc_args_flags != entry.allocation_kind.primary_alloc_flags() {
                issues.push(format!(
                    "slot {} {} alloc args flags 0x{:08x} != expected 0x{:08x}",
                    entry.slot,
                    entry.tensor,
                    entry.alloc_args_flags,
                    entry.allocation_kind.primary_alloc_flags()
                ));
            }
            if entry.fallback_alloc_args_flags != entry.allocation_kind.fallback_alloc_flags() {
                issues.push(format!(
                    "slot {} {} fallback flags {:?} != expected {:?}",
                    entry.slot,
                    entry.tensor,
                    entry.fallback_alloc_args_flags,
                    entry.allocation_kind.fallback_alloc_flags()
                ));
            }
            if entry.fallback_alloc_args_flags.is_some() {
                fallback_available_request_count += 1;
            }
            if entry.resident_gpu_ids != self.resident_gpu_ids {
                issues.push(format!(
                    "slot {} {} resident GPU IDs do not match plan",
                    entry.slot, entry.tensor
                ));
            }
            if entry.resident_gpu_id_count != entry.resident_gpu_ids.len() {
                issues.push(format!(
                    "slot {} {} resident GPU ID count {} != IDs {}",
                    entry.slot,
                    entry.tensor,
                    entry.resident_gpu_id_count,
                    entry.resident_gpu_ids.len()
                ));
            }
            if !entry.kfd_fd_required {
                issues.push(format!(
                    "slot {} {} does not require a KFD fd",
                    entry.slot, entry.tensor
                ));
            }
            if entry.kfd_fd_bound {
                kfd_fd_bound_count += 1;
                issues.push(format!(
                    "slot {} {} unexpectedly has a bound KFD fd",
                    entry.slot, entry.tensor
                ));
            }
            let resident_ids_present = entry.resident_gpu_id_count > 0;
            if entry.vm_acquire_required != resident_ids_present {
                issues.push(format!(
                    "slot {} {} VM-acquire requirement {} != resident IDs present {}",
                    entry.slot, entry.tensor, entry.vm_acquire_required, resident_ids_present
                ));
            }
            if entry.vm_acquire_performed {
                vm_acquire_performed_count += 1;
                issues.push(format!(
                    "slot {} {} unexpectedly reports VM acquisition performed",
                    entry.slot, entry.tensor
                ));
            }
            if !entry.allocation_required {
                issues.push(format!(
                    "slot {} {} does not require allocation",
                    entry.slot, entry.tensor
                ));
            }
            if entry.allocation_performed {
                allocation_performed_count += 1;
                issues.push(format!(
                    "slot {} {} unexpectedly reports allocation performed",
                    entry.slot, entry.tensor
                ));
            }
            if entry.map_to_gpu_required {
                map_to_gpu_request_count += 1;
            } else if resident_ids_present {
                issues.push(format!(
                    "slot {} {} does not request map-to-GPU after allocation",
                    entry.slot, entry.tensor
                ));
            }
            if entry.handle_bound {
                handle_bound_count += 1;
                issues.push(format!(
                    "slot {} {} unexpectedly has a bound allocation handle",
                    entry.slot, entry.tensor
                ));
            }
            if entry.mmap_offset_bound {
                mmap_offset_bound_count += 1;
                issues.push(format!(
                    "slot {} {} unexpectedly has a bound mmap offset",
                    entry.slot, entry.tensor
                ));
            }
            let expected_entry_ready = self.allocation_residency_request_ready
                && self.vm_acquire_request_metadata_ready
                && entry.issue_count == 0;
            if entry.request_metadata_ready != expected_entry_ready {
                issues.push(format!(
                    "slot {} {} request_metadata_ready {} != expected {}",
                    entry.slot, entry.tensor, entry.request_metadata_ready, expected_entry_ready
                ));
            }
            if !entry.request_metadata_ready {
                entries_ready = false;
            }
            total_storage_bytes = checked_add_usize(
                total_storage_bytes,
                entry.storage_bytes,
                "KFD alloc-memory storage bytes",
            )?;
            total_alloc_memory_bytes = checked_add_usize(
                total_alloc_memory_bytes,
                entry.requested_bytes,
                "KFD alloc-memory request bytes",
            )?;
            entry_issue_count = checked_add_usize(
                entry_issue_count,
                entry.issue_count,
                "KFD alloc-memory request entry issues",
            )?;
        }

        if host_visible_gtt_request_count != self.host_visible_gtt_request_count {
            issues.push(format!(
                "host-visible GTT request count {host_visible_gtt_request_count} != plan {}",
                self.host_visible_gtt_request_count
            ));
        }
        if device_local_vram_request_count != self.device_local_vram_request_count {
            issues.push(format!(
                "device-local VRAM request count {device_local_vram_request_count} != plan {}",
                self.device_local_vram_request_count
            ));
        }
        if fallback_available_request_count != self.fallback_available_request_count {
            issues.push(format!(
                "fallback-available request count {fallback_available_request_count} != plan {}",
                self.fallback_available_request_count
            ));
        }
        if map_to_gpu_request_count != self.map_to_gpu_request_count {
            issues.push(format!(
                "map-to-GPU request count {map_to_gpu_request_count} != plan {}",
                self.map_to_gpu_request_count
            ));
        }
        if total_storage_bytes != self.total_storage_bytes {
            issues.push(format!(
                "total storage bytes {total_storage_bytes} != plan {}",
                self.total_storage_bytes
            ));
        }
        if total_alloc_memory_bytes != self.total_alloc_memory_bytes {
            issues.push(format!(
                "total alloc-memory bytes {total_alloc_memory_bytes} != plan {}",
                self.total_alloc_memory_bytes
            ));
        }
        if kfd_fd_bound_count != self.kfd_fd_bound_count {
            issues.push(format!(
                "KFD fd bound count {kfd_fd_bound_count} != plan {}",
                self.kfd_fd_bound_count
            ));
        }
        if vm_acquire_performed_count != self.vm_acquire_performed_count {
            issues.push(format!(
                "VM acquire performed count {vm_acquire_performed_count} != plan {}",
                self.vm_acquire_performed_count
            ));
        }
        if allocation_performed_count != self.allocation_performed_count {
            issues.push(format!(
                "allocation performed count {allocation_performed_count} != plan {}",
                self.allocation_performed_count
            ));
        }
        if handle_bound_count != self.handle_bound_count {
            issues.push(format!(
                "handle bound count {handle_bound_count} != plan {}",
                self.handle_bound_count
            ));
        }
        if mmap_offset_bound_count != self.mmap_offset_bound_count {
            issues.push(format!(
                "mmap offset bound count {mmap_offset_bound_count} != plan {}",
                self.mmap_offset_bound_count
            ));
        }
        let slot_issue_rows = self
            .issues
            .iter()
            .filter(|issue| issue.slot.is_some())
            .count();
        if entry_issue_count != slot_issue_rows {
            issues.push(format!(
                "entry issue count {entry_issue_count} != slot issue rows {slot_issue_rows}"
            ));
        }
        let expected_all_request_metadata_ready = self.allocation_residency_request_ready
            && self.vm_acquire_request_metadata_ready
            && self.allocation_request_count > 0
            && self.request_issue_count == 0
            && entries_ready;
        if self.all_request_metadata_ready != expected_all_request_metadata_ready {
            issues.push(format!(
                "all_request_metadata_ready {} != expected {}",
                self.all_request_metadata_ready, expected_all_request_metadata_ready
            ));
        }
        if self.allocation_performed {
            issues.push("KFD alloc-memory request plan unexpectedly allocated buffers".to_string());
        }
        if self.live_execution_supported != MODEL_API_CONTRACT.live_execution_supported {
            issues.push(format!(
                "live execution support {} != contract {}",
                self.live_execution_supported, MODEL_API_CONTRACT.live_execution_supported
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD alloc-memory request plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn assert_kfd_alloc_memory_request_ready(&self) -> Result<()> {
        let mut issues = Vec::new();
        if let Err(err) = self.assert_consistent() {
            issues.push(format!("consistency: {err}"));
        }
        if !self.allocation_residency_request_ready {
            issues.push("slot KFD allocation/residency request plan is not ready".to_string());
        }
        if !self.vm_acquire_request_metadata_ready {
            issues.push("KFD VM-acquire request metadata is not ready".to_string());
        }
        if self.allocation_request_count == 0 {
            issues.push("no KFD alloc-memory requests produced".to_string());
        }
        if self.request_issue_count > 0 {
            issues.push(format!("request issues: {}", self.request_issue_count));
        }
        if self.kfd_fd_bound_count > 0
            || self.vm_acquire_performed_count > 0
            || self.allocation_performed_count > 0
            || self.handle_bound_count > 0
            || self.mmap_offset_bound_count > 0
        {
            issues.push("live KFD allocation state has already been marked bound".to_string());
        }
        if self.allocation_performed {
            issues.push("KFD allocation has already been marked performed".to_string());
        }
        if self.live_execution_supported {
            issues.push("live execution support is unexpectedly enabled".to_string());
        }
        if !self.all_request_metadata_ready {
            issues.push("not all alloc-memory request metadata is ready".to_string());
        }
        let issue_details = self
            .issues
            .iter()
            .map(runtime_kfd_alloc_memory_issue_label)
            .collect::<Vec<_>>();
        if !issue_details.is_empty() {
            issues.push(issue_details.join("; "));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD alloc-memory request plan for {} is not ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn runtime_kfd_alloc_memory_issue_label(issue: &RuntimeKfdAllocMemoryRequestIssue) -> String {
    match (&issue.slot, &issue.tensor) {
        (Some(slot), Some(tensor)) => format!("slot {slot} {tensor}: {}", issue.message),
        (Some(slot), None) => format!("slot {slot}: {}", issue.message),
        (None, Some(tensor)) => format!("{tensor}: {}", issue.message),
        (None, None) => issue.message.clone(),
    }
}

fn runtime_kfd_alloc_memory_request_plan_from(
    allocation_requests: &ModelRuntimeSlotKfdAllocationResidencyRequestPlan,
    vm_acquires: &ModelRuntimeKfdVmAcquireRequestPlan,
) -> ModelRuntimeKfdAllocMemoryRequestPlan {
    let mut issues = Vec::new();
    let allocation_residency_request_ready =
        match allocation_requests.assert_kfd_allocation_residency_request_ready() {
            Ok(()) => true,
            Err(err) => {
                issues.push(RuntimeKfdAllocMemoryRequestIssue {
                    slot: None,
                    tensor: None,
                    message: format!("slot allocation/residency request plan is not ready: {err}"),
                });
                false
            }
        };
    let vm_acquire_request_metadata_ready = match vm_acquires.assert_kfd_vm_acquire_request_ready()
    {
        Ok(()) => true,
        Err(err) => {
            issues.push(RuntimeKfdAllocMemoryRequestIssue {
                slot: None,
                tensor: None,
                message: format!("KFD VM-acquire request plan is not ready: {err}"),
            });
            false
        }
    };
    if vm_acquires.target != allocation_requests.target {
        issues.push(RuntimeKfdAllocMemoryRequestIssue {
            slot: None,
            tensor: None,
            message: format!(
                "KFD VM-acquire target {} != allocation/residency target {}",
                vm_acquires.target, allocation_requests.target
            ),
        });
    }
    if vm_acquires.resident_gpu_ids != allocation_requests.resident_gpu_ids {
        issues.push(RuntimeKfdAllocMemoryRequestIssue {
            slot: None,
            tensor: None,
            message: "KFD VM-acquire resident GPU IDs do not match allocation/residency requests"
                .to_string(),
        });
    }
    let allocation_gpu_id = allocation_requests.resident_gpu_ids.first().copied();
    if allocation_gpu_id
        .and_then(|gpu_id| vm_acquires.entry_for_gpu_id(gpu_id))
        .is_none()
        && allocation_gpu_id.is_some()
    {
        issues.push(RuntimeKfdAllocMemoryRequestIssue {
            slot: None,
            tensor: None,
            message: "KFD VM-acquire request is missing the allocation GPU ID".to_string(),
        });
    }

    let mut entries = Vec::new();
    let mut host_visible_gtt_request_count = 0usize;
    let mut device_local_vram_request_count = 0usize;
    let mut fallback_available_request_count = 0usize;
    let mut map_to_gpu_request_count = 0usize;
    let mut total_storage_bytes = 0usize;
    let mut total_alloc_memory_bytes = 0usize;

    for allocation in &allocation_requests.entries {
        let mut entry_issue_count = 0usize;
        match allocation.allocation_kind {
            RuntimeSlotKfdAllocationKind::HostVisibleGtt => {
                host_visible_gtt_request_count += 1;
            }
            RuntimeSlotKfdAllocationKind::DeviceLocalVramPreferPublicCoherent => {
                device_local_vram_request_count += 1;
            }
        }
        if allocation.fallback_alloc_flags.is_some() {
            fallback_available_request_count += 1;
        }
        if allocation.map_to_gpu_required {
            map_to_gpu_request_count += 1;
        }
        match total_storage_bytes.checked_add(allocation.storage_bytes) {
            Some(total) => total_storage_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryRequestIssue {
                    slot: Some(allocation.slot),
                    tensor: Some(allocation.tensor.clone()),
                    message: "total storage bytes overflow".to_string(),
                });
            }
        }
        match total_alloc_memory_bytes.checked_add(allocation.requested_bytes) {
            Some(total) => total_alloc_memory_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryRequestIssue {
                    slot: Some(allocation.slot),
                    tensor: Some(allocation.tensor.clone()),
                    message: "total alloc-memory bytes overflow".to_string(),
                });
            }
        }
        if !allocation.request_ready {
            entry_issue_count += 1;
            issues.push(RuntimeKfdAllocMemoryRequestIssue {
                slot: Some(allocation.slot),
                tensor: Some(allocation.tensor.clone()),
                message: "slot allocation/residency request is not ready".to_string(),
            });
        }
        if allocation.device_va == 0 {
            entry_issue_count += 1;
            issues.push(RuntimeKfdAllocMemoryRequestIssue {
                slot: Some(allocation.slot),
                tensor: Some(allocation.tensor.clone()),
                message: "slot has no proposed device VA for alloc-memory args".to_string(),
            });
        }
        let alloc_args_size = match u64::try_from(allocation.requested_bytes) {
            Ok(size) => size,
            Err(_) => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryRequestIssue {
                    slot: Some(allocation.slot),
                    tensor: Some(allocation.tensor.clone()),
                    message: "requested bytes exceed u64 alloc-memory args size".to_string(),
                });
                0
            }
        };
        if allocation_gpu_id.is_none() {
            entry_issue_count += 1;
            issues.push(RuntimeKfdAllocMemoryRequestIssue {
                slot: Some(allocation.slot),
                tensor: Some(allocation.tensor.clone()),
                message: "no allocation GPU ID available".to_string(),
            });
        }
        let request_metadata_ready = allocation_residency_request_ready
            && vm_acquire_request_metadata_ready
            && entry_issue_count == 0;
        entries.push(RuntimeKfdAllocMemoryRequestEntry {
            slot: allocation.slot,
            tensor: allocation.tensor.clone(),
            class: allocation.class,
            lifetime_access: allocation.lifetime_access,
            allocation_kind: allocation.allocation_kind,
            allocation_gpu_id: allocation_gpu_id.unwrap_or(0),
            allocation_gpu_selection_policy: MODEL_RUNTIME_KFD_ALLOC_MEMORY_GPU_SELECTION_POLICY,
            alloc_memory_ioctl: mainarch_sys::ioc_alloc_memory_of_gpu() as u64,
            alloc_args_va_addr: allocation.device_va,
            alloc_args_size,
            alloc_args_gpu_id: allocation_gpu_id.unwrap_or(0),
            alloc_args_flags: allocation.primary_alloc_flags,
            fallback_alloc_args_flags: allocation.fallback_alloc_flags,
            storage_bytes: allocation.storage_bytes,
            requested_bytes: allocation.requested_bytes,
            resident_gpu_ids: allocation.resident_gpu_ids.clone(),
            resident_gpu_id_count: allocation.resident_gpu_id_count,
            kfd_fd_required: true,
            kfd_fd_bound: false,
            vm_acquire_required: allocation.vm_acquire_required,
            vm_acquire_performed: false,
            allocation_required: allocation.allocation_required,
            allocation_performed: false,
            map_to_gpu_required: allocation.map_to_gpu_required,
            handle_bound: false,
            mmap_offset_bound: false,
            request_metadata_ready,
            issue_count: entry_issue_count,
        });
    }

    let allocation_request_count = entries.len();
    let request_issue_count = issues.len();
    let all_request_metadata_ready = allocation_residency_request_ready
        && vm_acquire_request_metadata_ready
        && allocation_request_count > 0
        && request_issue_count == 0
        && entries
            .iter()
            .all(|entry| entry.request_metadata_ready && entry.issue_count == 0);

    ModelRuntimeKfdAllocMemoryRequestPlan {
        target: allocation_requests.target,
        request_source: MODEL_RUNTIME_KFD_ALLOC_MEMORY_REQUEST_SOURCE,
        kfd_device_path: mainarch_sys::KFD_DEVICE,
        resident_gpu_ids: allocation_requests.resident_gpu_ids.clone(),
        resident_gpu_id_count: allocation_requests.resident_gpu_id_count,
        allocation_gpu_id,
        allocation_gpu_selection_policy: MODEL_RUNTIME_KFD_ALLOC_MEMORY_GPU_SELECTION_POLICY,
        slot_count: allocation_requests.slot_count,
        allocation_request_count,
        host_visible_gtt_request_count,
        device_local_vram_request_count,
        fallback_available_request_count,
        map_to_gpu_request_count,
        total_storage_bytes,
        total_alloc_memory_bytes,
        kfd_fd_bound_count: 0,
        vm_acquire_performed_count: 0,
        allocation_performed_count: 0,
        handle_bound_count: 0,
        mmap_offset_bound_count: 0,
        request_issue_count,
        allocation_residency_request_ready,
        vm_acquire_request_metadata_ready,
        all_request_metadata_ready,
        allocation_performed: false,
        live_execution_supported: MODEL_API_CONTRACT.live_execution_supported,
        entries,
        issues,
    }
}

const MODEL_RUNTIME_KFD_ALLOC_MEMORY_RESULT_BINDING_SOURCE: &str =
    "mainarch_kfd_alloc_memory_result_binding_v0";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdAllocMemoryResultBinding {
    pub slot: usize,
    pub tensor: TensorRef,
    pub allocation_gpu_id: u32,
    pub alloc_args_va_addr: u64,
    pub alloc_args_size: u64,
    pub alloc_args_flags: u32,
    pub handle: u64,
    pub mmap_offset: u64,
}

impl RuntimeKfdAllocMemoryResultBinding {
    pub fn new(
        slot: usize,
        tensor: impl Into<String>,
        allocation_gpu_id: u32,
        alloc_args_va_addr: u64,
        alloc_args_size: u64,
        alloc_args_flags: u32,
        handle: u64,
        mmap_offset: u64,
    ) -> Result<Self> {
        Ok(Self {
            slot,
            tensor: TensorRef::new(tensor)?,
            allocation_gpu_id,
            alloc_args_va_addr,
            alloc_args_size,
            alloc_args_flags,
            handle,
            mmap_offset,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdAllocMemoryResultBindingEntry {
    pub slot: usize,
    pub tensor: TensorRef,
    pub class: TensorBindingClass,
    pub lifetime_access: TensorBindingAccess,
    pub allocation_kind: RuntimeSlotKfdAllocationKind,
    pub allocation_gpu_id: u32,
    pub alloc_args_va_addr: u64,
    pub alloc_args_size: u64,
    pub requested_alloc_args_flags: u32,
    pub fallback_alloc_args_flags: Option<u32>,
    pub result_alloc_args_flags: u32,
    pub result_uses_primary_flags: bool,
    pub result_uses_fallback_flags: bool,
    pub handle: u64,
    pub mmap_offset: u64,
    pub storage_bytes: usize,
    pub requested_bytes: usize,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub result_binding_present: bool,
    pub handle_bound: bool,
    pub mmap_offset_bound: bool,
    pub allocation_performed: bool,
    pub result_metadata_ready: bool,
    pub issue_count: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdAllocMemoryResultBindingIssue {
    pub slot: Option<usize>,
    pub tensor: Option<TensorRef>,
    pub message: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeKfdAllocMemoryResultBindingPlan {
    pub target: &'static str,
    pub result_source: &'static str,
    pub kfd_device_path: &'static str,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub slot_count: usize,
    pub allocation_request_count: usize,
    pub result_binding_count: usize,
    pub matched_result_binding_count: usize,
    pub missing_result_binding_count: usize,
    pub duplicate_result_binding_count: usize,
    pub unmatched_result_binding_count: usize,
    pub handle_bound_count: usize,
    pub mmap_offset_bound_count: usize,
    pub allocation_performed_count: usize,
    pub primary_flag_result_count: usize,
    pub fallback_flag_result_count: usize,
    pub total_storage_bytes: usize,
    pub total_alloc_memory_bytes: usize,
    pub request_issue_count: usize,
    pub alloc_memory_request_metadata_ready: bool,
    pub all_result_bindings_ready: bool,
    pub allocation_performed: bool,
    pub live_execution_supported: bool,
    pub entries: Vec<RuntimeKfdAllocMemoryResultBindingEntry>,
    pub issues: Vec<RuntimeKfdAllocMemoryResultBindingIssue>,
}

impl ModelRuntimeKfdAllocMemoryResultBindingPlan {
    pub fn entry_for(&self, tensor: &str) -> Option<&RuntimeKfdAllocMemoryResultBindingEntry> {
        self.entries
            .iter()
            .find(|entry| entry.tensor.as_str() == tensor)
    }

    pub fn entry_for_slot(&self, slot: usize) -> Option<&RuntimeKfdAllocMemoryResultBindingEntry> {
        self.entries.iter().find(|entry| entry.slot == slot)
    }

    pub fn is_kfd_alloc_memory_result_bound(&self) -> bool {
        self.assert_kfd_alloc_memory_result_bound().is_ok()
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.result_source != MODEL_RUNTIME_KFD_ALLOC_MEMORY_RESULT_BINDING_SOURCE {
            issues.push(format!(
                "result source {} != {}",
                self.result_source, MODEL_RUNTIME_KFD_ALLOC_MEMORY_RESULT_BINDING_SOURCE
            ));
        }
        if self.kfd_device_path != mainarch_sys::KFD_DEVICE {
            issues.push(format!(
                "KFD device path {} != {}",
                self.kfd_device_path,
                mainarch_sys::KFD_DEVICE
            ));
        }
        if self.entries.len() != self.allocation_request_count {
            issues.push(format!(
                "entry count {} != allocation request count {}",
                self.entries.len(),
                self.allocation_request_count
            ));
        }
        let resident_gpu_ids = self
            .resident_gpu_ids
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if resident_gpu_ids.len() != self.resident_gpu_ids.len() {
            issues.push("resident GPU IDs contain duplicates".to_string());
        }
        let canonical_resident_gpu_ids = resident_gpu_ids.iter().copied().collect::<Vec<_>>();
        if canonical_resident_gpu_ids != self.resident_gpu_ids {
            issues.push("resident GPU IDs are not sorted and unique".to_string());
        }
        if self.resident_gpu_id_count != self.resident_gpu_ids.len() {
            issues.push(format!(
                "resident GPU ID count {} != IDs {}",
                self.resident_gpu_id_count,
                self.resident_gpu_ids.len()
            ));
        }
        if self.request_issue_count != self.issues.len() {
            issues.push(format!(
                "request issue count {} != issue rows {}",
                self.request_issue_count,
                self.issues.len()
            ));
        }
        match self
            .matched_result_binding_count
            .checked_add(self.duplicate_result_binding_count)
            .and_then(|count| count.checked_add(self.unmatched_result_binding_count))
        {
            Some(expected) if expected == self.result_binding_count => {}
            Some(expected) => issues.push(format!(
                "result binding accounting {} != raw binding count {}",
                expected, self.result_binding_count
            )),
            None => issues.push("result binding accounting overflows".to_string()),
        }

        let mut seen_slots = BTreeSet::new();
        let mut matched_result_binding_count = 0usize;
        let mut missing_result_binding_count = 0usize;
        let mut handle_bound_count = 0usize;
        let mut mmap_offset_bound_count = 0usize;
        let mut allocation_performed_count = 0usize;
        let mut primary_flag_result_count = 0usize;
        let mut fallback_flag_result_count = 0usize;
        let mut total_storage_bytes = 0usize;
        let mut total_alloc_memory_bytes = 0usize;
        let mut entry_issue_count = 0usize;
        let mut entries_ready = true;

        for entry in &self.entries {
            if !seen_slots.insert(entry.slot) {
                issues.push(format!("slot {} appears more than once", entry.slot));
            }
            if entry.tensor.as_str().trim().is_empty() {
                issues.push(format!("slot {} has empty tensor name", entry.slot));
            }
            if entry.resident_gpu_ids != self.resident_gpu_ids {
                issues.push(format!(
                    "slot {} {} resident GPU IDs do not match plan",
                    entry.slot, entry.tensor
                ));
            }
            if entry.resident_gpu_id_count != entry.resident_gpu_ids.len() {
                issues.push(format!(
                    "slot {} {} resident GPU ID count {} != IDs {}",
                    entry.slot,
                    entry.tensor,
                    entry.resident_gpu_id_count,
                    entry.resident_gpu_ids.len()
                ));
            }
            if entry.alloc_args_size != entry.requested_bytes as u64 {
                issues.push(format!(
                    "slot {} {} alloc args size {} != requested bytes {}",
                    entry.slot, entry.tensor, entry.alloc_args_size, entry.requested_bytes
                ));
            }
            if entry.alloc_args_size < entry.storage_bytes as u64 {
                issues.push(format!(
                    "slot {} {} alloc args size {} < storage bytes {}",
                    entry.slot, entry.tensor, entry.alloc_args_size, entry.storage_bytes
                ));
            }
            if entry.requested_alloc_args_flags != entry.allocation_kind.primary_alloc_flags() {
                issues.push(format!(
                    "slot {} {} requested flags 0x{:08x} != primary flags 0x{:08x}",
                    entry.slot,
                    entry.tensor,
                    entry.requested_alloc_args_flags,
                    entry.allocation_kind.primary_alloc_flags()
                ));
            }
            if entry.fallback_alloc_args_flags != entry.allocation_kind.fallback_alloc_flags() {
                issues.push(format!(
                    "slot {} {} fallback flags {:?} != expected {:?}",
                    entry.slot,
                    entry.tensor,
                    entry.fallback_alloc_args_flags,
                    entry.allocation_kind.fallback_alloc_flags()
                ));
            }
            let result_flags_match_primary = entry.result_binding_present
                && entry.result_alloc_args_flags == entry.requested_alloc_args_flags;
            let result_flags_match_fallback =
                entry.fallback_alloc_args_flags.is_some_and(|fallback| {
                    entry.result_binding_present && entry.result_alloc_args_flags == fallback
                });
            if entry.result_uses_primary_flags != result_flags_match_primary {
                issues.push(format!(
                    "slot {} {} result_uses_primary_flags {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.result_uses_primary_flags,
                    result_flags_match_primary
                ));
            }
            if entry.result_uses_fallback_flags != result_flags_match_fallback {
                issues.push(format!(
                    "slot {} {} result_uses_fallback_flags {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.result_uses_fallback_flags,
                    result_flags_match_fallback
                ));
            }
            if entry.result_binding_present {
                matched_result_binding_count += 1;
            } else {
                missing_result_binding_count += 1;
            }
            if entry.handle_bound {
                handle_bound_count += 1;
            }
            if entry.mmap_offset_bound {
                mmap_offset_bound_count += 1;
            }
            if entry.allocation_performed {
                allocation_performed_count += 1;
            }
            if entry.result_uses_primary_flags {
                primary_flag_result_count += 1;
            }
            if entry.result_uses_fallback_flags {
                fallback_flag_result_count += 1;
            }
            if entry.handle_bound != (entry.handle != 0) {
                issues.push(format!(
                    "slot {} {} handle_bound {} != handle nonzero {}",
                    entry.slot,
                    entry.tensor,
                    entry.handle_bound,
                    entry.handle != 0
                ));
            }
            if entry.mmap_offset_bound != entry.result_binding_present {
                issues.push(format!(
                    "slot {} {} mmap_offset_bound {} != result binding present {}",
                    entry.slot, entry.tensor, entry.mmap_offset_bound, entry.result_binding_present
                ));
            }
            let expected_allocation_performed = entry.result_binding_present && entry.handle_bound;
            if entry.allocation_performed != expected_allocation_performed {
                issues.push(format!(
                    "slot {} {} allocation_performed {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.allocation_performed,
                    expected_allocation_performed
                ));
            }
            let expected_result_ready = self.alloc_memory_request_metadata_ready
                && entry.result_binding_present
                && entry.handle_bound
                && (entry.result_uses_primary_flags || entry.result_uses_fallback_flags)
                && entry.issue_count == 0;
            if entry.result_metadata_ready != expected_result_ready {
                issues.push(format!(
                    "slot {} {} result_metadata_ready {} != expected {}",
                    entry.slot, entry.tensor, entry.result_metadata_ready, expected_result_ready
                ));
            }
            if !entry.result_metadata_ready {
                entries_ready = false;
            }
            total_storage_bytes = checked_add_usize(
                total_storage_bytes,
                entry.storage_bytes,
                "KFD alloc-memory result storage bytes",
            )?;
            total_alloc_memory_bytes = checked_add_usize(
                total_alloc_memory_bytes,
                entry.requested_bytes,
                "KFD alloc-memory result bytes",
            )?;
            entry_issue_count = checked_add_usize(
                entry_issue_count,
                entry.issue_count,
                "KFD alloc-memory result entry issues",
            )?;
        }

        if matched_result_binding_count != self.matched_result_binding_count {
            issues.push(format!(
                "matched result binding count {matched_result_binding_count} != plan {}",
                self.matched_result_binding_count
            ));
        }
        if missing_result_binding_count != self.missing_result_binding_count {
            issues.push(format!(
                "missing result binding count {missing_result_binding_count} != plan {}",
                self.missing_result_binding_count
            ));
        }
        if handle_bound_count != self.handle_bound_count {
            issues.push(format!(
                "handle bound count {handle_bound_count} != plan {}",
                self.handle_bound_count
            ));
        }
        if mmap_offset_bound_count != self.mmap_offset_bound_count {
            issues.push(format!(
                "mmap offset bound count {mmap_offset_bound_count} != plan {}",
                self.mmap_offset_bound_count
            ));
        }
        if allocation_performed_count != self.allocation_performed_count {
            issues.push(format!(
                "allocation performed count {allocation_performed_count} != plan {}",
                self.allocation_performed_count
            ));
        }
        if primary_flag_result_count != self.primary_flag_result_count {
            issues.push(format!(
                "primary flag result count {primary_flag_result_count} != plan {}",
                self.primary_flag_result_count
            ));
        }
        if fallback_flag_result_count != self.fallback_flag_result_count {
            issues.push(format!(
                "fallback flag result count {fallback_flag_result_count} != plan {}",
                self.fallback_flag_result_count
            ));
        }
        if total_storage_bytes != self.total_storage_bytes {
            issues.push(format!(
                "total storage bytes {total_storage_bytes} != plan {}",
                self.total_storage_bytes
            ));
        }
        if total_alloc_memory_bytes != self.total_alloc_memory_bytes {
            issues.push(format!(
                "total alloc-memory bytes {total_alloc_memory_bytes} != plan {}",
                self.total_alloc_memory_bytes
            ));
        }
        let slot_issue_rows = self
            .issues
            .iter()
            .filter(|issue| issue.slot.is_some())
            .count();
        let accounted_slot_issues = entry_issue_count
            .checked_add(self.duplicate_result_binding_count)
            .and_then(|count| count.checked_add(self.unmatched_result_binding_count))
            .ok_or_else(|| anyhow!("KFD alloc-memory result issue count overflows"))?;
        if accounted_slot_issues != slot_issue_rows {
            issues.push(format!(
                "accounted slot issue count {accounted_slot_issues} != slot issue rows {slot_issue_rows}"
            ));
        }
        let expected_allocation_performed = self.allocation_request_count > 0
            && self.allocation_performed_count == self.allocation_request_count;
        if self.allocation_performed != expected_allocation_performed {
            issues.push(format!(
                "allocation_performed {} != expected {}",
                self.allocation_performed, expected_allocation_performed
            ));
        }
        let expected_all_result_bindings_ready = self.alloc_memory_request_metadata_ready
            && self.allocation_request_count > 0
            && self.matched_result_binding_count == self.allocation_request_count
            && self.missing_result_binding_count == 0
            && self.duplicate_result_binding_count == 0
            && self.unmatched_result_binding_count == 0
            && self.request_issue_count == 0
            && entries_ready;
        if self.all_result_bindings_ready != expected_all_result_bindings_ready {
            issues.push(format!(
                "all_result_bindings_ready {} != expected {}",
                self.all_result_bindings_ready, expected_all_result_bindings_ready
            ));
        }
        if self.live_execution_supported != MODEL_API_CONTRACT.live_execution_supported {
            issues.push(format!(
                "live execution support {} != contract {}",
                self.live_execution_supported, MODEL_API_CONTRACT.live_execution_supported
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD alloc-memory result binding plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn assert_kfd_alloc_memory_result_bound(&self) -> Result<()> {
        let mut issues = Vec::new();
        if let Err(err) = self.assert_consistent() {
            issues.push(format!("consistency: {err}"));
        }
        if !self.alloc_memory_request_metadata_ready {
            issues.push("KFD alloc-memory request metadata is not ready".to_string());
        }
        if self.allocation_request_count == 0 {
            issues.push("no KFD alloc-memory requests available for result binding".to_string());
        }
        if self.missing_result_binding_count > 0 {
            issues.push(format!(
                "missing result bindings: {}",
                self.missing_result_binding_count
            ));
        }
        if self.duplicate_result_binding_count > 0 {
            issues.push(format!(
                "duplicate result bindings: {}",
                self.duplicate_result_binding_count
            ));
        }
        if self.unmatched_result_binding_count > 0 {
            issues.push(format!(
                "unmatched result bindings: {}",
                self.unmatched_result_binding_count
            ));
        }
        if self.handle_bound_count != self.allocation_request_count {
            issues.push("allocation handles are not bound for every request".to_string());
        }
        if self.allocation_performed_count != self.allocation_request_count {
            issues.push("allocation results do not cover every request".to_string());
        }
        if self.request_issue_count > 0 {
            issues.push(format!("request issues: {}", self.request_issue_count));
        }
        if !self.all_result_bindings_ready {
            issues.push("not all alloc-memory result bindings are ready".to_string());
        }
        if self.live_execution_supported {
            issues.push("live execution support is unexpectedly enabled".to_string());
        }
        let issue_details = self
            .issues
            .iter()
            .map(runtime_kfd_alloc_memory_result_binding_issue_label)
            .collect::<Vec<_>>();
        if !issue_details.is_empty() {
            issues.push(issue_details.join("; "));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD alloc-memory result binding plan for {} is not ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn runtime_kfd_alloc_memory_result_binding_issue_label(
    issue: &RuntimeKfdAllocMemoryResultBindingIssue,
) -> String {
    match (&issue.slot, &issue.tensor) {
        (Some(slot), Some(tensor)) => format!("slot {slot} {tensor}: {}", issue.message),
        (Some(slot), None) => format!("slot {slot}: {}", issue.message),
        (None, Some(tensor)) => format!("{tensor}: {}", issue.message),
        (None, None) => issue.message.clone(),
    }
}

fn runtime_kfd_alloc_memory_result_binding_plan_from(
    alloc_memory_requests: &ModelRuntimeKfdAllocMemoryRequestPlan,
    result_bindings: &[RuntimeKfdAllocMemoryResultBinding],
) -> ModelRuntimeKfdAllocMemoryResultBindingPlan {
    let mut issues = Vec::new();
    let alloc_memory_request_metadata_ready =
        match alloc_memory_requests.assert_kfd_alloc_memory_request_ready() {
            Ok(()) => true,
            Err(err) => {
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: None,
                    tensor: None,
                    message: format!("KFD alloc-memory request plan is not ready: {err}"),
                });
                false
            }
        };

    let request_slots = alloc_memory_requests
        .entries
        .iter()
        .map(|entry| entry.slot)
        .collect::<BTreeSet<_>>();
    let mut result_by_slot = BTreeMap::new();
    let mut duplicate_result_binding_count = 0usize;
    let mut unmatched_result_binding_count = 0usize;

    for binding in result_bindings {
        if !request_slots.contains(&binding.slot) {
            unmatched_result_binding_count += 1;
            issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                slot: Some(binding.slot),
                tensor: Some(binding.tensor.clone()),
                message: "result binding does not match an alloc-memory request slot".to_string(),
            });
            continue;
        }
        if result_by_slot.insert(binding.slot, binding).is_some() {
            duplicate_result_binding_count += 1;
            issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                slot: Some(binding.slot),
                tensor: Some(binding.tensor.clone()),
                message: "duplicate alloc-memory result binding for slot".to_string(),
            });
        }
    }

    let mut entries = Vec::new();
    let mut matched_result_binding_count = 0usize;
    let mut missing_result_binding_count = 0usize;
    let mut handle_bound_count = 0usize;
    let mut mmap_offset_bound_count = 0usize;
    let mut allocation_performed_count = 0usize;
    let mut primary_flag_result_count = 0usize;
    let mut fallback_flag_result_count = 0usize;
    let mut total_storage_bytes = 0usize;
    let mut total_alloc_memory_bytes = 0usize;

    for request in &alloc_memory_requests.entries {
        let mut entry_issue_count = 0usize;
        let result = result_by_slot.get(&request.slot).copied();
        if !request.request_metadata_ready {
            entry_issue_count += 1;
            issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                slot: Some(request.slot),
                tensor: Some(request.tensor.clone()),
                message: "alloc-memory request metadata is not ready".to_string(),
            });
        }

        let (
            result_binding_present,
            result_gpu_id,
            result_va,
            result_size,
            result_flags,
            handle,
            mmap_offset,
        ) = match result {
            Some(binding) => {
                matched_result_binding_count += 1;
                (
                    true,
                    binding.allocation_gpu_id,
                    binding.alloc_args_va_addr,
                    binding.alloc_args_size,
                    binding.alloc_args_flags,
                    binding.handle,
                    binding.mmap_offset,
                )
            }
            None => {
                missing_result_binding_count += 1;
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "missing alloc-memory result binding".to_string(),
                });
                (
                    false,
                    request.allocation_gpu_id,
                    request.alloc_args_va_addr,
                    request.alloc_args_size,
                    request.alloc_args_flags,
                    0,
                    0,
                )
            }
        };

        if let Some(binding) = result {
            if binding.tensor != request.tensor {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "result tensor {} != request tensor {}",
                        binding.tensor, request.tensor
                    ),
                });
            }
            if binding.allocation_gpu_id != request.allocation_gpu_id {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "result GPU ID {} != request GPU ID {}",
                        binding.allocation_gpu_id, request.allocation_gpu_id
                    ),
                });
            }
            if binding.alloc_args_va_addr != request.alloc_args_va_addr {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "result VA 0x{:x} != request VA 0x{:x}",
                        binding.alloc_args_va_addr, request.alloc_args_va_addr
                    ),
                });
            }
            if binding.alloc_args_size != request.alloc_args_size {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "result size {} != request size {}",
                        binding.alloc_args_size, request.alloc_args_size
                    ),
                });
            }
            let result_uses_primary_flags = binding.alloc_args_flags == request.alloc_args_flags;
            let result_uses_fallback_flags = request
                .fallback_alloc_args_flags
                .is_some_and(|fallback| binding.alloc_args_flags == fallback);
            if !result_uses_primary_flags && !result_uses_fallback_flags {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "result flags 0x{:08x} match neither primary 0x{:08x} nor fallback {:?}",
                        binding.alloc_args_flags,
                        request.alloc_args_flags,
                        request.fallback_alloc_args_flags
                    ),
                });
            }
            if binding.handle == 0 {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "result binding has empty allocation handle".to_string(),
                });
            }
        }

        let result_uses_primary_flags =
            result_binding_present && result_flags == request.alloc_args_flags;
        let result_uses_fallback_flags = request
            .fallback_alloc_args_flags
            .is_some_and(|fallback| result_binding_present && result_flags == fallback);
        if result_uses_primary_flags {
            primary_flag_result_count += 1;
        }
        if result_uses_fallback_flags {
            fallback_flag_result_count += 1;
        }
        let handle_bound = handle != 0;
        if handle_bound {
            handle_bound_count += 1;
        }
        let mmap_offset_bound = result_binding_present;
        if mmap_offset_bound {
            mmap_offset_bound_count += 1;
        }
        let allocation_performed = result_binding_present && handle_bound;
        if allocation_performed {
            allocation_performed_count += 1;
        }
        match total_storage_bytes.checked_add(request.storage_bytes) {
            Some(total) => total_storage_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "total storage bytes overflow".to_string(),
                });
            }
        }
        match total_alloc_memory_bytes.checked_add(request.requested_bytes) {
            Some(total) => total_alloc_memory_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdAllocMemoryResultBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "total alloc-memory bytes overflow".to_string(),
                });
            }
        }
        let result_metadata_ready = alloc_memory_request_metadata_ready
            && result_binding_present
            && handle_bound
            && (result_uses_primary_flags || result_uses_fallback_flags)
            && entry_issue_count == 0;

        entries.push(RuntimeKfdAllocMemoryResultBindingEntry {
            slot: request.slot,
            tensor: request.tensor.clone(),
            class: request.class,
            lifetime_access: request.lifetime_access,
            allocation_kind: request.allocation_kind,
            allocation_gpu_id: result_gpu_id,
            alloc_args_va_addr: result_va,
            alloc_args_size: result_size,
            requested_alloc_args_flags: request.alloc_args_flags,
            fallback_alloc_args_flags: request.fallback_alloc_args_flags,
            result_alloc_args_flags: result_flags,
            result_uses_primary_flags,
            result_uses_fallback_flags,
            handle,
            mmap_offset,
            storage_bytes: request.storage_bytes,
            requested_bytes: request.requested_bytes,
            resident_gpu_ids: request.resident_gpu_ids.clone(),
            resident_gpu_id_count: request.resident_gpu_id_count,
            result_binding_present,
            handle_bound,
            mmap_offset_bound,
            allocation_performed,
            result_metadata_ready,
            issue_count: entry_issue_count,
        });
    }

    let allocation_request_count = alloc_memory_requests.allocation_request_count;
    let request_issue_count = issues.len();
    let all_result_bindings_ready = alloc_memory_request_metadata_ready
        && allocation_request_count > 0
        && matched_result_binding_count == allocation_request_count
        && missing_result_binding_count == 0
        && duplicate_result_binding_count == 0
        && unmatched_result_binding_count == 0
        && request_issue_count == 0
        && entries
            .iter()
            .all(|entry| entry.result_metadata_ready && entry.issue_count == 0);
    let allocation_performed =
        allocation_request_count > 0 && allocation_performed_count == allocation_request_count;

    ModelRuntimeKfdAllocMemoryResultBindingPlan {
        target: alloc_memory_requests.target,
        result_source: MODEL_RUNTIME_KFD_ALLOC_MEMORY_RESULT_BINDING_SOURCE,
        kfd_device_path: mainarch_sys::KFD_DEVICE,
        resident_gpu_ids: alloc_memory_requests.resident_gpu_ids.clone(),
        resident_gpu_id_count: alloc_memory_requests.resident_gpu_id_count,
        slot_count: alloc_memory_requests.slot_count,
        allocation_request_count,
        result_binding_count: result_bindings.len(),
        matched_result_binding_count,
        missing_result_binding_count,
        duplicate_result_binding_count,
        unmatched_result_binding_count,
        handle_bound_count,
        mmap_offset_bound_count,
        allocation_performed_count,
        primary_flag_result_count,
        fallback_flag_result_count,
        total_storage_bytes,
        total_alloc_memory_bytes,
        request_issue_count,
        alloc_memory_request_metadata_ready,
        all_result_bindings_ready,
        allocation_performed,
        live_execution_supported: MODEL_API_CONTRACT.live_execution_supported,
        entries,
        issues,
    }
}

const MODEL_RUNTIME_KFD_MAP_MEMORY_REQUEST_SOURCE: &str = "mainarch_kfd_map_memory_request_v0";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdMapMemoryRequestEntry {
    pub slot: usize,
    pub tensor: TensorRef,
    pub class: TensorBindingClass,
    pub lifetime_access: TensorBindingAccess,
    pub allocation_kind: RuntimeSlotKfdAllocationKind,
    pub allocation_gpu_id: u32,
    pub map_memory_ioctl: u64,
    pub map_args_handle: u64,
    pub map_args_device_ids_array_ptr: u64,
    pub map_args_n_devices: u32,
    pub map_args_n_success: u32,
    pub storage_bytes: usize,
    pub requested_bytes: usize,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub kfd_fd_required: bool,
    pub kfd_fd_bound: bool,
    pub vm_acquire_required: bool,
    pub vm_acquire_performed: bool,
    pub allocation_required: bool,
    pub allocation_performed: bool,
    pub handle_required: bool,
    pub handle_bound: bool,
    pub device_ids_array_required: bool,
    pub device_ids_array_bound: bool,
    pub map_to_gpu_required: bool,
    pub map_memory_performed: bool,
    pub request_static_metadata_ready: bool,
    pub request_args_ready: bool,
    pub issue_count: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdMapMemoryRequestIssue {
    pub slot: Option<usize>,
    pub tensor: Option<TensorRef>,
    pub message: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeKfdMapMemoryRequestPlan {
    pub target: &'static str,
    pub request_source: &'static str,
    pub kfd_device_path: &'static str,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub slot_count: usize,
    pub map_memory_request_count: usize,
    pub map_to_gpu_required_count: usize,
    pub host_visible_gtt_request_count: usize,
    pub device_local_vram_request_count: usize,
    pub total_storage_bytes: usize,
    pub total_map_memory_bytes: usize,
    pub total_device_id_count: usize,
    pub kfd_fd_bound_count: usize,
    pub vm_acquire_performed_count: usize,
    pub allocation_performed_count: usize,
    pub handle_bound_count: usize,
    pub device_ids_array_bound_count: usize,
    pub map_memory_performed_count: usize,
    pub map_memory_success_count: usize,
    pub request_issue_count: usize,
    pub alloc_memory_request_metadata_ready: bool,
    pub all_static_request_metadata_ready: bool,
    pub all_live_request_args_bound: bool,
    pub all_request_args_ready: bool,
    pub map_memory_performed: bool,
    pub live_execution_supported: bool,
    pub entries: Vec<RuntimeKfdMapMemoryRequestEntry>,
    pub issues: Vec<RuntimeKfdMapMemoryRequestIssue>,
}

impl ModelRuntimeKfdMapMemoryRequestPlan {
    pub fn entry_for(&self, tensor: &str) -> Option<&RuntimeKfdMapMemoryRequestEntry> {
        self.entries
            .iter()
            .find(|entry| entry.tensor.as_str() == tensor)
    }

    pub fn entry_for_slot(&self, slot: usize) -> Option<&RuntimeKfdMapMemoryRequestEntry> {
        self.entries.iter().find(|entry| entry.slot == slot)
    }

    pub fn is_kfd_map_memory_request_ready(&self) -> bool {
        self.assert_kfd_map_memory_request_ready().is_ok()
    }

    pub fn kfd_map_memory_argument_binding_plan(
        &self,
        alloc_memory_results: &ModelRuntimeKfdAllocMemoryResultBindingPlan,
        device_ids_array_bindings: &[RuntimeKfdMapMemoryDeviceIdsArrayBinding],
    ) -> ModelRuntimeKfdMapMemoryArgumentBindingPlan {
        runtime_kfd_map_memory_argument_binding_plan_from(
            self,
            alloc_memory_results,
            device_ids_array_bindings,
        )
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.request_source != MODEL_RUNTIME_KFD_MAP_MEMORY_REQUEST_SOURCE {
            issues.push(format!(
                "request source {} != {}",
                self.request_source, MODEL_RUNTIME_KFD_MAP_MEMORY_REQUEST_SOURCE
            ));
        }
        if self.kfd_device_path != mainarch_sys::KFD_DEVICE {
            issues.push(format!(
                "KFD device path {} != {}",
                self.kfd_device_path,
                mainarch_sys::KFD_DEVICE
            ));
        }
        if self.entries.len() != self.map_memory_request_count {
            issues.push(format!(
                "entry count {} != map-memory request count {}",
                self.entries.len(),
                self.map_memory_request_count
            ));
        }
        let resident_gpu_ids = self
            .resident_gpu_ids
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if resident_gpu_ids.len() != self.resident_gpu_ids.len() {
            issues.push("resident GPU IDs contain duplicates".to_string());
        }
        let canonical_resident_gpu_ids = resident_gpu_ids.iter().copied().collect::<Vec<_>>();
        if canonical_resident_gpu_ids != self.resident_gpu_ids {
            issues.push("resident GPU IDs are not sorted and unique".to_string());
        }
        if self.resident_gpu_id_count != self.resident_gpu_ids.len() {
            issues.push(format!(
                "resident GPU ID count {} != IDs {}",
                self.resident_gpu_id_count,
                self.resident_gpu_ids.len()
            ));
        }
        if self.request_issue_count != self.issues.len() {
            issues.push(format!(
                "request issue count {} != issue rows {}",
                self.request_issue_count,
                self.issues.len()
            ));
        }
        if self.map_memory_performed_count != 0 {
            issues.push(format!(
                "map-memory performed count {} != 0",
                self.map_memory_performed_count
            ));
        }
        if self.map_memory_success_count != 0 {
            issues.push(format!(
                "map-memory success count {} != 0",
                self.map_memory_success_count
            ));
        }

        let mut seen_slots = BTreeSet::new();
        let mut map_to_gpu_required_count = 0usize;
        let mut host_visible_gtt_request_count = 0usize;
        let mut device_local_vram_request_count = 0usize;
        let mut total_storage_bytes = 0usize;
        let mut total_map_memory_bytes = 0usize;
        let mut total_device_id_count = 0usize;
        let mut kfd_fd_bound_count = 0usize;
        let mut vm_acquire_performed_count = 0usize;
        let mut allocation_performed_count = 0usize;
        let mut handle_bound_count = 0usize;
        let mut device_ids_array_bound_count = 0usize;
        let mut map_memory_performed_count = 0usize;
        let mut map_memory_success_count = 0usize;
        let mut entry_issue_count = 0usize;
        let mut entries_static_ready = true;
        let mut entries_args_ready = true;

        for entry in &self.entries {
            if !seen_slots.insert(entry.slot) {
                issues.push(format!("slot {} appears more than once", entry.slot));
            }
            if entry.tensor.as_str().trim().is_empty() {
                issues.push(format!("slot {} has empty tensor name", entry.slot));
            }
            match entry.allocation_kind {
                RuntimeSlotKfdAllocationKind::HostVisibleGtt => {
                    host_visible_gtt_request_count += 1;
                }
                RuntimeSlotKfdAllocationKind::DeviceLocalVramPreferPublicCoherent => {
                    device_local_vram_request_count += 1;
                }
            }
            if entry.map_memory_ioctl != mainarch_sys::ioc_map_memory_to_gpu() as u64 {
                issues.push(format!(
                    "slot {} {} map-memory ioctl 0x{:x} != expected 0x{:x}",
                    entry.slot,
                    entry.tensor,
                    entry.map_memory_ioctl,
                    mainarch_sys::ioc_map_memory_to_gpu() as u64
                ));
            }
            if entry.resident_gpu_ids != self.resident_gpu_ids {
                issues.push(format!(
                    "slot {} {} resident GPU IDs do not match plan",
                    entry.slot, entry.tensor
                ));
            }
            if entry.resident_gpu_id_count != entry.resident_gpu_ids.len() {
                issues.push(format!(
                    "slot {} {} resident GPU ID count {} != IDs {}",
                    entry.slot,
                    entry.tensor,
                    entry.resident_gpu_id_count,
                    entry.resident_gpu_ids.len()
                ));
            }
            match u32::try_from(entry.resident_gpu_id_count) {
                Ok(expected) if entry.map_args_n_devices == expected => {}
                Ok(expected) => issues.push(format!(
                    "slot {} {} map args n_devices {} != resident GPU ID count {}",
                    entry.slot, entry.tensor, entry.map_args_n_devices, expected
                )),
                Err(_) => issues.push(format!(
                    "slot {} {} resident GPU ID count {} exceeds u32",
                    entry.slot, entry.tensor, entry.resident_gpu_id_count
                )),
            }
            if entry.map_args_n_success != 0 {
                issues.push(format!(
                    "slot {} {} map args n_success {} != 0",
                    entry.slot, entry.tensor, entry.map_args_n_success
                ));
            }
            if !entry.kfd_fd_required {
                issues.push(format!(
                    "slot {} {} does not require a KFD fd",
                    entry.slot, entry.tensor
                ));
            }
            if entry.kfd_fd_bound {
                kfd_fd_bound_count += 1;
            }
            let resident_ids_present = entry.resident_gpu_id_count > 0;
            if entry.vm_acquire_required != resident_ids_present {
                issues.push(format!(
                    "slot {} {} VM-acquire requirement {} != resident IDs present {}",
                    entry.slot, entry.tensor, entry.vm_acquire_required, resident_ids_present
                ));
            }
            if entry.vm_acquire_performed {
                vm_acquire_performed_count += 1;
            }
            if !entry.allocation_required {
                issues.push(format!(
                    "slot {} {} does not require allocation",
                    entry.slot, entry.tensor
                ));
            }
            if entry.allocation_performed {
                allocation_performed_count += 1;
            }
            if entry.map_to_gpu_required {
                map_to_gpu_required_count += 1;
            } else if resident_ids_present {
                issues.push(format!(
                    "slot {} {} does not request map-to-GPU despite resident GPU IDs",
                    entry.slot, entry.tensor
                ));
            }
            if entry.handle_required != entry.map_to_gpu_required {
                issues.push(format!(
                    "slot {} {} handle requirement {} != map-to-GPU requirement {}",
                    entry.slot, entry.tensor, entry.handle_required, entry.map_to_gpu_required
                ));
            }
            if entry.handle_bound {
                handle_bound_count += 1;
            }
            if entry.handle_bound && entry.map_args_handle == 0 {
                issues.push(format!(
                    "slot {} {} has a bound allocation handle but map args handle is zero",
                    entry.slot, entry.tensor
                ));
            }
            if !entry.handle_bound && entry.map_args_handle != 0 {
                issues.push(format!(
                    "slot {} {} has an unbound allocation handle but map args handle is {}",
                    entry.slot, entry.tensor, entry.map_args_handle
                ));
            }
            if entry.device_ids_array_required != entry.map_to_gpu_required {
                issues.push(format!(
                    "slot {} {} device ID array requirement {} != map-to-GPU requirement {}",
                    entry.slot,
                    entry.tensor,
                    entry.device_ids_array_required,
                    entry.map_to_gpu_required
                ));
            }
            if entry.device_ids_array_bound {
                device_ids_array_bound_count += 1;
            }
            if entry.device_ids_array_bound && entry.map_args_device_ids_array_ptr == 0 {
                issues.push(format!(
                    "slot {} {} has a bound device ID array but map args pointer is zero",
                    entry.slot, entry.tensor
                ));
            }
            if !entry.device_ids_array_bound && entry.map_args_device_ids_array_ptr != 0 {
                issues.push(format!(
                    "slot {} {} has an unbound device ID array but map args pointer is 0x{:x}",
                    entry.slot, entry.tensor, entry.map_args_device_ids_array_ptr
                ));
            }
            if entry.map_memory_performed {
                map_memory_performed_count += 1;
                issues.push(format!(
                    "slot {} {} unexpectedly reports map-memory performed",
                    entry.slot, entry.tensor
                ));
            }
            map_memory_success_count = checked_add_usize(
                map_memory_success_count,
                entry.map_args_n_success as usize,
                "KFD map-memory success count",
            )?;
            let expected_static_ready =
                self.alloc_memory_request_metadata_ready && entry.issue_count == 0;
            if entry.request_static_metadata_ready != expected_static_ready {
                issues.push(format!(
                    "slot {} {} request_static_metadata_ready {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.request_static_metadata_ready,
                    expected_static_ready
                ));
            }
            let expected_args_ready = entry.request_static_metadata_ready
                && entry.kfd_fd_bound
                && entry.vm_acquire_performed
                && entry.allocation_performed
                && entry.handle_required
                && entry.handle_bound
                && entry.map_args_handle != 0
                && entry.device_ids_array_required
                && entry.device_ids_array_bound
                && entry.map_args_device_ids_array_ptr != 0
                && entry.map_args_n_devices == entry.resident_gpu_id_count as u32
                && entry.map_args_n_success == 0
                && !entry.map_memory_performed;
            if entry.request_args_ready != expected_args_ready {
                issues.push(format!(
                    "slot {} {} request_args_ready {} != expected {}",
                    entry.slot, entry.tensor, entry.request_args_ready, expected_args_ready
                ));
            }
            if !entry.request_static_metadata_ready {
                entries_static_ready = false;
            }
            if !entry.request_args_ready {
                entries_args_ready = false;
            }
            total_storage_bytes = checked_add_usize(
                total_storage_bytes,
                entry.storage_bytes,
                "KFD map-memory storage bytes",
            )?;
            total_map_memory_bytes = checked_add_usize(
                total_map_memory_bytes,
                entry.requested_bytes,
                "KFD map-memory bytes",
            )?;
            total_device_id_count = checked_add_usize(
                total_device_id_count,
                entry.resident_gpu_id_count,
                "KFD map-memory device ID count",
            )?;
            entry_issue_count = checked_add_usize(
                entry_issue_count,
                entry.issue_count,
                "KFD map-memory request entry issues",
            )?;
        }

        if map_to_gpu_required_count != self.map_to_gpu_required_count {
            issues.push(format!(
                "map-to-GPU required count {map_to_gpu_required_count} != plan {}",
                self.map_to_gpu_required_count
            ));
        }
        if host_visible_gtt_request_count != self.host_visible_gtt_request_count {
            issues.push(format!(
                "host-visible GTT request count {host_visible_gtt_request_count} != plan {}",
                self.host_visible_gtt_request_count
            ));
        }
        if device_local_vram_request_count != self.device_local_vram_request_count {
            issues.push(format!(
                "device-local VRAM request count {device_local_vram_request_count} != plan {}",
                self.device_local_vram_request_count
            ));
        }
        if total_storage_bytes != self.total_storage_bytes {
            issues.push(format!(
                "total storage bytes {total_storage_bytes} != plan {}",
                self.total_storage_bytes
            ));
        }
        if total_map_memory_bytes != self.total_map_memory_bytes {
            issues.push(format!(
                "total map-memory bytes {total_map_memory_bytes} != plan {}",
                self.total_map_memory_bytes
            ));
        }
        if total_device_id_count != self.total_device_id_count {
            issues.push(format!(
                "total device ID count {total_device_id_count} != plan {}",
                self.total_device_id_count
            ));
        }
        if kfd_fd_bound_count != self.kfd_fd_bound_count {
            issues.push(format!(
                "KFD fd bound count {kfd_fd_bound_count} != plan {}",
                self.kfd_fd_bound_count
            ));
        }
        if vm_acquire_performed_count != self.vm_acquire_performed_count {
            issues.push(format!(
                "VM acquire performed count {vm_acquire_performed_count} != plan {}",
                self.vm_acquire_performed_count
            ));
        }
        if allocation_performed_count != self.allocation_performed_count {
            issues.push(format!(
                "allocation performed count {allocation_performed_count} != plan {}",
                self.allocation_performed_count
            ));
        }
        if handle_bound_count != self.handle_bound_count {
            issues.push(format!(
                "handle bound count {handle_bound_count} != plan {}",
                self.handle_bound_count
            ));
        }
        if device_ids_array_bound_count != self.device_ids_array_bound_count {
            issues.push(format!(
                "device ID array bound count {device_ids_array_bound_count} != plan {}",
                self.device_ids_array_bound_count
            ));
        }
        if map_memory_performed_count != self.map_memory_performed_count {
            issues.push(format!(
                "map-memory performed count {map_memory_performed_count} != plan {}",
                self.map_memory_performed_count
            ));
        }
        if map_memory_success_count != self.map_memory_success_count {
            issues.push(format!(
                "map-memory success count {map_memory_success_count} != plan {}",
                self.map_memory_success_count
            ));
        }
        let slot_issue_rows = self
            .issues
            .iter()
            .filter(|issue| issue.slot.is_some())
            .count();
        if entry_issue_count != slot_issue_rows {
            issues.push(format!(
                "entry issue count {entry_issue_count} != slot issue rows {slot_issue_rows}"
            ));
        }
        let expected_all_static_request_metadata_ready = self.alloc_memory_request_metadata_ready
            && self.map_memory_request_count > 0
            && self.map_to_gpu_required_count == self.map_memory_request_count
            && self.request_issue_count == 0
            && entries_static_ready;
        if self.all_static_request_metadata_ready != expected_all_static_request_metadata_ready {
            issues.push(format!(
                "all_static_request_metadata_ready {} != expected {}",
                self.all_static_request_metadata_ready, expected_all_static_request_metadata_ready
            ));
        }
        let expected_all_live_request_args_bound = self.map_memory_request_count > 0
            && self.handle_bound_count == self.map_memory_request_count
            && self.device_ids_array_bound_count == self.map_memory_request_count;
        if self.all_live_request_args_bound != expected_all_live_request_args_bound {
            issues.push(format!(
                "all_live_request_args_bound {} != expected {}",
                self.all_live_request_args_bound, expected_all_live_request_args_bound
            ));
        }
        let expected_all_request_args_ready = self.all_static_request_metadata_ready
            && self.all_live_request_args_bound
            && self.request_issue_count == 0
            && entries_args_ready;
        if self.all_request_args_ready != expected_all_request_args_ready {
            issues.push(format!(
                "all_request_args_ready {} != expected {}",
                self.all_request_args_ready, expected_all_request_args_ready
            ));
        }
        if self.map_memory_performed {
            issues.push("KFD map-memory request plan unexpectedly mapped buffers".to_string());
        }
        if self.live_execution_supported != MODEL_API_CONTRACT.live_execution_supported {
            issues.push(format!(
                "live execution support {} != contract {}",
                self.live_execution_supported, MODEL_API_CONTRACT.live_execution_supported
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD map-memory request plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn assert_kfd_map_memory_request_ready(&self) -> Result<()> {
        let mut issues = Vec::new();
        if let Err(err) = self.assert_consistent() {
            issues.push(format!("consistency: {err}"));
        }
        if !self.alloc_memory_request_metadata_ready {
            issues.push("KFD alloc-memory request metadata is not ready".to_string());
        }
        if self.map_memory_request_count == 0 {
            issues.push("no KFD map-memory requests produced".to_string());
        }
        if self.request_issue_count > 0 {
            issues.push(format!("request issues: {}", self.request_issue_count));
        }
        if !self.all_static_request_metadata_ready {
            issues.push("not all map-memory static metadata is ready".to_string());
        }
        if self.kfd_fd_bound_count != self.map_memory_request_count {
            issues.push("KFD fds are not bound for every map-memory request".to_string());
        }
        if self.vm_acquire_performed_count != self.map_memory_request_count {
            issues.push("VM acquisition is not performed for every map-memory request".to_string());
        }
        if self.allocation_performed_count != self.map_memory_request_count {
            issues.push("allocations are not performed for every map-memory request".to_string());
        }
        if self.handle_bound_count != self.map_memory_request_count {
            issues.push("allocation handles are not bound".to_string());
        }
        if self.device_ids_array_bound_count != self.map_memory_request_count {
            issues.push("device ID arrays are not bound".to_string());
        }
        if !self.all_live_request_args_bound {
            issues.push("not all live map-memory request args are bound".to_string());
        }
        if !self.all_request_args_ready {
            issues.push("not all map-memory request args are ready".to_string());
        }
        if self.map_memory_performed {
            issues.push("KFD map-memory has already been marked performed".to_string());
        }
        if self.live_execution_supported {
            issues.push("live execution support is unexpectedly enabled".to_string());
        }
        let issue_details = self
            .issues
            .iter()
            .map(runtime_kfd_map_memory_issue_label)
            .collect::<Vec<_>>();
        if !issue_details.is_empty() {
            issues.push(issue_details.join("; "));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD map-memory request plan for {} is not ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn runtime_kfd_map_memory_issue_label(issue: &RuntimeKfdMapMemoryRequestIssue) -> String {
    match (&issue.slot, &issue.tensor) {
        (Some(slot), Some(tensor)) => format!("slot {slot} {tensor}: {}", issue.message),
        (Some(slot), None) => format!("slot {slot}: {}", issue.message),
        (None, Some(tensor)) => format!("{tensor}: {}", issue.message),
        (None, None) => issue.message.clone(),
    }
}

fn runtime_kfd_map_memory_request_plan_from(
    alloc_memory_requests: &ModelRuntimeKfdAllocMemoryRequestPlan,
) -> ModelRuntimeKfdMapMemoryRequestPlan {
    let mut issues = Vec::new();
    let alloc_memory_request_metadata_ready =
        match alloc_memory_requests.assert_kfd_alloc_memory_request_ready() {
            Ok(()) => true,
            Err(err) => {
                issues.push(RuntimeKfdMapMemoryRequestIssue {
                    slot: None,
                    tensor: None,
                    message: format!("KFD alloc-memory request plan is not ready: {err}"),
                });
                false
            }
        };

    let mut entries = Vec::new();
    let mut map_to_gpu_required_count = 0usize;
    let mut host_visible_gtt_request_count = 0usize;
    let mut device_local_vram_request_count = 0usize;
    let mut total_storage_bytes = 0usize;
    let mut total_map_memory_bytes = 0usize;
    let mut total_device_id_count = 0usize;

    for allocation in &alloc_memory_requests.entries {
        let mut entry_issue_count = 0usize;
        match allocation.allocation_kind {
            RuntimeSlotKfdAllocationKind::HostVisibleGtt => {
                host_visible_gtt_request_count += 1;
            }
            RuntimeSlotKfdAllocationKind::DeviceLocalVramPreferPublicCoherent => {
                device_local_vram_request_count += 1;
            }
        }
        if allocation.map_to_gpu_required {
            map_to_gpu_required_count += 1;
        } else {
            entry_issue_count += 1;
            issues.push(RuntimeKfdMapMemoryRequestIssue {
                slot: Some(allocation.slot),
                tensor: Some(allocation.tensor.clone()),
                message: "alloc-memory row does not require map-to-GPU".to_string(),
            });
        }
        if !allocation.request_metadata_ready {
            entry_issue_count += 1;
            issues.push(RuntimeKfdMapMemoryRequestIssue {
                slot: Some(allocation.slot),
                tensor: Some(allocation.tensor.clone()),
                message: "alloc-memory request metadata is not ready".to_string(),
            });
        }
        if allocation.resident_gpu_id_count == 0 {
            entry_issue_count += 1;
            issues.push(RuntimeKfdMapMemoryRequestIssue {
                slot: Some(allocation.slot),
                tensor: Some(allocation.tensor.clone()),
                message: "no resident GPU IDs available for map-memory args".to_string(),
            });
        }
        let map_args_n_devices = match u32::try_from(allocation.resident_gpu_id_count) {
            Ok(count) => count,
            Err(_) => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryRequestIssue {
                    slot: Some(allocation.slot),
                    tensor: Some(allocation.tensor.clone()),
                    message: "resident GPU ID count exceeds u32 map-memory n_devices".to_string(),
                });
                0
            }
        };
        match total_storage_bytes.checked_add(allocation.storage_bytes) {
            Some(total) => total_storage_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryRequestIssue {
                    slot: Some(allocation.slot),
                    tensor: Some(allocation.tensor.clone()),
                    message: "total storage bytes overflow".to_string(),
                });
            }
        }
        match total_map_memory_bytes.checked_add(allocation.requested_bytes) {
            Some(total) => total_map_memory_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryRequestIssue {
                    slot: Some(allocation.slot),
                    tensor: Some(allocation.tensor.clone()),
                    message: "total map-memory bytes overflow".to_string(),
                });
            }
        }
        match total_device_id_count.checked_add(allocation.resident_gpu_id_count) {
            Some(total) => total_device_id_count = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryRequestIssue {
                    slot: Some(allocation.slot),
                    tensor: Some(allocation.tensor.clone()),
                    message: "total map-memory device ID count overflow".to_string(),
                });
            }
        }

        let handle_required = allocation.map_to_gpu_required;
        let device_ids_array_required = allocation.map_to_gpu_required;
        let request_static_metadata_ready =
            alloc_memory_request_metadata_ready && entry_issue_count == 0;
        entries.push(RuntimeKfdMapMemoryRequestEntry {
            slot: allocation.slot,
            tensor: allocation.tensor.clone(),
            class: allocation.class,
            lifetime_access: allocation.lifetime_access,
            allocation_kind: allocation.allocation_kind,
            allocation_gpu_id: allocation.allocation_gpu_id,
            map_memory_ioctl: mainarch_sys::ioc_map_memory_to_gpu() as u64,
            map_args_handle: 0,
            map_args_device_ids_array_ptr: 0,
            map_args_n_devices,
            map_args_n_success: 0,
            storage_bytes: allocation.storage_bytes,
            requested_bytes: allocation.requested_bytes,
            resident_gpu_ids: allocation.resident_gpu_ids.clone(),
            resident_gpu_id_count: allocation.resident_gpu_id_count,
            kfd_fd_required: true,
            kfd_fd_bound: false,
            vm_acquire_required: allocation.vm_acquire_required,
            vm_acquire_performed: false,
            allocation_required: allocation.allocation_required,
            allocation_performed: false,
            handle_required,
            handle_bound: false,
            device_ids_array_required,
            device_ids_array_bound: false,
            map_to_gpu_required: allocation.map_to_gpu_required,
            map_memory_performed: false,
            request_static_metadata_ready,
            request_args_ready: false,
            issue_count: entry_issue_count,
        });
    }

    let map_memory_request_count = entries.len();
    let request_issue_count = issues.len();
    let all_static_request_metadata_ready = alloc_memory_request_metadata_ready
        && map_memory_request_count > 0
        && map_to_gpu_required_count == map_memory_request_count
        && request_issue_count == 0
        && entries
            .iter()
            .all(|entry| entry.request_static_metadata_ready && entry.issue_count == 0);

    ModelRuntimeKfdMapMemoryRequestPlan {
        target: alloc_memory_requests.target,
        request_source: MODEL_RUNTIME_KFD_MAP_MEMORY_REQUEST_SOURCE,
        kfd_device_path: mainarch_sys::KFD_DEVICE,
        resident_gpu_ids: alloc_memory_requests.resident_gpu_ids.clone(),
        resident_gpu_id_count: alloc_memory_requests.resident_gpu_id_count,
        slot_count: alloc_memory_requests.slot_count,
        map_memory_request_count,
        map_to_gpu_required_count,
        host_visible_gtt_request_count,
        device_local_vram_request_count,
        total_storage_bytes,
        total_map_memory_bytes,
        total_device_id_count,
        kfd_fd_bound_count: 0,
        vm_acquire_performed_count: 0,
        allocation_performed_count: 0,
        handle_bound_count: 0,
        device_ids_array_bound_count: 0,
        map_memory_performed_count: 0,
        map_memory_success_count: 0,
        request_issue_count,
        alloc_memory_request_metadata_ready,
        all_static_request_metadata_ready,
        all_live_request_args_bound: false,
        all_request_args_ready: false,
        map_memory_performed: false,
        live_execution_supported: MODEL_API_CONTRACT.live_execution_supported,
        entries,
        issues,
    }
}

const MODEL_RUNTIME_KFD_MAP_MEMORY_ARGUMENT_BINDING_SOURCE: &str =
    "mainarch_kfd_map_memory_argument_binding_v0";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdMapMemoryDeviceIdsArrayBinding {
    pub slot: usize,
    pub tensor: TensorRef,
    pub device_ids_array_ptr: u64,
    pub device_ids: Vec<u32>,
}

impl RuntimeKfdMapMemoryDeviceIdsArrayBinding {
    pub fn new(
        slot: usize,
        tensor: impl Into<String>,
        device_ids_array_ptr: u64,
        device_ids: Vec<u32>,
    ) -> Result<Self> {
        Ok(Self {
            slot,
            tensor: TensorRef::new(tensor)?,
            device_ids_array_ptr,
            device_ids,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdMapMemoryArgumentBindingEntry {
    pub slot: usize,
    pub tensor: TensorRef,
    pub class: TensorBindingClass,
    pub lifetime_access: TensorBindingAccess,
    pub allocation_kind: RuntimeSlotKfdAllocationKind,
    pub allocation_gpu_id: u32,
    pub map_memory_ioctl: u64,
    pub map_args_handle: u64,
    pub map_args_device_ids_array_ptr: u64,
    pub map_args_n_devices: u32,
    pub map_args_n_success: u32,
    pub device_ids: Vec<u32>,
    pub device_id_count: usize,
    pub storage_bytes: usize,
    pub requested_bytes: usize,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub request_static_metadata_ready: bool,
    pub alloc_result_binding_present: bool,
    pub alloc_result_metadata_ready: bool,
    pub allocation_performed: bool,
    pub handle_bound: bool,
    pub device_ids_array_binding_present: bool,
    pub device_ids_array_bound: bool,
    pub device_ids_match_resident_gpu_ids: bool,
    pub map_memory_argument_ready: bool,
    pub map_memory_performed: bool,
    pub issue_count: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdMapMemoryArgumentBindingIssue {
    pub slot: Option<usize>,
    pub tensor: Option<TensorRef>,
    pub message: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeKfdMapMemoryArgumentBindingPlan {
    pub target: &'static str,
    pub binding_source: &'static str,
    pub kfd_device_path: &'static str,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub slot_count: usize,
    pub map_memory_request_count: usize,
    pub alloc_memory_result_entry_count: usize,
    pub device_ids_array_binding_count: usize,
    pub matched_device_ids_array_binding_count: usize,
    pub missing_device_ids_array_binding_count: usize,
    pub duplicate_device_ids_array_binding_count: usize,
    pub unmatched_device_ids_array_binding_count: usize,
    pub handle_bound_count: usize,
    pub device_ids_array_bound_count: usize,
    pub device_ids_array_match_count: usize,
    pub allocation_performed_count: usize,
    pub map_memory_argument_ready_count: usize,
    pub total_storage_bytes: usize,
    pub total_map_memory_bytes: usize,
    pub total_device_id_count: usize,
    pub binding_issue_count: usize,
    pub map_memory_request_static_metadata_ready: bool,
    pub alloc_memory_result_binding_ready: bool,
    pub all_map_memory_arguments_ready: bool,
    pub map_memory_performed: bool,
    pub live_execution_supported: bool,
    pub entries: Vec<RuntimeKfdMapMemoryArgumentBindingEntry>,
    pub issues: Vec<RuntimeKfdMapMemoryArgumentBindingIssue>,
}

impl ModelRuntimeKfdMapMemoryArgumentBindingPlan {
    pub fn entry_for(&self, tensor: &str) -> Option<&RuntimeKfdMapMemoryArgumentBindingEntry> {
        self.entries
            .iter()
            .find(|entry| entry.tensor.as_str() == tensor)
    }

    pub fn entry_for_slot(&self, slot: usize) -> Option<&RuntimeKfdMapMemoryArgumentBindingEntry> {
        self.entries.iter().find(|entry| entry.slot == slot)
    }

    pub fn is_kfd_map_memory_arguments_bound(&self) -> bool {
        self.assert_kfd_map_memory_arguments_bound().is_ok()
    }

    pub fn kfd_map_memory_result_binding_plan(
        &self,
        result_bindings: &[RuntimeKfdMapMemoryResultBinding],
    ) -> ModelRuntimeKfdMapMemoryResultBindingPlan {
        runtime_kfd_map_memory_result_binding_plan_from(self, result_bindings)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.binding_source != MODEL_RUNTIME_KFD_MAP_MEMORY_ARGUMENT_BINDING_SOURCE {
            issues.push(format!(
                "binding source {} != {}",
                self.binding_source, MODEL_RUNTIME_KFD_MAP_MEMORY_ARGUMENT_BINDING_SOURCE
            ));
        }
        if self.kfd_device_path != mainarch_sys::KFD_DEVICE {
            issues.push(format!(
                "KFD device path {} != {}",
                self.kfd_device_path,
                mainarch_sys::KFD_DEVICE
            ));
        }
        if self.entries.len() != self.map_memory_request_count {
            issues.push(format!(
                "entry count {} != map-memory request count {}",
                self.entries.len(),
                self.map_memory_request_count
            ));
        }
        let resident_gpu_ids = self
            .resident_gpu_ids
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if resident_gpu_ids.len() != self.resident_gpu_ids.len() {
            issues.push("resident GPU IDs contain duplicates".to_string());
        }
        let canonical_resident_gpu_ids = resident_gpu_ids.iter().copied().collect::<Vec<_>>();
        if canonical_resident_gpu_ids != self.resident_gpu_ids {
            issues.push("resident GPU IDs are not sorted and unique".to_string());
        }
        if self.resident_gpu_id_count != self.resident_gpu_ids.len() {
            issues.push(format!(
                "resident GPU ID count {} != IDs {}",
                self.resident_gpu_id_count,
                self.resident_gpu_ids.len()
            ));
        }
        if self.binding_issue_count != self.issues.len() {
            issues.push(format!(
                "binding issue count {} != issue rows {}",
                self.binding_issue_count,
                self.issues.len()
            ));
        }
        match self
            .matched_device_ids_array_binding_count
            .checked_add(self.duplicate_device_ids_array_binding_count)
            .and_then(|count| count.checked_add(self.unmatched_device_ids_array_binding_count))
        {
            Some(expected) if expected == self.device_ids_array_binding_count => {}
            Some(expected) => issues.push(format!(
                "device ID array binding accounting {} != raw binding count {}",
                expected, self.device_ids_array_binding_count
            )),
            None => issues.push("device ID array binding accounting overflows".to_string()),
        }

        let mut seen_slots = BTreeSet::new();
        let mut matched_device_ids_array_binding_count = 0usize;
        let mut missing_device_ids_array_binding_count = 0usize;
        let mut handle_bound_count = 0usize;
        let mut device_ids_array_bound_count = 0usize;
        let mut device_ids_array_match_count = 0usize;
        let mut allocation_performed_count = 0usize;
        let mut map_memory_argument_ready_count = 0usize;
        let mut total_storage_bytes = 0usize;
        let mut total_map_memory_bytes = 0usize;
        let mut total_device_id_count = 0usize;
        let mut entry_issue_count = 0usize;
        let mut entries_ready = true;

        for entry in &self.entries {
            if !seen_slots.insert(entry.slot) {
                issues.push(format!("slot {} appears more than once", entry.slot));
            }
            if entry.tensor.as_str().trim().is_empty() {
                issues.push(format!("slot {} has empty tensor name", entry.slot));
            }
            if entry.map_memory_ioctl != mainarch_sys::ioc_map_memory_to_gpu() as u64 {
                issues.push(format!(
                    "slot {} {} map-memory ioctl 0x{:x} != expected 0x{:x}",
                    entry.slot,
                    entry.tensor,
                    entry.map_memory_ioctl,
                    mainarch_sys::ioc_map_memory_to_gpu() as u64
                ));
            }
            if entry.resident_gpu_ids != self.resident_gpu_ids {
                issues.push(format!(
                    "slot {} {} resident GPU IDs do not match plan",
                    entry.slot, entry.tensor
                ));
            }
            if entry.resident_gpu_id_count != entry.resident_gpu_ids.len() {
                issues.push(format!(
                    "slot {} {} resident GPU ID count {} != IDs {}",
                    entry.slot,
                    entry.tensor,
                    entry.resident_gpu_id_count,
                    entry.resident_gpu_ids.len()
                ));
            }
            if entry.device_id_count != entry.device_ids.len() {
                issues.push(format!(
                    "slot {} {} device ID count {} != IDs {}",
                    entry.slot,
                    entry.tensor,
                    entry.device_id_count,
                    entry.device_ids.len()
                ));
            }
            match u32::try_from(entry.resident_gpu_id_count) {
                Ok(expected) if entry.map_args_n_devices == expected => {}
                Ok(expected) => issues.push(format!(
                    "slot {} {} map args n_devices {} != resident GPU ID count {}",
                    entry.slot, entry.tensor, entry.map_args_n_devices, expected
                )),
                Err(_) => issues.push(format!(
                    "slot {} {} resident GPU ID count {} exceeds u32",
                    entry.slot, entry.tensor, entry.resident_gpu_id_count
                )),
            }
            if entry.map_args_n_success != 0 {
                issues.push(format!(
                    "slot {} {} map args n_success {} != 0",
                    entry.slot, entry.tensor, entry.map_args_n_success
                ));
            }
            if entry.alloc_result_binding_present
                && entry.issue_count == 0
                && entry.map_args_handle == 0
            {
                issues.push(format!(
                    "slot {} {} has an alloc result binding but map args handle is zero",
                    entry.slot, entry.tensor
                ));
            }
            if entry.handle_bound != (entry.map_args_handle != 0) {
                issues.push(format!(
                    "slot {} {} handle_bound {} != handle nonzero {}",
                    entry.slot,
                    entry.tensor,
                    entry.handle_bound,
                    entry.map_args_handle != 0
                ));
            }
            if entry.device_ids_array_binding_present {
                matched_device_ids_array_binding_count += 1;
            } else {
                missing_device_ids_array_binding_count += 1;
            }
            let expected_device_ids_array_bound =
                entry.device_ids_array_binding_present && entry.map_args_device_ids_array_ptr != 0;
            if entry.device_ids_array_bound != expected_device_ids_array_bound {
                issues.push(format!(
                    "slot {} {} device_ids_array_bound {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.device_ids_array_bound,
                    expected_device_ids_array_bound
                ));
            }
            let expected_device_ids_match = entry.device_ids_array_binding_present
                && entry.device_ids == entry.resident_gpu_ids;
            if entry.device_ids_match_resident_gpu_ids != expected_device_ids_match {
                issues.push(format!(
                    "slot {} {} device_ids_match_resident_gpu_ids {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.device_ids_match_resident_gpu_ids,
                    expected_device_ids_match
                ));
            }
            if entry.handle_bound {
                handle_bound_count += 1;
            }
            if entry.device_ids_array_bound {
                device_ids_array_bound_count += 1;
            }
            if entry.device_ids_match_resident_gpu_ids {
                device_ids_array_match_count += 1;
            }
            if entry.allocation_performed {
                allocation_performed_count += 1;
            }
            if entry.map_memory_performed {
                issues.push(format!(
                    "slot {} {} unexpectedly reports map-memory performed",
                    entry.slot, entry.tensor
                ));
            }
            let expected_ready = self.map_memory_request_static_metadata_ready
                && self.alloc_memory_result_binding_ready
                && entry.request_static_metadata_ready
                && entry.alloc_result_binding_present
                && entry.alloc_result_metadata_ready
                && entry.allocation_performed
                && entry.handle_bound
                && entry.device_ids_array_binding_present
                && entry.device_ids_array_bound
                && entry.device_ids_match_resident_gpu_ids
                && entry.map_args_n_success == 0
                && !entry.map_memory_performed
                && entry.issue_count == 0;
            if entry.map_memory_argument_ready != expected_ready {
                issues.push(format!(
                    "slot {} {} map_memory_argument_ready {} != expected {}",
                    entry.slot, entry.tensor, entry.map_memory_argument_ready, expected_ready
                ));
            }
            if entry.map_memory_argument_ready {
                map_memory_argument_ready_count += 1;
            } else {
                entries_ready = false;
            }
            total_storage_bytes = checked_add_usize(
                total_storage_bytes,
                entry.storage_bytes,
                "KFD map-memory argument storage bytes",
            )?;
            total_map_memory_bytes = checked_add_usize(
                total_map_memory_bytes,
                entry.requested_bytes,
                "KFD map-memory argument bytes",
            )?;
            total_device_id_count = checked_add_usize(
                total_device_id_count,
                entry.device_id_count,
                "KFD map-memory argument device ID count",
            )?;
            entry_issue_count = checked_add_usize(
                entry_issue_count,
                entry.issue_count,
                "KFD map-memory argument entry issues",
            )?;
        }

        if matched_device_ids_array_binding_count != self.matched_device_ids_array_binding_count {
            issues.push(format!(
                "matched device ID array binding count {matched_device_ids_array_binding_count} != plan {}",
                self.matched_device_ids_array_binding_count
            ));
        }
        if missing_device_ids_array_binding_count != self.missing_device_ids_array_binding_count {
            issues.push(format!(
                "missing device ID array binding count {missing_device_ids_array_binding_count} != plan {}",
                self.missing_device_ids_array_binding_count
            ));
        }
        if handle_bound_count != self.handle_bound_count {
            issues.push(format!(
                "handle bound count {handle_bound_count} != plan {}",
                self.handle_bound_count
            ));
        }
        if device_ids_array_bound_count != self.device_ids_array_bound_count {
            issues.push(format!(
                "device ID array bound count {device_ids_array_bound_count} != plan {}",
                self.device_ids_array_bound_count
            ));
        }
        if device_ids_array_match_count != self.device_ids_array_match_count {
            issues.push(format!(
                "device ID array match count {device_ids_array_match_count} != plan {}",
                self.device_ids_array_match_count
            ));
        }
        if allocation_performed_count != self.allocation_performed_count {
            issues.push(format!(
                "allocation performed count {allocation_performed_count} != plan {}",
                self.allocation_performed_count
            ));
        }
        if map_memory_argument_ready_count != self.map_memory_argument_ready_count {
            issues.push(format!(
                "map-memory argument ready count {map_memory_argument_ready_count} != plan {}",
                self.map_memory_argument_ready_count
            ));
        }
        if total_storage_bytes != self.total_storage_bytes {
            issues.push(format!(
                "total storage bytes {total_storage_bytes} != plan {}",
                self.total_storage_bytes
            ));
        }
        if total_map_memory_bytes != self.total_map_memory_bytes {
            issues.push(format!(
                "total map-memory bytes {total_map_memory_bytes} != plan {}",
                self.total_map_memory_bytes
            ));
        }
        if total_device_id_count != self.total_device_id_count {
            issues.push(format!(
                "total device ID count {total_device_id_count} != plan {}",
                self.total_device_id_count
            ));
        }
        let slot_issue_rows = self
            .issues
            .iter()
            .filter(|issue| issue.slot.is_some())
            .count();
        let accounted_slot_issues = entry_issue_count
            .checked_add(self.duplicate_device_ids_array_binding_count)
            .and_then(|count| count.checked_add(self.unmatched_device_ids_array_binding_count))
            .ok_or_else(|| anyhow!("KFD map-memory argument issue count overflows"))?;
        if accounted_slot_issues != slot_issue_rows {
            issues.push(format!(
                "accounted slot issue count {accounted_slot_issues} != slot issue rows {slot_issue_rows}"
            ));
        }
        let expected_all_map_memory_arguments_ready = self.map_memory_request_static_metadata_ready
            && self.alloc_memory_result_binding_ready
            && self.map_memory_request_count > 0
            && self.matched_device_ids_array_binding_count == self.map_memory_request_count
            && self.missing_device_ids_array_binding_count == 0
            && self.duplicate_device_ids_array_binding_count == 0
            && self.unmatched_device_ids_array_binding_count == 0
            && self.binding_issue_count == 0
            && entries_ready;
        if self.all_map_memory_arguments_ready != expected_all_map_memory_arguments_ready {
            issues.push(format!(
                "all_map_memory_arguments_ready {} != expected {}",
                self.all_map_memory_arguments_ready, expected_all_map_memory_arguments_ready
            ));
        }
        if self.map_memory_performed {
            issues.push("KFD map-memory argument binding unexpectedly mapped buffers".to_string());
        }
        if self.live_execution_supported != MODEL_API_CONTRACT.live_execution_supported {
            issues.push(format!(
                "live execution support {} != contract {}",
                self.live_execution_supported, MODEL_API_CONTRACT.live_execution_supported
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD map-memory argument binding plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn assert_kfd_map_memory_arguments_bound(&self) -> Result<()> {
        let mut issues = Vec::new();
        if let Err(err) = self.assert_consistent() {
            issues.push(format!("consistency: {err}"));
        }
        if !self.map_memory_request_static_metadata_ready {
            issues.push("KFD map-memory request static metadata is not ready".to_string());
        }
        if !self.alloc_memory_result_binding_ready {
            issues.push("KFD alloc-memory result bindings are not ready".to_string());
        }
        if self.map_memory_request_count == 0 {
            issues.push("no KFD map-memory requests available for argument binding".to_string());
        }
        if self.missing_device_ids_array_binding_count > 0 {
            issues.push(format!(
                "missing device ID array bindings: {}",
                self.missing_device_ids_array_binding_count
            ));
        }
        if self.duplicate_device_ids_array_binding_count > 0 {
            issues.push(format!(
                "duplicate device ID array bindings: {}",
                self.duplicate_device_ids_array_binding_count
            ));
        }
        if self.unmatched_device_ids_array_binding_count > 0 {
            issues.push(format!(
                "unmatched device ID array bindings: {}",
                self.unmatched_device_ids_array_binding_count
            ));
        }
        if self.handle_bound_count != self.map_memory_request_count {
            issues
                .push("allocation handles are not bound for every map-memory request".to_string());
        }
        if self.device_ids_array_bound_count != self.map_memory_request_count {
            issues.push("device ID arrays are not bound for every map-memory request".to_string());
        }
        if self.device_ids_array_match_count != self.map_memory_request_count {
            issues.push("device ID arrays do not match resident GPU IDs".to_string());
        }
        if self.allocation_performed_count != self.map_memory_request_count {
            issues.push("allocation results do not cover every map-memory request".to_string());
        }
        if self.map_memory_argument_ready_count != self.map_memory_request_count {
            issues.push("map-memory arguments are not ready for every request".to_string());
        }
        if self.binding_issue_count > 0 {
            issues.push(format!("binding issues: {}", self.binding_issue_count));
        }
        if !self.all_map_memory_arguments_ready {
            issues.push("not all map-memory arguments are ready".to_string());
        }
        if self.map_memory_performed {
            issues.push("KFD map-memory has already been marked performed".to_string());
        }
        if self.live_execution_supported {
            issues.push("live execution support is unexpectedly enabled".to_string());
        }
        let issue_details = self
            .issues
            .iter()
            .map(runtime_kfd_map_memory_argument_binding_issue_label)
            .collect::<Vec<_>>();
        if !issue_details.is_empty() {
            issues.push(issue_details.join("; "));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD map-memory argument binding plan for {} is not ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn runtime_kfd_map_memory_argument_binding_issue_label(
    issue: &RuntimeKfdMapMemoryArgumentBindingIssue,
) -> String {
    match (&issue.slot, &issue.tensor) {
        (Some(slot), Some(tensor)) => format!("slot {slot} {tensor}: {}", issue.message),
        (Some(slot), None) => format!("slot {slot}: {}", issue.message),
        (None, Some(tensor)) => format!("{tensor}: {}", issue.message),
        (None, None) => issue.message.clone(),
    }
}

fn runtime_kfd_map_memory_argument_binding_plan_from(
    map_memory_requests: &ModelRuntimeKfdMapMemoryRequestPlan,
    alloc_memory_results: &ModelRuntimeKfdAllocMemoryResultBindingPlan,
    device_ids_array_bindings: &[RuntimeKfdMapMemoryDeviceIdsArrayBinding],
) -> ModelRuntimeKfdMapMemoryArgumentBindingPlan {
    let mut issues = Vec::new();
    let map_memory_request_static_metadata_ready = match map_memory_requests.assert_consistent() {
        Ok(()) if map_memory_requests.all_static_request_metadata_ready => true,
        Ok(()) => {
            issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                slot: None,
                tensor: None,
                message: "KFD map-memory request static metadata is not ready".to_string(),
            });
            false
        }
        Err(err) => {
            issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                slot: None,
                tensor: None,
                message: format!("KFD map-memory request plan is not consistent: {err}"),
            });
            false
        }
    };
    let alloc_memory_result_binding_ready =
        match alloc_memory_results.assert_kfd_alloc_memory_result_bound() {
            Ok(()) => true,
            Err(err) => {
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: None,
                    tensor: None,
                    message: format!("KFD alloc-memory result binding plan is not ready: {err}"),
                });
                false
            }
        };
    if map_memory_requests.target != alloc_memory_results.target {
        issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
            slot: None,
            tensor: None,
            message: format!(
                "KFD map-memory target {} != alloc-memory result target {}",
                map_memory_requests.target, alloc_memory_results.target
            ),
        });
    }
    if map_memory_requests.resident_gpu_ids != alloc_memory_results.resident_gpu_ids {
        issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
            slot: None,
            tensor: None,
            message: "KFD map-memory resident GPU IDs do not match alloc-memory results"
                .to_string(),
        });
    }

    let request_slots = map_memory_requests
        .entries
        .iter()
        .map(|entry| entry.slot)
        .collect::<BTreeSet<_>>();
    let mut device_ids_array_by_slot = BTreeMap::new();
    let mut duplicate_device_ids_array_binding_count = 0usize;
    let mut unmatched_device_ids_array_binding_count = 0usize;
    for binding in device_ids_array_bindings {
        if !request_slots.contains(&binding.slot) {
            unmatched_device_ids_array_binding_count += 1;
            issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                slot: Some(binding.slot),
                tensor: Some(binding.tensor.clone()),
                message: "device ID array binding does not match a map-memory request slot"
                    .to_string(),
            });
            continue;
        }
        if device_ids_array_by_slot
            .insert(binding.slot, binding)
            .is_some()
        {
            duplicate_device_ids_array_binding_count += 1;
            issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                slot: Some(binding.slot),
                tensor: Some(binding.tensor.clone()),
                message: "duplicate device ID array binding for slot".to_string(),
            });
        }
    }

    let mut entries = Vec::new();
    let mut matched_device_ids_array_binding_count = 0usize;
    let mut missing_device_ids_array_binding_count = 0usize;
    let mut handle_bound_count = 0usize;
    let mut device_ids_array_bound_count = 0usize;
    let mut device_ids_array_match_count = 0usize;
    let mut allocation_performed_count = 0usize;
    let mut map_memory_argument_ready_count = 0usize;
    let mut total_storage_bytes = 0usize;
    let mut total_map_memory_bytes = 0usize;
    let mut total_device_id_count = 0usize;

    for request in &map_memory_requests.entries {
        let mut entry_issue_count = 0usize;
        if !request.request_static_metadata_ready {
            entry_issue_count += 1;
            issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                slot: Some(request.slot),
                tensor: Some(request.tensor.clone()),
                message: "map-memory request static metadata is not ready".to_string(),
            });
        }

        let alloc_result = alloc_memory_results.entry_for_slot(request.slot);
        if let Some(result) = alloc_result {
            if result.tensor != request.tensor {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "alloc result tensor {} != map-memory request tensor {}",
                        result.tensor, request.tensor
                    ),
                });
            }
            if result.allocation_gpu_id != request.allocation_gpu_id {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "alloc result GPU ID {} != map-memory request GPU ID {}",
                        result.allocation_gpu_id, request.allocation_gpu_id
                    ),
                });
            }
            if result.requested_bytes != request.requested_bytes {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "alloc result requested bytes {} != map-memory request bytes {}",
                        result.requested_bytes, request.requested_bytes
                    ),
                });
            }
            if !result.result_metadata_ready {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "alloc result metadata is not ready".to_string(),
                });
            }
            if !result.allocation_performed {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "alloc result does not report allocation performed".to_string(),
                });
            }
            if !result.handle_bound {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "alloc result handle is not bound".to_string(),
                });
            }
        } else {
            entry_issue_count += 1;
            issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                slot: Some(request.slot),
                tensor: Some(request.tensor.clone()),
                message: "missing alloc-memory result entry for map-memory request".to_string(),
            });
        }

        let device_binding = device_ids_array_by_slot.get(&request.slot).copied();
        if let Some(binding) = device_binding {
            matched_device_ids_array_binding_count += 1;
            if binding.tensor != request.tensor {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "device ID array tensor {} != map-memory request tensor {}",
                        binding.tensor, request.tensor
                    ),
                });
            }
            if binding.device_ids_array_ptr == 0 {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "device ID array binding has empty pointer".to_string(),
                });
            }
            if binding.device_ids != request.resident_gpu_ids {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "device ID array values do not match resident GPU IDs".to_string(),
                });
            }
            match u32::try_from(binding.device_ids.len()) {
                Ok(count) if count == request.map_args_n_devices => {}
                Ok(count) => {
                    entry_issue_count += 1;
                    issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                        slot: Some(request.slot),
                        tensor: Some(request.tensor.clone()),
                        message: format!(
                            "device ID array count {} != map args n_devices {}",
                            count, request.map_args_n_devices
                        ),
                    });
                }
                Err(_) => {
                    entry_issue_count += 1;
                    issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                        slot: Some(request.slot),
                        tensor: Some(request.tensor.clone()),
                        message: "device ID array count exceeds u32 map-memory n_devices"
                            .to_string(),
                    });
                }
            }
        } else {
            missing_device_ids_array_binding_count += 1;
            entry_issue_count += 1;
            issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                slot: Some(request.slot),
                tensor: Some(request.tensor.clone()),
                message: "missing device ID array binding for map-memory request".to_string(),
            });
        }

        let map_args_handle = alloc_result.map_or(0, |result| result.handle);
        let handle_bound = map_args_handle != 0;
        if handle_bound {
            handle_bound_count += 1;
        }
        let alloc_result_binding_present = alloc_result.is_some();
        let alloc_result_metadata_ready =
            alloc_result.is_some_and(|result| result.result_metadata_ready);
        let allocation_performed =
            alloc_result.is_some_and(|result| result.allocation_performed && result.handle_bound);
        if allocation_performed {
            allocation_performed_count += 1;
        }
        let (device_ids_array_binding_present, map_args_device_ids_array_ptr, device_ids) =
            match device_binding {
                Some(binding) => (
                    true,
                    binding.device_ids_array_ptr,
                    binding.device_ids.clone(),
                ),
                None => (false, 0, Vec::new()),
            };
        let device_ids_array_bound =
            device_ids_array_binding_present && map_args_device_ids_array_ptr != 0;
        if device_ids_array_bound {
            device_ids_array_bound_count += 1;
        }
        let device_ids_match_resident_gpu_ids =
            device_ids_array_binding_present && device_ids == request.resident_gpu_ids;
        if device_ids_match_resident_gpu_ids {
            device_ids_array_match_count += 1;
        }
        match total_storage_bytes.checked_add(request.storage_bytes) {
            Some(total) => total_storage_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "total storage bytes overflow".to_string(),
                });
            }
        }
        match total_map_memory_bytes.checked_add(request.requested_bytes) {
            Some(total) => total_map_memory_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "total map-memory bytes overflow".to_string(),
                });
            }
        }
        match total_device_id_count.checked_add(device_ids.len()) {
            Some(total) => total_device_id_count = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryArgumentBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "total map-memory device ID count overflow".to_string(),
                });
            }
        }
        let map_memory_argument_ready = map_memory_request_static_metadata_ready
            && alloc_memory_result_binding_ready
            && request.request_static_metadata_ready
            && alloc_result_binding_present
            && alloc_result_metadata_ready
            && allocation_performed
            && handle_bound
            && device_ids_array_binding_present
            && device_ids_array_bound
            && device_ids_match_resident_gpu_ids
            && request.map_args_n_success == 0
            && !request.map_memory_performed
            && entry_issue_count == 0;
        if map_memory_argument_ready {
            map_memory_argument_ready_count += 1;
        }

        entries.push(RuntimeKfdMapMemoryArgumentBindingEntry {
            slot: request.slot,
            tensor: request.tensor.clone(),
            class: request.class,
            lifetime_access: request.lifetime_access,
            allocation_kind: request.allocation_kind,
            allocation_gpu_id: request.allocation_gpu_id,
            map_memory_ioctl: request.map_memory_ioctl,
            map_args_handle,
            map_args_device_ids_array_ptr,
            map_args_n_devices: request.map_args_n_devices,
            map_args_n_success: request.map_args_n_success,
            device_id_count: device_ids.len(),
            device_ids,
            storage_bytes: request.storage_bytes,
            requested_bytes: request.requested_bytes,
            resident_gpu_ids: request.resident_gpu_ids.clone(),
            resident_gpu_id_count: request.resident_gpu_id_count,
            request_static_metadata_ready: request.request_static_metadata_ready,
            alloc_result_binding_present,
            alloc_result_metadata_ready,
            allocation_performed,
            handle_bound,
            device_ids_array_binding_present,
            device_ids_array_bound,
            device_ids_match_resident_gpu_ids,
            map_memory_argument_ready,
            map_memory_performed: false,
            issue_count: entry_issue_count,
        });
    }

    let map_memory_request_count = map_memory_requests.map_memory_request_count;
    let binding_issue_count = issues.len();
    let all_map_memory_arguments_ready = map_memory_request_static_metadata_ready
        && alloc_memory_result_binding_ready
        && map_memory_request_count > 0
        && matched_device_ids_array_binding_count == map_memory_request_count
        && missing_device_ids_array_binding_count == 0
        && duplicate_device_ids_array_binding_count == 0
        && unmatched_device_ids_array_binding_count == 0
        && binding_issue_count == 0
        && entries
            .iter()
            .all(|entry| entry.map_memory_argument_ready && entry.issue_count == 0);

    ModelRuntimeKfdMapMemoryArgumentBindingPlan {
        target: map_memory_requests.target,
        binding_source: MODEL_RUNTIME_KFD_MAP_MEMORY_ARGUMENT_BINDING_SOURCE,
        kfd_device_path: mainarch_sys::KFD_DEVICE,
        resident_gpu_ids: map_memory_requests.resident_gpu_ids.clone(),
        resident_gpu_id_count: map_memory_requests.resident_gpu_id_count,
        slot_count: map_memory_requests.slot_count,
        map_memory_request_count,
        alloc_memory_result_entry_count: alloc_memory_results.entries.len(),
        device_ids_array_binding_count: device_ids_array_bindings.len(),
        matched_device_ids_array_binding_count,
        missing_device_ids_array_binding_count,
        duplicate_device_ids_array_binding_count,
        unmatched_device_ids_array_binding_count,
        handle_bound_count,
        device_ids_array_bound_count,
        device_ids_array_match_count,
        allocation_performed_count,
        map_memory_argument_ready_count,
        total_storage_bytes,
        total_map_memory_bytes,
        total_device_id_count,
        binding_issue_count,
        map_memory_request_static_metadata_ready,
        alloc_memory_result_binding_ready,
        all_map_memory_arguments_ready,
        map_memory_performed: false,
        live_execution_supported: MODEL_API_CONTRACT.live_execution_supported,
        entries,
        issues,
    }
}

const MODEL_RUNTIME_KFD_MAP_MEMORY_RESULT_BINDING_SOURCE: &str =
    "mainarch_kfd_map_memory_result_binding_v0";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdMapMemoryResultBinding {
    pub slot: usize,
    pub tensor: TensorRef,
    pub map_args_handle: u64,
    pub map_args_device_ids_array_ptr: u64,
    pub map_args_n_devices: u32,
    pub map_args_n_success: u32,
}

impl RuntimeKfdMapMemoryResultBinding {
    pub fn new(
        slot: usize,
        tensor: impl Into<String>,
        map_args_handle: u64,
        map_args_device_ids_array_ptr: u64,
        map_args_n_devices: u32,
        map_args_n_success: u32,
    ) -> Result<Self> {
        Ok(Self {
            slot,
            tensor: TensorRef::new(tensor)?,
            map_args_handle,
            map_args_device_ids_array_ptr,
            map_args_n_devices,
            map_args_n_success,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdMapMemoryResultBindingEntry {
    pub slot: usize,
    pub tensor: TensorRef,
    pub class: TensorBindingClass,
    pub lifetime_access: TensorBindingAccess,
    pub allocation_kind: RuntimeSlotKfdAllocationKind,
    pub allocation_gpu_id: u32,
    pub map_memory_ioctl: u64,
    pub map_args_handle: u64,
    pub result_map_args_handle: u64,
    pub map_args_device_ids_array_ptr: u64,
    pub result_map_args_device_ids_array_ptr: u64,
    pub map_args_n_devices: u32,
    pub result_map_args_n_devices: u32,
    pub map_args_n_success: u32,
    pub result_map_args_n_success: u32,
    pub device_ids: Vec<u32>,
    pub device_id_count: usize,
    pub storage_bytes: usize,
    pub requested_bytes: usize,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub argument_binding_ready: bool,
    pub result_binding_present: bool,
    pub handle_bound: bool,
    pub device_ids_array_bound: bool,
    pub device_ids_match_resident_gpu_ids: bool,
    pub allocation_performed: bool,
    pub map_memory_performed: bool,
    pub map_memory_successful: bool,
    pub result_metadata_ready: bool,
    pub issue_count: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeKfdMapMemoryResultBindingIssue {
    pub slot: Option<usize>,
    pub tensor: Option<TensorRef>,
    pub message: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeKfdMapMemoryResultBindingPlan {
    pub target: &'static str,
    pub result_source: &'static str,
    pub kfd_device_path: &'static str,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub slot_count: usize,
    pub map_memory_request_count: usize,
    pub argument_binding_count: usize,
    pub result_binding_count: usize,
    pub matched_result_binding_count: usize,
    pub missing_result_binding_count: usize,
    pub duplicate_result_binding_count: usize,
    pub unmatched_result_binding_count: usize,
    pub handle_bound_count: usize,
    pub device_ids_array_bound_count: usize,
    pub device_ids_array_match_count: usize,
    pub allocation_performed_count: usize,
    pub map_memory_performed_count: usize,
    pub map_memory_success_count: usize,
    pub total_storage_bytes: usize,
    pub total_map_memory_bytes: usize,
    pub total_device_id_count: usize,
    pub result_issue_count: usize,
    pub map_memory_argument_binding_ready: bool,
    pub all_result_bindings_ready: bool,
    pub map_memory_performed: bool,
    pub residency_proven: bool,
    pub live_execution_supported: bool,
    pub entries: Vec<RuntimeKfdMapMemoryResultBindingEntry>,
    pub issues: Vec<RuntimeKfdMapMemoryResultBindingIssue>,
}

impl ModelRuntimeKfdMapMemoryResultBindingPlan {
    pub fn entry_for(&self, tensor: &str) -> Option<&RuntimeKfdMapMemoryResultBindingEntry> {
        self.entries
            .iter()
            .find(|entry| entry.tensor.as_str() == tensor)
    }

    pub fn entry_for_slot(&self, slot: usize) -> Option<&RuntimeKfdMapMemoryResultBindingEntry> {
        self.entries.iter().find(|entry| entry.slot == slot)
    }

    pub fn is_kfd_map_memory_result_bound(&self) -> bool {
        self.assert_kfd_map_memory_result_bound().is_ok()
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.result_source != MODEL_RUNTIME_KFD_MAP_MEMORY_RESULT_BINDING_SOURCE {
            issues.push(format!(
                "result source {} != {}",
                self.result_source, MODEL_RUNTIME_KFD_MAP_MEMORY_RESULT_BINDING_SOURCE
            ));
        }
        if self.kfd_device_path != mainarch_sys::KFD_DEVICE {
            issues.push(format!(
                "KFD device path {} != {}",
                self.kfd_device_path,
                mainarch_sys::KFD_DEVICE
            ));
        }
        if self.entries.len() != self.argument_binding_count {
            issues.push(format!(
                "entry count {} != argument binding count {}",
                self.entries.len(),
                self.argument_binding_count
            ));
        }
        if self.entries.len() != self.map_memory_request_count {
            issues.push(format!(
                "entry count {} != map-memory request count {}",
                self.entries.len(),
                self.map_memory_request_count
            ));
        }
        let resident_gpu_ids = self
            .resident_gpu_ids
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if resident_gpu_ids.len() != self.resident_gpu_ids.len() {
            issues.push("resident GPU IDs contain duplicates".to_string());
        }
        let canonical_resident_gpu_ids = resident_gpu_ids.iter().copied().collect::<Vec<_>>();
        if canonical_resident_gpu_ids != self.resident_gpu_ids {
            issues.push("resident GPU IDs are not sorted and unique".to_string());
        }
        if self.resident_gpu_id_count != self.resident_gpu_ids.len() {
            issues.push(format!(
                "resident GPU ID count {} != IDs {}",
                self.resident_gpu_id_count,
                self.resident_gpu_ids.len()
            ));
        }
        if self.result_issue_count != self.issues.len() {
            issues.push(format!(
                "result issue count {} != issue rows {}",
                self.result_issue_count,
                self.issues.len()
            ));
        }
        match self
            .matched_result_binding_count
            .checked_add(self.duplicate_result_binding_count)
            .and_then(|count| count.checked_add(self.unmatched_result_binding_count))
        {
            Some(expected) if expected == self.result_binding_count => {}
            Some(expected) => issues.push(format!(
                "result binding accounting {} != raw binding count {}",
                expected, self.result_binding_count
            )),
            None => issues.push("result binding accounting overflows".to_string()),
        }

        let mut seen_slots = BTreeSet::new();
        let mut matched_result_binding_count = 0usize;
        let mut missing_result_binding_count = 0usize;
        let mut handle_bound_count = 0usize;
        let mut device_ids_array_bound_count = 0usize;
        let mut device_ids_array_match_count = 0usize;
        let mut allocation_performed_count = 0usize;
        let mut map_memory_performed_count = 0usize;
        let mut map_memory_success_count = 0usize;
        let mut total_storage_bytes = 0usize;
        let mut total_map_memory_bytes = 0usize;
        let mut total_device_id_count = 0usize;
        let mut entry_issue_count = 0usize;
        let mut entries_ready = true;

        for entry in &self.entries {
            if !seen_slots.insert(entry.slot) {
                issues.push(format!("slot {} appears more than once", entry.slot));
            }
            if entry.tensor.as_str().trim().is_empty() {
                issues.push(format!("slot {} has empty tensor name", entry.slot));
            }
            if entry.map_memory_ioctl != mainarch_sys::ioc_map_memory_to_gpu() as u64 {
                issues.push(format!(
                    "slot {} {} map-memory ioctl 0x{:x} != expected 0x{:x}",
                    entry.slot,
                    entry.tensor,
                    entry.map_memory_ioctl,
                    mainarch_sys::ioc_map_memory_to_gpu() as u64
                ));
            }
            if entry.resident_gpu_ids != self.resident_gpu_ids {
                issues.push(format!(
                    "slot {} {} resident GPU IDs do not match plan",
                    entry.slot, entry.tensor
                ));
            }
            if entry.resident_gpu_id_count != entry.resident_gpu_ids.len() {
                issues.push(format!(
                    "slot {} {} resident GPU ID count {} != IDs {}",
                    entry.slot,
                    entry.tensor,
                    entry.resident_gpu_id_count,
                    entry.resident_gpu_ids.len()
                ));
            }
            if entry.device_id_count != entry.device_ids.len() {
                issues.push(format!(
                    "slot {} {} device ID count {} != IDs {}",
                    entry.slot,
                    entry.tensor,
                    entry.device_id_count,
                    entry.device_ids.len()
                ));
            }
            match u32::try_from(entry.resident_gpu_id_count) {
                Ok(expected) if entry.map_args_n_devices == expected => {}
                Ok(expected) => issues.push(format!(
                    "slot {} {} map args n_devices {} != resident GPU ID count {}",
                    entry.slot, entry.tensor, entry.map_args_n_devices, expected
                )),
                Err(_) => issues.push(format!(
                    "slot {} {} resident GPU ID count {} exceeds u32",
                    entry.slot, entry.tensor, entry.resident_gpu_id_count
                )),
            }
            if entry.map_args_n_success != 0 {
                issues.push(format!(
                    "slot {} {} pre-call map args n_success {} != 0",
                    entry.slot, entry.tensor, entry.map_args_n_success
                ));
            }
            let expected_handle_bound = entry.map_args_handle != 0;
            if entry.handle_bound != expected_handle_bound {
                issues.push(format!(
                    "slot {} {} handle_bound {} != expected {}",
                    entry.slot, entry.tensor, entry.handle_bound, expected_handle_bound
                ));
            }
            let expected_device_ids_array_bound = entry.map_args_device_ids_array_ptr != 0;
            if entry.device_ids_array_bound != expected_device_ids_array_bound {
                issues.push(format!(
                    "slot {} {} device_ids_array_bound {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.device_ids_array_bound,
                    expected_device_ids_array_bound
                ));
            }
            let expected_device_ids_match = entry.device_ids == entry.resident_gpu_ids;
            if entry.device_ids_match_resident_gpu_ids != expected_device_ids_match {
                issues.push(format!(
                    "slot {} {} device_ids_match_resident_gpu_ids {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.device_ids_match_resident_gpu_ids,
                    expected_device_ids_match
                ));
            }
            if entry.result_binding_present {
                matched_result_binding_count += 1;
            } else {
                missing_result_binding_count += 1;
            }
            if entry.handle_bound {
                handle_bound_count += 1;
            }
            if entry.device_ids_array_bound {
                device_ids_array_bound_count += 1;
            }
            if entry.device_ids_match_resident_gpu_ids {
                device_ids_array_match_count += 1;
            }
            if entry.allocation_performed {
                allocation_performed_count += 1;
            }
            let expected_map_memory_performed = entry.result_binding_present;
            if entry.map_memory_performed != expected_map_memory_performed {
                issues.push(format!(
                    "slot {} {} map_memory_performed {} != result binding present {}",
                    entry.slot,
                    entry.tensor,
                    entry.map_memory_performed,
                    entry.result_binding_present
                ));
            }
            if entry.map_memory_performed {
                map_memory_performed_count += 1;
            }
            let result_args_match = entry.result_binding_present
                && entry.result_map_args_handle == entry.map_args_handle
                && entry.result_map_args_device_ids_array_ptr
                    == entry.map_args_device_ids_array_ptr
                && entry.result_map_args_n_devices == entry.map_args_n_devices;
            let result_success_matches_residents = entry.result_binding_present
                && entry.result_map_args_n_success == entry.map_args_n_devices
                && usize::try_from(entry.result_map_args_n_success).ok()
                    == Some(entry.resident_gpu_id_count);
            let expected_map_memory_successful = entry.argument_binding_ready
                && result_args_match
                && result_success_matches_residents
                && entry.map_args_n_success == 0
                && entry.issue_count == 0;
            if entry.map_memory_successful != expected_map_memory_successful {
                issues.push(format!(
                    "slot {} {} map_memory_successful {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.map_memory_successful,
                    expected_map_memory_successful
                ));
            }
            if entry.map_memory_successful {
                map_memory_success_count += 1;
            }
            let expected_result_metadata_ready = self.map_memory_argument_binding_ready
                && entry.map_memory_successful
                && entry.issue_count == 0;
            if entry.result_metadata_ready != expected_result_metadata_ready {
                issues.push(format!(
                    "slot {} {} result_metadata_ready {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.result_metadata_ready,
                    expected_result_metadata_ready
                ));
            }
            if !entry.result_metadata_ready {
                entries_ready = false;
            }
            total_storage_bytes = checked_add_usize(
                total_storage_bytes,
                entry.storage_bytes,
                "KFD map-memory result storage bytes",
            )?;
            total_map_memory_bytes = checked_add_usize(
                total_map_memory_bytes,
                entry.requested_bytes,
                "KFD map-memory result bytes",
            )?;
            total_device_id_count = checked_add_usize(
                total_device_id_count,
                entry.device_id_count,
                "KFD map-memory result device ID count",
            )?;
            entry_issue_count = checked_add_usize(
                entry_issue_count,
                entry.issue_count,
                "KFD map-memory result entry issues",
            )?;
        }

        if matched_result_binding_count != self.matched_result_binding_count {
            issues.push(format!(
                "matched result binding count {matched_result_binding_count} != plan {}",
                self.matched_result_binding_count
            ));
        }
        if missing_result_binding_count != self.missing_result_binding_count {
            issues.push(format!(
                "missing result binding count {missing_result_binding_count} != plan {}",
                self.missing_result_binding_count
            ));
        }
        if handle_bound_count != self.handle_bound_count {
            issues.push(format!(
                "handle bound count {handle_bound_count} != plan {}",
                self.handle_bound_count
            ));
        }
        if device_ids_array_bound_count != self.device_ids_array_bound_count {
            issues.push(format!(
                "device ID array bound count {device_ids_array_bound_count} != plan {}",
                self.device_ids_array_bound_count
            ));
        }
        if device_ids_array_match_count != self.device_ids_array_match_count {
            issues.push(format!(
                "device ID array match count {device_ids_array_match_count} != plan {}",
                self.device_ids_array_match_count
            ));
        }
        if allocation_performed_count != self.allocation_performed_count {
            issues.push(format!(
                "allocation performed count {allocation_performed_count} != plan {}",
                self.allocation_performed_count
            ));
        }
        if map_memory_performed_count != self.map_memory_performed_count {
            issues.push(format!(
                "map-memory performed count {map_memory_performed_count} != plan {}",
                self.map_memory_performed_count
            ));
        }
        if map_memory_success_count != self.map_memory_success_count {
            issues.push(format!(
                "map-memory success count {map_memory_success_count} != plan {}",
                self.map_memory_success_count
            ));
        }
        if total_storage_bytes != self.total_storage_bytes {
            issues.push(format!(
                "total storage bytes {total_storage_bytes} != plan {}",
                self.total_storage_bytes
            ));
        }
        if total_map_memory_bytes != self.total_map_memory_bytes {
            issues.push(format!(
                "total map-memory bytes {total_map_memory_bytes} != plan {}",
                self.total_map_memory_bytes
            ));
        }
        if total_device_id_count != self.total_device_id_count {
            issues.push(format!(
                "total device ID count {total_device_id_count} != plan {}",
                self.total_device_id_count
            ));
        }
        let slot_issue_rows = self
            .issues
            .iter()
            .filter(|issue| issue.slot.is_some())
            .count();
        let accounted_slot_issues = entry_issue_count
            .checked_add(self.duplicate_result_binding_count)
            .and_then(|count| count.checked_add(self.unmatched_result_binding_count))
            .ok_or_else(|| anyhow!("KFD map-memory result issue count overflows"))?;
        if accounted_slot_issues != slot_issue_rows {
            issues.push(format!(
                "accounted slot issue count {accounted_slot_issues} != slot issue rows {slot_issue_rows}"
            ));
        }
        let expected_all_result_bindings_ready = self.map_memory_argument_binding_ready
            && self.map_memory_request_count > 0
            && self.matched_result_binding_count == self.map_memory_request_count
            && self.missing_result_binding_count == 0
            && self.duplicate_result_binding_count == 0
            && self.unmatched_result_binding_count == 0
            && self.result_issue_count == 0
            && entries_ready;
        if self.all_result_bindings_ready != expected_all_result_bindings_ready {
            issues.push(format!(
                "all_result_bindings_ready {} != expected {}",
                self.all_result_bindings_ready, expected_all_result_bindings_ready
            ));
        }
        let expected_map_memory_performed = self.map_memory_request_count > 0
            && self.map_memory_performed_count == self.map_memory_request_count;
        if self.map_memory_performed != expected_map_memory_performed {
            issues.push(format!(
                "map_memory_performed {} != expected {}",
                self.map_memory_performed, expected_map_memory_performed
            ));
        }
        let expected_residency_proven = self.all_result_bindings_ready
            && self.map_memory_request_count > 0
            && self.map_memory_success_count == self.map_memory_request_count;
        if self.residency_proven != expected_residency_proven {
            issues.push(format!(
                "residency_proven {} != expected {}",
                self.residency_proven, expected_residency_proven
            ));
        }
        if self.live_execution_supported != MODEL_API_CONTRACT.live_execution_supported {
            issues.push(format!(
                "live execution support {} != contract {}",
                self.live_execution_supported, MODEL_API_CONTRACT.live_execution_supported
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD map-memory result binding plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn assert_kfd_map_memory_result_bound(&self) -> Result<()> {
        let mut issues = Vec::new();
        if let Err(err) = self.assert_consistent() {
            issues.push(format!("consistency: {err}"));
        }
        if !self.map_memory_argument_binding_ready {
            issues.push("KFD map-memory argument bindings are not ready".to_string());
        }
        if self.map_memory_request_count == 0 {
            issues.push("no KFD map-memory requests available for result binding".to_string());
        }
        if self.missing_result_binding_count > 0 {
            issues.push(format!(
                "missing map-memory result bindings: {}",
                self.missing_result_binding_count
            ));
        }
        if self.duplicate_result_binding_count > 0 {
            issues.push(format!(
                "duplicate map-memory result bindings: {}",
                self.duplicate_result_binding_count
            ));
        }
        if self.unmatched_result_binding_count > 0 {
            issues.push(format!(
                "unmatched map-memory result bindings: {}",
                self.unmatched_result_binding_count
            ));
        }
        if self.map_memory_performed_count != self.map_memory_request_count {
            issues.push("map-memory result receipts do not cover every request".to_string());
        }
        if self.map_memory_success_count != self.map_memory_request_count {
            issues.push(
                "map-memory result receipts do not report every resident GPU ID mapped".to_string(),
            );
        }
        if self.result_issue_count > 0 {
            issues.push(format!("result issues: {}", self.result_issue_count));
        }
        if !self.all_result_bindings_ready {
            issues.push("not all map-memory result bindings are ready".to_string());
        }
        if !self.map_memory_performed {
            issues.push(
                "KFD map-memory has not been marked performed by result receipts".to_string(),
            );
        }
        if !self.residency_proven {
            issues.push(
                "map-memory residency is not proven by successful result receipts".to_string(),
            );
        }
        if self.live_execution_supported {
            issues.push("live execution support is unexpectedly enabled".to_string());
        }
        let issue_details = self
            .issues
            .iter()
            .map(runtime_kfd_map_memory_result_binding_issue_label)
            .collect::<Vec<_>>();
        if !issue_details.is_empty() {
            issues.push(issue_details.join("; "));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime KFD map-memory result binding plan for {} is not ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn runtime_kfd_map_memory_result_binding_issue_label(
    issue: &RuntimeKfdMapMemoryResultBindingIssue,
) -> String {
    match (&issue.slot, &issue.tensor) {
        (Some(slot), Some(tensor)) => format!("slot {slot} {tensor}: {}", issue.message),
        (Some(slot), None) => format!("slot {slot}: {}", issue.message),
        (None, Some(tensor)) => format!("{tensor}: {}", issue.message),
        (None, None) => issue.message.clone(),
    }
}

fn runtime_kfd_map_memory_result_binding_plan_from(
    argument_bindings: &ModelRuntimeKfdMapMemoryArgumentBindingPlan,
    result_bindings: &[RuntimeKfdMapMemoryResultBinding],
) -> ModelRuntimeKfdMapMemoryResultBindingPlan {
    let mut issues = Vec::new();
    let map_memory_argument_binding_ready =
        match argument_bindings.assert_kfd_map_memory_arguments_bound() {
            Ok(()) => true,
            Err(err) => {
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: None,
                    tensor: None,
                    message: format!("KFD map-memory argument binding plan is not ready: {err}"),
                });
                false
            }
        };

    let request_slots = argument_bindings
        .entries
        .iter()
        .map(|entry| entry.slot)
        .collect::<BTreeSet<_>>();
    let mut result_by_slot = BTreeMap::new();
    let mut duplicate_result_binding_count = 0usize;
    let mut unmatched_result_binding_count = 0usize;
    for binding in result_bindings {
        if !request_slots.contains(&binding.slot) {
            unmatched_result_binding_count += 1;
            issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                slot: Some(binding.slot),
                tensor: Some(binding.tensor.clone()),
                message: "map-memory result binding does not match a request slot".to_string(),
            });
            continue;
        }
        if result_by_slot.insert(binding.slot, binding).is_some() {
            duplicate_result_binding_count += 1;
            issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                slot: Some(binding.slot),
                tensor: Some(binding.tensor.clone()),
                message: "duplicate map-memory result binding for slot".to_string(),
            });
        }
    }

    let mut entries = Vec::new();
    let mut matched_result_binding_count = 0usize;
    let mut missing_result_binding_count = 0usize;
    let mut handle_bound_count = 0usize;
    let mut device_ids_array_bound_count = 0usize;
    let mut device_ids_array_match_count = 0usize;
    let mut allocation_performed_count = 0usize;
    let mut map_memory_performed_count = 0usize;
    let mut map_memory_success_count = 0usize;
    let mut total_storage_bytes = 0usize;
    let mut total_map_memory_bytes = 0usize;
    let mut total_device_id_count = 0usize;

    for argument in &argument_bindings.entries {
        let mut entry_issue_count = 0usize;
        if !argument.map_memory_argument_ready {
            entry_issue_count += 1;
            issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                slot: Some(argument.slot),
                tensor: Some(argument.tensor.clone()),
                message: "map-memory argument binding is not ready".to_string(),
            });
        }
        if argument.map_args_n_success != 0 {
            entry_issue_count += 1;
            issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                slot: Some(argument.slot),
                tensor: Some(argument.tensor.clone()),
                message: "map-memory argument n_success is not zero before ioctl".to_string(),
            });
        }

        let result = result_by_slot.get(&argument.slot).copied();
        let (
            result_binding_present,
            result_map_args_handle,
            result_map_args_device_ids_array_ptr,
            result_map_args_n_devices,
            result_map_args_n_success,
        ) = match result {
            Some(binding) => {
                matched_result_binding_count += 1;
                (
                    true,
                    binding.map_args_handle,
                    binding.map_args_device_ids_array_ptr,
                    binding.map_args_n_devices,
                    binding.map_args_n_success,
                )
            }
            None => {
                missing_result_binding_count += 1;
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: "missing map-memory result binding".to_string(),
                });
                (
                    false,
                    argument.map_args_handle,
                    argument.map_args_device_ids_array_ptr,
                    argument.map_args_n_devices,
                    0,
                )
            }
        };

        if let Some(binding) = result {
            if binding.tensor != argument.tensor {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: format!(
                        "result tensor {} != map-memory argument tensor {}",
                        binding.tensor, argument.tensor
                    ),
                });
            }
            if binding.map_args_handle != argument.map_args_handle {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: format!(
                        "result handle 0x{:x} != map args handle 0x{:x}",
                        binding.map_args_handle, argument.map_args_handle
                    ),
                });
            }
            if binding.map_args_device_ids_array_ptr != argument.map_args_device_ids_array_ptr {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: format!(
                        "result device ID array pointer 0x{:x} != map args device_ids_array_ptr 0x{:x}",
                        binding.map_args_device_ids_array_ptr, argument.map_args_device_ids_array_ptr
                    ),
                });
            }
            if binding.map_args_n_devices != argument.map_args_n_devices {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: format!(
                        "result n_devices {} != map args n_devices {}",
                        binding.map_args_n_devices, argument.map_args_n_devices
                    ),
                });
            }
            if binding.map_args_n_success != argument.map_args_n_devices {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: format!(
                        "result n_success {} did not map every resident GPU ID (expected {})",
                        binding.map_args_n_success, argument.map_args_n_devices
                    ),
                });
            }
            if usize::try_from(binding.map_args_n_success).ok()
                != Some(argument.resident_gpu_id_count)
            {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: format!(
                        "result n_success {} != resident GPU ID count {}",
                        binding.map_args_n_success, argument.resident_gpu_id_count
                    ),
                });
            }
        }

        let handle_bound = argument.handle_bound;
        if handle_bound {
            handle_bound_count += 1;
        }
        let device_ids_array_bound = argument.device_ids_array_bound;
        if device_ids_array_bound {
            device_ids_array_bound_count += 1;
        }
        let device_ids_match_resident_gpu_ids = argument.device_ids_match_resident_gpu_ids;
        if device_ids_match_resident_gpu_ids {
            device_ids_array_match_count += 1;
        }
        let allocation_performed = argument.allocation_performed;
        if allocation_performed {
            allocation_performed_count += 1;
        }
        let map_memory_performed = result_binding_present;
        if map_memory_performed {
            map_memory_performed_count += 1;
        }
        let result_args_match = result_binding_present
            && result_map_args_handle == argument.map_args_handle
            && result_map_args_device_ids_array_ptr == argument.map_args_device_ids_array_ptr
            && result_map_args_n_devices == argument.map_args_n_devices;
        let result_success_matches_residents = result_binding_present
            && result_map_args_n_success == argument.map_args_n_devices
            && usize::try_from(result_map_args_n_success).ok()
                == Some(argument.resident_gpu_id_count);
        let map_memory_successful = argument.map_memory_argument_ready
            && result_args_match
            && result_success_matches_residents
            && argument.map_args_n_success == 0
            && entry_issue_count == 0;
        if map_memory_successful {
            map_memory_success_count += 1;
        }
        match total_storage_bytes.checked_add(argument.storage_bytes) {
            Some(total) => total_storage_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: "total storage bytes overflow".to_string(),
                });
            }
        }
        match total_map_memory_bytes.checked_add(argument.requested_bytes) {
            Some(total) => total_map_memory_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: "total map-memory bytes overflow".to_string(),
                });
            }
        }
        match total_device_id_count.checked_add(argument.device_id_count) {
            Some(total) => total_device_id_count = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeKfdMapMemoryResultBindingIssue {
                    slot: Some(argument.slot),
                    tensor: Some(argument.tensor.clone()),
                    message: "total map-memory device ID count overflow".to_string(),
                });
            }
        }
        let result_metadata_ready =
            map_memory_argument_binding_ready && map_memory_successful && entry_issue_count == 0;

        entries.push(RuntimeKfdMapMemoryResultBindingEntry {
            slot: argument.slot,
            tensor: argument.tensor.clone(),
            class: argument.class,
            lifetime_access: argument.lifetime_access,
            allocation_kind: argument.allocation_kind,
            allocation_gpu_id: argument.allocation_gpu_id,
            map_memory_ioctl: argument.map_memory_ioctl,
            map_args_handle: argument.map_args_handle,
            result_map_args_handle,
            map_args_device_ids_array_ptr: argument.map_args_device_ids_array_ptr,
            result_map_args_device_ids_array_ptr,
            map_args_n_devices: argument.map_args_n_devices,
            result_map_args_n_devices,
            map_args_n_success: argument.map_args_n_success,
            result_map_args_n_success,
            device_ids: argument.device_ids.clone(),
            device_id_count: argument.device_id_count,
            storage_bytes: argument.storage_bytes,
            requested_bytes: argument.requested_bytes,
            resident_gpu_ids: argument.resident_gpu_ids.clone(),
            resident_gpu_id_count: argument.resident_gpu_id_count,
            argument_binding_ready: argument.map_memory_argument_ready,
            result_binding_present,
            handle_bound,
            device_ids_array_bound,
            device_ids_match_resident_gpu_ids,
            allocation_performed,
            map_memory_performed,
            map_memory_successful,
            result_metadata_ready,
            issue_count: entry_issue_count,
        });
    }

    let map_memory_request_count = argument_bindings.map_memory_request_count;
    let result_issue_count = issues.len();
    let all_result_bindings_ready = map_memory_argument_binding_ready
        && map_memory_request_count > 0
        && matched_result_binding_count == map_memory_request_count
        && missing_result_binding_count == 0
        && duplicate_result_binding_count == 0
        && unmatched_result_binding_count == 0
        && result_issue_count == 0
        && entries
            .iter()
            .all(|entry| entry.result_metadata_ready && entry.issue_count == 0);
    let map_memory_performed =
        map_memory_request_count > 0 && map_memory_performed_count == map_memory_request_count;
    let residency_proven = all_result_bindings_ready
        && map_memory_request_count > 0
        && map_memory_success_count == map_memory_request_count;

    ModelRuntimeKfdMapMemoryResultBindingPlan {
        target: argument_bindings.target,
        result_source: MODEL_RUNTIME_KFD_MAP_MEMORY_RESULT_BINDING_SOURCE,
        kfd_device_path: mainarch_sys::KFD_DEVICE,
        resident_gpu_ids: argument_bindings.resident_gpu_ids.clone(),
        resident_gpu_id_count: argument_bindings.resident_gpu_id_count,
        slot_count: argument_bindings.slot_count,
        map_memory_request_count,
        argument_binding_count: argument_bindings.entries.len(),
        result_binding_count: result_bindings.len(),
        matched_result_binding_count,
        missing_result_binding_count,
        duplicate_result_binding_count,
        unmatched_result_binding_count,
        handle_bound_count,
        device_ids_array_bound_count,
        device_ids_array_match_count,
        allocation_performed_count,
        map_memory_performed_count,
        map_memory_success_count,
        total_storage_bytes,
        total_map_memory_bytes,
        total_device_id_count,
        result_issue_count,
        map_memory_argument_binding_ready,
        all_result_bindings_ready,
        map_memory_performed,
        residency_proven,
        live_execution_supported: MODEL_API_CONTRACT.live_execution_supported,
        entries,
        issues,
    }
}

const MODEL_RUNTIME_SLOT_KFD_RESIDENCY_BINDING_SOURCE: &str =
    "mainarch_kfd_slot_residency_binding_v0";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeSlotKfdResidencyBindingEntry {
    pub slot: usize,
    pub tensor: TensorRef,
    pub class: TensorBindingClass,
    pub lifetime_access: TensorBindingAccess,
    pub allocation_kind: RuntimeSlotKfdAllocationKind,
    pub allocation_gpu_id: u32,
    pub device_va: u64,
    pub device_va_end: Option<u64>,
    pub storage_bytes: usize,
    pub requested_bytes: usize,
    pub allocation_handle: u64,
    pub device_ids_array_ptr: u64,
    pub map_args_n_devices: u32,
    pub result_map_args_n_success: u32,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub allocation_request_ready: bool,
    pub map_memory_result_present: bool,
    pub device_pointer_bound: bool,
    pub allocation_performed: bool,
    pub handle_bound: bool,
    pub device_ids_array_bound: bool,
    pub map_memory_performed: bool,
    pub map_memory_successful: bool,
    pub result_metadata_ready: bool,
    pub kfd_residency_proven: bool,
    pub issue_count: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeSlotKfdResidencyBindingIssue {
    pub slot: Option<usize>,
    pub tensor: Option<TensorRef>,
    pub message: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeSlotKfdResidencyBindingPlan {
    pub target: &'static str,
    pub binding_source: &'static str,
    pub kfd_device_path: &'static str,
    pub resident_gpu_ids: Vec<u32>,
    pub resident_gpu_id_count: usize,
    pub slot_count: usize,
    pub request_count: usize,
    pub map_memory_result_entry_count: usize,
    pub matched_map_memory_result_count: usize,
    pub missing_map_memory_result_count: usize,
    pub host_visible_gtt_binding_count: usize,
    pub device_local_vram_binding_count: usize,
    pub device_pointer_bound_count: usize,
    pub allocation_performed_count: usize,
    pub handle_bound_count: usize,
    pub device_ids_array_bound_count: usize,
    pub map_memory_performed_count: usize,
    pub map_memory_success_count: usize,
    pub residency_proven_count: usize,
    pub total_storage_bytes: usize,
    pub total_requested_bytes: usize,
    pub residency_map_count: usize,
    pub binding_issue_count: usize,
    pub allocation_residency_request_ready: bool,
    pub map_memory_result_binding_ready: bool,
    pub all_residency_bindings_ready: bool,
    pub allocation_performed: bool,
    pub residency_proven: bool,
    pub live_execution_supported: bool,
    pub entries: Vec<RuntimeSlotKfdResidencyBindingEntry>,
    pub issues: Vec<RuntimeSlotKfdResidencyBindingIssue>,
}

impl ModelRuntimeSlotKfdResidencyBindingPlan {
    pub fn entry_for(&self, tensor: &str) -> Option<&RuntimeSlotKfdResidencyBindingEntry> {
        self.entries
            .iter()
            .find(|entry| entry.tensor.as_str() == tensor)
    }

    pub fn entry_for_slot(&self, slot: usize) -> Option<&RuntimeSlotKfdResidencyBindingEntry> {
        self.entries.iter().find(|entry| entry.slot == slot)
    }

    pub fn is_kfd_residency_bound(&self) -> bool {
        self.assert_kfd_residency_bound().is_ok()
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.binding_source != MODEL_RUNTIME_SLOT_KFD_RESIDENCY_BINDING_SOURCE {
            issues.push(format!(
                "binding source {} != {}",
                self.binding_source, MODEL_RUNTIME_SLOT_KFD_RESIDENCY_BINDING_SOURCE
            ));
        }
        if self.kfd_device_path != mainarch_sys::KFD_DEVICE {
            issues.push(format!(
                "KFD device path {} != {}",
                self.kfd_device_path,
                mainarch_sys::KFD_DEVICE
            ));
        }
        if self.entries.len() != self.request_count {
            issues.push(format!(
                "entry count {} != request count {}",
                self.entries.len(),
                self.request_count
            ));
        }
        let resident_gpu_ids = self
            .resident_gpu_ids
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if resident_gpu_ids.len() != self.resident_gpu_ids.len() {
            issues.push("resident GPU IDs contain duplicates".to_string());
        }
        let canonical_resident_gpu_ids = resident_gpu_ids.iter().copied().collect::<Vec<_>>();
        if canonical_resident_gpu_ids != self.resident_gpu_ids {
            issues.push("resident GPU IDs are not sorted and unique".to_string());
        }
        if self.resident_gpu_id_count != self.resident_gpu_ids.len() {
            issues.push(format!(
                "resident GPU ID count {} != IDs {}",
                self.resident_gpu_id_count,
                self.resident_gpu_ids.len()
            ));
        }
        match self.request_count.checked_mul(self.resident_gpu_id_count) {
            Some(expected) if expected == self.residency_map_count => {}
            Some(expected) => issues.push(format!(
                "residency map count {} != expected {}",
                self.residency_map_count, expected
            )),
            None => issues.push("residency map count overflows".to_string()),
        }
        if self.binding_issue_count != self.issues.len() {
            issues.push(format!(
                "binding issue count {} != issue rows {}",
                self.binding_issue_count,
                self.issues.len()
            ));
        }
        match self
            .matched_map_memory_result_count
            .checked_add(self.missing_map_memory_result_count)
        {
            Some(expected) if expected == self.request_count => {}
            Some(expected) => issues.push(format!(
                "map-memory result accounting {} != request count {}",
                expected, self.request_count
            )),
            None => issues.push("map-memory result accounting overflows".to_string()),
        }
        if self.map_memory_result_entry_count < self.matched_map_memory_result_count {
            issues.push(format!(
                "map-memory result entry count {} < matched result count {}",
                self.map_memory_result_entry_count, self.matched_map_memory_result_count
            ));
        }

        let mut seen_slots = BTreeSet::new();
        let mut matched_map_memory_result_count = 0usize;
        let mut missing_map_memory_result_count = 0usize;
        let mut host_visible_gtt_binding_count = 0usize;
        let mut device_local_vram_binding_count = 0usize;
        let mut device_pointer_bound_count = 0usize;
        let mut allocation_performed_count = 0usize;
        let mut handle_bound_count = 0usize;
        let mut device_ids_array_bound_count = 0usize;
        let mut map_memory_performed_count = 0usize;
        let mut map_memory_success_count = 0usize;
        let mut residency_proven_count = 0usize;
        let mut total_storage_bytes = 0usize;
        let mut total_requested_bytes = 0usize;
        let mut entry_issue_count = 0usize;
        let mut entries_ready = true;

        for entry in &self.entries {
            if !seen_slots.insert(entry.slot) {
                issues.push(format!("slot {} appears more than once", entry.slot));
            }
            if entry.tensor.as_str().trim().is_empty() {
                issues.push(format!("slot {} has empty tensor name", entry.slot));
            }
            match entry.allocation_kind {
                RuntimeSlotKfdAllocationKind::HostVisibleGtt => {
                    host_visible_gtt_binding_count += 1;
                }
                RuntimeSlotKfdAllocationKind::DeviceLocalVramPreferPublicCoherent => {
                    device_local_vram_binding_count += 1;
                }
            }
            if entry.requested_bytes < entry.storage_bytes {
                issues.push(format!(
                    "slot {} {} requested bytes {} < storage bytes {}",
                    entry.slot, entry.tensor, entry.requested_bytes, entry.storage_bytes
                ));
            }
            if entry.device_va == 0 {
                issues.push(format!(
                    "slot {} {} device VA is null",
                    entry.slot, entry.tensor
                ));
            }
            match (
                entry.device_va_end,
                entry.device_va.checked_add(entry.storage_bytes as u64),
            ) {
                (Some(actual), Some(required)) if actual >= required => {}
                (actual, required) => issues.push(format!(
                    "slot {} {} device VA end {:?} does not cover storage span end {:?}",
                    entry.slot, entry.tensor, actual, required
                )),
            }
            if entry.resident_gpu_ids != self.resident_gpu_ids {
                issues.push(format!(
                    "slot {} {} resident GPU IDs do not match plan",
                    entry.slot, entry.tensor
                ));
            }
            if entry.resident_gpu_id_count != entry.resident_gpu_ids.len() {
                issues.push(format!(
                    "slot {} {} resident GPU ID count {} != IDs {}",
                    entry.slot,
                    entry.tensor,
                    entry.resident_gpu_id_count,
                    entry.resident_gpu_ids.len()
                ));
            }
            match u32::try_from(entry.resident_gpu_id_count) {
                Ok(expected) if entry.map_args_n_devices == expected => {}
                Ok(expected) => issues.push(format!(
                    "slot {} {} map args n_devices {} != resident GPU ID count {}",
                    entry.slot, entry.tensor, entry.map_args_n_devices, expected
                )),
                Err(_) => issues.push(format!(
                    "slot {} {} resident GPU ID count {} exceeds u32",
                    entry.slot, entry.tensor, entry.resident_gpu_id_count
                )),
            }
            if entry.map_memory_result_present {
                matched_map_memory_result_count += 1;
            } else {
                missing_map_memory_result_count += 1;
            }
            if entry.device_pointer_bound {
                device_pointer_bound_count += 1;
            }
            if entry.allocation_performed {
                allocation_performed_count += 1;
            }
            if entry.handle_bound {
                handle_bound_count += 1;
            }
            if entry.device_ids_array_bound {
                device_ids_array_bound_count += 1;
            }
            if entry.map_memory_performed {
                map_memory_performed_count += 1;
            }
            if entry.map_memory_successful {
                map_memory_success_count += 1;
            }
            let expected_kfd_residency_proven = self.allocation_residency_request_ready
                && self.map_memory_result_binding_ready
                && entry.allocation_request_ready
                && entry.map_memory_result_present
                && entry.device_pointer_bound
                && entry.allocation_performed
                && entry.handle_bound
                && entry.device_ids_array_bound
                && entry.map_memory_performed
                && entry.map_memory_successful
                && entry.result_metadata_ready
                && entry.issue_count == 0;
            if entry.kfd_residency_proven != expected_kfd_residency_proven {
                issues.push(format!(
                    "slot {} {} kfd_residency_proven {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.kfd_residency_proven,
                    expected_kfd_residency_proven
                ));
            }
            if entry.kfd_residency_proven {
                residency_proven_count += 1;
            } else {
                entries_ready = false;
            }
            total_storage_bytes = checked_add_usize(
                total_storage_bytes,
                entry.storage_bytes,
                "KFD residency binding storage bytes",
            )?;
            total_requested_bytes = checked_add_usize(
                total_requested_bytes,
                entry.requested_bytes,
                "KFD residency binding requested bytes",
            )?;
            entry_issue_count = checked_add_usize(
                entry_issue_count,
                entry.issue_count,
                "KFD residency binding entry issues",
            )?;
        }

        if matched_map_memory_result_count != self.matched_map_memory_result_count {
            issues.push(format!(
                "matched map-memory result count {matched_map_memory_result_count} != plan {}",
                self.matched_map_memory_result_count
            ));
        }
        if missing_map_memory_result_count != self.missing_map_memory_result_count {
            issues.push(format!(
                "missing map-memory result count {missing_map_memory_result_count} != plan {}",
                self.missing_map_memory_result_count
            ));
        }
        if host_visible_gtt_binding_count != self.host_visible_gtt_binding_count {
            issues.push(format!(
                "host-visible GTT binding count {host_visible_gtt_binding_count} != plan {}",
                self.host_visible_gtt_binding_count
            ));
        }
        if device_local_vram_binding_count != self.device_local_vram_binding_count {
            issues.push(format!(
                "device-local VRAM binding count {device_local_vram_binding_count} != plan {}",
                self.device_local_vram_binding_count
            ));
        }
        if device_pointer_bound_count != self.device_pointer_bound_count {
            issues.push(format!(
                "device pointer bound count {device_pointer_bound_count} != plan {}",
                self.device_pointer_bound_count
            ));
        }
        if allocation_performed_count != self.allocation_performed_count {
            issues.push(format!(
                "allocation performed count {allocation_performed_count} != plan {}",
                self.allocation_performed_count
            ));
        }
        if handle_bound_count != self.handle_bound_count {
            issues.push(format!(
                "handle bound count {handle_bound_count} != plan {}",
                self.handle_bound_count
            ));
        }
        if device_ids_array_bound_count != self.device_ids_array_bound_count {
            issues.push(format!(
                "device ID array bound count {device_ids_array_bound_count} != plan {}",
                self.device_ids_array_bound_count
            ));
        }
        if map_memory_performed_count != self.map_memory_performed_count {
            issues.push(format!(
                "map-memory performed count {map_memory_performed_count} != plan {}",
                self.map_memory_performed_count
            ));
        }
        if map_memory_success_count != self.map_memory_success_count {
            issues.push(format!(
                "map-memory success count {map_memory_success_count} != plan {}",
                self.map_memory_success_count
            ));
        }
        if residency_proven_count != self.residency_proven_count {
            issues.push(format!(
                "residency proven count {residency_proven_count} != plan {}",
                self.residency_proven_count
            ));
        }
        if total_storage_bytes != self.total_storage_bytes {
            issues.push(format!(
                "total storage bytes {total_storage_bytes} != plan {}",
                self.total_storage_bytes
            ));
        }
        if total_requested_bytes != self.total_requested_bytes {
            issues.push(format!(
                "total requested bytes {total_requested_bytes} != plan {}",
                self.total_requested_bytes
            ));
        }
        let slot_issue_rows = self
            .issues
            .iter()
            .filter(|issue| issue.slot.is_some())
            .count();
        if entry_issue_count != slot_issue_rows {
            issues.push(format!(
                "entry issue count {entry_issue_count} != slot issue rows {slot_issue_rows}"
            ));
        }
        let expected_all_residency_bindings_ready = self.allocation_residency_request_ready
            && self.map_memory_result_binding_ready
            && self.request_count > 0
            && self.matched_map_memory_result_count == self.request_count
            && self.missing_map_memory_result_count == 0
            && self.binding_issue_count == 0
            && entries_ready;
        if self.all_residency_bindings_ready != expected_all_residency_bindings_ready {
            issues.push(format!(
                "all_residency_bindings_ready {} != expected {}",
                self.all_residency_bindings_ready, expected_all_residency_bindings_ready
            ));
        }
        let expected_allocation_performed =
            self.request_count > 0 && self.allocation_performed_count == self.request_count;
        if self.allocation_performed != expected_allocation_performed {
            issues.push(format!(
                "allocation_performed {} != expected {}",
                self.allocation_performed, expected_allocation_performed
            ));
        }
        let expected_residency_proven = self.all_residency_bindings_ready
            && self.request_count > 0
            && self.residency_proven_count == self.request_count;
        if self.residency_proven != expected_residency_proven {
            issues.push(format!(
                "residency_proven {} != expected {}",
                self.residency_proven, expected_residency_proven
            ));
        }
        if self.live_execution_supported != MODEL_API_CONTRACT.live_execution_supported {
            issues.push(format!(
                "live execution support {} != contract {}",
                self.live_execution_supported, MODEL_API_CONTRACT.live_execution_supported
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime slot KFD residency binding plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn assert_kfd_residency_bound(&self) -> Result<()> {
        let mut issues = Vec::new();
        if let Err(err) = self.assert_consistent() {
            issues.push(format!("consistency: {err}"));
        }
        if !self.allocation_residency_request_ready {
            issues.push("KFD allocation/residency requests are not ready".to_string());
        }
        if !self.map_memory_result_binding_ready {
            issues.push("KFD map-memory result bindings are not ready".to_string());
        }
        if self.request_count == 0 {
            issues.push("no KFD allocation/residency requests available for binding".to_string());
        }
        if self.missing_map_memory_result_count > 0 {
            issues.push(format!(
                "missing map-memory result bindings: {}",
                self.missing_map_memory_result_count
            ));
        }
        if self.device_pointer_bound_count != self.request_count {
            issues.push("device pointers are not bound for every KFD residency row".to_string());
        }
        if self.allocation_performed_count != self.request_count {
            issues.push(
                "allocation result receipts do not cover every KFD residency row".to_string(),
            );
        }
        if self.handle_bound_count != self.request_count {
            issues.push("allocation handles are not bound for every KFD residency row".to_string());
        }
        if self.device_ids_array_bound_count != self.request_count {
            issues.push("device ID arrays are not bound for every KFD residency row".to_string());
        }
        if self.map_memory_performed_count != self.request_count {
            issues.push("map-memory receipts do not cover every KFD residency row".to_string());
        }
        if self.map_memory_success_count != self.request_count {
            issues.push("map-memory receipts do not map every resident GPU ID".to_string());
        }
        if self.residency_proven_count != self.request_count {
            issues.push("KFD residency is not proven for every slot".to_string());
        }
        if self.binding_issue_count > 0 {
            issues.push(format!("binding issues: {}", self.binding_issue_count));
        }
        if !self.all_residency_bindings_ready {
            issues.push("not all KFD residency bindings are ready".to_string());
        }
        if !self.allocation_performed {
            issues.push("KFD allocation is not marked performed by receipts".to_string());
        }
        if !self.residency_proven {
            issues
                .push("KFD residency is not proven by successful map-memory receipts".to_string());
        }
        if self.live_execution_supported {
            issues.push("live execution support is unexpectedly enabled".to_string());
        }
        let issue_details = self
            .issues
            .iter()
            .map(runtime_slot_kfd_residency_binding_issue_label)
            .collect::<Vec<_>>();
        if !issue_details.is_empty() {
            issues.push(issue_details.join("; "));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime slot KFD residency binding plan for {} is not ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

const MODEL_RUNTIME_CHECKPOINT_PAYLOAD_BINDING_SOURCE: &str =
    "mainarch_checkpoint_payload_slot_binding_v0";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeCheckpointPayloadBinding {
    pub tensor: TensorRef,
    pub checkpoint_key: String,
    pub payload_source: String,
    pub payload_offset: u64,
    pub payload_bytes: usize,
    pub dtype: DType,
    pub shape: Vec<usize>,
}

impl RuntimeCheckpointPayloadBinding {
    pub fn new(
        tensor: impl Into<String>,
        checkpoint_key: impl Into<String>,
        payload_source: impl Into<String>,
        payload_offset: u64,
        payload_bytes: usize,
        dtype: DType,
        shape: Vec<usize>,
    ) -> Result<Self> {
        let checkpoint_key = checkpoint_key.into();
        validate_name("checkpoint payload key", &checkpoint_key)?;
        let payload_source = payload_source.into();
        validate_name("checkpoint payload source", &payload_source)?;
        require_nonempty_shape(&checkpoint_key, &shape)?;
        Ok(Self {
            tensor: TensorRef::new(tensor)?,
            checkpoint_key,
            payload_source,
            payload_offset,
            payload_bytes,
            dtype,
            shape,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeCheckpointPayloadSlotBindingEntry {
    pub slot: usize,
    pub tensor: TensorRef,
    pub checkpoint_key: String,
    pub matched_checkpoint_keys: Vec<String>,
    pub class: TensorBindingClass,
    pub lifetime_access: TensorBindingAccess,
    pub dtype: DType,
    pub shape: Vec<usize>,
    pub storage_bytes: usize,
    pub device_va: u64,
    pub device_va_end: Option<u64>,
    pub allocation_handle: u64,
    pub payload_source_count: usize,
    pub expected_payload_key_count: usize,
    pub matched_payload_key_count: usize,
    pub missing_payload_key_count: usize,
    pub payload_bytes: usize,
    pub resolved_checkpoint_present: bool,
    pub slot_binding_ready: bool,
    pub kfd_residency_present: bool,
    pub kfd_residency_proven: bool,
    pub destination_span_bound: bool,
    pub payload_metadata_ready: bool,
    pub payload_byte_count_matches: bool,
    pub checkpoint_payload_bound: bool,
    pub payload_bindings: Vec<RuntimeCheckpointPayloadBinding>,
    pub issue_count: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeCheckpointPayloadSlotBindingIssue {
    pub slot: Option<usize>,
    pub tensor: Option<TensorRef>,
    pub checkpoint_key: Option<String>,
    pub message: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeCheckpointPayloadBindingPlan {
    pub target: &'static str,
    pub binding_source: &'static str,
    pub checkpoint_entry_count: usize,
    pub checkpoint_weight_slot_count: usize,
    pub resolved_checkpoint_entry_count: usize,
    pub missing_checkpoint_entry_count: usize,
    pub unbound_weight_tensor_count: usize,
    pub expected_payload_binding_count: usize,
    pub payload_binding_count: usize,
    pub matched_payload_binding_count: usize,
    pub missing_payload_binding_count: usize,
    pub duplicate_payload_binding_count: usize,
    pub unmatched_payload_binding_count: usize,
    pub kfd_residency_request_count: usize,
    pub slot_binding_count: usize,
    pub residency_proven_count: usize,
    pub payload_metadata_ready_count: usize,
    pub checkpoint_payload_bound_count: usize,
    pub total_checkpoint_bytes: usize,
    pub total_payload_bytes: usize,
    pub binding_issue_count: usize,
    pub checkpoint_binding_ready: bool,
    pub checkpoint_key_resolution_ready: bool,
    pub kfd_residency_binding_ready: bool,
    pub all_payload_bindings_ready: bool,
    pub checkpoint_payloads_bound: bool,
    pub live_execution_supported: bool,
    pub entries: Vec<RuntimeCheckpointPayloadSlotBindingEntry>,
    pub unmatched_payload_bindings: Vec<RuntimeCheckpointPayloadBinding>,
    pub issues: Vec<RuntimeCheckpointPayloadSlotBindingIssue>,
}

impl ModelRuntimeCheckpointPayloadBindingPlan {
    pub fn entry_for(&self, tensor: &str) -> Option<&RuntimeCheckpointPayloadSlotBindingEntry> {
        self.entries
            .iter()
            .find(|entry| entry.tensor.as_str() == tensor)
    }

    pub fn entry_for_slot(&self, slot: usize) -> Option<&RuntimeCheckpointPayloadSlotBindingEntry> {
        self.entries.iter().find(|entry| entry.slot == slot)
    }

    pub fn is_checkpoint_payload_bound(&self) -> bool {
        self.assert_checkpoint_payload_bound().is_ok()
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.binding_source != MODEL_RUNTIME_CHECKPOINT_PAYLOAD_BINDING_SOURCE {
            issues.push(format!(
                "binding source {} != {}",
                self.binding_source, MODEL_RUNTIME_CHECKPOINT_PAYLOAD_BINDING_SOURCE
            ));
        }
        if self.live_execution_supported != MODEL_API_CONTRACT.live_execution_supported {
            issues.push(format!(
                "live execution support {} != contract {}",
                self.live_execution_supported, MODEL_API_CONTRACT.live_execution_supported
            ));
        }
        if self.entries.len() != self.checkpoint_entry_count {
            issues.push(format!(
                "entry count {} != checkpoint entry count {}",
                self.entries.len(),
                self.checkpoint_entry_count
            ));
        }
        if self.unmatched_payload_bindings.len() != self.unmatched_payload_binding_count {
            issues.push(format!(
                "unmatched payload binding rows {} != unmatched count {}",
                self.unmatched_payload_bindings.len(),
                self.unmatched_payload_binding_count
            ));
        }
        if self.binding_issue_count != self.issues.len() {
            issues.push(format!(
                "binding issue count {} != issue rows {}",
                self.binding_issue_count,
                self.issues.len()
            ));
        }
        match self
            .matched_payload_binding_count
            .checked_add(self.missing_payload_binding_count)
        {
            Some(expected) if expected == self.expected_payload_binding_count => {}
            Some(expected) => issues.push(format!(
                "matched+missing payload count {expected} != expected payload count {}",
                self.expected_payload_binding_count
            )),
            None => issues.push("matched+missing payload count overflows".to_string()),
        }
        match self
            .matched_payload_binding_count
            .checked_add(self.duplicate_payload_binding_count)
            .and_then(|count| count.checked_add(self.unmatched_payload_binding_count))
        {
            Some(expected) if expected == self.payload_binding_count => {}
            Some(expected) => issues.push(format!(
                "matched+duplicate+unmatched payload count {expected} != payload binding count {}",
                self.payload_binding_count
            )),
            None => issues.push("payload binding accounting overflows".to_string()),
        }

        let mut seen_slots = BTreeSet::new();
        let mut expected_payload_binding_count = 0usize;
        let mut matched_payload_binding_count = 0usize;
        let mut missing_payload_binding_count = 0usize;
        let mut slot_binding_count = 0usize;
        let mut residency_proven_count = 0usize;
        let mut payload_metadata_ready_count = 0usize;
        let mut checkpoint_payload_bound_count = 0usize;
        let mut total_checkpoint_bytes = 0usize;
        let mut total_payload_bytes = 0usize;
        let mut entry_issue_count = 0usize;
        let mut entries_bound = true;

        for entry in &self.entries {
            if !seen_slots.insert(entry.slot) {
                issues.push(format!("slot {} appears more than once", entry.slot));
            }
            if entry.class != TensorBindingClass::CheckpointWeight {
                issues.push(format!(
                    "slot {} {} class {:?} is not checkpoint weight",
                    entry.slot, entry.tensor, entry.class
                ));
            }
            if entry.lifetime_access != TensorBindingAccess::ReadOnly {
                issues.push(format!(
                    "slot {} {} lifetime access {:?} is not read-only",
                    entry.slot, entry.tensor, entry.lifetime_access
                ));
            }
            if entry.expected_payload_key_count != entry.matched_checkpoint_keys.len() {
                issues.push(format!(
                    "slot {} {} expected payload key count {} != matched checkpoint keys {}",
                    entry.slot,
                    entry.tensor,
                    entry.expected_payload_key_count,
                    entry.matched_checkpoint_keys.len()
                ));
            }
            match entry
                .matched_payload_key_count
                .checked_add(entry.missing_payload_key_count)
            {
                Some(expected) if expected == entry.expected_payload_key_count => {}
                Some(expected) => issues.push(format!(
                    "slot {} {} matched+missing payload keys {} != expected {}",
                    entry.slot, entry.tensor, expected, entry.expected_payload_key_count
                )),
                None => issues.push(format!(
                    "slot {} {} payload key accounting overflows",
                    entry.slot, entry.tensor
                )),
            }
            if entry.payload_bindings.len() != entry.matched_payload_key_count {
                issues.push(format!(
                    "slot {} {} payload binding rows {} != matched payload keys {}",
                    entry.slot,
                    entry.tensor,
                    entry.payload_bindings.len(),
                    entry.matched_payload_key_count
                ));
            }
            let payload_source_count = entry
                .payload_bindings
                .iter()
                .map(|binding| binding.payload_source.as_str())
                .collect::<BTreeSet<_>>()
                .len();
            if payload_source_count != entry.payload_source_count {
                issues.push(format!(
                    "slot {} {} payload source count {} != entry {}",
                    entry.slot, entry.tensor, payload_source_count, entry.payload_source_count
                ));
            }
            let payload_bytes =
                entry
                    .payload_bindings
                    .iter()
                    .try_fold(0usize, |acc, binding| {
                        checked_add_usize(acc, binding.payload_bytes, "checkpoint payload bytes")
                    })?;
            if payload_bytes != entry.payload_bytes {
                issues.push(format!(
                    "slot {} {} payload bytes {} != entry {}",
                    entry.slot, entry.tensor, payload_bytes, entry.payload_bytes
                ));
            }
            let expected_payload_byte_count_matches = entry.payload_bytes == entry.storage_bytes;
            if entry.payload_byte_count_matches != expected_payload_byte_count_matches {
                issues.push(format!(
                    "slot {} {} payload byte match {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.payload_byte_count_matches,
                    expected_payload_byte_count_matches
                ));
            }
            match (
                entry.device_va_end,
                entry.device_va.checked_add(entry.storage_bytes as u64),
            ) {
                (Some(actual), Some(required)) if actual >= required => {}
                (actual, required) => issues.push(format!(
                    "slot {} {} destination VA end {:?} does not cover storage end {:?}",
                    entry.slot, entry.tensor, actual, required
                )),
            }
            let expected_destination_span_bound =
                entry.kfd_residency_present && entry.kfd_residency_proven && entry.device_va != 0;
            if entry.destination_span_bound != expected_destination_span_bound {
                issues.push(format!(
                    "slot {} {} destination span bound {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.destination_span_bound,
                    expected_destination_span_bound
                ));
            }
            let expected_payload_metadata_ready = entry.resolved_checkpoint_present
                && entry.expected_payload_key_count > 0
                && entry.missing_payload_key_count == 0
                && entry.payload_byte_count_matches
                && entry.issue_count == 0;
            if entry.payload_metadata_ready != expected_payload_metadata_ready {
                issues.push(format!(
                    "slot {} {} payload metadata ready {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.payload_metadata_ready,
                    expected_payload_metadata_ready
                ));
            }
            let expected_checkpoint_payload_bound = self.checkpoint_binding_ready
                && self.checkpoint_key_resolution_ready
                && self.kfd_residency_binding_ready
                && entry.slot_binding_ready
                && entry.destination_span_bound
                && entry.payload_metadata_ready
                && entry.issue_count == 0;
            if entry.checkpoint_payload_bound != expected_checkpoint_payload_bound {
                issues.push(format!(
                    "slot {} {} checkpoint payload bound {} != expected {}",
                    entry.slot,
                    entry.tensor,
                    entry.checkpoint_payload_bound,
                    expected_checkpoint_payload_bound
                ));
            }
            if entry.slot_binding_ready {
                slot_binding_count += 1;
            }
            if entry.kfd_residency_proven {
                residency_proven_count += 1;
            }
            if entry.payload_metadata_ready {
                payload_metadata_ready_count += 1;
            }
            if entry.checkpoint_payload_bound {
                checkpoint_payload_bound_count += 1;
            } else {
                entries_bound = false;
            }
            expected_payload_binding_count = checked_add_usize(
                expected_payload_binding_count,
                entry.expected_payload_key_count,
                "expected checkpoint payload bindings",
            )?;
            matched_payload_binding_count = checked_add_usize(
                matched_payload_binding_count,
                entry.matched_payload_key_count,
                "matched checkpoint payload bindings",
            )?;
            missing_payload_binding_count = checked_add_usize(
                missing_payload_binding_count,
                entry.missing_payload_key_count,
                "missing checkpoint payload bindings",
            )?;
            total_checkpoint_bytes = checked_add_usize(
                total_checkpoint_bytes,
                entry.storage_bytes,
                "checkpoint payload binding storage bytes",
            )?;
            total_payload_bytes = checked_add_usize(
                total_payload_bytes,
                entry.payload_bytes,
                "checkpoint payload binding payload bytes",
            )?;
            entry_issue_count = checked_add_usize(
                entry_issue_count,
                entry.issue_count,
                "checkpoint payload binding entry issues",
            )?;
        }

        if expected_payload_binding_count != self.expected_payload_binding_count {
            issues.push(format!(
                "expected payload binding count {expected_payload_binding_count} != plan {}",
                self.expected_payload_binding_count
            ));
        }
        if matched_payload_binding_count != self.matched_payload_binding_count {
            issues.push(format!(
                "matched payload binding count {matched_payload_binding_count} != plan {}",
                self.matched_payload_binding_count
            ));
        }
        if missing_payload_binding_count != self.missing_payload_binding_count {
            issues.push(format!(
                "missing payload binding count {missing_payload_binding_count} != plan {}",
                self.missing_payload_binding_count
            ));
        }
        if slot_binding_count != self.slot_binding_count {
            issues.push(format!(
                "slot binding count {slot_binding_count} != plan {}",
                self.slot_binding_count
            ));
        }
        if residency_proven_count != self.residency_proven_count {
            issues.push(format!(
                "residency proven count {residency_proven_count} != plan {}",
                self.residency_proven_count
            ));
        }
        if payload_metadata_ready_count != self.payload_metadata_ready_count {
            issues.push(format!(
                "payload metadata ready count {payload_metadata_ready_count} != plan {}",
                self.payload_metadata_ready_count
            ));
        }
        if checkpoint_payload_bound_count != self.checkpoint_payload_bound_count {
            issues.push(format!(
                "checkpoint payload bound count {checkpoint_payload_bound_count} != plan {}",
                self.checkpoint_payload_bound_count
            ));
        }
        if total_checkpoint_bytes != self.total_checkpoint_bytes {
            issues.push(format!(
                "total checkpoint bytes {total_checkpoint_bytes} != plan {}",
                self.total_checkpoint_bytes
            ));
        }
        if total_payload_bytes != self.total_payload_bytes {
            issues.push(format!(
                "total payload bytes {total_payload_bytes} != plan {}",
                self.total_payload_bytes
            ));
        }
        let slot_issue_rows = self
            .issues
            .iter()
            .filter(|issue| issue.slot.is_some())
            .count();
        if entry_issue_count != slot_issue_rows {
            issues.push(format!(
                "entry issue count {entry_issue_count} != slot issue rows {slot_issue_rows}"
            ));
        }
        let expected_all_payload_bindings_ready = self.checkpoint_binding_ready
            && self.checkpoint_key_resolution_ready
            && self.kfd_residency_binding_ready
            && self.checkpoint_entry_count > 0
            && self.missing_payload_binding_count == 0
            && self.duplicate_payload_binding_count == 0
            && self.unmatched_payload_binding_count == 0
            && self.binding_issue_count == 0
            && entries_bound;
        if self.all_payload_bindings_ready != expected_all_payload_bindings_ready {
            issues.push(format!(
                "all payload bindings ready {} != expected {}",
                self.all_payload_bindings_ready, expected_all_payload_bindings_ready
            ));
        }
        let expected_checkpoint_payloads_bound = self.all_payload_bindings_ready
            && self.checkpoint_entry_count > 0
            && self.checkpoint_payload_bound_count == self.checkpoint_entry_count;
        if self.checkpoint_payloads_bound != expected_checkpoint_payloads_bound {
            issues.push(format!(
                "checkpoint payloads bound {} != expected {}",
                self.checkpoint_payloads_bound, expected_checkpoint_payloads_bound
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime checkpoint payload binding plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn assert_checkpoint_payload_bound(&self) -> Result<()> {
        let mut issues = Vec::new();
        if let Err(err) = self.assert_consistent() {
            issues.push(format!("consistency: {err}"));
        }
        if !self.checkpoint_binding_ready {
            issues.push("checkpoint binding plan has unbound weight tensors".to_string());
        }
        if !self.checkpoint_key_resolution_ready {
            issues.push("checkpoint key resolution is not fully resolved".to_string());
        }
        if !self.kfd_residency_binding_ready {
            issues.push("KFD residency is not proven for model runtime slots".to_string());
        }
        if self.checkpoint_entry_count == 0 {
            issues.push("no checkpoint payload entries available for binding".to_string());
        }
        if self.missing_payload_binding_count > 0 {
            issues.push(format!(
                "missing checkpoint payload bindings: {}",
                self.missing_payload_binding_count
            ));
        }
        if self.duplicate_payload_binding_count > 0 {
            issues.push(format!(
                "duplicate checkpoint payload bindings: {}",
                self.duplicate_payload_binding_count
            ));
        }
        if self.unmatched_payload_binding_count > 0 {
            issues.push(format!(
                "unmatched checkpoint payload bindings: {}",
                self.unmatched_payload_binding_count
            ));
        }
        if self.slot_binding_count != self.checkpoint_entry_count {
            issues.push("checkpoint weights are not all bound to runtime slots".to_string());
        }
        if self.residency_proven_count != self.checkpoint_entry_count {
            issues
                .push("checkpoint weight slots do not all have KFD residency receipts".to_string());
        }
        if self.payload_metadata_ready_count != self.checkpoint_entry_count {
            issues
                .push("checkpoint payload metadata is not ready for every weight slot".to_string());
        }
        if self.checkpoint_payload_bound_count != self.checkpoint_entry_count {
            issues.push("checkpoint payloads are not bound for every weight slot".to_string());
        }
        if self.binding_issue_count > 0 {
            issues.push(format!("binding issues: {}", self.binding_issue_count));
        }
        if !self.all_payload_bindings_ready {
            issues.push("not all checkpoint payload bindings are ready".to_string());
        }
        if !self.checkpoint_payloads_bound {
            issues.push("checkpoint payloads are not bound".to_string());
        }
        if self.live_execution_supported {
            issues.push("live execution support is unexpectedly enabled".to_string());
        }
        let issue_details = self
            .issues
            .iter()
            .map(runtime_checkpoint_payload_binding_issue_label)
            .collect::<Vec<_>>();
        if !issue_details.is_empty() {
            issues.push(issue_details.join("; "));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime checkpoint payload binding plan for {} is not ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn runtime_checkpoint_payload_binding_issue_label(
    issue: &RuntimeCheckpointPayloadSlotBindingIssue,
) -> String {
    match (&issue.slot, &issue.tensor, &issue.checkpoint_key) {
        (Some(slot), Some(tensor), Some(key)) => {
            format!("slot {slot} {tensor} {key}: {}", issue.message)
        }
        (Some(slot), Some(tensor), None) => format!("slot {slot} {tensor}: {}", issue.message),
        (Some(slot), None, Some(key)) => format!("slot {slot} {key}: {}", issue.message),
        (Some(slot), None, None) => format!("slot {slot}: {}", issue.message),
        (None, Some(tensor), Some(key)) => format!("{tensor} {key}: {}", issue.message),
        (None, Some(tensor), None) => format!("{tensor}: {}", issue.message),
        (None, None, Some(key)) => format!("{key}: {}", issue.message),
        (None, None, None) => issue.message.clone(),
    }
}

fn checkpoint_payload_expected_shape(entry: &ResolvedCheckpointEntry) -> Result<Vec<usize>> {
    if entry.checkpoint_key.contains('*') {
        if entry.shape.is_empty() {
            return Err(anyhow!(
                "checkpoint payload wildcard entry {} has empty packed shape",
                entry.checkpoint_key
            ));
        }
        Ok(entry.shape[1..].to_vec())
    } else {
        Ok(entry.shape.clone())
    }
}

fn checkpoint_payload_expected_bytes(entry: &ResolvedCheckpointEntry) -> Result<usize> {
    let shape = checkpoint_payload_expected_shape(entry)?;
    let elements = element_count(&shape)?;
    entry.dtype.storage_bytes_for_elements(elements)
}

fn runtime_checkpoint_payload_binding_plan_from(
    checkpoint: &ModelCheckpointBindingPlan,
    slots: &ModelRuntimeSlotPlan,
    key_resolution: &ModelCheckpointKeyResolution,
    kfd_residency: &ModelRuntimeSlotKfdResidencyBindingPlan,
    payload_bindings: &[RuntimeCheckpointPayloadBinding],
) -> ModelRuntimeCheckpointPayloadBindingPlan {
    let checkpoint_binding_ready = checkpoint.missing_weight_tensors.is_empty();
    let checkpoint_key_resolution_ready = key_resolution.assert_fully_resolved().is_ok();
    let kfd_residency_binding_ready = kfd_residency.is_kfd_residency_bound();

    let mut issues = Vec::new();
    if slots.target != kfd_residency.target {
        issues.push(RuntimeCheckpointPayloadSlotBindingIssue {
            slot: None,
            tensor: None,
            checkpoint_key: None,
            message: format!(
                "runtime slot target {} != KFD residency target {}",
                slots.target, kfd_residency.target
            ),
        });
    }
    if !checkpoint_binding_ready {
        for tensor in &checkpoint.missing_weight_tensors {
            issues.push(RuntimeCheckpointPayloadSlotBindingIssue {
                slot: None,
                tensor: Some(tensor.clone()),
                checkpoint_key: None,
                message: "weight tensor has no checkpoint binding".to_string(),
            });
        }
    }
    if !checkpoint_key_resolution_ready {
        for entry in &key_resolution.missing_checkpoint_entries {
            issues.push(RuntimeCheckpointPayloadSlotBindingIssue {
                slot: None,
                tensor: Some(entry.tensor.clone()),
                checkpoint_key: Some(entry.checkpoint_key.clone()),
                message: "checkpoint key did not resolve to payload metadata".to_string(),
            });
        }
        for tensor in &key_resolution.unbound_weight_tensors {
            issues.push(RuntimeCheckpointPayloadSlotBindingIssue {
                slot: None,
                tensor: Some(tensor.clone()),
                checkpoint_key: None,
                message: "checkpoint key resolution carries unbound weight tensor".to_string(),
            });
        }
    }

    let resolved_by_tensor = key_resolution
        .resolved_entries
        .iter()
        .map(|entry| (entry.tensor.clone(), entry))
        .collect::<BTreeMap<_, _>>();
    let mut expected_payload_keys = BTreeSet::new();
    for entry in &key_resolution.resolved_entries {
        for key in &entry.matched_checkpoint_keys {
            expected_payload_keys.insert((entry.tensor.clone(), key.clone()));
        }
    }

    let mut payload_by_key = BTreeMap::new();
    let mut unmatched_payload_bindings = Vec::new();
    let mut duplicate_payload_binding_count = 0usize;
    let mut unmatched_payload_binding_count = 0usize;
    for binding in payload_bindings {
        let key = (binding.tensor.clone(), binding.checkpoint_key.clone());
        if !expected_payload_keys.contains(&key) {
            unmatched_payload_binding_count += 1;
            unmatched_payload_bindings.push(binding.clone());
            issues.push(RuntimeCheckpointPayloadSlotBindingIssue {
                slot: None,
                tensor: Some(binding.tensor.clone()),
                checkpoint_key: Some(binding.checkpoint_key.clone()),
                message: "payload binding does not match a resolved checkpoint key".to_string(),
            });
            continue;
        }
        if payload_by_key.insert(key, binding).is_some() {
            duplicate_payload_binding_count += 1;
            issues.push(RuntimeCheckpointPayloadSlotBindingIssue {
                slot: None,
                tensor: Some(binding.tensor.clone()),
                checkpoint_key: Some(binding.checkpoint_key.clone()),
                message: "duplicate checkpoint payload binding".to_string(),
            });
        }
    }

    let mut entries = Vec::new();
    let mut expected_payload_binding_count = 0usize;
    let mut matched_payload_binding_count = 0usize;
    let mut missing_payload_binding_count = 0usize;
    let mut slot_binding_count = 0usize;
    let mut residency_proven_count = 0usize;
    let mut payload_metadata_ready_count = 0usize;
    let mut checkpoint_payload_bound_count = 0usize;
    let mut total_checkpoint_bytes = 0usize;
    let mut total_payload_bytes = 0usize;

    for checkpoint_entry in &checkpoint.entries {
        let slot = slots.tensor_slot_for(checkpoint_entry.tensor.as_str());
        let resolved = resolved_by_tensor.get(&checkpoint_entry.tensor).copied();
        let residency = kfd_residency.entry_for(checkpoint_entry.tensor.as_str());
        let slot_index = slot.map(|slot| slot.slot).unwrap_or(usize::MAX);
        let class = slot
            .map(|slot| slot.class)
            .unwrap_or(TensorBindingClass::Unused);
        let lifetime_access = slot
            .map(|slot| slot.lifetime_access)
            .unwrap_or(TensorBindingAccess::Unused);
        let mut entry_issues = Vec::new();

        if slot.is_none() {
            entry_issues.push("checkpoint tensor has no runtime slot".to_string());
        }
        if let Some(slot) = slot {
            if slot.class != TensorBindingClass::CheckpointWeight {
                entry_issues.push(format!(
                    "runtime slot class {:?} is not checkpoint weight",
                    slot.class
                ));
            }
            if slot.role != TensorRole::Weight {
                entry_issues.push(format!("runtime slot role {:?} is not weight", slot.role));
            }
            if slot.lifetime_access != TensorBindingAccess::ReadOnly {
                entry_issues.push(format!(
                    "runtime slot lifetime access {:?} is not read-only",
                    slot.lifetime_access
                ));
            }
            if slot.dtype != checkpoint_entry.dtype {
                entry_issues.push(format!(
                    "runtime slot dtype {:?} != checkpoint dtype {:?}",
                    slot.dtype, checkpoint_entry.dtype
                ));
            }
            if slot.storage_bytes != checkpoint_entry.storage_bytes {
                entry_issues.push(format!(
                    "runtime slot bytes {} != checkpoint bytes {}",
                    slot.storage_bytes, checkpoint_entry.storage_bytes
                ));
            }
            if slot.checkpoint_key.as_deref() != Some(checkpoint_entry.checkpoint_key.as_str()) {
                entry_issues.push(format!(
                    "runtime slot checkpoint key {:?} != checkpoint key {}",
                    slot.checkpoint_key, checkpoint_entry.checkpoint_key
                ));
            }
        }
        let slot_binding_ready = slot.is_some()
            && slot
                .map(|slot| {
                    slot.class == TensorBindingClass::CheckpointWeight
                        && slot.role == TensorRole::Weight
                        && slot.lifetime_access == TensorBindingAccess::ReadOnly
                        && slot.dtype == checkpoint_entry.dtype
                        && slot.storage_bytes == checkpoint_entry.storage_bytes
                        && slot.checkpoint_key.as_deref()
                            == Some(checkpoint_entry.checkpoint_key.as_str())
                })
                .unwrap_or(false);
        if slot_binding_ready {
            slot_binding_count += 1;
        }

        let mut device_va = 0u64;
        let mut device_va_end = None;
        let mut allocation_handle = 0u64;
        let mut kfd_residency_proven = false;
        if let Some(residency) = residency {
            device_va = residency.device_va;
            device_va_end = residency.device_va_end;
            allocation_handle = residency.allocation_handle;
            kfd_residency_proven = residency.kfd_residency_proven;
            if residency.slot != slot_index {
                entry_issues.push(format!(
                    "KFD residency slot {} != runtime slot {}",
                    residency.slot, slot_index
                ));
            }
            if residency.class != TensorBindingClass::CheckpointWeight {
                entry_issues.push(format!(
                    "KFD residency class {:?} is not checkpoint weight",
                    residency.class
                ));
            }
            if residency.lifetime_access != TensorBindingAccess::ReadOnly {
                entry_issues.push(format!(
                    "KFD residency lifetime access {:?} is not read-only",
                    residency.lifetime_access
                ));
            }
            if residency.storage_bytes != checkpoint_entry.storage_bytes {
                entry_issues.push(format!(
                    "KFD residency storage bytes {} != checkpoint bytes {}",
                    residency.storage_bytes, checkpoint_entry.storage_bytes
                ));
            }
            if !residency.kfd_residency_proven {
                entry_issues.push("KFD residency receipt is not proven".to_string());
            }
        } else {
            entry_issues.push("checkpoint tensor has no KFD residency row".to_string());
        }
        if kfd_residency_proven {
            residency_proven_count += 1;
        }
        let destination_span_bound = residency.is_some()
            && kfd_residency_proven
            && device_va != 0
            && device_va_end.is_some();

        let (matched_checkpoint_keys, expected_payload_bytes, expected_payload_shape) =
            match resolved {
                Some(resolved) => {
                    let expected_payload_bytes = checkpoint_payload_expected_bytes(resolved)
                        .unwrap_or_else(|err| {
                            entry_issues.push(err.to_string());
                            0
                        });
                    let expected_payload_shape = checkpoint_payload_expected_shape(resolved)
                        .unwrap_or_else(|err| {
                            entry_issues.push(err.to_string());
                            Vec::new()
                        });
                    (
                        resolved.matched_checkpoint_keys.clone(),
                        expected_payload_bytes,
                        expected_payload_shape,
                    )
                }
                None => {
                    entry_issues.push("checkpoint tensor has no resolved key entry".to_string());
                    (Vec::new(), 0, Vec::new())
                }
            };

        let mut payload_rows = Vec::new();
        let mut payload_bytes = 0usize;
        let mut missing_payload_key_count = 0usize;
        for key in &matched_checkpoint_keys {
            expected_payload_binding_count += 1;
            match payload_by_key.get(&(checkpoint_entry.tensor.clone(), key.clone())) {
                Some(binding) => {
                    matched_payload_binding_count += 1;
                    payload_bytes = match checked_add_usize(
                        payload_bytes,
                        binding.payload_bytes,
                        "checkpoint payload bytes",
                    ) {
                        Ok(bytes) => bytes,
                        Err(err) => {
                            entry_issues.push(err.to_string());
                            payload_bytes
                        }
                    };
                    if binding.dtype != checkpoint_entry.dtype {
                        entry_issues.push(format!(
                            "payload {} dtype {:?} != checkpoint dtype {:?}",
                            key, binding.dtype, checkpoint_entry.dtype
                        ));
                    }
                    if binding.shape != expected_payload_shape {
                        entry_issues.push(format!(
                            "payload {} shape {:?} != expected {:?}",
                            key, binding.shape, expected_payload_shape
                        ));
                    }
                    if expected_payload_bytes != 0
                        && binding.payload_bytes != expected_payload_bytes
                    {
                        entry_issues.push(format!(
                            "payload {} bytes {} != expected {}",
                            key, binding.payload_bytes, expected_payload_bytes
                        ));
                    }
                    if binding
                        .payload_offset
                        .checked_add(binding.payload_bytes as u64)
                        .is_none()
                    {
                        entry_issues.push(format!("payload {} file span overflows", key));
                    }
                    payload_rows.push((*binding).clone());
                }
                None => {
                    missing_payload_binding_count += 1;
                    missing_payload_key_count += 1;
                    entry_issues.push(format!("missing payload binding for checkpoint key {key}"));
                }
            }
        }

        let payload_source_count = payload_rows
            .iter()
            .map(|binding| binding.payload_source.as_str())
            .collect::<BTreeSet<_>>()
            .len();
        let payload_byte_count_matches = payload_bytes == checkpoint_entry.storage_bytes;
        if !payload_byte_count_matches {
            entry_issues.push(format!(
                "payload bytes {} != checkpoint storage bytes {}",
                payload_bytes, checkpoint_entry.storage_bytes
            ));
        }
        let resolved_checkpoint_present = resolved.is_some();
        let payload_metadata_ready = resolved_checkpoint_present
            && !matched_checkpoint_keys.is_empty()
            && missing_payload_key_count == 0
            && payload_byte_count_matches
            && entry_issues.is_empty();
        if payload_metadata_ready {
            payload_metadata_ready_count += 1;
        }
        let checkpoint_payload_bound = checkpoint_binding_ready
            && checkpoint_key_resolution_ready
            && kfd_residency_binding_ready
            && slot_binding_ready
            && destination_span_bound
            && payload_metadata_ready
            && entry_issues.is_empty();
        if checkpoint_payload_bound {
            checkpoint_payload_bound_count += 1;
        }

        for message in &entry_issues {
            issues.push(RuntimeCheckpointPayloadSlotBindingIssue {
                slot: slot.map(|slot| slot.slot),
                tensor: Some(checkpoint_entry.tensor.clone()),
                checkpoint_key: Some(checkpoint_entry.checkpoint_key.clone()),
                message: message.clone(),
            });
        }
        total_checkpoint_bytes = match checked_add_usize(
            total_checkpoint_bytes,
            checkpoint_entry.storage_bytes,
            "checkpoint payload binding storage bytes",
        ) {
            Ok(bytes) => bytes,
            Err(err) => {
                issues.push(RuntimeCheckpointPayloadSlotBindingIssue {
                    slot: slot.map(|slot| slot.slot),
                    tensor: Some(checkpoint_entry.tensor.clone()),
                    checkpoint_key: Some(checkpoint_entry.checkpoint_key.clone()),
                    message: err.to_string(),
                });
                total_checkpoint_bytes
            }
        };
        total_payload_bytes = match checked_add_usize(
            total_payload_bytes,
            payload_bytes,
            "checkpoint payload bytes",
        ) {
            Ok(bytes) => bytes,
            Err(err) => {
                issues.push(RuntimeCheckpointPayloadSlotBindingIssue {
                    slot: slot.map(|slot| slot.slot),
                    tensor: Some(checkpoint_entry.tensor.clone()),
                    checkpoint_key: Some(checkpoint_entry.checkpoint_key.clone()),
                    message: err.to_string(),
                });
                total_payload_bytes
            }
        };

        let expected_payload_key_count = matched_checkpoint_keys.len();
        entries.push(RuntimeCheckpointPayloadSlotBindingEntry {
            slot: slot_index,
            tensor: checkpoint_entry.tensor.clone(),
            checkpoint_key: checkpoint_entry.checkpoint_key.clone(),
            matched_checkpoint_keys,
            class,
            lifetime_access,
            dtype: checkpoint_entry.dtype,
            shape: checkpoint_entry.shape.clone(),
            storage_bytes: checkpoint_entry.storage_bytes,
            device_va,
            device_va_end,
            allocation_handle,
            payload_source_count,
            expected_payload_key_count,
            matched_payload_key_count: payload_rows.len(),
            missing_payload_key_count,
            payload_bytes,
            resolved_checkpoint_present,
            slot_binding_ready,
            kfd_residency_present: residency.is_some(),
            kfd_residency_proven,
            destination_span_bound,
            payload_metadata_ready,
            payload_byte_count_matches,
            checkpoint_payload_bound,
            payload_bindings: payload_rows,
            issue_count: entry_issues.len(),
        });
    }

    let binding_issue_count = issues.len();
    let checkpoint_entry_count = checkpoint.entries.len();
    let all_payload_bindings_ready = checkpoint_binding_ready
        && checkpoint_key_resolution_ready
        && kfd_residency_binding_ready
        && checkpoint_entry_count > 0
        && missing_payload_binding_count == 0
        && duplicate_payload_binding_count == 0
        && unmatched_payload_binding_count == 0
        && binding_issue_count == 0
        && entries
            .iter()
            .all(|entry| entry.checkpoint_payload_bound && entry.issue_count == 0);
    let checkpoint_payloads_bound = all_payload_bindings_ready
        && checkpoint_entry_count > 0
        && checkpoint_payload_bound_count == checkpoint_entry_count;

    ModelRuntimeCheckpointPayloadBindingPlan {
        target: slots.target,
        binding_source: MODEL_RUNTIME_CHECKPOINT_PAYLOAD_BINDING_SOURCE,
        checkpoint_entry_count,
        checkpoint_weight_slot_count: slots.checkpoint_weight_slots.len(),
        resolved_checkpoint_entry_count: key_resolution.resolved_entries.len(),
        missing_checkpoint_entry_count: key_resolution.missing_checkpoint_entries.len(),
        unbound_weight_tensor_count: key_resolution.unbound_weight_tensors.len(),
        expected_payload_binding_count,
        payload_binding_count: payload_bindings.len(),
        matched_payload_binding_count,
        missing_payload_binding_count,
        duplicate_payload_binding_count,
        unmatched_payload_binding_count,
        kfd_residency_request_count: kfd_residency.request_count,
        slot_binding_count,
        residency_proven_count,
        payload_metadata_ready_count,
        checkpoint_payload_bound_count,
        total_checkpoint_bytes,
        total_payload_bytes,
        binding_issue_count,
        checkpoint_binding_ready,
        checkpoint_key_resolution_ready,
        kfd_residency_binding_ready,
        all_payload_bindings_ready,
        checkpoint_payloads_bound,
        live_execution_supported: MODEL_API_CONTRACT.live_execution_supported,
        entries,
        unmatched_payload_bindings,
        issues,
    }
}

fn runtime_slot_kfd_residency_binding_issue_label(
    issue: &RuntimeSlotKfdResidencyBindingIssue,
) -> String {
    match (&issue.slot, &issue.tensor) {
        (Some(slot), Some(tensor)) => format!("slot {slot} {tensor}: {}", issue.message),
        (Some(slot), None) => format!("slot {slot}: {}", issue.message),
        (None, Some(tensor)) => format!("{tensor}: {}", issue.message),
        (None, None) => issue.message.clone(),
    }
}

fn runtime_slot_kfd_residency_binding_plan_from(
    allocation_requests: &ModelRuntimeSlotKfdAllocationResidencyRequestPlan,
    map_memory_results: &ModelRuntimeKfdMapMemoryResultBindingPlan,
) -> ModelRuntimeSlotKfdResidencyBindingPlan {
    let mut issues = Vec::new();
    let allocation_residency_request_ready =
        match allocation_requests.assert_kfd_allocation_residency_request_ready() {
            Ok(()) => true,
            Err(err) => {
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: None,
                    tensor: None,
                    message: format!("KFD allocation/residency request plan is not ready: {err}"),
                });
                false
            }
        };
    let map_memory_result_binding_ready =
        match map_memory_results.assert_kfd_map_memory_result_bound() {
            Ok(()) => true,
            Err(err) => {
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: None,
                    tensor: None,
                    message: format!("KFD map-memory result binding plan is not ready: {err}"),
                });
                false
            }
        };
    if allocation_requests.target != map_memory_results.target {
        issues.push(RuntimeSlotKfdResidencyBindingIssue {
            slot: None,
            tensor: None,
            message: format!(
                "KFD residency target {} != map-memory result target {}",
                allocation_requests.target, map_memory_results.target
            ),
        });
    }
    if allocation_requests.resident_gpu_ids != map_memory_results.resident_gpu_ids {
        issues.push(RuntimeSlotKfdResidencyBindingIssue {
            slot: None,
            tensor: None,
            message: "KFD residency resident GPU IDs do not match map-memory results".to_string(),
        });
    }

    let result_by_slot = map_memory_results
        .entries
        .iter()
        .map(|entry| (entry.slot, entry))
        .collect::<BTreeMap<_, _>>();
    let mut entries = Vec::new();
    let mut matched_map_memory_result_count = 0usize;
    let mut missing_map_memory_result_count = 0usize;
    let mut host_visible_gtt_binding_count = 0usize;
    let mut device_local_vram_binding_count = 0usize;
    let mut device_pointer_bound_count = 0usize;
    let mut allocation_performed_count = 0usize;
    let mut handle_bound_count = 0usize;
    let mut device_ids_array_bound_count = 0usize;
    let mut map_memory_performed_count = 0usize;
    let mut map_memory_success_count = 0usize;
    let mut residency_proven_count = 0usize;
    let mut total_storage_bytes = 0usize;
    let mut total_requested_bytes = 0usize;

    for request in &allocation_requests.entries {
        let mut entry_issue_count = 0usize;
        if !request.request_ready {
            entry_issue_count += 1;
            issues.push(RuntimeSlotKfdResidencyBindingIssue {
                slot: Some(request.slot),
                tensor: Some(request.tensor.clone()),
                message: "KFD allocation/residency request row is not ready".to_string(),
            });
        }
        if request.device_va == 0 || request.device_va_end.is_none() {
            entry_issue_count += 1;
            issues.push(RuntimeSlotKfdResidencyBindingIssue {
                slot: Some(request.slot),
                tensor: Some(request.tensor.clone()),
                message: "slot device pointer span is not bound".to_string(),
            });
        }

        match request.allocation_kind {
            RuntimeSlotKfdAllocationKind::HostVisibleGtt => host_visible_gtt_binding_count += 1,
            RuntimeSlotKfdAllocationKind::DeviceLocalVramPreferPublicCoherent => {
                device_local_vram_binding_count += 1
            }
        }
        let result = result_by_slot.get(&request.slot).copied();
        let (
            map_memory_result_present,
            allocation_gpu_id,
            allocation_handle,
            device_ids_array_ptr,
            map_args_n_devices,
            result_map_args_n_success,
            allocation_performed,
            handle_bound,
            device_ids_array_bound,
            map_memory_performed,
            map_memory_successful,
            result_metadata_ready,
        ) = match result {
            Some(result) => (
                result.result_binding_present,
                result.allocation_gpu_id,
                result.map_args_handle,
                result.map_args_device_ids_array_ptr,
                result.map_args_n_devices,
                result.result_map_args_n_success,
                result.allocation_performed,
                result.handle_bound,
                result.device_ids_array_bound,
                result.map_memory_performed,
                result.map_memory_successful,
                result.result_metadata_ready,
            ),
            None => (
                false, 0, 0, 0, 0, 0, false, false, false, false, false, false,
            ),
        };

        if let Some(result) = result {
            if result.tensor != request.tensor {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "map-memory result tensor {} != residency request tensor {}",
                        result.tensor, request.tensor
                    ),
                });
            }
            if result.class != request.class {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "map-memory result class {:?} != residency request class {:?}",
                        result.class, request.class
                    ),
                });
            }
            if result.lifetime_access != request.lifetime_access {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "map-memory result lifetime access {:?} != residency request access {:?}",
                        result.lifetime_access, request.lifetime_access
                    ),
                });
            }
            if result.allocation_kind != request.allocation_kind {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "map-memory result allocation kind {:?} != residency request kind {:?}",
                        result.allocation_kind, request.allocation_kind
                    ),
                });
            }
            if result.storage_bytes != request.storage_bytes {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "map-memory result storage bytes {} != residency request storage bytes {}",
                        result.storage_bytes, request.storage_bytes
                    ),
                });
            }
            if result.requested_bytes != request.requested_bytes {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: format!(
                        "map-memory result requested bytes {} != residency request bytes {}",
                        result.requested_bytes, request.requested_bytes
                    ),
                });
            }
            if result.resident_gpu_ids != request.resident_gpu_ids {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "map-memory result resident GPU IDs do not match residency request"
                        .to_string(),
                });
            }
            if !result.result_binding_present {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "missing successful map-memory result receipt for residency row"
                        .to_string(),
                });
            }
            if !result.map_memory_successful || !result.result_metadata_ready {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "map-memory result receipt does not prove residency for every resident GPU ID"
                        .to_string(),
                });
            }
        } else {
            entry_issue_count += 1;
            issues.push(RuntimeSlotKfdResidencyBindingIssue {
                slot: Some(request.slot),
                tensor: Some(request.tensor.clone()),
                message: "missing map-memory result entry for residency row".to_string(),
            });
        }

        if map_memory_result_present {
            matched_map_memory_result_count += 1;
        } else {
            missing_map_memory_result_count += 1;
        }
        let device_pointer_bound =
            request.cpu_lifetime_bound && request.device_va != 0 && request.device_va_end.is_some();
        if device_pointer_bound {
            device_pointer_bound_count += 1;
        }
        if allocation_performed {
            allocation_performed_count += 1;
        }
        if handle_bound {
            handle_bound_count += 1;
        }
        if device_ids_array_bound {
            device_ids_array_bound_count += 1;
        }
        if map_memory_performed {
            map_memory_performed_count += 1;
        }
        if map_memory_successful {
            map_memory_success_count += 1;
        }
        match total_storage_bytes.checked_add(request.storage_bytes) {
            Some(total) => total_storage_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "total storage bytes overflow".to_string(),
                });
            }
        }
        match total_requested_bytes.checked_add(request.requested_bytes) {
            Some(total) => total_requested_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: Some(request.slot),
                    tensor: Some(request.tensor.clone()),
                    message: "total requested bytes overflow".to_string(),
                });
            }
        }
        let kfd_residency_proven = allocation_residency_request_ready
            && map_memory_result_binding_ready
            && request.request_ready
            && map_memory_result_present
            && device_pointer_bound
            && allocation_performed
            && handle_bound
            && device_ids_array_bound
            && map_memory_performed
            && map_memory_successful
            && result_metadata_ready
            && entry_issue_count == 0;
        if kfd_residency_proven {
            residency_proven_count += 1;
        }

        entries.push(RuntimeSlotKfdResidencyBindingEntry {
            slot: request.slot,
            tensor: request.tensor.clone(),
            class: request.class,
            lifetime_access: request.lifetime_access,
            allocation_kind: request.allocation_kind,
            allocation_gpu_id,
            device_va: request.device_va,
            device_va_end: request.device_va_end,
            storage_bytes: request.storage_bytes,
            requested_bytes: request.requested_bytes,
            allocation_handle,
            device_ids_array_ptr,
            map_args_n_devices,
            result_map_args_n_success,
            resident_gpu_ids: request.resident_gpu_ids.clone(),
            resident_gpu_id_count: request.resident_gpu_id_count,
            allocation_request_ready: request.request_ready,
            map_memory_result_present,
            device_pointer_bound,
            allocation_performed,
            handle_bound,
            device_ids_array_bound,
            map_memory_performed,
            map_memory_successful,
            result_metadata_ready,
            kfd_residency_proven,
            issue_count: entry_issue_count,
        });
    }

    let request_count = allocation_requests.request_count;
    let residency_map_count =
        match request_count.checked_mul(allocation_requests.resident_gpu_id_count) {
            Some(count) => count,
            None => {
                issues.push(RuntimeSlotKfdResidencyBindingIssue {
                    slot: None,
                    tensor: None,
                    message: "residency map count overflow".to_string(),
                });
                0
            }
        };
    let binding_issue_count = issues.len();
    let all_residency_bindings_ready = allocation_residency_request_ready
        && map_memory_result_binding_ready
        && request_count > 0
        && matched_map_memory_result_count == request_count
        && missing_map_memory_result_count == 0
        && binding_issue_count == 0
        && entries
            .iter()
            .all(|entry| entry.kfd_residency_proven && entry.issue_count == 0);
    let allocation_performed = request_count > 0 && allocation_performed_count == request_count;
    let residency_proven = all_residency_bindings_ready
        && request_count > 0
        && residency_proven_count == request_count;

    ModelRuntimeSlotKfdResidencyBindingPlan {
        target: allocation_requests.target,
        binding_source: MODEL_RUNTIME_SLOT_KFD_RESIDENCY_BINDING_SOURCE,
        kfd_device_path: mainarch_sys::KFD_DEVICE,
        resident_gpu_ids: allocation_requests.resident_gpu_ids.clone(),
        resident_gpu_id_count: allocation_requests.resident_gpu_id_count,
        slot_count: allocation_requests.slot_count,
        request_count,
        map_memory_result_entry_count: map_memory_results.entries.len(),
        matched_map_memory_result_count,
        missing_map_memory_result_count,
        host_visible_gtt_binding_count,
        device_local_vram_binding_count,
        device_pointer_bound_count,
        allocation_performed_count,
        handle_bound_count,
        device_ids_array_bound_count,
        map_memory_performed_count,
        map_memory_success_count,
        residency_proven_count,
        total_storage_bytes,
        total_requested_bytes,
        residency_map_count,
        binding_issue_count,
        allocation_residency_request_ready,
        map_memory_result_binding_ready,
        all_residency_bindings_ready,
        allocation_performed,
        residency_proven,
        live_execution_supported: MODEL_API_CONTRACT.live_execution_supported,
        entries,
        issues,
    }
}

fn runtime_slot_kfd_allocation_issue_label(
    issue: &RuntimeSlotKfdAllocationResidencyRequestIssue,
) -> String {
    match (&issue.slot, &issue.tensor) {
        (Some(slot), Some(tensor)) => format!("slot {slot} {tensor}: {}", issue.message),
        (Some(slot), None) => format!("slot {slot}: {}", issue.message),
        (None, Some(tensor)) => format!("{tensor}: {}", issue.message),
        (None, None) => issue.message.clone(),
    }
}

fn runtime_slot_kfd_allocation_kind_for_class(
    class: TensorBindingClass,
) -> RuntimeSlotKfdAllocationKind {
    match class {
        TensorBindingClass::ExternalInput | TensorBindingClass::ExternalOutput => {
            RuntimeSlotKfdAllocationKind::HostVisibleGtt
        }
        TensorBindingClass::CheckpointWeight
        | TensorBindingClass::PersistentState
        | TensorBindingClass::Scratch
        | TensorBindingClass::Unused => {
            RuntimeSlotKfdAllocationKind::DeviceLocalVramPreferPublicCoherent
        }
    }
}

fn runtime_slot_kfd_allocation_residency_request_plan_from(
    lifetimes: &ModelRuntimeSlotDevicePointerLifetimePlan,
    resident_gpu_ids: &[u32],
) -> ModelRuntimeSlotKfdAllocationResidencyRequestPlan {
    let cpu_lifetime_ready = lifetimes.is_cpu_lifetime_ready();
    let mut seen_resident_gpu_ids = BTreeSet::new();
    let mut duplicated_resident_gpu_ids = false;
    for gpu_id in resident_gpu_ids {
        if !seen_resident_gpu_ids.insert(*gpu_id) {
            duplicated_resident_gpu_ids = true;
        }
    }
    let resident_gpu_ids = seen_resident_gpu_ids.into_iter().collect::<Vec<_>>();
    let resident_gpu_id_count = resident_gpu_ids.len();

    let mut issues = Vec::new();
    if resident_gpu_id_count == 0 {
        issues.push(RuntimeSlotKfdAllocationResidencyRequestIssue {
            slot: None,
            tensor: None,
            message: "no resident GPU IDs supplied".to_string(),
        });
    }
    if duplicated_resident_gpu_ids {
        issues.push(RuntimeSlotKfdAllocationResidencyRequestIssue {
            slot: None,
            tensor: None,
            message: "resident GPU ID list contains duplicates".to_string(),
        });
    }

    let alignment = DEFAULT_RUNTIME_DEVICE_POINTER_ALIGNMENT as usize;
    let mut entries = Vec::new();
    let mut host_visible_gtt_request_count = 0usize;
    let mut device_local_vram_request_count = 0usize;
    let mut total_storage_bytes = 0usize;
    let mut total_requested_bytes = 0usize;

    for lifetime in &lifetimes.entries {
        let allocation_kind = runtime_slot_kfd_allocation_kind_for_class(lifetime.class);
        match allocation_kind {
            RuntimeSlotKfdAllocationKind::HostVisibleGtt => host_visible_gtt_request_count += 1,
            RuntimeSlotKfdAllocationKind::DeviceLocalVramPreferPublicCoherent => {
                device_local_vram_request_count += 1
            }
        }
        let mut entry_issue_count = 0usize;
        match total_storage_bytes.checked_add(lifetime.storage_bytes) {
            Some(total) => total_storage_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdAllocationResidencyRequestIssue {
                    slot: Some(lifetime.slot),
                    tensor: Some(lifetime.tensor.clone()),
                    message: "total storage bytes overflow".to_string(),
                });
            }
        }
        if !lifetime.cpu_lifetime_bound {
            entry_issue_count += 1;
            issues.push(RuntimeSlotKfdAllocationResidencyRequestIssue {
                slot: Some(lifetime.slot),
                tensor: Some(lifetime.tensor.clone()),
                message: "slot lifetime is not CPU-bound".to_string(),
            });
        }
        if !lifetime.binding_present {
            entry_issue_count += 1;
            issues.push(RuntimeSlotKfdAllocationResidencyRequestIssue {
                slot: Some(lifetime.slot),
                tensor: Some(lifetime.tensor.clone()),
                message: "slot has no device pointer binding".to_string(),
            });
        }
        if lifetime.device_va_end.is_none() {
            entry_issue_count += 1;
            issues.push(RuntimeSlotKfdAllocationResidencyRequestIssue {
                slot: Some(lifetime.slot),
                tensor: Some(lifetime.tensor.clone()),
                message: "slot device VA span is unavailable".to_string(),
            });
        }
        let requested_bytes =
            match align_up_usize(lifetime.storage_bytes, alignment, "KFD allocation request") {
                Ok(bytes) => bytes,
                Err(err) => {
                    entry_issue_count += 1;
                    issues.push(RuntimeSlotKfdAllocationResidencyRequestIssue {
                        slot: Some(lifetime.slot),
                        tensor: Some(lifetime.tensor.clone()),
                        message: err.to_string(),
                    });
                    0
                }
            };
        match total_requested_bytes.checked_add(requested_bytes) {
            Some(total) => total_requested_bytes = total,
            None => {
                entry_issue_count += 1;
                issues.push(RuntimeSlotKfdAllocationResidencyRequestIssue {
                    slot: Some(lifetime.slot),
                    tensor: Some(lifetime.tensor.clone()),
                    message: "total requested bytes overflow".to_string(),
                });
            }
        }
        let resident_ids_present = resident_gpu_id_count > 0;
        let request_ready = cpu_lifetime_ready
            && lifetime.cpu_lifetime_bound
            && resident_ids_present
            && entry_issue_count == 0;
        entries.push(RuntimeSlotKfdAllocationResidencyRequestEntry {
            slot: lifetime.slot,
            tensor: lifetime.tensor.clone(),
            class: lifetime.class,
            lifetime_access: lifetime.lifetime_access,
            allocation_kind,
            storage_bytes: lifetime.storage_bytes,
            requested_bytes,
            alignment,
            device_va: lifetime.device_va,
            device_va_end: lifetime.device_va_end,
            first_op_index: lifetime.first_op_index,
            first_op_name: lifetime.first_op_name.clone(),
            last_op_index: lifetime.last_op_index,
            last_op_name: lifetime.last_op_name.clone(),
            live_range_op_count: lifetime.live_range_op_count,
            resident_gpu_ids: resident_gpu_ids.clone(),
            resident_gpu_id_count,
            primary_alloc_flags: allocation_kind.primary_alloc_flags(),
            fallback_alloc_flags: allocation_kind.fallback_alloc_flags(),
            vm_acquire_required: resident_ids_present,
            allocation_required: true,
            map_to_gpu_required: resident_ids_present,
            kfd_allocation_performed: false,
            kfd_residency_proven: false,
            cpu_lifetime_bound: lifetime.cpu_lifetime_bound,
            request_ready,
            issue_count: entry_issue_count,
        });
    }

    let request_count = entries.len();
    let residency_map_request_count = match request_count.checked_mul(resident_gpu_id_count) {
        Some(count) => count,
        None => {
            issues.push(RuntimeSlotKfdAllocationResidencyRequestIssue {
                slot: None,
                tensor: None,
                message: "residency map request count overflow".to_string(),
            });
            0
        }
    };
    let request_issue_count = issues.len();
    let all_requests_ready = cpu_lifetime_ready
        && request_count > 0
        && resident_gpu_id_count > 0
        && request_issue_count == 0
        && entries.iter().all(|entry| entry.request_ready);

    ModelRuntimeSlotKfdAllocationResidencyRequestPlan {
        target: lifetimes.target,
        request_source: MODEL_RUNTIME_SLOT_KFD_ALLOCATION_RESIDENCY_REQUEST_SOURCE,
        resident_gpu_ids,
        resident_gpu_id_count,
        slot_count: lifetimes.slot_count,
        request_count,
        host_visible_gtt_request_count,
        device_local_vram_request_count,
        residency_map_request_count,
        total_storage_bytes,
        total_requested_bytes,
        request_issue_count,
        cpu_lifetime_ready,
        all_requests_ready,
        allocation_performed: false,
        residency_proven: false,
        live_execution_supported: MODEL_API_CONTRACT.live_execution_supported,
        entries,
        issues,
    }
}

fn runtime_slot_device_pointer_lifetime_plan_from(
    slots: &ModelRuntimeSlotPlan,
    lifetime: &ModelTensorLifetimePlan,
    device_pointers: &ModelRuntimeSlotDevicePointerValidation,
) -> ModelRuntimeSlotDevicePointerLifetimePlan {
    let mut binding_by_slot = BTreeMap::new();
    for binding in &device_pointers.bindings {
        binding_by_slot
            .entry(binding.slot)
            .or_insert_with(|| binding.clone());
    }
    let issue_count_by_slot =
        device_pointers
            .issues
            .iter()
            .fold(BTreeMap::<usize, usize>::new(), |mut counts, issue| {
                *counts.entry(issue.slot).or_default() += 1;
                counts
            });
    let missing_slots = device_pointers
        .missing_slots
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let lifetime_by_tensor = lifetime
        .entries
        .iter()
        .map(|entry| (entry.tensor.as_str(), entry))
        .collect::<BTreeMap<_, _>>();

    let mut entries = Vec::new();
    let mut issues = Vec::new();
    let mut tracked_slot_count = 0usize;
    let mut accessed_slot_count = 0usize;
    let mut unused_slot_count = 0usize;
    let mut total_storage_bytes = 0usize;
    let mut total_binding_bytes = 0usize;
    let mut bound_slot_count = 0usize;
    let mut cpu_lifetime_bound_count = 0usize;
    let mut cpu_lifetime_unbound_count = 0usize;
    let mut lifetime_issue_count = 0usize;

    for slot in &slots.tensor_slots {
        if slot.class == TensorBindingClass::Unused {
            unused_slot_count += 1;
            continue;
        }
        tracked_slot_count += 1;
        match total_storage_bytes.checked_add(slot.storage_bytes) {
            Some(total) => total_storage_bytes = total,
            None => {
                lifetime_issue_count += 1;
                issues.push(RuntimeSlotDevicePointerLifetimeIssue {
                    slot: slot.slot,
                    tensor: slot.tensor.clone(),
                    message: "total storage bytes overflow".to_string(),
                });
            }
        }

        let binding = binding_by_slot.get(&slot.slot);
        let binding_present = binding.is_some();
        let binding_bytes = binding.map(|binding| binding.bytes).unwrap_or(0);
        let device_va = binding.map(|binding| binding.device_va).unwrap_or(0);
        let device_va_end =
            binding.and_then(|binding| binding.device_va.checked_add(binding.bytes as u64));
        if binding_present {
            bound_slot_count += 1;
            match total_binding_bytes.checked_add(binding_bytes) {
                Some(total) => total_binding_bytes = total,
                None => {
                    lifetime_issue_count += 1;
                    issues.push(RuntimeSlotDevicePointerLifetimeIssue {
                        slot: slot.slot,
                        tensor: slot.tensor.clone(),
                        message: "total binding bytes overflow".to_string(),
                    });
                }
            }
        }
        let pointer_validation_issue_count =
            issue_count_by_slot.get(&slot.slot).copied().unwrap_or(0);

        let mut entry_lifetime_issue_count = 0usize;
        let lifetime_entry = lifetime_by_tensor.get(slot.tensor.as_str()).copied();
        if lifetime_entry.is_none() {
            entry_lifetime_issue_count += 1;
            issues.push(RuntimeSlotDevicePointerLifetimeIssue {
                slot: slot.slot,
                tensor: slot.tensor.clone(),
                message: "slot has no tensor lifetime row".to_string(),
            });
        }
        let first_op_index = lifetime_entry.and_then(|entry| entry.first_op_index);
        let first_op_name = lifetime_entry.and_then(|entry| entry.first_op_name.clone());
        let last_op_index = lifetime_entry.and_then(|entry| entry.last_op_index);
        let last_op_name = lifetime_entry.and_then(|entry| entry.last_op_name.clone());
        let read_count = lifetime_entry.map(|entry| entry.read_count).unwrap_or(0);
        let write_count = lifetime_entry.map(|entry| entry.write_count).unwrap_or(0);
        let live_range_op_count = match (first_op_index, last_op_index) {
            (Some(first), Some(last)) if first <= last => last - first + 1,
            (Some(first), Some(last)) => {
                entry_lifetime_issue_count += 1;
                issues.push(RuntimeSlotDevicePointerLifetimeIssue {
                    slot: slot.slot,
                    tensor: slot.tensor.clone(),
                    message: format!("lifetime range {first}..{last} is inverted"),
                });
                0
            }
            _ => 0,
        };
        let accessed = first_op_index.is_some();
        if accessed {
            accessed_slot_count += 1;
        }

        if let Some(entry) = lifetime_entry {
            if entry.storage_bytes != slot.storage_bytes {
                entry_lifetime_issue_count += 1;
                issues.push(RuntimeSlotDevicePointerLifetimeIssue {
                    slot: slot.slot,
                    tensor: slot.tensor.clone(),
                    message: format!(
                        "lifetime storage bytes {} != slot bytes {}",
                        entry.storage_bytes, slot.storage_bytes
                    ),
                });
            }
            let access = TensorBindingAccess::from_counts(entry.read_count, entry.write_count);
            if access != slot.lifetime_access {
                entry_lifetime_issue_count += 1;
                issues.push(RuntimeSlotDevicePointerLifetimeIssue {
                    slot: slot.slot,
                    tensor: slot.tensor.clone(),
                    message: format!(
                        "lifetime access {:?} != slot access {:?}",
                        access, slot.lifetime_access
                    ),
                });
            }
        }

        let cpu_lifetime_bound = accessed
            && binding_present
            && !missing_slots.contains(&slot.slot)
            && pointer_validation_issue_count == 0
            && entry_lifetime_issue_count == 0;
        if accessed {
            if cpu_lifetime_bound {
                cpu_lifetime_bound_count += 1;
            } else {
                cpu_lifetime_unbound_count += 1;
            }
        }
        lifetime_issue_count += entry_lifetime_issue_count;

        entries.push(RuntimeSlotDevicePointerLifetimeEntry {
            slot: slot.slot,
            tensor: slot.tensor.clone(),
            class: slot.class,
            lifetime_access: slot.lifetime_access,
            storage_bytes: slot.storage_bytes,
            binding_present,
            binding_bytes,
            device_va,
            device_va_end,
            first_op_index,
            first_op_name,
            last_op_index,
            last_op_name,
            live_range_op_count,
            read_count,
            write_count,
            pointer_validation_issue_count,
            lifetime_issue_count: entry_lifetime_issue_count,
            cpu_lifetime_bound,
        });
    }

    let complete_device_pointer_validation =
        device_pointers.issues.is_empty() && device_pointers.missing_slots.is_empty();
    let all_accessed_lifetimes_bound = accessed_slot_count > 0
        && cpu_lifetime_bound_count == accessed_slot_count
        && cpu_lifetime_unbound_count == 0;

    ModelRuntimeSlotDevicePointerLifetimePlan {
        target: slots.target,
        slot_count: slots.tensor_slots.len(),
        tracked_slot_count,
        bound_slot_count,
        accessed_slot_count,
        unused_slot_count,
        pointer_validation_issue_count: device_pointers.issues.len(),
        missing_slot_count: device_pointers.missing_slots.len(),
        lifetime_issue_count,
        total_storage_bytes,
        total_binding_bytes,
        cpu_lifetime_bound_count,
        cpu_lifetime_unbound_count,
        complete_device_pointer_validation,
        all_accessed_lifetimes_bound,
        residency_proven: false,
        live_execution_supported: MODEL_API_CONTRACT.live_execution_supported,
        entries,
        issues,
    }
}

fn runtime_slot_plan_from(
    binding: &ModelTensorBindingPlan,
    execution: &ModelPrimitiveExecutionPlan,
) -> Result<ModelRuntimeSlotPlan> {
    let mut tensor_slots = Vec::with_capacity(binding.entries.len());
    let mut slot_by_tensor = BTreeMap::new();
    let mut external_input_slots = Vec::new();
    let mut external_output_slots = Vec::new();
    let mut checkpoint_weight_slots = Vec::new();
    let mut persistent_state_slots = Vec::new();
    let mut scratch_slots = Vec::new();
    let mut unused_slots = Vec::new();

    for (slot, binding_entry) in binding.entries.iter().enumerate() {
        let slot_entry = RuntimeTensorSlot::from_binding(slot, binding_entry);
        push_runtime_slot_class(
            slot_entry.class,
            slot,
            &mut external_input_slots,
            &mut external_output_slots,
            &mut checkpoint_weight_slots,
            &mut persistent_state_slots,
            &mut scratch_slots,
            &mut unused_slots,
        );
        if slot_by_tensor
            .insert(slot_entry.tensor.clone(), slot)
            .is_some()
        {
            return Err(anyhow!(
                "runtime slot plan saw duplicate tensor {}",
                slot_entry.tensor
            ));
        }
        tensor_slots.push(slot_entry);
    }

    let mut op_slots = Vec::with_capacity(execution.entries.len());
    for execution_entry in &execution.entries {
        op_slots.push(RuntimeOpSlotPlanEntry {
            op_index: execution_entry.op_index,
            op_name: execution_entry.op_name.clone(),
            kind: execution_entry.kind,
            stage_name: execution_entry.stage_name.clone(),
            stage_kind: execution_entry.stage_kind,
            route: execution_entry.route.clone(),
            read_slots: runtime_slot_refs(
                &execution_entry.reads,
                &slot_by_tensor,
                &tensor_slots,
                &execution_entry.op_name,
            )?,
            write_slots: runtime_slot_refs(
                &execution_entry.writes,
                &slot_by_tensor,
                &tensor_slots,
                &execution_entry.op_name,
            )?,
        });
    }

    Ok(ModelRuntimeSlotPlan {
        target: execution.target,
        tensor_slots,
        op_slots,
        external_input_slots,
        external_output_slots,
        checkpoint_weight_slots,
        persistent_state_slots,
        scratch_slots,
        unused_slots,
        gap_ops: execution.gap_ops,
        unstaged_ops: execution.unstaged_ops.clone(),
        binding_issues: execution.binding_issues.clone(),
    })
}

fn push_runtime_slot_class(
    class: TensorBindingClass,
    slot: usize,
    external_input_slots: &mut Vec<usize>,
    external_output_slots: &mut Vec<usize>,
    checkpoint_weight_slots: &mut Vec<usize>,
    persistent_state_slots: &mut Vec<usize>,
    scratch_slots: &mut Vec<usize>,
    unused_slots: &mut Vec<usize>,
) {
    match class {
        TensorBindingClass::ExternalInput => external_input_slots.push(slot),
        TensorBindingClass::ExternalOutput => external_output_slots.push(slot),
        TensorBindingClass::CheckpointWeight => checkpoint_weight_slots.push(slot),
        TensorBindingClass::PersistentState => persistent_state_slots.push(slot),
        TensorBindingClass::Scratch => scratch_slots.push(slot),
        TensorBindingClass::Unused => unused_slots.push(slot),
    }
}

fn runtime_slot_refs(
    bindings: &[PrimitiveExecutionTensorBinding],
    slot_by_tensor: &BTreeMap<TensorRef, usize>,
    tensor_slots: &[RuntimeTensorSlot],
    op_name: &str,
) -> Result<Vec<RuntimeTensorSlotRef>> {
    bindings
        .iter()
        .map(|binding| {
            let slot = slot_by_tensor.get(&binding.tensor).ok_or_else(|| {
                anyhow!(
                    "op {op_name} references tensor {} outside runtime slot plan",
                    binding.tensor
                )
            })?;
            let slot_entry = tensor_slots.get(*slot).ok_or_else(|| {
                anyhow!(
                    "op {op_name} references tensor {} at missing runtime slot {}",
                    binding.tensor,
                    slot
                )
            })?;
            Ok(RuntimeTensorSlotRef::from_slot(slot_entry))
        })
        .collect()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RuntimeDispatchSlotArgumentAccess {
    Read,
    Write,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeDispatchSlotArgument {
    pub name: &'static str,
    pub slot: usize,
    pub access: RuntimeDispatchSlotArgumentAccess,
}

impl RuntimeDispatchSlotArgument {
    pub fn is_read(&self) -> bool {
        self.access == RuntimeDispatchSlotArgumentAccess::Read
    }

    pub fn is_write(&self) -> bool {
        self.access == RuntimeDispatchSlotArgumentAccess::Write
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RuntimeDispatchScalarValue {
    Usize(usize),
    F32Bits(u32),
    DType(DType),
    WeightFormat(WeightFormat),
    LinearParallelism(LinearParallelism),
    RopeMode(RopeMode),
    KvCacheFormat(KvCacheFormat),
    CollectiveKind(CollectiveKind),
    MoeActivation(MoeActivation),
}

impl RuntimeDispatchScalarValue {
    pub fn as_usize(&self) -> Option<usize> {
        match self {
            Self::Usize(value) => Some(*value),
            _ => None,
        }
    }

    pub fn as_f32(&self) -> Option<f32> {
        match self {
            Self::F32Bits(value) => Some(f32::from_bits(*value)),
            _ => None,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeDispatchScalarArgument {
    pub name: &'static str,
    pub value: RuntimeDispatchScalarValue,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeDispatchIntentEntry {
    pub op_index: usize,
    pub op_name: String,
    pub kind: PrimitiveKind,
    pub stage_name: Option<String>,
    pub stage_kind: Option<ModelStageKind>,
    pub route: PrimitiveLoweringRoute,
    pub entrypoint_symbols: Vec<String>,
    pub slot_arguments: Vec<RuntimeDispatchSlotArgument>,
    pub scalar_arguments: Vec<RuntimeDispatchScalarArgument>,
    pub read_slots: Vec<usize>,
    pub write_slots: Vec<usize>,
}

impl RuntimeDispatchIntentEntry {
    pub fn has_lowering_gap(&self) -> bool {
        self.route.status.is_gap()
    }

    pub fn reads_slot(&self, slot: usize) -> bool {
        self.read_slots.contains(&slot)
    }

    pub fn writes_slot(&self, slot: usize) -> bool {
        self.write_slots.contains(&slot)
    }

    pub fn slot_argument_for(&self, name: &str) -> Option<&RuntimeDispatchSlotArgument> {
        self.slot_arguments
            .iter()
            .find(|argument| argument.name == name)
    }

    pub fn scalar_argument_for(&self, name: &str) -> Option<&RuntimeDispatchScalarArgument> {
        self.scalar_arguments
            .iter()
            .find(|argument| argument.name == name)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeDispatchIntentPlan {
    pub target: &'static str,
    pub entries: Vec<RuntimeDispatchIntentEntry>,
    pub gap_ops: usize,
    pub unstaged_ops: Vec<String>,
    pub binding_issues: Vec<TensorBindingIssue>,
}

impl ModelRuntimeDispatchIntentPlan {
    pub fn entry_for(&self, op_name: &str) -> Option<&RuntimeDispatchIntentEntry> {
        self.entries.iter().find(|entry| entry.op_name == op_name)
    }

    pub fn validate_slot_buffer_bindings(
        &self,
        slots: &ModelRuntimeSlotPlan,
        bindings: &[RuntimeSlotBufferBinding],
    ) -> ModelRuntimeDispatchBindingValidation {
        runtime_dispatch_binding_validation_from(self, slots, bindings)
    }

    pub fn assert_static_ready(&self) -> Result<()> {
        let mut issues = Vec::new();
        if !self.binding_issues.is_empty() {
            let binding_issues = self
                .binding_issues
                .iter()
                .map(|issue| format!("{}: {}", issue.tensor, issue.message))
                .collect::<Vec<_>>();
            issues.push(format!("binding issues: {}", binding_issues.join("; ")));
        }
        if self.gap_ops > 0 {
            let gap_ops = self
                .entries
                .iter()
                .filter(|entry| entry.has_lowering_gap())
                .map(|entry| format!("{}:{:?}", entry.op_name, entry.kind))
                .collect::<Vec<_>>();
            issues.push(format!("lowering gaps: {}", gap_ops.join(", ")));
        }
        if !self.unstaged_ops.is_empty() {
            issues.push(format!("unstaged ops: {}", self.unstaged_ops.join(", ")));
        }
        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime dispatch intent plan for {} is not static-ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn runtime_dispatch_intent_plan_from(
    graph: &ModelPrimitiveGraph,
    slots: &ModelRuntimeSlotPlan,
) -> Result<ModelRuntimeDispatchIntentPlan> {
    let slot_by_tensor = slots
        .tensor_slots
        .iter()
        .map(|slot| (slot.tensor.clone(), slot.slot))
        .collect::<BTreeMap<_, _>>();
    let entries = slots
        .op_slots
        .iter()
        .map(|op| {
            let primitive = graph.ops.get(op.op_index).ok_or_else(|| {
                anyhow!(
                    "runtime dispatch intent plan missing primitive op row {} for {}",
                    op.op_index,
                    op.op_name
                )
            })?;
            if primitive.name() != op.op_name || primitive.kind() != op.kind {
                return Err(anyhow!(
                    "runtime dispatch intent plan op row {} mismatch: slot {:?}:{:?}, primitive {}:{:?}",
                    op.op_index,
                    op.op_name,
                    op.kind,
                    primitive.name(),
                    primitive.kind()
                ));
            }
            Ok(RuntimeDispatchIntentEntry {
                op_index: op.op_index,
                op_name: op.op_name.clone(),
                kind: op.kind,
                stage_name: op.stage_name.clone(),
                stage_kind: op.stage_kind,
                route: op.route.clone(),
                entrypoint_symbols: op
                    .route
                    .entrypoint_symbols()
                    .into_iter()
                    .map(str::to_string)
                    .collect(),
                slot_arguments: runtime_dispatch_slot_arguments(primitive, &slot_by_tensor)?,
                scalar_arguments: runtime_dispatch_scalar_arguments(graph, primitive)?,
                read_slots: op.read_slots.iter().map(|slot| slot.slot).collect(),
                write_slots: op.write_slots.iter().map(|slot| slot.slot).collect(),
            })
        })
        .collect::<Result<Vec<_>>>()?;
    Ok(ModelRuntimeDispatchIntentPlan {
        target: slots.target,
        entries,
        gap_ops: slots.gap_ops,
        unstaged_ops: slots.unstaged_ops.clone(),
        binding_issues: slots.binding_issues.clone(),
    })
}

fn runtime_dispatch_slot_arguments(
    op: &PrimitiveOp,
    slot_by_tensor: &BTreeMap<TensorRef, usize>,
) -> Result<Vec<RuntimeDispatchSlotArgument>> {
    let mut arguments = Vec::new();
    match op {
        PrimitiveOp::EmbeddingLookup(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "token_ids",
                &op.token_ids,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "weight",
                &op.weight,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "output",
                &op.output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::Linear(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "input",
                &op.input,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "weight",
                &op.weight,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            if let Some(scale) = &op.scale {
                push_dispatch_slot_argument(
                    &mut arguments,
                    "scale",
                    scale,
                    RuntimeDispatchSlotArgumentAccess::Read,
                    slot_by_tensor,
                    &op.name,
                )?;
            }
            push_dispatch_slot_argument(
                &mut arguments,
                "output",
                &op.output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::RmsNorm(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "input",
                &op.input,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "weight",
                &op.weight,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "output",
                &op.output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::AddRmsNorm(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "input",
                &op.input,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "residual",
                &op.residual,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "weight",
                &op.weight,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "residual_output",
                &op.residual_output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "norm_output",
                &op.norm_output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::ApplyRope(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "query",
                &op.query,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "key",
                &op.key,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "position",
                &op.position,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "query_output",
                &op.query_output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "key_output",
                &op.key_output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::KvCacheAppend(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "key",
                &op.key,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "value",
                &op.value,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "block_table",
                &op.block_table,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "position",
                &op.position,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_cache_dispatch_slot_arguments(
                &mut arguments,
                &op.cache,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::PagedAttention(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "query",
                &op.query,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "block_table",
                &op.block_table,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "seq_len",
                &op.seq_len,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_cache_dispatch_slot_arguments(
                &mut arguments,
                &op.cache,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "output",
                &op.output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::MoeRouterTopK(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "hidden",
                &op.hidden,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "gate_weight",
                &op.gate_weight,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "expert_ids",
                &op.expert_ids,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "expert_weights",
                &op.expert_weights,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::MoeLocalFfn(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "hidden",
                &op.hidden,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "gate_weight",
                &op.gate_weight,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "up_weight",
                &op.up_weight,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "down_weight",
                &op.down_weight,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "expert_ids",
                &op.expert_ids,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "expert_weights",
                &op.expert_weights,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "output",
                &op.output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::ResidualAdd(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "lhs",
                &op.lhs,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "rhs",
                &op.rhs,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "output",
                &op.output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::Collective(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "input",
                &op.input,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "output",
                &op.output,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
        PrimitiveOp::ArgmaxSample(op) => {
            push_dispatch_slot_argument(
                &mut arguments,
                "logits",
                &op.logits,
                RuntimeDispatchSlotArgumentAccess::Read,
                slot_by_tensor,
                &op.name,
            )?;
            push_dispatch_slot_argument(
                &mut arguments,
                "output_token",
                &op.output_token,
                RuntimeDispatchSlotArgumentAccess::Write,
                slot_by_tensor,
                &op.name,
            )?;
        }
    }
    Ok(arguments)
}

fn runtime_dispatch_scalar_arguments(
    graph: &ModelPrimitiveGraph,
    op: &PrimitiveOp,
) -> Result<Vec<RuntimeDispatchScalarArgument>> {
    match op {
        PrimitiveOp::EmbeddingLookup(op) => Ok(vec![
            tensor_element_count_arg(graph, op.name.as_str(), "token_count", &op.token_ids)?,
            scalar_arg("vocab", RuntimeDispatchScalarValue::Usize(op.vocab)),
            scalar_arg("hidden", RuntimeDispatchScalarValue::Usize(op.hidden)),
        ]),
        PrimitiveOp::Linear(op) => Ok(vec![
            scalar_arg(
                "in_features",
                RuntimeDispatchScalarValue::Usize(op.in_features),
            ),
            scalar_arg(
                "out_features",
                RuntimeDispatchScalarValue::Usize(op.out_features),
            ),
            scalar_arg(
                "weight_format",
                RuntimeDispatchScalarValue::WeightFormat(op.weight_format),
            ),
            scalar_arg(
                "parallelism",
                RuntimeDispatchScalarValue::LinearParallelism(op.parallelism),
            ),
        ]),
        PrimitiveOp::RmsNorm(op) => Ok(vec![
            scalar_arg(
                "normalized_dim",
                RuntimeDispatchScalarValue::Usize(op.normalized_dim),
            ),
            scalar_arg("eps", RuntimeDispatchScalarValue::F32Bits(op.eps.to_bits())),
        ]),
        PrimitiveOp::AddRmsNorm(op) => Ok(vec![
            scalar_arg(
                "normalized_dim",
                RuntimeDispatchScalarValue::Usize(op.normalized_dim),
            ),
            scalar_arg("eps", RuntimeDispatchScalarValue::F32Bits(op.eps.to_bits())),
        ]),
        PrimitiveOp::ApplyRope(op) => Ok(vec![
            scalar_arg(
                "query_heads",
                RuntimeDispatchScalarValue::Usize(op.query_heads),
            ),
            scalar_arg("kv_heads", RuntimeDispatchScalarValue::Usize(op.kv_heads)),
            scalar_arg("head_dim", RuntimeDispatchScalarValue::Usize(op.head_dim)),
            scalar_arg(
                "theta",
                RuntimeDispatchScalarValue::F32Bits(op.theta.to_bits()),
            ),
            scalar_arg("mode", RuntimeDispatchScalarValue::RopeMode(op.mode)),
        ]),
        PrimitiveOp::KvCacheAppend(op) => Ok(vec![
            scalar_arg("kv_heads", RuntimeDispatchScalarValue::Usize(op.kv_heads)),
            scalar_arg("head_dim", RuntimeDispatchScalarValue::Usize(op.head_dim)),
            scalar_arg(
                "max_context",
                RuntimeDispatchScalarValue::Usize(op.max_context),
            ),
            scalar_arg(
                "block_size",
                RuntimeDispatchScalarValue::Usize(op.block_size),
            ),
            scalar_arg(
                "cache_dtype",
                RuntimeDispatchScalarValue::DType(op.cache_dtype),
            ),
            scalar_arg("cache_format", cache_format_scalar(&op.cache)),
        ]),
        PrimitiveOp::PagedAttention(op) => Ok(vec![
            scalar_arg(
                "query_heads",
                RuntimeDispatchScalarValue::Usize(op.query_heads),
            ),
            scalar_arg("kv_heads", RuntimeDispatchScalarValue::Usize(op.kv_heads)),
            scalar_arg("head_dim", RuntimeDispatchScalarValue::Usize(op.head_dim)),
            scalar_arg(
                "max_context",
                RuntimeDispatchScalarValue::Usize(op.max_context),
            ),
            scalar_arg(
                "block_size",
                RuntimeDispatchScalarValue::Usize(op.block_size),
            ),
            scalar_arg(
                "cache_dtype",
                RuntimeDispatchScalarValue::DType(op.cache_dtype),
            ),
            scalar_arg("cache_format", cache_format_scalar(&op.cache)),
        ]),
        PrimitiveOp::MoeRouterTopK(op) => {
            let mut arguments = vec![
                scalar_arg(
                    "hidden_dim",
                    RuntimeDispatchScalarValue::Usize(op.hidden_dim),
                ),
                scalar_arg("experts", RuntimeDispatchScalarValue::Usize(op.experts)),
                scalar_arg("top_k", RuntimeDispatchScalarValue::Usize(op.top_k)),
            ];
            if let Some(group) = op.group {
                arguments.push(scalar_arg(
                    "expert_groups",
                    RuntimeDispatchScalarValue::Usize(group.expert_groups),
                ));
                arguments.push(scalar_arg(
                    "topk_groups",
                    RuntimeDispatchScalarValue::Usize(group.topk_groups),
                ));
            }
            Ok(arguments)
        }
        PrimitiveOp::MoeLocalFfn(op) => Ok(vec![
            scalar_arg(
                "hidden_dim",
                RuntimeDispatchScalarValue::Usize(op.hidden_dim),
            ),
            scalar_arg(
                "intermediate_dim",
                RuntimeDispatchScalarValue::Usize(op.intermediate_dim),
            ),
            scalar_arg("experts", RuntimeDispatchScalarValue::Usize(op.experts)),
            scalar_arg("top_k", RuntimeDispatchScalarValue::Usize(op.top_k)),
            scalar_arg(
                "activation",
                RuntimeDispatchScalarValue::MoeActivation(op.activation),
            ),
        ]),
        PrimitiveOp::ResidualAdd(op) => Ok(vec![tensor_element_count_arg(
            graph,
            op.name.as_str(),
            "n",
            &op.output,
        )?]),
        PrimitiveOp::Collective(op) => Ok(vec![
            tensor_element_count_arg(graph, op.name.as_str(), "n", &op.output)?,
            scalar_arg(
                "collective_kind",
                RuntimeDispatchScalarValue::CollectiveKind(op.kind),
            ),
            scalar_arg(
                "group_size",
                RuntimeDispatchScalarValue::Usize(op.group_size),
            ),
        ]),
        PrimitiveOp::ArgmaxSample(op) => Ok(vec![
            tensor_element_count_arg(graph, op.name.as_str(), "token_count", &op.output_token)?,
            scalar_arg("vocab", RuntimeDispatchScalarValue::Usize(op.vocab)),
        ]),
    }
}

fn tensor_element_count_arg(
    graph: &ModelPrimitiveGraph,
    op_name: &str,
    name: &'static str,
    tensor: &TensorRef,
) -> Result<RuntimeDispatchScalarArgument> {
    let tensor = graph.tensor(tensor)?;
    let elements = element_count(&tensor.shape).map_err(|err| {
        anyhow!(
            "op {op_name} cannot derive scalar argument {name} from tensor {}: {err}",
            tensor.id
        )
    })?;
    Ok(scalar_arg(
        name,
        RuntimeDispatchScalarValue::Usize(elements),
    ))
}

fn scalar_arg(
    name: &'static str,
    value: RuntimeDispatchScalarValue,
) -> RuntimeDispatchScalarArgument {
    RuntimeDispatchScalarArgument { name, value }
}

fn cache_format_scalar(cache: &KvCacheRef) -> RuntimeDispatchScalarValue {
    let format = match cache {
        KvCacheRef::Separate { format, .. } | KvCacheRef::Opaque { format, .. } => format.clone(),
    };
    RuntimeDispatchScalarValue::KvCacheFormat(format)
}

fn push_cache_dispatch_slot_arguments(
    arguments: &mut Vec<RuntimeDispatchSlotArgument>,
    cache: &KvCacheRef,
    access: RuntimeDispatchSlotArgumentAccess,
    slot_by_tensor: &BTreeMap<TensorRef, usize>,
    op_name: &str,
) -> Result<()> {
    match cache {
        KvCacheRef::Separate { key, value, .. } => {
            push_dispatch_slot_argument(
                arguments,
                "cache.key",
                key,
                access,
                slot_by_tensor,
                op_name,
            )?;
            push_dispatch_slot_argument(
                arguments,
                "cache.value",
                value,
                access,
                slot_by_tensor,
                op_name,
            )
        }
        KvCacheRef::Opaque { cache, .. } => {
            push_dispatch_slot_argument(arguments, "cache", cache, access, slot_by_tensor, op_name)
        }
    }
}

fn push_dispatch_slot_argument(
    arguments: &mut Vec<RuntimeDispatchSlotArgument>,
    name: &'static str,
    tensor: &TensorRef,
    access: RuntimeDispatchSlotArgumentAccess,
    slot_by_tensor: &BTreeMap<TensorRef, usize>,
    op_name: &str,
) -> Result<()> {
    let slot = slot_by_tensor.get(tensor).ok_or_else(|| {
        anyhow!("op {op_name} argument {name} references tensor {tensor} outside runtime slot plan")
    })?;
    arguments.push(RuntimeDispatchSlotArgument {
        name,
        slot: *slot,
        access,
    });
    Ok(())
}

