#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeStageSlotPlan {
    pub target: &'static str,
    pub stages: Vec<RuntimeStageSlotPlanEntry>,
    pub unstaged_ops: Vec<String>,
    pub gap_ops: usize,
    pub binding_issues: Vec<TensorBindingIssue>,
}

impl ModelRuntimeStageSlotPlan {
    pub fn stage_for(&self, stage_name: &str) -> Option<&RuntimeStageSlotPlanEntry> {
        self.stages
            .iter()
            .find(|stage| stage.stage_name == stage_name)
    }

    pub fn validate_stage_buffer_bindings(
        &self,
        slots: &ModelRuntimeSlotPlan,
        bindings: &[RuntimeSlotBufferBinding],
    ) -> ModelRuntimeStageSlotBindingValidation {
        let stages = self
            .stages
            .iter()
            .map(|stage| RuntimeStageSlotBindingValidationEntry {
                stage_index: stage.stage_index,
                stage_name: stage.stage_name.clone(),
                kind: stage.kind,
                required_slots: stage.resource_slots.clone(),
                validation: slots
                    .validate_required_buffer_bindings(&stage.resource_slots, bindings),
            })
            .collect();
        ModelRuntimeStageSlotBindingValidation {
            target: self.target,
            stages,
        }
    }

    pub fn assert_static_ready(&self) -> Result<()> {
        let mut issues = Vec::new();
        if !self.binding_issues.is_empty() {
            let binding_issues = self
                .binding_issues
                .iter()
                .map(|issue| format!("{}: {}", issue.tensor, issue.message))
                .collect::<Vec<_>>();
            issues.push(format!("binding issues: {}", binding_issues.join("; ")));
        }
        if !self.unstaged_ops.is_empty() {
            issues.push(format!("unstaged ops: {}", self.unstaged_ops.join(", ")));
        }
        let stage_gaps = self
            .stages
            .iter()
            .filter(|stage| stage.has_gaps())
            .map(|stage| {
                format!(
                    "{}:{:?} gaps: {}",
                    stage.stage_name,
                    stage.kind,
                    stage.gap_op_names.join(", ")
                )
            })
            .collect::<Vec<_>>();
        if !stage_gaps.is_empty() {
            issues.push(format!("stage gaps: {}", stage_gaps.join("; ")));
        }
        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime stage slot plan for {} is not static-ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn runtime_stage_slot_plan_from(
    graph: &ModelPrimitiveGraph,
    slots: &ModelRuntimeSlotPlan,
) -> Result<ModelRuntimeStageSlotPlan> {
    let mut stages = Vec::with_capacity(graph.stages.len());

    for (stage_index, stage) in graph.stages.iter().enumerate() {
        let mut op_names = Vec::new();
        let mut read_slots = BTreeSet::new();
        let mut write_slots = BTreeSet::new();
        let mut stage_input_slots = BTreeSet::new();
        let mut produced_in_stage = BTreeSet::new();
        let mut native_gpu_ops = 0usize;
        let mut fused_native_gpu_ops = 0usize;
        let mut gap_op_names = Vec::new();

        for op_index in stage.op_range() {
            let op = slots.op_slots.get(op_index).ok_or_else(|| {
                anyhow!(
                    "runtime stage slot plan missing op slot row {} for stage {}",
                    op_index,
                    stage.name
                )
            })?;
            op_names.push(op.op_name.clone());
            match op.route.status {
                LoweringStatus::NativeGpu => native_gpu_ops += 1,
                LoweringStatus::FusedNativeGpu => fused_native_gpu_ops += 1,
                LoweringStatus::Gap => gap_op_names.push(op.op_name.clone()),
            }
            for slot_ref in &op.read_slots {
                read_slots.insert(slot_ref.slot);
                if !produced_in_stage.contains(&slot_ref.slot) {
                    stage_input_slots.insert(slot_ref.slot);
                }
            }
            for slot_ref in &op.write_slots {
                write_slots.insert(slot_ref.slot);
                produced_in_stage.insert(slot_ref.slot);
            }
        }

        let resource_slots = read_slots.union(&write_slots).copied().collect::<Vec<_>>();
        let mut external_input_slots = Vec::new();
        let mut external_output_slots = Vec::new();
        let mut checkpoint_weight_slots = Vec::new();
        let mut persistent_state_slots = Vec::new();
        let mut scratch_slots = Vec::new();
        let mut unused_slots = Vec::new();
        let mut footprint = RuntimeStageSlotFootprint::default();
        for slot in &resource_slots {
            let tensor_slot = slots.tensor_slots.get(*slot).ok_or_else(|| {
                anyhow!(
                    "runtime stage slot plan references missing tensor slot {}",
                    slot
                )
            })?;
            push_runtime_slot_class(
                tensor_slot.class,
                *slot,
                &mut external_input_slots,
                &mut external_output_slots,
                &mut checkpoint_weight_slots,
                &mut persistent_state_slots,
                &mut scratch_slots,
                &mut unused_slots,
            );
            footprint.add(tensor_slot)?;
        }

        stages.push(RuntimeStageSlotPlanEntry {
            stage_index,
            stage_name: stage.name.clone(),
            kind: stage.kind,
            first_op: stage.first_op,
            op_count: stage.op_count,
            op_names,
            read_slots: read_slots.into_iter().collect(),
            write_slots: write_slots.into_iter().collect(),
            stage_input_slots: stage_input_slots.into_iter().collect(),
            resource_slots,
            external_input_slots,
            external_output_slots,
            checkpoint_weight_slots,
            persistent_state_slots,
            scratch_slots,
            unused_slots,
            footprint,
            native_gpu_ops,
            fused_native_gpu_ops,
            gap_ops: gap_op_names.len(),
            gap_op_names,
        });
    }

    Ok(ModelRuntimeStageSlotPlan {
        target: slots.target,
        stages,
        unstaged_ops: slots.unstaged_ops.clone(),
        gap_ops: slots.gap_ops,
        binding_issues: slots.binding_issues.clone(),
    })
}

