#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeStageBundlePlan {
    pub target: &'static str,
    pub stages: Vec<RuntimeStageBundlePlanEntry>,
    pub unstaged_ops: Vec<String>,
    pub unstaged_op_slots: Vec<RuntimeOpSlotPlanEntry>,
    pub gap_ops: usize,
    pub binding_issues: Vec<TensorBindingIssue>,
}

impl ModelRuntimeStageBundlePlan {
    pub fn stage_for(&self, stage_name: &str) -> Option<&RuntimeStageBundlePlanEntry> {
        self.stages
            .iter()
            .find(|stage| stage.stage_name == stage_name)
    }

    pub fn op_entry_for(&self, op_name: &str) -> Option<&RuntimeOpSlotPlanEntry> {
        self.stages
            .iter()
            .flat_map(|stage| stage.op_slots.iter())
            .chain(self.unstaged_op_slots.iter())
            .find(|entry| entry.op_name == op_name)
    }

    pub fn assert_static_ready(&self) -> Result<()> {
        let mut issues = Vec::new();
        if !self.binding_issues.is_empty() {
            let binding_issues = self
                .binding_issues
                .iter()
                .map(|issue| format!("{}: {}", issue.tensor, issue.message))
                .collect::<Vec<_>>();
            issues.push(format!("binding issues: {}", binding_issues.join("; ")));
        }
        if !self.unstaged_ops.is_empty() {
            issues.push(format!("unstaged ops: {}", self.unstaged_ops.join(", ")));
        }
        let stage_gaps = self
            .stages
            .iter()
            .filter(|stage| stage.has_gaps())
            .map(|stage| {
                format!(
                    "{}:{:?} gaps: {}",
                    stage.stage_name,
                    stage.kind,
                    stage.resources.gap_op_names.join(", ")
                )
            })
            .collect::<Vec<_>>();
        if !stage_gaps.is_empty() {
            issues.push(format!("stage gaps: {}", stage_gaps.join("; ")));
        }
        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime stage bundle plan for {} is not static-ready: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }
}

fn runtime_stage_bundle_plan_from(
    slots: &ModelRuntimeSlotPlan,
    stage_slots: &ModelRuntimeStageSlotPlan,
) -> Result<ModelRuntimeStageBundlePlan> {
    let mut stages = Vec::with_capacity(stage_slots.stages.len());

    for resources in &stage_slots.stages {
        let end = resources
            .first_op
            .checked_add(resources.op_count)
            .ok_or_else(|| {
                anyhow!(
                    "runtime stage bundle plan stage {} op range overflows",
                    resources.stage_name
                )
            })?;
        let mut op_slots = Vec::with_capacity(resources.op_count);
        for op_index in resources.first_op..end {
            let op = slots.op_slots.get(op_index).ok_or_else(|| {
                anyhow!(
                    "runtime stage bundle plan missing op slot row {} for stage {}",
                    op_index,
                    resources.stage_name
                )
            })?;
            if op.stage_name.as_deref() != Some(resources.stage_name.as_str())
                || op.stage_kind != Some(resources.kind)
            {
                return Err(anyhow!(
                    "runtime stage bundle plan row {} stage mismatch: op {:?}:{:?}, stage {}:{:?}",
                    op_index,
                    op.stage_name,
                    op.stage_kind,
                    resources.stage_name,
                    resources.kind
                ));
            }
            op_slots.push(op.clone());
        }

        let op_names = op_slots
            .iter()
            .map(|op| op.op_name.clone())
            .collect::<Vec<_>>();
        if op_names != resources.op_names {
            return Err(anyhow!(
                "runtime stage bundle plan stage {} op names mismatch: slots {:?}, resources {:?}",
                resources.stage_name,
                op_names,
                resources.op_names
            ));
        }

        stages.push(RuntimeStageBundlePlanEntry {
            stage_index: resources.stage_index,
            stage_name: resources.stage_name.clone(),
            kind: resources.kind,
            first_op: resources.first_op,
            op_count: resources.op_count,
            resources: resources.clone(),
            op_slots,
        });
    }

    let unstaged_op_slots = slots
        .op_slots
        .iter()
        .filter(|entry| entry.stage_name.is_none())
        .cloned()
        .collect::<Vec<_>>();
    let unstaged_ops = unstaged_op_slots
        .iter()
        .map(|entry| entry.op_name.clone())
        .collect::<Vec<_>>();
    if unstaged_ops != slots.unstaged_ops || unstaged_ops != stage_slots.unstaged_ops {
        return Err(anyhow!(
            "runtime stage bundle plan unstaged ops mismatch: slots {:?}, stage slots {:?}, derived {:?}",
            slots.unstaged_ops,
            stage_slots.unstaged_ops,
            unstaged_ops
        ));
    }

    Ok(ModelRuntimeStageBundlePlan {
        target: slots.target,
        stages,
        unstaged_ops,
        unstaged_op_slots,
        gap_ops: slots.gap_ops,
        binding_issues: slots.binding_issues.clone(),
    })
}

