#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeLaunchSlotHandle {
    pub slot: usize,
    pub tensor: TensorRef,
    pub class: TensorBindingClass,
    pub lifetime_access: TensorBindingAccess,
    pub bytes: usize,
    pub access: RuntimeBufferAccess,
    pub handle: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeDispatchLaunchCandidate {
    pub op_index: usize,
    pub op_name: String,
    pub kind: PrimitiveKind,
    pub stage_name: String,
    pub stage_kind: ModelStageKind,
    pub route: PrimitiveLoweringRoute,
    pub entrypoint_symbols: Vec<String>,
    pub slot_arguments: Vec<RuntimeDispatchSlotArgument>,
    pub scalar_arguments: Vec<RuntimeDispatchScalarArgument>,
    pub read_handles: Vec<RuntimeLaunchSlotHandle>,
    pub write_handles: Vec<RuntimeLaunchSlotHandle>,
}

impl RuntimeDispatchLaunchCandidate {
    pub fn read_handle_for(&self, slot: usize) -> Option<&RuntimeLaunchSlotHandle> {
        self.read_handles.iter().find(|handle| handle.slot == slot)
    }

    pub fn write_handle_for(&self, slot: usize) -> Option<&RuntimeLaunchSlotHandle> {
        self.write_handles.iter().find(|handle| handle.slot == slot)
    }

    pub fn slot_argument_for(&self, name: &str) -> Option<&RuntimeDispatchSlotArgument> {
        self.slot_arguments
            .iter()
            .find(|argument| argument.name == name)
    }

    pub fn scalar_argument_for(&self, name: &str) -> Option<&RuntimeDispatchScalarArgument> {
        self.scalar_arguments
            .iter()
            .find(|argument| argument.name == name)
    }

    pub fn launch_argument_entry(&self) -> Result<RuntimeDispatchLaunchArgumentEntry> {
        runtime_dispatch_launch_argument_entry_from(self)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeStageLaunchCandidateEntry {
    pub stage_index: usize,
    pub stage_name: String,
    pub kind: ModelStageKind,
    pub required_slots: Vec<usize>,
    pub resource_handles: Vec<RuntimeLaunchSlotHandle>,
    pub op_names: Vec<String>,
    pub entrypoint_symbols: Vec<String>,
    pub dispatches: Vec<RuntimeDispatchLaunchCandidate>,
}

impl RuntimeStageLaunchCandidateEntry {
    pub fn dispatch_for(&self, op_name: &str) -> Option<&RuntimeDispatchLaunchCandidate> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn resource_handle_for(&self, slot: usize) -> Option<&RuntimeLaunchSlotHandle> {
        self.resource_handles
            .iter()
            .find(|handle| handle.slot == slot)
    }

    pub fn launch_argument_entry(&self) -> Result<RuntimeStageLaunchArgumentEntry> {
        runtime_stage_launch_argument_entry_from(self)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeStageLaunchCandidatePlan {
    pub target: &'static str,
    pub stages: Vec<RuntimeStageLaunchCandidateEntry>,
    pub dispatch_count: usize,
}

impl ModelRuntimeStageLaunchCandidatePlan {
    pub fn stage_for(&self, stage_name: &str) -> Option<&RuntimeStageLaunchCandidateEntry> {
        self.stages
            .iter()
            .find(|stage| stage.stage_name == stage_name)
    }

    pub fn dispatch_for(&self, op_name: &str) -> Option<&RuntimeDispatchLaunchCandidate> {
        self.stages
            .iter()
            .flat_map(|stage| stage.dispatches.iter())
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn launch_window_plan(
        &self,
        max_dispatches_per_window: usize,
    ) -> Result<ModelRuntimeLaunchWindowPlan> {
        runtime_launch_window_plan_from(self, max_dispatches_per_window)
    }

    pub fn launch_entrypoint_provenance_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchEntrypointProvenancePlan> {
        runtime_launch_entrypoint_provenance_plan_from(self)
    }

    pub fn launch_kernel_requirement_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelRequirementPlan> {
        runtime_launch_kernel_requirement_plan_from(self)
    }

    pub fn launch_argument_plan(&self) -> Result<ModelRuntimeLaunchArgumentPlan> {
        runtime_launch_argument_plan_from(self)
    }
}

