#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchAqlPacketFieldPlan {
    pub target: &'static str,
    pub code_object_target: String,
    pub code_object_sha256: String,
    pub dispatch_count: usize,
    pub argument_count: usize,
    pub required_kernel_count: usize,
    pub kernel_candidate_count: usize,
    pub resolved_aql_packet_fields: Vec<&'static str>,
    pub unresolved_aql_packet_fields: Vec<&'static str>,
    pub unresolved_runtime_requirements: Vec<&'static str>,
    pub stages: Vec<RuntimeStageLaunchAqlPacketFieldEntry>,
}

impl ModelRuntimeLaunchAqlPacketFieldPlan {
    pub fn stage_for(&self, stage_name: &str) -> Option<&RuntimeStageLaunchAqlPacketFieldEntry> {
        self.stages
            .iter()
            .find(|stage| stage.stage_name == stage_name)
    }

    pub fn dispatch_for(&self, op_name: &str) -> Option<&RuntimeDispatchLaunchAqlPacketFieldEntry> {
        self.stages
            .iter()
            .flat_map(|stage| stage.dispatches.iter())
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn has_unresolved_runtime_fields(&self) -> bool {
        !self.unresolved_aql_packet_fields.is_empty()
            || !self.unresolved_runtime_requirements.is_empty()
    }

    pub fn kernel_selection_readiness_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelSelectionReadinessPlan> {
        runtime_launch_kernel_selection_readiness_plan_from_packet_fields(self)
    }

    pub fn host_launcher_branch_resolution_request_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchHostLauncherBranchResolutionRequestPlan> {
        self.kernel_selection_readiness_plan()?
            .host_launcher_branch_resolution_request_plan()
    }

    pub fn assert_metadata_handoff_ready(&self) -> Result<()> {
        let mut issues = Vec::new();
        let dispatch_count = self
            .stages
            .iter()
            .map(|stage| stage.dispatches.len())
            .sum::<usize>();
        let argument_count = self
            .stages
            .iter()
            .map(|stage| stage.argument_count)
            .sum::<usize>();
        let kernel_candidate_count = self
            .stages
            .iter()
            .map(|stage| stage.kernel_candidate_count)
            .sum::<usize>();
        if dispatch_count != self.dispatch_count {
            issues.push(format!(
                "stage dispatch count {dispatch_count} != plan dispatch count {}",
                self.dispatch_count
            ));
        }
        if argument_count != self.argument_count {
            issues.push(format!(
                "stage argument count {argument_count} != plan argument count {}",
                self.argument_count
            ));
        }
        if kernel_candidate_count != self.kernel_candidate_count {
            issues.push(format!(
                "stage kernel candidate count {kernel_candidate_count} != plan kernel candidate count {}",
                self.kernel_candidate_count
            ));
        }
        if self.required_kernel_count > self.kernel_candidate_count {
            issues.push(format!(
                "required kernel count {} exceeds packet kernel candidate count {}",
                self.required_kernel_count, self.kernel_candidate_count
            ));
        }
        if self.resolved_aql_packet_fields != MODEL_RUNTIME_AQL_RESOLVED_PACKET_FIELDS {
            issues.push(format!(
                "resolved AQL packet fields changed: {}",
                self.resolved_aql_packet_fields.join(", ")
            ));
        }
        if self.unresolved_aql_packet_fields != MODEL_RUNTIME_AQL_UNRESOLVED_PACKET_FIELDS {
            issues.push(format!(
                "unresolved AQL packet fields changed: {}",
                self.unresolved_aql_packet_fields.join(", ")
            ));
        }
        if self.unresolved_runtime_requirements != MODEL_RUNTIME_AQL_UNRESOLVED_RUNTIME_REQUIREMENTS
        {
            issues.push(format!(
                "unresolved runtime requirements changed: {}",
                self.unresolved_runtime_requirements.join(", ")
            ));
        }
        if !self.has_unresolved_runtime_fields() {
            issues
                .push("packet field plan unexpectedly marks executable packets ready".to_string());
        }
        for stage in &self.stages {
            let stage_argument_count = stage
                .dispatches
                .iter()
                .map(|dispatch| dispatch.argument_count)
                .sum::<usize>();
            let stage_kernel_candidate_count = stage
                .dispatches
                .iter()
                .map(|dispatch| dispatch.kernel_candidates.len())
                .sum::<usize>();
            if stage_argument_count != stage.argument_count {
                issues.push(format!(
                    "stage {} argument count {} != dispatch argument count {stage_argument_count}",
                    stage.stage_name, stage.argument_count
                ));
            }
            if stage_kernel_candidate_count != stage.kernel_candidate_count {
                issues.push(format!(
                    "stage {} kernel candidate count {} != dispatch kernel candidate count {stage_kernel_candidate_count}",
                    stage.stage_name, stage.kernel_candidate_count
                ));
            }
            for dispatch in &stage.dispatches {
                if dispatch.kernel_candidates.is_empty() {
                    issues.push(format!(
                        "dispatch {} has no kernel candidates",
                        dispatch.op_name
                    ));
                }
                if dispatch.argument_names.len() != dispatch.argument_count {
                    issues.push(format!(
                        "dispatch {} argument names {} != argument count {}",
                        dispatch.op_name,
                        dispatch.argument_names.len(),
                        dispatch.argument_count
                    ));
                }
                if dispatch.required_kernel_symbols.len() != dispatch.kernel_candidates.len() {
                    issues.push(format!(
                        "dispatch {} required kernel symbols {} != kernel candidates {}",
                        dispatch.op_name,
                        dispatch.required_kernel_symbols.len(),
                        dispatch.kernel_candidates.len()
                    ));
                }
                for kernel in &dispatch.kernel_candidates {
                    if kernel.kernarg_size == 0 {
                        issues.push(format!(
                            "dispatch {} kernel {} has zero kernarg size",
                            dispatch.op_name, kernel.kernel_symbol
                        ));
                    }
                }
            }
        }
        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch AQL packet field plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

fn runtime_launch_aql_packet_field_plan_from(
    preflight: &ModelRuntimeLaunchPreflightReport,
) -> Result<ModelRuntimeLaunchAqlPacketFieldPlan> {
    preflight.assert_ready()?;
    let mut dispatch_count = 0usize;
    let mut argument_count = 0usize;
    let mut kernel_candidate_count = 0usize;
    let stages = preflight
        .stage_launch_candidates
        .stages
        .iter()
        .map(|stage| {
            let entry = runtime_stage_launch_aql_packet_field_entry_from(preflight, stage)?;
            dispatch_count += entry.dispatches.len();
            argument_count += entry.argument_count;
            kernel_candidate_count += entry.kernel_candidate_count;
            Ok(entry)
        })
        .collect::<Result<Vec<_>>>()?;
    let plan = ModelRuntimeLaunchAqlPacketFieldPlan {
        target: preflight.target,
        code_object_target: preflight.code_object_target.clone(),
        code_object_sha256: preflight.code_object_sha256.clone(),
        dispatch_count,
        argument_count,
        required_kernel_count: preflight.required_kernel_count,
        kernel_candidate_count,
        resolved_aql_packet_fields: MODEL_RUNTIME_AQL_RESOLVED_PACKET_FIELDS.to_vec(),
        unresolved_aql_packet_fields: MODEL_RUNTIME_AQL_UNRESOLVED_PACKET_FIELDS.to_vec(),
        unresolved_runtime_requirements: MODEL_RUNTIME_AQL_UNRESOLVED_RUNTIME_REQUIREMENTS.to_vec(),
        stages,
    };
    plan.assert_metadata_handoff_ready()?;
    Ok(plan)
}

fn runtime_stage_launch_aql_packet_field_entry_from(
    preflight: &ModelRuntimeLaunchPreflightReport,
    stage: &RuntimeStageLaunchCandidateEntry,
) -> Result<RuntimeStageLaunchAqlPacketFieldEntry> {
    let dispatches = stage
        .dispatches
        .iter()
        .map(|dispatch| runtime_dispatch_launch_aql_packet_field_entry_from(preflight, dispatch))
        .collect::<Result<Vec<_>>>()?;
    let argument_count = dispatches
        .iter()
        .map(|dispatch| dispatch.argument_count)
        .sum::<usize>();
    let kernel_candidate_count = dispatches
        .iter()
        .map(|dispatch| dispatch.kernel_candidates.len())
        .sum::<usize>();
    Ok(RuntimeStageLaunchAqlPacketFieldEntry {
        stage_index: stage.stage_index,
        stage_name: stage.stage_name.clone(),
        kind: stage.kind,
        dispatches,
        argument_count,
        kernel_candidate_count,
    })
}

fn runtime_dispatch_launch_aql_packet_field_entry_from(
    preflight: &ModelRuntimeLaunchPreflightReport,
    dispatch: &RuntimeDispatchLaunchCandidate,
) -> Result<RuntimeDispatchLaunchAqlPacketFieldEntry> {
    let kernel_metadata = preflight
        .kernel_metadata
        .dispatch_for(&dispatch.op_name)
        .ok_or_else(|| {
            anyhow!(
                "runtime launch preflight report missing kernel metadata for dispatch {}",
                dispatch.op_name
            )
        })?;
    let launch_arguments = preflight
        .launch_arguments
        .dispatch_for(&dispatch.op_name)
        .ok_or_else(|| {
            anyhow!(
                "runtime launch preflight report missing launch arguments for dispatch {}",
                dispatch.op_name
            )
        })?;
    let kernel_candidates = kernel_metadata
        .kernels
        .iter()
        .map(RuntimeLaunchAqlPacketKernelCandidate::from_metadata)
        .collect::<Vec<_>>();
    Ok(RuntimeDispatchLaunchAqlPacketFieldEntry {
        op_index: dispatch.op_index,
        op_name: dispatch.op_name.clone(),
        kind: dispatch.kind,
        stage_name: dispatch.stage_name.clone(),
        stage_kind: dispatch.stage_kind,
        entrypoint_symbols: dispatch.entrypoint_symbols.clone(),
        argument_names: launch_arguments
            .arguments
            .iter()
            .map(|argument| argument.name)
            .collect(),
        argument_count: launch_arguments.arguments.len(),
        required_kernel_symbols: kernel_metadata.required_kernel_symbols.clone(),
        kernel_candidates,
    })
}

