#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchKernelSelectionReadinessPlan {
    pub target: &'static str,
    pub code_object_target: String,
    pub code_object_sha256: String,
    pub dispatch_count: usize,
    pub selected_dispatch_count: usize,
    pub ambiguous_dispatch_count: usize,
    pub missing_dispatch_count: usize,
    pub kernel_candidate_count: usize,
    pub selected_kernel_symbols: Vec<String>,
    pub unresolved_candidate_symbols: Vec<String>,
    pub unresolved_runtime_requirements: Vec<&'static str>,
    pub stages: Vec<RuntimeStageLaunchKernelSelectionEntry>,
}

impl ModelRuntimeLaunchKernelSelectionReadinessPlan {
    pub fn stage_for(&self, stage_name: &str) -> Option<&RuntimeStageLaunchKernelSelectionEntry> {
        self.stages
            .iter()
            .find(|stage| stage.stage_name == stage_name)
    }

    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelSelectionEntry> {
        self.stages
            .iter()
            .flat_map(|stage| stage.dispatches.iter())
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn all_dispatches_selected(&self) -> bool {
        self.selected_dispatch_count == self.dispatch_count
            && self.ambiguous_dispatch_count == 0
            && self.missing_dispatch_count == 0
    }

    pub fn assert_all_selected(&self) -> Result<()> {
        self.assert_consistent()?;
        if self.all_dispatches_selected() {
            return Ok(());
        }
        Err(anyhow!(
            "runtime launch kernel selection for {} has unresolved dispatches: selected={} ambiguous={} missing={} unresolved_requirements={}",
            self.target,
            self.selected_dispatch_count,
            self.ambiguous_dispatch_count,
            self.missing_dispatch_count,
            self.unresolved_runtime_requirements.join(", ")
        ))
    }

    pub fn host_launcher_branch_resolution_request_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchHostLauncherBranchResolutionRequestPlan> {
        runtime_launch_host_launcher_branch_resolution_request_plan_from(self)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        let dispatch_count = self
            .stages
            .iter()
            .map(|stage| stage.dispatch_count)
            .sum::<usize>();
        let selected_dispatch_count = self
            .stages
            .iter()
            .map(|stage| stage.selected_dispatch_count)
            .sum::<usize>();
        let ambiguous_dispatch_count = self
            .stages
            .iter()
            .map(|stage| stage.ambiguous_dispatch_count)
            .sum::<usize>();
        let missing_dispatch_count = self
            .stages
            .iter()
            .map(|stage| stage.missing_dispatch_count)
            .sum::<usize>();
        let kernel_candidate_count = self
            .stages
            .iter()
            .map(|stage| stage.kernel_candidate_count)
            .sum::<usize>();
        let mut selected_kernel_symbols = Vec::new();
        let mut unresolved_candidate_symbols = Vec::new();

        if dispatch_count != self.dispatch_count {
            issues.push(format!(
                "stage dispatch count {dispatch_count} != plan dispatch count {}",
                self.dispatch_count
            ));
        }
        if selected_dispatch_count != self.selected_dispatch_count {
            issues.push(format!(
                "stage selected dispatch count {selected_dispatch_count} != plan selected dispatch count {}",
                self.selected_dispatch_count
            ));
        }
        if ambiguous_dispatch_count != self.ambiguous_dispatch_count {
            issues.push(format!(
                "stage ambiguous dispatch count {ambiguous_dispatch_count} != plan ambiguous dispatch count {}",
                self.ambiguous_dispatch_count
            ));
        }
        if missing_dispatch_count != self.missing_dispatch_count {
            issues.push(format!(
                "stage missing dispatch count {missing_dispatch_count} != plan missing dispatch count {}",
                self.missing_dispatch_count
            ));
        }
        if selected_dispatch_count + ambiguous_dispatch_count + missing_dispatch_count
            != self.dispatch_count
        {
            issues.push(format!(
                "selected+ambiguous+missing dispatch count {} != plan dispatch count {}",
                selected_dispatch_count + ambiguous_dispatch_count + missing_dispatch_count,
                self.dispatch_count
            ));
        }
        if kernel_candidate_count != self.kernel_candidate_count {
            issues.push(format!(
                "stage kernel candidate count {kernel_candidate_count} != plan kernel candidate count {}",
                self.kernel_candidate_count
            ));
        }

        for stage in &self.stages {
            let stage_dispatch_count = stage.dispatches.len();
            let stage_selected_dispatch_count = stage
                .dispatches
                .iter()
                .filter(|dispatch| {
                    dispatch.state == RuntimeLaunchKernelSelectionState::SelectedSingleCandidate
                })
                .count();
            let stage_ambiguous_dispatch_count = stage
                .dispatches
                .iter()
                .filter(|dispatch| {
                    dispatch.state == RuntimeLaunchKernelSelectionState::AmbiguousCandidateSet
                })
                .count();
            let stage_missing_dispatch_count = stage
                .dispatches
                .iter()
                .filter(|dispatch| {
                    dispatch.state == RuntimeLaunchKernelSelectionState::MissingCandidate
                })
                .count();
            let stage_kernel_candidate_count = stage
                .dispatches
                .iter()
                .map(|dispatch| dispatch.candidate_count)
                .sum::<usize>();
            let mut stage_selected_kernel_symbols = Vec::new();
            let mut stage_unresolved_candidate_symbols = Vec::new();

            if stage_dispatch_count != stage.dispatch_count {
                issues.push(format!(
                    "stage {} dispatch entries {} != dispatch count {}",
                    stage.stage_name, stage_dispatch_count, stage.dispatch_count
                ));
            }
            if stage_selected_dispatch_count != stage.selected_dispatch_count {
                issues.push(format!(
                    "stage {} selected dispatch count {stage_selected_dispatch_count} != stage selected dispatch count {}",
                    stage.stage_name, stage.selected_dispatch_count
                ));
            }
            if stage_ambiguous_dispatch_count != stage.ambiguous_dispatch_count {
                issues.push(format!(
                    "stage {} ambiguous dispatch count {stage_ambiguous_dispatch_count} != stage ambiguous dispatch count {}",
                    stage.stage_name, stage.ambiguous_dispatch_count
                ));
            }
            if stage_missing_dispatch_count != stage.missing_dispatch_count {
                issues.push(format!(
                    "stage {} missing dispatch count {stage_missing_dispatch_count} != stage missing dispatch count {}",
                    stage.stage_name, stage.missing_dispatch_count
                ));
            }
            if stage_selected_dispatch_count
                + stage_ambiguous_dispatch_count
                + stage_missing_dispatch_count
                != stage.dispatch_count
            {
                issues.push(format!(
                    "stage {} selected+ambiguous+missing dispatch count mismatch",
                    stage.stage_name
                ));
            }
            if stage_kernel_candidate_count != stage.kernel_candidate_count {
                issues.push(format!(
                    "stage {} kernel candidate count {stage_kernel_candidate_count} != stage kernel candidate count {}",
                    stage.stage_name, stage.kernel_candidate_count
                ));
            }

            for dispatch in &stage.dispatches {
                if dispatch.candidate_symbols.len() != dispatch.candidate_count {
                    issues.push(format!(
                        "dispatch {} candidate symbols {} != candidate count {}",
                        dispatch.op_name,
                        dispatch.candidate_symbols.len(),
                        dispatch.candidate_count
                    ));
                }
                let unique_candidates = dispatch
                    .candidate_symbols
                    .iter()
                    .collect::<BTreeSet<_>>()
                    .len();
                if unique_candidates != dispatch.candidate_symbols.len() {
                    issues.push(format!(
                        "dispatch {} has duplicate candidate symbols",
                        dispatch.op_name
                    ));
                }
                match dispatch.state {
                    RuntimeLaunchKernelSelectionState::SelectedSingleCandidate => {
                        if dispatch.candidate_count != 1 {
                            issues.push(format!(
                                "dispatch {} is selected but candidate count is {}",
                                dispatch.op_name, dispatch.candidate_count
                            ));
                        }
                        match &dispatch.selected_kernel {
                            Some(kernel) => {
                                if !dispatch.candidate_symbols.contains(&kernel.kernel_symbol) {
                                    issues.push(format!(
                                        "dispatch {} selected kernel {} is not in candidate symbols",
                                        dispatch.op_name, kernel.kernel_symbol
                                    ));
                                }
                                extend_unique_strings(
                                    &mut stage_selected_kernel_symbols,
                                    &[kernel.kernel_symbol.clone()],
                                );
                                extend_unique_strings(
                                    &mut selected_kernel_symbols,
                                    &[kernel.kernel_symbol.clone()],
                                );
                            }
                            None => issues.push(format!(
                                "dispatch {} is selected without selected kernel metadata",
                                dispatch.op_name
                            )),
                        }
                        if dispatch.unresolved_reason.is_some() {
                            issues.push(format!(
                                "dispatch {} selected unexpectedly has unresolved reason",
                                dispatch.op_name
                            ));
                        }
                    }
                    RuntimeLaunchKernelSelectionState::AmbiguousCandidateSet => {
                        if dispatch.candidate_count <= 1 {
                            issues.push(format!(
                                "dispatch {} is ambiguous but candidate count is {}",
                                dispatch.op_name, dispatch.candidate_count
                            ));
                        }
                        if dispatch.selected_kernel.is_some() {
                            issues.push(format!(
                                "dispatch {} is ambiguous but has selected kernel metadata",
                                dispatch.op_name
                            ));
                        }
                        if dispatch.unresolved_reason != Some("ambiguous_kernel_candidate_set") {
                            issues.push(format!(
                                "dispatch {} ambiguous reason mismatch",
                                dispatch.op_name
                            ));
                        }
                        extend_unique_strings(
                            &mut stage_unresolved_candidate_symbols,
                            &dispatch.candidate_symbols,
                        );
                        extend_unique_strings(
                            &mut unresolved_candidate_symbols,
                            &dispatch.candidate_symbols,
                        );
                    }
                    RuntimeLaunchKernelSelectionState::MissingCandidate => {
                        if dispatch.candidate_count != 0 {
                            issues.push(format!(
                                "dispatch {} is missing but candidate count is {}",
                                dispatch.op_name, dispatch.candidate_count
                            ));
                        }
                        if dispatch.selected_kernel.is_some() {
                            issues.push(format!(
                                "dispatch {} is missing but has selected kernel metadata",
                                dispatch.op_name
                            ));
                        }
                        if dispatch.unresolved_reason != Some("missing_kernel_candidate") {
                            issues.push(format!(
                                "dispatch {} missing reason mismatch",
                                dispatch.op_name
                            ));
                        }
                    }
                }
            }

            if stage_selected_kernel_symbols != stage.selected_kernel_symbols {
                issues.push(format!(
                    "stage {} selected kernel symbols {:?} != {:?}",
                    stage.stage_name, stage_selected_kernel_symbols, stage.selected_kernel_symbols
                ));
            }
            if stage_unresolved_candidate_symbols != stage.unresolved_candidate_symbols {
                issues.push(format!(
                    "stage {} unresolved candidate symbols {:?} != {:?}",
                    stage.stage_name,
                    stage_unresolved_candidate_symbols,
                    stage.unresolved_candidate_symbols
                ));
            }
        }

        if selected_kernel_symbols != self.selected_kernel_symbols {
            issues.push(format!(
                "selected kernel symbols {:?} != plan selected kernel symbols {:?}",
                selected_kernel_symbols, self.selected_kernel_symbols
            ));
        }
        if unresolved_candidate_symbols != self.unresolved_candidate_symbols {
            issues.push(format!(
                "unresolved candidate symbols {:?} != plan unresolved candidate symbols {:?}",
                unresolved_candidate_symbols, self.unresolved_candidate_symbols
            ));
        }
        let expected_requirements = kernel_selection_unresolved_runtime_requirements(
            ambiguous_dispatch_count,
            missing_dispatch_count,
        );
        if expected_requirements != self.unresolved_runtime_requirements {
            issues.push(format!(
                "unresolved runtime requirements {:?} != expected {:?}",
                self.unresolved_runtime_requirements, expected_requirements
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel selection readiness for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

fn runtime_launch_kernel_selection_readiness_plan_from(
    preflight: &ModelRuntimeLaunchPreflightReport,
) -> Result<ModelRuntimeLaunchKernelSelectionReadinessPlan> {
    preflight.assert_ready()?;
    preflight
        .aql_packet_field_plan()?
        .kernel_selection_readiness_plan()
}

fn runtime_launch_kernel_selection_readiness_plan_from_packet_fields(
    packet_fields: &ModelRuntimeLaunchAqlPacketFieldPlan,
) -> Result<ModelRuntimeLaunchKernelSelectionReadinessPlan> {
    packet_fields.assert_metadata_handoff_ready()?;
    let mut dispatch_count = 0usize;
    let mut selected_dispatch_count = 0usize;
    let mut ambiguous_dispatch_count = 0usize;
    let mut missing_dispatch_count = 0usize;
    let mut kernel_candidate_count = 0usize;
    let mut selected_kernel_symbols = Vec::new();
    let mut unresolved_candidate_symbols = Vec::new();
    let stages = packet_fields
        .stages
        .iter()
        .map(|stage| {
            let entry = runtime_stage_launch_kernel_selection_entry_from(stage)?;
            dispatch_count += entry.dispatch_count;
            selected_dispatch_count += entry.selected_dispatch_count;
            ambiguous_dispatch_count += entry.ambiguous_dispatch_count;
            missing_dispatch_count += entry.missing_dispatch_count;
            kernel_candidate_count += entry.kernel_candidate_count;
            extend_unique_strings(&mut selected_kernel_symbols, &entry.selected_kernel_symbols);
            extend_unique_strings(
                &mut unresolved_candidate_symbols,
                &entry.unresolved_candidate_symbols,
            );
            Ok(entry)
        })
        .collect::<Result<Vec<_>>>()?;
    let plan = ModelRuntimeLaunchKernelSelectionReadinessPlan {
        target: packet_fields.target,
        code_object_target: packet_fields.code_object_target.clone(),
        code_object_sha256: packet_fields.code_object_sha256.clone(),
        dispatch_count,
        selected_dispatch_count,
        ambiguous_dispatch_count,
        missing_dispatch_count,
        kernel_candidate_count,
        selected_kernel_symbols,
        unresolved_candidate_symbols,
        unresolved_runtime_requirements: kernel_selection_unresolved_runtime_requirements(
            ambiguous_dispatch_count,
            missing_dispatch_count,
        ),
        stages,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

const MODEL_RUNTIME_HOST_LAUNCHER_BRANCH_RESOLUTION_REASON_AMBIGUOUS: &str =
    "ambiguous_kernel_candidate_set";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeDispatchLaunchHostLauncherBranchResolutionRequestEntry {
    pub op_index: usize,
    pub op_name: String,
    pub kind: PrimitiveKind,
    pub stage_name: String,
    pub stage_kind: ModelStageKind,
    pub entrypoint_symbols: Vec<String>,
    pub candidate_count: usize,
    pub candidate_symbols: Vec<String>,
    pub branch_resolution_requested: bool,
    pub branch_resolution_applied: bool,
    pub branch_resolution_reason: &'static str,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchHostLauncherBranchResolutionRequestPlan {
    pub target: &'static str,
    pub code_object_target: String,
    pub code_object_sha256: String,
    pub dispatch_count: usize,
    pub selected_dispatch_count: usize,
    pub ambiguous_dispatch_count: usize,
    pub missing_dispatch_count: usize,
    pub branch_resolution_request_count: usize,
    pub branch_resolution_applied_count: usize,
    pub unresolved_candidate_symbol_count: usize,
    pub all_branches_resolved: bool,
    pub request_plan_ready: bool,
    pub unresolved_runtime_requirements: Vec<&'static str>,
    pub dispatches: Vec<RuntimeDispatchLaunchHostLauncherBranchResolutionRequestEntry>,
}

impl ModelRuntimeLaunchHostLauncherBranchResolutionRequestPlan {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchHostLauncherBranchResolutionRequestEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn branch_resolution_request_op_names(&self) -> Vec<String> {
        self.dispatches
            .iter()
            .map(|dispatch| dispatch.op_name.clone())
            .collect()
    }

    /// Returns delimiter-safe launch-order `(op_name, candidate_symbols)` pairs.
    pub fn branch_resolution_request_candidate_symbol_sets(&self) -> Vec<(String, Vec<String>)> {
        self.dispatches
            .iter()
            .map(|dispatch| (dispatch.op_name.clone(), dispatch.candidate_symbols.clone()))
            .collect()
    }

    /// Returns display-oriented `op=symbol|symbol` labels for fixture output.
    ///
    /// Use `branch_resolution_request_candidate_symbol_sets()` or `dispatches`
    /// directly when delimiter-safe structured data is needed.
    pub fn branch_resolution_request_candidate_symbol_labels(&self) -> Vec<String> {
        self.dispatches
            .iter()
            .map(|dispatch| {
                format!(
                    "{}={}",
                    dispatch.op_name,
                    dispatch.candidate_symbols.join("|")
                )
            })
            .collect()
    }

    pub fn unresolved_candidate_symbols(&self) -> Vec<String> {
        let mut symbols = BTreeSet::new();
        for dispatch in &self.dispatches {
            for symbol in &dispatch.candidate_symbols {
                symbols.insert(symbol.clone());
            }
        }
        symbols.into_iter().collect()
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.branch_resolution_request_count {
            issues.push(format!(
                "branch resolution request entries {} != request count {}",
                self.dispatches.len(),
                self.branch_resolution_request_count
            ));
        }
        if self.branch_resolution_request_count != self.ambiguous_dispatch_count {
            issues.push(format!(
                "branch resolution requests {} != ambiguous dispatch count {}",
                self.branch_resolution_request_count, self.ambiguous_dispatch_count
            ));
        }
        if self.selected_dispatch_count
            + self.ambiguous_dispatch_count
            + self.missing_dispatch_count
            != self.dispatch_count
        {
            issues.push(format!(
                "selected+ambiguous+missing dispatch count {} != dispatch count {}",
                self.selected_dispatch_count
                    + self.ambiguous_dispatch_count
                    + self.missing_dispatch_count,
                self.dispatch_count
            ));
        }
        if self.branch_resolution_applied_count != 0 {
            issues.push(format!(
                "branch resolution applied count {} != 0",
                self.branch_resolution_applied_count
            ));
        }
        if self.all_branches_resolved
            != (self.branch_resolution_applied_count == self.branch_resolution_request_count)
        {
            issues.push("all_branches_resolved does not match applied count".to_string());
        }
        if !self.request_plan_ready {
            issues.push("host-launcher branch resolution request plan is not ready".to_string());
        }
        if self.ambiguous_dispatch_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&"host_launcher_runtime_branch_resolution")
        {
            issues.push(format!(
                "host-launcher branch resolution requirements missing blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut unresolved_candidate_symbols = BTreeSet::new();
        let mut branch_resolution_request_count = 0usize;
        let mut branch_resolution_applied_count = 0usize;
        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in host-launcher branch request plan",
                    dispatch.op_name
                ));
            }
            if dispatch.candidate_symbols.len() != dispatch.candidate_count {
                issues.push(format!(
                    "dispatch {} candidate symbols {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.candidate_symbols.len(),
                    dispatch.candidate_count
                ));
            }
            if dispatch.candidate_count <= 1 {
                issues.push(format!(
                    "dispatch {} branch request has non-ambiguous candidate count {}",
                    dispatch.op_name, dispatch.candidate_count
                ));
            }
            let unique_candidates = dispatch
                .candidate_symbols
                .iter()
                .collect::<BTreeSet<_>>()
                .len();
            if unique_candidates != dispatch.candidate_symbols.len() {
                issues.push(format!(
                    "dispatch {} has duplicate branch candidate symbols",
                    dispatch.op_name
                ));
            }
            if !dispatch.branch_resolution_requested {
                issues.push(format!(
                    "dispatch {} branch resolution is not requested",
                    dispatch.op_name
                ));
            } else {
                branch_resolution_request_count += 1;
            }
            if dispatch.branch_resolution_applied {
                branch_resolution_applied_count += 1;
                issues.push(format!(
                    "dispatch {} branch resolution is unexpectedly applied",
                    dispatch.op_name
                ));
            }
            if dispatch.branch_resolution_reason
                != MODEL_RUNTIME_HOST_LAUNCHER_BRANCH_RESOLUTION_REASON_AMBIGUOUS
            {
                issues.push(format!(
                    "dispatch {} branch resolution reason {} != {}",
                    dispatch.op_name,
                    dispatch.branch_resolution_reason,
                    MODEL_RUNTIME_HOST_LAUNCHER_BRANCH_RESOLUTION_REASON_AMBIGUOUS
                ));
            }
            for symbol in &dispatch.candidate_symbols {
                unresolved_candidate_symbols.insert(symbol.as_str());
            }
        }
        if branch_resolution_request_count != self.branch_resolution_request_count {
            issues.push(format!(
                "branch resolution request count {branch_resolution_request_count} != plan {}",
                self.branch_resolution_request_count
            ));
        }
        if branch_resolution_applied_count != self.branch_resolution_applied_count {
            issues.push(format!(
                "branch resolution applied count {branch_resolution_applied_count} != plan {}",
                self.branch_resolution_applied_count
            ));
        }
        if unresolved_candidate_symbols.len() != self.unresolved_candidate_symbol_count {
            issues.push(format!(
                "unresolved candidate symbol count {} != plan {}",
                unresolved_candidate_symbols.len(),
                self.unresolved_candidate_symbol_count
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch host-launcher branch resolution request plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

fn runtime_launch_host_launcher_branch_resolution_request_plan_from(
    selection: &ModelRuntimeLaunchKernelSelectionReadinessPlan,
) -> Result<ModelRuntimeLaunchHostLauncherBranchResolutionRequestPlan> {
    selection.assert_consistent()?;
    let mut dispatches = Vec::new();
    for dispatch in selection
        .stages
        .iter()
        .flat_map(|stage| stage.dispatches.iter())
    {
        if dispatch.state != RuntimeLaunchKernelSelectionState::AmbiguousCandidateSet {
            continue;
        }
        dispatches.push(
            RuntimeDispatchLaunchHostLauncherBranchResolutionRequestEntry {
                op_index: dispatch.op_index,
                op_name: dispatch.op_name.clone(),
                kind: dispatch.kind,
                stage_name: dispatch.stage_name.clone(),
                stage_kind: dispatch.stage_kind,
                entrypoint_symbols: dispatch.entrypoint_symbols.clone(),
                candidate_count: dispatch.candidate_count,
                candidate_symbols: dispatch.candidate_symbols.clone(),
                branch_resolution_requested: true,
                branch_resolution_applied: false,
                branch_resolution_reason:
                    MODEL_RUNTIME_HOST_LAUNCHER_BRANCH_RESOLUTION_REASON_AMBIGUOUS,
            },
        );
    }
    let unresolved_candidate_symbol_count = dispatches
        .iter()
        .flat_map(|dispatch| dispatch.candidate_symbols.iter())
        .collect::<BTreeSet<_>>()
        .len();
    let branch_resolution_request_count = dispatches.len();
    let branch_resolution_applied_count = 0;
    let plan = ModelRuntimeLaunchHostLauncherBranchResolutionRequestPlan {
        target: selection.target,
        code_object_target: selection.code_object_target.clone(),
        code_object_sha256: selection.code_object_sha256.clone(),
        dispatch_count: selection.dispatch_count,
        selected_dispatch_count: selection.selected_dispatch_count,
        ambiguous_dispatch_count: selection.ambiguous_dispatch_count,
        missing_dispatch_count: selection.missing_dispatch_count,
        branch_resolution_request_count,
        branch_resolution_applied_count,
        unresolved_candidate_symbol_count,
        all_branches_resolved: branch_resolution_applied_count == branch_resolution_request_count,
        request_plan_ready: true,
        unresolved_runtime_requirements: selection.unresolved_runtime_requirements.clone(),
        dispatches,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

fn runtime_stage_launch_kernel_selection_entry_from(
    stage: &RuntimeStageLaunchAqlPacketFieldEntry,
) -> Result<RuntimeStageLaunchKernelSelectionEntry> {
    let dispatches = stage
        .dispatches
        .iter()
        .map(runtime_dispatch_launch_kernel_selection_entry_from)
        .collect::<Result<Vec<_>>>()?;
    let dispatch_count = dispatches.len();
    let selected_dispatch_count = dispatches
        .iter()
        .filter(|dispatch| {
            dispatch.state == RuntimeLaunchKernelSelectionState::SelectedSingleCandidate
        })
        .count();
    let ambiguous_dispatch_count = dispatches
        .iter()
        .filter(|dispatch| {
            dispatch.state == RuntimeLaunchKernelSelectionState::AmbiguousCandidateSet
        })
        .count();
    let missing_dispatch_count = dispatches
        .iter()
        .filter(|dispatch| dispatch.state == RuntimeLaunchKernelSelectionState::MissingCandidate)
        .count();
    let kernel_candidate_count = dispatches
        .iter()
        .map(|dispatch| dispatch.candidate_count)
        .sum::<usize>();
    let mut selected_kernel_symbols = Vec::new();
    let mut unresolved_candidate_symbols = Vec::new();
    for dispatch in &dispatches {
        match &dispatch.selected_kernel {
            Some(kernel) => extend_unique_strings(
                &mut selected_kernel_symbols,
                &[kernel.kernel_symbol.clone()],
            ),
            None => extend_unique_strings(
                &mut unresolved_candidate_symbols,
                &dispatch.candidate_symbols,
            ),
        }
    }
    Ok(RuntimeStageLaunchKernelSelectionEntry {
        stage_index: stage.stage_index,
        stage_name: stage.stage_name.clone(),
        kind: stage.kind,
        dispatches,
        dispatch_count,
        selected_dispatch_count,
        ambiguous_dispatch_count,
        missing_dispatch_count,
        kernel_candidate_count,
        selected_kernel_symbols,
        unresolved_candidate_symbols,
    })
}

fn runtime_dispatch_launch_kernel_selection_entry_from(
    dispatch: &RuntimeDispatchLaunchAqlPacketFieldEntry,
) -> Result<RuntimeDispatchLaunchKernelSelectionEntry> {
    let candidate_symbols = dispatch
        .kernel_candidates
        .iter()
        .map(|candidate| candidate.kernel_symbol.clone())
        .collect::<Vec<_>>();
    let (state, selected_kernel, unresolved_reason) = match dispatch.kernel_candidates.len() {
        0 => (
            RuntimeLaunchKernelSelectionState::MissingCandidate,
            None,
            Some("missing_kernel_candidate"),
        ),
        1 => (
            RuntimeLaunchKernelSelectionState::SelectedSingleCandidate,
            Some(dispatch.kernel_candidates[0].clone()),
            None,
        ),
        _ => (
            RuntimeLaunchKernelSelectionState::AmbiguousCandidateSet,
            None,
            Some("ambiguous_kernel_candidate_set"),
        ),
    };
    Ok(RuntimeDispatchLaunchKernelSelectionEntry {
        op_index: dispatch.op_index,
        op_name: dispatch.op_name.clone(),
        kind: dispatch.kind,
        stage_name: dispatch.stage_name.clone(),
        stage_kind: dispatch.stage_kind,
        entrypoint_symbols: dispatch.entrypoint_symbols.clone(),
        argument_names: dispatch.argument_names.clone(),
        state,
        candidate_count: dispatch.kernel_candidates.len(),
        candidate_symbols,
        selected_kernel,
        unresolved_reason,
    })
}

fn kernel_selection_unresolved_runtime_requirements(
    ambiguous_dispatch_count: usize,
    missing_dispatch_count: usize,
) -> Vec<&'static str> {
    let mut requirements = Vec::new();
    if ambiguous_dispatch_count > 0 {
        requirements.push("kernel_candidate_selection_policy");
        requirements.push("host_launcher_runtime_branch_resolution");
    }
    if missing_dispatch_count > 0 {
        requirements.push("code_object_kernel_mapping");
    }
    requirements
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeLaunchDevicePointerArgument {
    pub slot: usize,
    pub argument_access: RuntimeDispatchSlotArgumentAccess,
    pub logical_handle: RuntimeLaunchSlotHandle,
    pub device_pointer: RuntimeSlotDevicePointerBinding,
}

#[derive(Clone, Debug, PartialEq, Eq)]
