#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchDeviceArgumentPlan {
    pub target: &'static str,
    pub stages: Vec<RuntimeStageLaunchDeviceArgumentEntry>,
    pub dispatch_count: usize,
    pub argument_count: usize,
    pub pointer_argument_count: usize,
    pub scalar_argument_count: usize,
}

impl ModelRuntimeLaunchDeviceArgumentPlan {
    pub fn stage_for(&self, stage_name: &str) -> Option<&RuntimeStageLaunchDeviceArgumentEntry> {
        self.stages
            .iter()
            .find(|stage| stage.stage_name == stage_name)
    }

    pub fn dispatch_for(&self, op_name: &str) -> Option<&RuntimeDispatchLaunchDeviceArgumentEntry> {
        self.stages
            .iter()
            .flat_map(|stage| stage.dispatches.iter())
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn assert_bound(&self) -> Result<()> {
        let mut issues = Vec::new();
        let dispatch_count = self
            .stages
            .iter()
            .map(|stage| stage.dispatches.len())
            .sum::<usize>();
        let argument_count = self
            .stages
            .iter()
            .map(|stage| stage.argument_count)
            .sum::<usize>();
        let pointer_argument_count = self
            .stages
            .iter()
            .map(|stage| stage.pointer_argument_count)
            .sum::<usize>();
        let scalar_argument_count = self
            .stages
            .iter()
            .map(|stage| stage.scalar_argument_count)
            .sum::<usize>();
        if dispatch_count != self.dispatch_count {
            issues.push(format!(
                "stage dispatch count {dispatch_count} != plan dispatch count {}",
                self.dispatch_count
            ));
        }
        if argument_count != self.argument_count {
            issues.push(format!(
                "stage argument count {argument_count} != plan argument count {}",
                self.argument_count
            ));
        }
        if pointer_argument_count != self.pointer_argument_count {
            issues.push(format!(
                "stage pointer argument count {pointer_argument_count} != plan pointer argument count {}",
                self.pointer_argument_count
            ));
        }
        if scalar_argument_count != self.scalar_argument_count {
            issues.push(format!(
                "stage scalar argument count {scalar_argument_count} != plan scalar argument count {}",
                self.scalar_argument_count
            ));
        }
        if self.pointer_argument_count + self.scalar_argument_count != self.argument_count {
            issues.push(format!(
                "pointer+scalar argument count {} != plan argument count {}",
                self.pointer_argument_count + self.scalar_argument_count,
                self.argument_count
            ));
        }
        for stage in &self.stages {
            let stage_argument_count = stage
                .dispatches
                .iter()
                .map(|dispatch| dispatch.arguments.len())
                .sum::<usize>();
            let stage_pointer_argument_count = stage
                .dispatches
                .iter()
                .map(|dispatch| dispatch.pointer_argument_count)
                .sum::<usize>();
            let stage_scalar_argument_count = stage
                .dispatches
                .iter()
                .map(|dispatch| dispatch.scalar_argument_count)
                .sum::<usize>();
            if stage_argument_count != stage.argument_count {
                issues.push(format!(
                    "stage {} argument count {} != dispatch argument count {stage_argument_count}",
                    stage.stage_name, stage.argument_count
                ));
            }
            if stage_pointer_argument_count != stage.pointer_argument_count {
                issues.push(format!(
                    "stage {} pointer argument count {} != dispatch pointer argument count {stage_pointer_argument_count}",
                    stage.stage_name, stage.pointer_argument_count
                ));
            }
            if stage_scalar_argument_count != stage.scalar_argument_count {
                issues.push(format!(
                    "stage {} scalar argument count {} != dispatch scalar argument count {stage_scalar_argument_count}",
                    stage.stage_name, stage.scalar_argument_count
                ));
            }
            for dispatch in &stage.dispatches {
                let mut dispatch_pointer_argument_count = 0usize;
                let mut dispatch_scalar_argument_count = 0usize;
                for argument in &dispatch.arguments {
                    match &argument.value {
                        RuntimeLaunchDeviceArgumentValue::Pointer(pointer) => {
                            dispatch_pointer_argument_count += 1;
                            if pointer.slot != pointer.logical_handle.slot
                                || pointer.slot != pointer.device_pointer.slot
                            {
                                issues.push(format!(
                                    "dispatch {} argument {} slot mismatch",
                                    dispatch.op_name, argument.name
                                ));
                            }
                            if pointer.logical_handle.tensor != pointer.device_pointer.tensor {
                                issues.push(format!(
                                    "dispatch {} argument {} tensor mismatch",
                                    dispatch.op_name, argument.name
                                ));
                            }
                            if pointer.device_pointer.bytes < pointer.logical_handle.bytes {
                                issues.push(format!(
                                    "dispatch {} argument {} device bytes {} < logical bytes {}",
                                    dispatch.op_name,
                                    argument.name,
                                    pointer.device_pointer.bytes,
                                    pointer.logical_handle.bytes
                                ));
                            }
                            if pointer.device_pointer.device_va == 0 {
                                issues.push(format!(
                                    "dispatch {} argument {} device VA is null",
                                    dispatch.op_name, argument.name
                                ));
                            }
                            if pointer.device_pointer.device_va
                                & (DEFAULT_RUNTIME_DEVICE_POINTER_ALIGNMENT - 1)
                                != 0
                            {
                                issues.push(format!(
                                    "dispatch {} argument {} device VA 0x{:016x} is not {}-byte aligned",
                                    dispatch.op_name,
                                    argument.name,
                                    pointer.device_pointer.device_va,
                                    DEFAULT_RUNTIME_DEVICE_POINTER_ALIGNMENT
                                ));
                            }
                            if !runtime_buffer_access_covers_argument(
                                pointer.device_pointer.access,
                                pointer.argument_access,
                            ) {
                                issues.push(format!(
                                    "dispatch {} argument {} device access {:?} does not cover {:?}",
                                    dispatch.op_name,
                                    argument.name,
                                    pointer.device_pointer.access,
                                    pointer.argument_access
                                ));
                            }
                        }
                        RuntimeLaunchDeviceArgumentValue::Scalar(_) => {
                            dispatch_scalar_argument_count += 1;
                        }
                    }
                }
                if dispatch_pointer_argument_count != dispatch.pointer_argument_count {
                    issues.push(format!(
                        "dispatch {} pointer argument count {} != observed {}",
                        dispatch.op_name,
                        dispatch.pointer_argument_count,
                        dispatch_pointer_argument_count
                    ));
                }
                if dispatch_scalar_argument_count != dispatch.scalar_argument_count {
                    issues.push(format!(
                        "dispatch {} scalar argument count {} != observed {}",
                        dispatch.op_name,
                        dispatch.scalar_argument_count,
                        dispatch_scalar_argument_count
                    ));
                }
                if dispatch.pointer_argument_count + dispatch.scalar_argument_count
                    != dispatch.arguments.len()
                {
                    issues.push(format!(
                        "dispatch {} pointer+scalar count mismatch",
                        dispatch.op_name
                    ));
                }
            }
        }
        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch device argument plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

fn runtime_launch_device_argument_plan_from(
    preflight: &ModelRuntimeLaunchPreflightReport,
    device_pointers: &ModelRuntimeSlotDevicePointerValidation,
) -> Result<ModelRuntimeLaunchDeviceArgumentPlan> {
    preflight.assert_ready()?;
    device_pointers.assert_complete()?;

    let mut pointer_by_slot = BTreeMap::new();
    for pointer in &device_pointers.bindings {
        if pointer_by_slot
            .insert(pointer.slot, pointer.clone())
            .is_some()
        {
            return Err(anyhow!(
                "runtime launch device argument plan has duplicate device pointer binding for slot {}",
                pointer.slot
            ));
        }
    }

    let mut dispatch_count = 0usize;
    let mut argument_count = 0usize;
    let mut pointer_argument_count = 0usize;
    let mut scalar_argument_count = 0usize;
    let stages = preflight
        .launch_arguments
        .stages
        .iter()
        .map(|stage| {
            let entry = runtime_stage_launch_device_argument_entry_from(stage, &pointer_by_slot)?;
            dispatch_count += entry.dispatches.len();
            argument_count += entry.argument_count;
            pointer_argument_count += entry.pointer_argument_count;
            scalar_argument_count += entry.scalar_argument_count;
            Ok(entry)
        })
        .collect::<Result<Vec<_>>>()?;
    let plan = ModelRuntimeLaunchDeviceArgumentPlan {
        target: preflight.target,
        stages,
        dispatch_count,
        argument_count,
        pointer_argument_count,
        scalar_argument_count,
    };
    plan.assert_bound()?;
    Ok(plan)
}

fn runtime_stage_launch_device_argument_entry_from(
    stage: &RuntimeStageLaunchArgumentEntry,
    pointer_by_slot: &BTreeMap<usize, RuntimeSlotDevicePointerBinding>,
) -> Result<RuntimeStageLaunchDeviceArgumentEntry> {
    let dispatches = stage
        .dispatches
        .iter()
        .map(|dispatch| {
            runtime_dispatch_launch_device_argument_entry_from(dispatch, pointer_by_slot)
        })
        .collect::<Result<Vec<_>>>()?;
    let argument_count = dispatches
        .iter()
        .map(|dispatch| dispatch.arguments.len())
        .sum::<usize>();
    let pointer_argument_count = dispatches
        .iter()
        .map(|dispatch| dispatch.pointer_argument_count)
        .sum::<usize>();
    let scalar_argument_count = dispatches
        .iter()
        .map(|dispatch| dispatch.scalar_argument_count)
        .sum::<usize>();
    Ok(RuntimeStageLaunchDeviceArgumentEntry {
        stage_index: stage.stage_index,
        stage_name: stage.stage_name.clone(),
        kind: stage.kind,
        dispatches,
        argument_count,
        pointer_argument_count,
        scalar_argument_count,
    })
}

fn runtime_dispatch_launch_device_argument_entry_from(
    dispatch: &RuntimeDispatchLaunchArgumentEntry,
    pointer_by_slot: &BTreeMap<usize, RuntimeSlotDevicePointerBinding>,
) -> Result<RuntimeDispatchLaunchDeviceArgumentEntry> {
    let mut pointer_argument_count = 0usize;
    let mut scalar_argument_count = 0usize;
    let mut arguments = Vec::with_capacity(dispatch.arguments.len());
    for argument in &dispatch.arguments {
        let value = match &argument.value {
            RuntimeLaunchArgumentValue::Slot(slot_argument) => {
                pointer_argument_count += 1;
                let device_pointer = pointer_by_slot.get(&slot_argument.slot).cloned().ok_or_else(|| {
                    anyhow!(
                        "runtime launch device argument plan dispatch {} argument {} slot {} has no device pointer binding",
                        dispatch.op_name,
                        argument.name,
                        slot_argument.slot
                    )
                })?;
                if device_pointer.tensor != slot_argument.handle.tensor {
                    return Err(anyhow!(
                        "runtime launch device argument plan dispatch {} argument {} slot {} names tensor {}, expected {}",
                        dispatch.op_name,
                        argument.name,
                        slot_argument.slot,
                        device_pointer.tensor,
                        slot_argument.handle.tensor
                    ));
                }
                if device_pointer.bytes < slot_argument.handle.bytes {
                    return Err(anyhow!(
                        "runtime launch device argument plan dispatch {} argument {} slot {} provides {} bytes, expected at least {}",
                        dispatch.op_name,
                        argument.name,
                        slot_argument.slot,
                        device_pointer.bytes,
                        slot_argument.handle.bytes
                    ));
                }
                if !runtime_buffer_access_covers_argument(
                    device_pointer.access,
                    slot_argument.argument_access,
                ) {
                    return Err(anyhow!(
                        "runtime launch device argument plan dispatch {} argument {} slot {} access {:?} does not cover {:?}",
                        dispatch.op_name,
                        argument.name,
                        slot_argument.slot,
                        device_pointer.access,
                        slot_argument.argument_access
                    ));
                }
                RuntimeLaunchDeviceArgumentValue::Pointer(RuntimeLaunchDevicePointerArgument {
                    slot: slot_argument.slot,
                    argument_access: slot_argument.argument_access,
                    logical_handle: slot_argument.handle.clone(),
                    device_pointer,
                })
            }
            RuntimeLaunchArgumentValue::Scalar(value) => {
                scalar_argument_count += 1;
                RuntimeLaunchDeviceArgumentValue::Scalar(value.clone())
            }
        };
        arguments.push(RuntimeLaunchDeviceArgumentBinding {
            name: argument.name,
            value,
        });
    }
    Ok(RuntimeDispatchLaunchDeviceArgumentEntry {
        op_index: dispatch.op_index,
        op_name: dispatch.op_name.clone(),
        kind: dispatch.kind,
        stage_name: dispatch.stage_name.clone(),
        stage_kind: dispatch.stage_kind,
        entrypoint_symbols: dispatch.entrypoint_symbols.clone(),
        arguments,
        pointer_argument_count,
        scalar_argument_count,
    })
}

fn runtime_buffer_access_covers_argument(
    access: RuntimeBufferAccess,
    required: RuntimeDispatchSlotArgumentAccess,
) -> bool {
    match required {
        RuntimeDispatchSlotArgumentAccess::Read => {
            matches!(
                access,
                RuntimeBufferAccess::ReadOnly | RuntimeBufferAccess::ReadWrite
            )
        }
        RuntimeDispatchSlotArgumentAccess::Write => {
            matches!(
                access,
                RuntimeBufferAccess::WriteOnly | RuntimeBufferAccess::ReadWrite
            )
        }
    }
}

