fn runtime_launch_kernarg_allocation_request_plan_from(
    serialization: &ModelRuntimeLaunchKernargSerializationPlan,
) -> Result<ModelRuntimeLaunchKernargAllocationRequestPlan> {
    serialization.assert_consistent()?;
    let dispatches = serialization
        .stages
        .iter()
        .flat_map(|stage| stage.dispatches.iter())
        .map(
            |dispatch| RuntimeDispatchLaunchKernargAllocationRequestEntry {
                op_index: dispatch.op_index,
                op_name: dispatch.op_name.clone(),
                kind: dispatch.kind,
                stage_name: dispatch.stage_name.clone(),
                stage_kind: dispatch.stage_kind,
                kernarg_region_offset: dispatch.kernarg_region_offset,
                kernarg_region_bytes: dispatch.kernarg_region_bytes,
                serialized_kernarg_bytes: dispatch.serialized_kernarg_bytes,
                trailing_capacity_bytes: dispatch.trailing_capacity_bytes,
                candidate_capacity_shortfall_bytes: dispatch.candidate_capacity_shortfall_bytes,
                backing_allocation_bound: false,
                kernarg_device_va_bound: false,
                copy_request_bytes: dispatch.serialized_kernarg_bytes,
                copy_applied_bytes: 0,
                copy_applied: false,
            },
        )
        .collect::<Vec<_>>();
    let dispatch_copy_request_bytes = dispatches
        .iter()
        .map(|dispatch| dispatch.copy_request_bytes)
        .sum::<usize>();
    let plan = ModelRuntimeLaunchKernargAllocationRequestPlan {
        target: serialization.target,
        code_object_target: serialization.code_object_target.clone(),
        code_object_sha256: serialization.code_object_sha256.clone(),
        dispatch_count: serialization.dispatch_count,
        window_count: serialization.window_count,
        backing_allocation_request_count: 1,
        backing_allocation_bound_count: 0,
        backing_allocation_request_bytes: serialization.kernarg_region_bytes,
        backing_allocation_bound_bytes: 0,
        dispatch_copy_request_count: serialization.dispatch_count,
        dispatch_copy_applied_count: 0,
        dispatch_copy_request_bytes,
        dispatch_copy_applied_bytes: 0,
        device_va_bound_dispatch_count: 0,
        all_kernargs_allocated: false,
        request_plan_ready: true,
        unresolved_runtime_requirements: serialization.unresolved_runtime_requirements.clone(),
        dispatches,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

