pub fn runtime_launch_kernel_argument_abi_schema_for(
    kernel_symbol: &str,
) -> Option<&'static RuntimeLaunchKernelArgumentAbiSchema> {
    MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_NAMED_SCHEMAS
        .iter()
        .find(|schema| schema.kernel_symbol == kernel_symbol)
}

pub fn runtime_launch_kernel_argument_abi_schema_count() -> usize {
    MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_NAMED_SCHEMAS.len()
}

pub fn runtime_launch_kernel_argument_abi_semantic_schema_for(
    kernel_symbol: &str,
) -> Option<&'static RuntimeLaunchKernelArgumentAbiSemanticSchema> {
    MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMAS
        .iter()
        .find(|schema| schema.kernel_symbol == kernel_symbol)
}

pub fn runtime_launch_kernel_argument_abi_semantic_schema_count() -> usize {
    MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMAS.len()
}

fn runtime_launch_kernel_argument_abi_requirements(
    requirements: &[&'static str],
    abi_verification_ready: bool,
) -> Vec<&'static str> {
    requirements
        .iter()
        .copied()
        .filter(|requirement| {
            !abi_verification_ready || *requirement != "kernel_argument_abi_verification"
        })
        .collect()
}

