impl ModelRuntimeLaunchKernelArgumentAbiSemanticPlan {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelArgumentAbiSemanticEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn kernel_argument_abi_semantic_gap_report(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiSemanticGapReport> {
        runtime_launch_kernel_argument_abi_semantic_gap_report_from(self)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "semantic dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if self.semantic_schema_source != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE {
            issues.push(format!(
                "semantic schema source {} != {}",
                self.semantic_schema_source,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE
            ));
        }

        let mut kernel_candidate_count = 0usize;
        let mut semantic_schema_candidate_count = 0usize;
        let mut missing_semantic_schema_candidate_count = 0usize;
        let mut semantic_descriptor_match_candidate_count = 0usize;
        let mut semantic_verified_candidate_count = 0usize;
        let mut dispatches_with_semantic_verified_candidate_count = 0usize;
        let mut dispatches_without_semantic_verified_candidate_count = 0usize;
        let mut field_schema_count = 0usize;
        let mut verified_field_count = 0usize;
        let mut missing_field_count = 0usize;
        let mut field_mismatch_count = 0usize;
        let mut extra_argument_count = 0usize;
        let mut seen_dispatches = BTreeSet::new();

        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in semantic ABI plan",
                    dispatch.op_name
                ));
            }
            if dispatch.candidates.len() != dispatch.kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} semantic candidates {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.candidates.len(),
                    dispatch.kernel_candidate_count
                ));
            }
            let dispatch_schema_candidates = dispatch
                .candidates
                .iter()
                .filter(|candidate| candidate.semantic_schema_available)
                .count();
            let dispatch_missing_schema_candidates =
                dispatch.kernel_candidate_count - dispatch_schema_candidates;
            let dispatch_descriptor_matches = dispatch
                .candidates
                .iter()
                .filter(|candidate| candidate.semantic_descriptor_match)
                .count();
            let dispatch_verified_candidates = dispatch
                .candidates
                .iter()
                .filter(|candidate| candidate.semantic_verified)
                .count();
            let dispatch_field_schema_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.field_schema_count)
                .sum::<usize>();
            let dispatch_verified_field_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.verified_field_count)
                .sum::<usize>();
            let dispatch_missing_field_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.missing_field_count)
                .sum::<usize>();
            let dispatch_field_mismatch_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.field_mismatch_count)
                .sum::<usize>();
            let dispatch_extra_argument_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.extra_argument_count)
                .sum::<usize>();

            if dispatch_schema_candidates != dispatch.semantic_schema_candidate_count {
                issues.push(format!(
                    "dispatch {} schema candidate count {} != {}",
                    dispatch.op_name,
                    dispatch_schema_candidates,
                    dispatch.semantic_schema_candidate_count
                ));
            }
            if dispatch_missing_schema_candidates
                != dispatch.missing_semantic_schema_candidate_count
            {
                issues.push(format!(
                    "dispatch {} missing schema candidate count {} != {}",
                    dispatch.op_name,
                    dispatch_missing_schema_candidates,
                    dispatch.missing_semantic_schema_candidate_count
                ));
            }
            if dispatch_descriptor_matches != dispatch.semantic_descriptor_match_candidate_count {
                issues.push(format!(
                    "dispatch {} descriptor-match candidate count {} != {}",
                    dispatch.op_name,
                    dispatch_descriptor_matches,
                    dispatch.semantic_descriptor_match_candidate_count
                ));
            }
            if dispatch_verified_candidates != dispatch.semantic_verified_candidate_count {
                issues.push(format!(
                    "dispatch {} verified semantic candidate count {} != {}",
                    dispatch.op_name,
                    dispatch_verified_candidates,
                    dispatch.semantic_verified_candidate_count
                ));
            }
            if dispatch.has_semantic_verified_candidate != (dispatch_verified_candidates > 0) {
                issues.push(format!(
                    "dispatch {} verified semantic flag mismatches count {}",
                    dispatch.op_name, dispatch_verified_candidates
                ));
            }
            if dispatch_field_schema_count != dispatch.field_schema_count {
                issues.push(format!(
                    "dispatch {} field schema count {} != {}",
                    dispatch.op_name, dispatch_field_schema_count, dispatch.field_schema_count
                ));
            }
            if dispatch_verified_field_count != dispatch.verified_field_count {
                issues.push(format!(
                    "dispatch {} verified field count {} != {}",
                    dispatch.op_name, dispatch_verified_field_count, dispatch.verified_field_count
                ));
            }
            if dispatch_missing_field_count != dispatch.missing_field_count {
                issues.push(format!(
                    "dispatch {} missing field count {} != {}",
                    dispatch.op_name, dispatch_missing_field_count, dispatch.missing_field_count
                ));
            }
            if dispatch_field_mismatch_count != dispatch.field_mismatch_count {
                issues.push(format!(
                    "dispatch {} field mismatch count {} != {}",
                    dispatch.op_name, dispatch_field_mismatch_count, dispatch.field_mismatch_count
                ));
            }
            if dispatch_extra_argument_count != dispatch.extra_argument_count {
                issues.push(format!(
                    "dispatch {} extra argument count {} != {}",
                    dispatch.op_name, dispatch_extra_argument_count, dispatch.extra_argument_count
                ));
            }

            for candidate in &dispatch.candidates {
                if candidate.semantic_schema_available
                    != (candidate.semantic_schema_kernarg_size.is_some()
                        && candidate.semantic_schema_kernarg_segment_align.is_some())
                {
                    issues.push(format!(
                        "candidate {} schema availability mismatches schema metadata",
                        candidate.kernel_symbol
                    ));
                }
                if candidate.semantic_descriptor_match
                    != (candidate.semantic_schema_kernarg_size == Some(candidate.kernarg_size)
                        && candidate.semantic_schema_kernarg_segment_align
                            == Some(candidate.kernarg_segment_align))
                {
                    issues.push(format!(
                        "candidate {} semantic descriptor-match flag is inconsistent",
                        candidate.kernel_symbol
                    ));
                }
                if candidate.fields.len() != candidate.field_schema_count {
                    issues.push(format!(
                        "candidate {} field rows {} != field schema count {}",
                        candidate.kernel_symbol,
                        candidate.fields.len(),
                        candidate.field_schema_count
                    ));
                }
                let verified_fields = candidate
                    .fields
                    .iter()
                    .filter(|field| field.field_verified)
                    .count();
                let missing_fields = candidate
                    .fields
                    .iter()
                    .filter(|field| !field.model_argument_present)
                    .count();
                let mismatched_fields = candidate
                    .fields
                    .iter()
                    .filter(|field| field.model_argument_present && !field.field_verified)
                    .count();
                if verified_fields != candidate.verified_field_count {
                    issues.push(format!(
                        "candidate {} verified fields {} != {}",
                        candidate.kernel_symbol, verified_fields, candidate.verified_field_count
                    ));
                }
                if missing_fields != candidate.missing_field_count {
                    issues.push(format!(
                        "candidate {} missing fields {} != {}",
                        candidate.kernel_symbol, missing_fields, candidate.missing_field_count
                    ));
                }
                if mismatched_fields != candidate.field_mismatch_count {
                    issues.push(format!(
                        "candidate {} mismatched fields {} != {}",
                        candidate.kernel_symbol, mismatched_fields, candidate.field_mismatch_count
                    ));
                }
                if candidate.extra_model_argument_names.len() != candidate.extra_argument_count {
                    issues.push(format!(
                        "candidate {} extra argument names {} != count {}",
                        candidate.kernel_symbol,
                        candidate.extra_model_argument_names.len(),
                        candidate.extra_argument_count
                    ));
                }
                let semantic_verified = candidate.semantic_schema_available
                    && candidate.semantic_descriptor_match
                    && candidate.kernarg_serialized_fits
                    && candidate.missing_field_count == 0
                    && candidate.field_mismatch_count == 0
                    && candidate.extra_argument_count == 0;
                if candidate.semantic_verified != semantic_verified {
                    issues.push(format!(
                        "candidate {} semantic verified flag is inconsistent",
                        candidate.kernel_symbol
                    ));
                }
                if candidate.semantic_verified != candidate.primary_gap_reason.is_none() {
                    issues.push(format!(
                        "candidate {} semantic verified flag mismatches gap reason {:?}",
                        candidate.kernel_symbol, candidate.primary_gap_reason
                    ));
                }
                let expected_gap_reason =
                    runtime_launch_kernel_argument_abi_semantic_primary_gap_reason_for(candidate);
                if candidate.primary_gap_reason != expected_gap_reason {
                    issues.push(format!(
                        "candidate {} semantic primary gap reason {:?} != expected {:?}",
                        candidate.kernel_symbol, candidate.primary_gap_reason, expected_gap_reason
                    ));
                }
            }

            kernel_candidate_count = checked_add_usize(
                kernel_candidate_count,
                dispatch.kernel_candidate_count,
                "semantic ABI candidate count",
            )?;
            semantic_schema_candidate_count = checked_add_usize(
                semantic_schema_candidate_count,
                dispatch.semantic_schema_candidate_count,
                "semantic ABI schema candidate count",
            )?;
            missing_semantic_schema_candidate_count = checked_add_usize(
                missing_semantic_schema_candidate_count,
                dispatch.missing_semantic_schema_candidate_count,
                "semantic ABI missing schema candidate count",
            )?;
            semantic_descriptor_match_candidate_count = checked_add_usize(
                semantic_descriptor_match_candidate_count,
                dispatch.semantic_descriptor_match_candidate_count,
                "semantic ABI descriptor match candidate count",
            )?;
            semantic_verified_candidate_count = checked_add_usize(
                semantic_verified_candidate_count,
                dispatch.semantic_verified_candidate_count,
                "semantic ABI verified candidate count",
            )?;
            if dispatch.has_semantic_verified_candidate {
                dispatches_with_semantic_verified_candidate_count += 1;
            } else {
                dispatches_without_semantic_verified_candidate_count += 1;
            }
            field_schema_count = checked_add_usize(
                field_schema_count,
                dispatch.field_schema_count,
                "semantic ABI field schema count",
            )?;
            verified_field_count = checked_add_usize(
                verified_field_count,
                dispatch.verified_field_count,
                "semantic ABI verified field count",
            )?;
            missing_field_count = checked_add_usize(
                missing_field_count,
                dispatch.missing_field_count,
                "semantic ABI missing field count",
            )?;
            field_mismatch_count = checked_add_usize(
                field_mismatch_count,
                dispatch.field_mismatch_count,
                "semantic ABI field mismatch count",
            )?;
            extra_argument_count = checked_add_usize(
                extra_argument_count,
                dispatch.extra_argument_count,
                "semantic ABI extra argument count",
            )?;
        }

        macro_rules! check_count {
            ($observed:ident, $field:ident, $label:literal) => {
                if $observed != self.$field {
                    issues.push(format!("{} {} != plan {}", $label, $observed, self.$field));
                }
            };
        }

        check_count!(
            kernel_candidate_count,
            kernel_candidate_count,
            "semantic candidate count"
        );
        check_count!(
            semantic_schema_candidate_count,
            semantic_schema_candidate_count,
            "semantic schema candidate count"
        );
        check_count!(
            missing_semantic_schema_candidate_count,
            missing_semantic_schema_candidate_count,
            "missing semantic schema candidate count"
        );
        check_count!(
            semantic_descriptor_match_candidate_count,
            semantic_descriptor_match_candidate_count,
            "semantic descriptor-match candidate count"
        );
        check_count!(
            semantic_verified_candidate_count,
            semantic_verified_candidate_count,
            "semantic verified candidate count"
        );
        check_count!(
            dispatches_with_semantic_verified_candidate_count,
            dispatches_with_semantic_verified_candidate_count,
            "dispatches with semantic verified candidate"
        );
        check_count!(
            dispatches_without_semantic_verified_candidate_count,
            dispatches_without_semantic_verified_candidate_count,
            "dispatches without semantic verified candidate"
        );
        check_count!(field_schema_count, field_schema_count, "field schema count");
        check_count!(
            verified_field_count,
            verified_field_count,
            "verified field count"
        );
        check_count!(
            missing_field_count,
            missing_field_count,
            "missing field count"
        );
        check_count!(
            field_mismatch_count,
            field_mismatch_count,
            "field mismatch count"
        );
        check_count!(
            extra_argument_count,
            extra_argument_count,
            "extra argument count"
        );

        if self.semantic_schema_candidate_count + self.missing_semantic_schema_candidate_count
            != self.kernel_candidate_count
        {
            issues.push(format!(
                "semantic schema+missing candidate count {} != candidate count {}",
                self.semantic_schema_candidate_count + self.missing_semantic_schema_candidate_count,
                self.kernel_candidate_count
            ));
        }
        if self.dispatches_with_semantic_verified_candidate_count
            + self.dispatches_without_semantic_verified_candidate_count
            != self.dispatch_count
        {
            issues.push(format!(
                "dispatches with+without semantic verified candidates {} != dispatch count {}",
                self.dispatches_with_semantic_verified_candidate_count
                    + self.dispatches_without_semantic_verified_candidate_count,
                self.dispatch_count
            ));
        }
        if self.semantic_abi_ready
            != (self.kernel_candidate_count > 0
                && self.semantic_verified_candidate_count == self.kernel_candidate_count)
        {
            issues.push(
                "semantic ABI readiness mismatches verified semantic candidate count".to_string(),
            );
        }
        let has_abi_requirement = self
            .unresolved_runtime_requirements
            .contains(&"kernel_argument_abi_verification");
        if self.semantic_abi_ready && has_abi_requirement {
            issues.push("semantic ABI is ready but still unresolved".to_string());
        }
        if !self.semantic_abi_ready && !has_abi_requirement {
            issues.push(format!(
                "semantic ABI plan requirements missing verification blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI semantic plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiSemanticGapReport {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelArgumentAbiSemanticGapEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn missing_semantic_schema_kernel_symbols(&self) -> Vec<String> {
        let mut symbols = BTreeSet::new();
        for dispatch in &self.dispatches {
            for candidate in &dispatch.candidate_gaps {
                if !candidate.semantic_schema_available {
                    symbols.insert(candidate.kernel_symbol.clone());
                }
            }
        }
        symbols.into_iter().collect()
    }

    pub fn missing_model_argument_names(&self) -> Vec<String> {
        let mut names = BTreeSet::new();
        for dispatch in &self.dispatches {
            for candidate in &dispatch.candidate_gaps {
                for field in &candidate.fields {
                    if !field.model_argument_present {
                        names.insert(field.model_argument_name.to_string());
                    }
                }
            }
        }
        names.into_iter().collect()
    }

    pub fn missing_model_argument_requirements(
        &self,
    ) -> Vec<RuntimeLaunchKernelArgumentAbiMissingModelArgumentRequirement> {
        let mut requirements = Vec::new();
        for dispatch in &self.dispatches {
            for candidate in &dispatch.candidate_gaps {
                for field in &candidate.fields {
                    if !field.model_argument_present {
                        requirements.push(
                            RuntimeLaunchKernelArgumentAbiMissingModelArgumentRequirement {
                                op_index: dispatch.op_index,
                                op_name: dispatch.op_name.clone(),
                                kind: dispatch.kind,
                                stage_name: dispatch.stage_name.clone(),
                                stage_kind: dispatch.stage_kind,
                                window_index: dispatch.window_index,
                                queue_packet_index: dispatch.queue_packet_index,
                                kernel_symbol: candidate.kernel_symbol.clone(),
                                field_index: field.field_index,
                                kernel_argument_name: field.kernel_argument_name,
                                model_argument_name: field.model_argument_name,
                                expected_kind: field.expected_kind,
                                expected_encoding: field.expected_encoding,
                                expected_offset: field.expected_offset,
                                expected_size_bytes: field.expected_size_bytes,
                            },
                        );
                    }
                }
            }
        }
        requirements
    }

    pub fn field_mismatch_diagnostics(
        &self,
    ) -> Vec<RuntimeLaunchKernelArgumentAbiSemanticFieldMismatchDiagnostic> {
        let mut diagnostics = Vec::new();
        for dispatch in &self.dispatches {
            for candidate in &dispatch.candidate_gaps {
                for field in &candidate.fields {
                    if field.model_argument_present && !field.field_verified {
                        diagnostics.push(
                            RuntimeLaunchKernelArgumentAbiSemanticFieldMismatchDiagnostic {
                                op_index: dispatch.op_index,
                                op_name: dispatch.op_name.clone(),
                                kind: dispatch.kind,
                                stage_name: dispatch.stage_name.clone(),
                                stage_kind: dispatch.stage_kind,
                                window_index: dispatch.window_index,
                                queue_packet_index: dispatch.queue_packet_index,
                                kernel_symbol: candidate.kernel_symbol.clone(),
                                field_index: field.field_index,
                                kernel_argument_name: field.kernel_argument_name,
                                model_argument_name: field.model_argument_name,
                                expected_kind: field.expected_kind,
                                expected_encoding: field.expected_encoding,
                                expected_offset: field.expected_offset,
                                expected_size_bytes: field.expected_size_bytes,
                                actual_argument_index: field.actual_argument_index,
                                actual_kind: field.actual_kind,
                                actual_encoding: field.actual_encoding,
                                actual_offset: field.actual_offset,
                                actual_size_bytes: field.actual_size_bytes,
                                kind_matches: field.kind_matches,
                                encoding_matches: field.encoding_matches,
                                offset_matches: field.offset_matches,
                                size_matches: field.size_matches,
                            },
                        );
                    }
                }
            }
        }
        diagnostics
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_gap_count {
            issues.push(format!(
                "semantic ABI gap dispatch entries {} != gap count {}",
                self.dispatches.len(),
                self.dispatch_gap_count
            ));
        }
        if self.dispatch_gap_count > self.source_dispatch_count {
            issues.push(format!(
                "semantic ABI gap dispatch count {} > source dispatch count {}",
                self.dispatch_gap_count, self.source_dispatch_count
            ));
        }
        if self.all_dispatches_have_semantic_verified_candidate != (self.dispatch_gap_count == 0) {
            issues.push(
                "all_dispatches_have_semantic_verified_candidate does not match gap count"
                    .to_string(),
            );
        }
        if self.gap_semantic_verified_candidate_count != 0 {
            issues.push(format!(
                "semantic ABI gap verified candidate count {} != 0",
                self.gap_semantic_verified_candidate_count
            ));
        }
        if self.semantic_schema_source != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE {
            issues.push(format!(
                "semantic schema source {} != {}",
                self.semantic_schema_source,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE
            ));
        }
        if self.dispatch_gap_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&"kernel_argument_abi_verification")
        {
            issues.push(format!(
                "semantic ABI gap report requirements missing verification blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut gap_kernel_candidate_count = 0usize;
        let mut gap_semantic_schema_candidate_count = 0usize;
        let mut gap_missing_semantic_schema_candidate_count = 0usize;
        let mut gap_semantic_descriptor_match_candidate_count = 0usize;
        let mut gap_semantic_verified_candidate_count = 0usize;
        let mut gap_primary_missing_semantic_schema_candidate_count = 0usize;
        let mut gap_primary_semantic_descriptor_mismatch_candidate_count = 0usize;
        let mut gap_primary_missing_model_argument_candidate_count = 0usize;
        let mut gap_primary_field_shape_mismatch_candidate_count = 0usize;
        let mut gap_primary_extra_model_argument_candidate_count = 0usize;
        let mut gap_primary_kernarg_size_shortfall_candidate_count = 0usize;
        let mut gap_primary_unknown_unverified_semantic_candidate_count = 0usize;
        let mut gap_field_schema_count = 0usize;
        let mut gap_verified_field_count = 0usize;
        let mut gap_missing_field_count = 0usize;
        let mut gap_field_mismatch_count = 0usize;
        let mut gap_extra_argument_count = 0usize;

        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in semantic ABI gap report",
                    dispatch.op_name
                ));
            }
            if dispatch.kernel_candidate_count == 0 {
                issues.push(format!(
                    "dispatch {} has no semantic ABI gap candidates",
                    dispatch.op_name
                ));
            }
            if dispatch.candidate_kernel_symbols.len() != dispatch.kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} candidate symbols {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.candidate_kernel_symbols.len(),
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.candidate_gaps.len() != dispatch.kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} semantic candidate gap rows {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.candidate_gaps.len(),
                    dispatch.kernel_candidate_count
                ));
            }
            let candidate_gap_symbols = dispatch
                .candidate_gaps
                .iter()
                .map(|candidate| candidate.kernel_symbol.as_str())
                .collect::<Vec<_>>();
            let candidate_kernel_symbols = dispatch
                .candidate_kernel_symbols
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>();
            if candidate_gap_symbols != candidate_kernel_symbols {
                issues.push(format!(
                    "dispatch {} semantic gap symbols do not match candidate symbol list",
                    dispatch.op_name
                ));
            }
            if dispatch
                .candidate_kernel_symbols
                .iter()
                .any(|symbol| symbol.is_empty())
            {
                issues.push(format!(
                    "dispatch {} has an empty semantic ABI gap candidate symbol",
                    dispatch.op_name
                ));
            }
            if dispatch.semantic_schema_candidate_count
                + dispatch.missing_semantic_schema_candidate_count
                != dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} semantic schema+missing {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.semantic_schema_candidate_count
                        + dispatch.missing_semantic_schema_candidate_count,
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.semantic_verified_candidate_count != 0 {
                issues.push(format!(
                    "dispatch {} is in semantic ABI gap report but has {} verified candidates",
                    dispatch.op_name, dispatch.semantic_verified_candidate_count
                ));
            }

            let primary_missing_schema = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticGapReason::MissingSemanticSchema,
                        )
                })
                .count();
            let primary_descriptor_mismatch = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticGapReason::SemanticDescriptorMismatch,
                        )
                })
                .count();
            let primary_missing_model_argument = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticGapReason::MissingModelArgument,
                        )
                })
                .count();
            let primary_field_shape_mismatch = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::FieldShapeMismatch)
                })
                .count();
            let primary_extra_model_argument = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::ExtraModelArgument)
                })
                .count();
            let primary_size_shortfall = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticGapReason::KernargSizeShortfall,
                        )
                })
                .count();
            let primary_unknown = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticGapReason::UnknownUnverifiedSemantic,
                        )
                })
                .count();

            macro_rules! check_dispatch_count {
                ($observed:expr, $field:ident, $label:literal) => {
                    if $observed != dispatch.$field {
                        issues.push(format!(
                            "dispatch {} {} {} != count {}",
                            dispatch.op_name, $label, $observed, dispatch.$field
                        ));
                    }
                };
            }
            check_dispatch_count!(
                primary_missing_schema,
                primary_missing_semantic_schema_candidate_count,
                "primary missing semantic schema candidates"
            );
            check_dispatch_count!(
                primary_descriptor_mismatch,
                primary_semantic_descriptor_mismatch_candidate_count,
                "primary semantic descriptor mismatch candidates"
            );
            check_dispatch_count!(
                primary_missing_model_argument,
                primary_missing_model_argument_candidate_count,
                "primary missing model argument candidates"
            );
            check_dispatch_count!(
                primary_field_shape_mismatch,
                primary_field_shape_mismatch_candidate_count,
                "primary field shape mismatch candidates"
            );
            check_dispatch_count!(
                primary_extra_model_argument,
                primary_extra_model_argument_candidate_count,
                "primary extra model argument candidates"
            );
            check_dispatch_count!(
                primary_size_shortfall,
                primary_kernarg_size_shortfall_candidate_count,
                "primary kernarg size shortfall candidates"
            );
            check_dispatch_count!(
                primary_unknown,
                primary_unknown_unverified_semantic_candidate_count,
                "primary unknown unverified semantic candidates"
            );
            if dispatch.primary_missing_semantic_schema_candidate_count
                + dispatch.primary_semantic_descriptor_mismatch_candidate_count
                + dispatch.primary_missing_model_argument_candidate_count
                + dispatch.primary_field_shape_mismatch_candidate_count
                + dispatch.primary_extra_model_argument_candidate_count
                + dispatch.primary_kernarg_size_shortfall_candidate_count
                + dispatch.primary_unknown_unverified_semantic_candidate_count
                != dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} primary semantic gap reason counts {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.primary_missing_semantic_schema_candidate_count
                        + dispatch.primary_semantic_descriptor_mismatch_candidate_count
                        + dispatch.primary_missing_model_argument_candidate_count
                        + dispatch.primary_field_shape_mismatch_candidate_count
                        + dispatch.primary_extra_model_argument_candidate_count
                        + dispatch.primary_kernarg_size_shortfall_candidate_count
                        + dispatch.primary_unknown_unverified_semantic_candidate_count,
                    dispatch.kernel_candidate_count
                ));
            }

            for candidate in &dispatch.candidate_gaps {
                if candidate.kernel_symbol.is_empty() {
                    issues.push(format!(
                        "dispatch {} has an empty semantic ABI gap candidate symbol",
                        dispatch.op_name
                    ));
                }
                if !dispatch
                    .candidate_kernel_symbols
                    .iter()
                    .any(|symbol| symbol == &candidate.kernel_symbol)
                {
                    issues.push(format!(
                        "dispatch {} semantic gap candidate {} is missing from candidate symbol list",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.semantic_verified {
                    issues.push(format!(
                        "dispatch {} candidate {} is semantically verified inside semantic gap report",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                let expected_gap_reason =
                    runtime_launch_kernel_argument_abi_semantic_primary_gap_reason_for(candidate);
                if candidate.primary_gap_reason != expected_gap_reason {
                    issues.push(format!(
                        "dispatch {} candidate {} semantic primary gap reason {:?} != expected {:?}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.primary_gap_reason,
                        expected_gap_reason
                    ));
                }
                if candidate.semantic_schema_available
                    != (candidate.semantic_schema_kernarg_size.is_some()
                        && candidate.semantic_schema_kernarg_segment_align.is_some())
                {
                    issues.push(format!(
                        "dispatch {} candidate {} semantic schema availability mismatches metadata",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.semantic_descriptor_match
                    != (candidate.semantic_schema_kernarg_size == Some(candidate.kernarg_size)
                        && candidate.semantic_schema_kernarg_segment_align
                            == Some(candidate.kernarg_segment_align))
                {
                    issues.push(format!(
                        "dispatch {} candidate {} semantic descriptor match mismatches metadata",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
            }

            gap_kernel_candidate_count = checked_add_usize(
                gap_kernel_candidate_count,
                dispatch.kernel_candidate_count,
                "semantic ABI gap candidate count",
            )?;
            gap_semantic_schema_candidate_count = checked_add_usize(
                gap_semantic_schema_candidate_count,
                dispatch.semantic_schema_candidate_count,
                "semantic ABI gap schema candidate count",
            )?;
            gap_missing_semantic_schema_candidate_count = checked_add_usize(
                gap_missing_semantic_schema_candidate_count,
                dispatch.missing_semantic_schema_candidate_count,
                "semantic ABI gap missing schema candidate count",
            )?;
            gap_semantic_descriptor_match_candidate_count = checked_add_usize(
                gap_semantic_descriptor_match_candidate_count,
                dispatch.semantic_descriptor_match_candidate_count,
                "semantic ABI gap descriptor match candidate count",
            )?;
            gap_semantic_verified_candidate_count = checked_add_usize(
                gap_semantic_verified_candidate_count,
                dispatch.semantic_verified_candidate_count,
                "semantic ABI gap verified candidate count",
            )?;
            gap_primary_missing_semantic_schema_candidate_count = checked_add_usize(
                gap_primary_missing_semantic_schema_candidate_count,
                dispatch.primary_missing_semantic_schema_candidate_count,
                "semantic ABI gap primary missing schema count",
            )?;
            gap_primary_semantic_descriptor_mismatch_candidate_count = checked_add_usize(
                gap_primary_semantic_descriptor_mismatch_candidate_count,
                dispatch.primary_semantic_descriptor_mismatch_candidate_count,
                "semantic ABI gap primary descriptor mismatch count",
            )?;
            gap_primary_missing_model_argument_candidate_count = checked_add_usize(
                gap_primary_missing_model_argument_candidate_count,
                dispatch.primary_missing_model_argument_candidate_count,
                "semantic ABI gap primary missing model argument count",
            )?;
            gap_primary_field_shape_mismatch_candidate_count = checked_add_usize(
                gap_primary_field_shape_mismatch_candidate_count,
                dispatch.primary_field_shape_mismatch_candidate_count,
                "semantic ABI gap primary field shape mismatch count",
            )?;
            gap_primary_extra_model_argument_candidate_count = checked_add_usize(
                gap_primary_extra_model_argument_candidate_count,
                dispatch.primary_extra_model_argument_candidate_count,
                "semantic ABI gap primary extra model argument count",
            )?;
            gap_primary_kernarg_size_shortfall_candidate_count = checked_add_usize(
                gap_primary_kernarg_size_shortfall_candidate_count,
                dispatch.primary_kernarg_size_shortfall_candidate_count,
                "semantic ABI gap primary size shortfall count",
            )?;
            gap_primary_unknown_unverified_semantic_candidate_count = checked_add_usize(
                gap_primary_unknown_unverified_semantic_candidate_count,
                dispatch.primary_unknown_unverified_semantic_candidate_count,
                "semantic ABI gap primary unknown unverified count",
            )?;
            gap_field_schema_count = checked_add_usize(
                gap_field_schema_count,
                dispatch.field_schema_count,
                "semantic ABI gap field schema count",
            )?;
            gap_verified_field_count = checked_add_usize(
                gap_verified_field_count,
                dispatch.verified_field_count,
                "semantic ABI gap verified field count",
            )?;
            gap_missing_field_count = checked_add_usize(
                gap_missing_field_count,
                dispatch.missing_field_count,
                "semantic ABI gap missing field count",
            )?;
            gap_field_mismatch_count = checked_add_usize(
                gap_field_mismatch_count,
                dispatch.field_mismatch_count,
                "semantic ABI gap field mismatch count",
            )?;
            gap_extra_argument_count = checked_add_usize(
                gap_extra_argument_count,
                dispatch.extra_argument_count,
                "semantic ABI gap extra argument count",
            )?;
        }

        macro_rules! check_report_count {
            ($observed:ident, $field:ident, $label:literal) => {
                if $observed != self.$field {
                    issues.push(format!(
                        "{} {} != report {}",
                        $label, $observed, self.$field
                    ));
                }
            };
        }
        check_report_count!(
            gap_kernel_candidate_count,
            gap_kernel_candidate_count,
            "semantic ABI gap candidate count"
        );
        check_report_count!(
            gap_semantic_schema_candidate_count,
            gap_semantic_schema_candidate_count,
            "semantic ABI gap schema candidate count"
        );
        check_report_count!(
            gap_missing_semantic_schema_candidate_count,
            gap_missing_semantic_schema_candidate_count,
            "semantic ABI gap missing schema candidate count"
        );
        check_report_count!(
            gap_semantic_descriptor_match_candidate_count,
            gap_semantic_descriptor_match_candidate_count,
            "semantic ABI gap descriptor-match candidate count"
        );
        check_report_count!(
            gap_semantic_verified_candidate_count,
            gap_semantic_verified_candidate_count,
            "semantic ABI gap verified candidate count"
        );
        check_report_count!(
            gap_primary_missing_semantic_schema_candidate_count,
            gap_primary_missing_semantic_schema_candidate_count,
            "semantic ABI gap primary missing schema count"
        );
        check_report_count!(
            gap_primary_semantic_descriptor_mismatch_candidate_count,
            gap_primary_semantic_descriptor_mismatch_candidate_count,
            "semantic ABI gap primary descriptor mismatch count"
        );
        check_report_count!(
            gap_primary_missing_model_argument_candidate_count,
            gap_primary_missing_model_argument_candidate_count,
            "semantic ABI gap primary missing model argument count"
        );
        check_report_count!(
            gap_primary_field_shape_mismatch_candidate_count,
            gap_primary_field_shape_mismatch_candidate_count,
            "semantic ABI gap primary field mismatch count"
        );
        check_report_count!(
            gap_primary_extra_model_argument_candidate_count,
            gap_primary_extra_model_argument_candidate_count,
            "semantic ABI gap primary extra argument count"
        );
        check_report_count!(
            gap_primary_kernarg_size_shortfall_candidate_count,
            gap_primary_kernarg_size_shortfall_candidate_count,
            "semantic ABI gap primary size shortfall count"
        );
        check_report_count!(
            gap_primary_unknown_unverified_semantic_candidate_count,
            gap_primary_unknown_unverified_semantic_candidate_count,
            "semantic ABI gap primary unknown count"
        );
        check_report_count!(
            gap_field_schema_count,
            gap_field_schema_count,
            "semantic ABI gap field schema count"
        );
        check_report_count!(
            gap_verified_field_count,
            gap_verified_field_count,
            "semantic ABI gap verified field count"
        );
        check_report_count!(
            gap_missing_field_count,
            gap_missing_field_count,
            "semantic ABI gap missing field count"
        );
        check_report_count!(
            gap_field_mismatch_count,
            gap_field_mismatch_count,
            "semantic ABI gap field mismatch count"
        );
        check_report_count!(
            gap_extra_argument_count,
            gap_extra_argument_count,
            "semantic ABI gap extra argument count"
        );
        if self.gap_semantic_schema_candidate_count
            + self.gap_missing_semantic_schema_candidate_count
            != self.gap_kernel_candidate_count
        {
            issues.push(format!(
                "semantic ABI gap schema+missing count {} != candidate count {}",
                self.gap_semantic_schema_candidate_count
                    + self.gap_missing_semantic_schema_candidate_count,
                self.gap_kernel_candidate_count
            ));
        }
        if self.gap_primary_missing_semantic_schema_candidate_count
            + self.gap_primary_semantic_descriptor_mismatch_candidate_count
            + self.gap_primary_missing_model_argument_candidate_count
            + self.gap_primary_field_shape_mismatch_candidate_count
            + self.gap_primary_extra_model_argument_candidate_count
            + self.gap_primary_kernarg_size_shortfall_candidate_count
            + self.gap_primary_unknown_unverified_semantic_candidate_count
            != self.gap_kernel_candidate_count
        {
            issues.push(format!(
                "semantic ABI gap primary reason counts {} != candidate count {}",
                self.gap_primary_missing_semantic_schema_candidate_count
                    + self.gap_primary_semantic_descriptor_mismatch_candidate_count
                    + self.gap_primary_missing_model_argument_candidate_count
                    + self.gap_primary_field_shape_mismatch_candidate_count
                    + self.gap_primary_extra_model_argument_candidate_count
                    + self.gap_primary_kernarg_size_shortfall_candidate_count
                    + self.gap_primary_unknown_unverified_semantic_candidate_count,
                self.gap_kernel_candidate_count
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI semantic gap report for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionPlan {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelArgumentAbiSemanticProjectionEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn kernel_argument_abi_semantic_projection_gap_report(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionGapReport> {
        runtime_launch_kernel_argument_abi_semantic_projection_gap_report_from(self)
    }

    pub fn kernel_argument_abi_semantic_projection_candidate_recommendation_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionCandidateRecommendationPlan>
    {
        runtime_launch_kernel_argument_abi_semantic_projection_candidate_recommendation_plan_from(
            self,
        )
    }

    pub fn kernel_argument_abi_semantic_projection_candidate_selection_request_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionCandidateSelectionRequestPlan>
    {
        self.kernel_argument_abi_semantic_projection_candidate_recommendation_plan()?
            .kernel_argument_abi_semantic_projection_candidate_selection_request_plan(self)
    }

    pub fn kernel_argument_abi_semantic_projection_recommendation_report(
        &self,
        recommendations: &ModelRuntimeLaunchKernelCandidateRecommendationPlan,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionRecommendationReport> {
        runtime_launch_kernel_argument_abi_semantic_projection_recommendation_report_from(
            recommendations,
            self,
        )
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "semantic projection dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if self.semantic_schema_source != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE {
            issues.push(format!(
                "semantic projection schema source {} != {}",
                self.semantic_schema_source,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE
            ));
        }
        if self.semantic_projection_ready
            != (self.kernel_candidate_count > 0
                && self.projection_ready_candidate_count == self.kernel_candidate_count)
        {
            issues.push(
                "semantic projection readiness does not match candidate coverage".to_string(),
            );
        }
        if !self.semantic_projection_ready
            && !self
                .unresolved_runtime_requirements
                .contains(&MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT)
        {
            issues.push(format!(
                "semantic projection requirements missing projection blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        if self.semantic_projection_ready
            && self
                .unresolved_runtime_requirements
                .contains(&MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT)
        {
            issues.push(format!(
                "semantic projection is ready but projection blocker remains: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        if self.dispatches_with_projection_ready_candidate_count
            + self.dispatches_without_projection_ready_candidate_count
            != self.dispatch_count
        {
            issues.push(format!(
                "semantic projection dispatch ready+not-ready count {} != dispatch count {}",
                self.dispatches_with_projection_ready_candidate_count
                    + self.dispatches_without_projection_ready_candidate_count,
                self.dispatch_count
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut kernel_candidate_count = 0usize;
        let mut semantic_schema_candidate_count = 0usize;
        let mut missing_semantic_schema_candidate_count = 0usize;
        let mut semantic_descriptor_match_candidate_count = 0usize;
        let mut projection_ready_candidate_count = 0usize;
        let mut dispatches_with_projection_ready_candidate_count = 0usize;
        let mut dispatches_without_projection_ready_candidate_count = 0usize;
        let mut field_schema_count = 0usize;
        let mut projected_field_count = 0usize;
        let mut missing_field_count = 0usize;
        let mut kind_mismatch_field_count = 0usize;
        let mut unsupported_encoding_field_count = 0usize;
        let mut scalar_narrowing_overflow_field_count = 0usize;
        let mut field_range_overflow_count = 0usize;
        let mut projected_kernarg_bytes = 0usize;

        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in semantic projection plan",
                    dispatch.op_name
                ));
            }
            if dispatch.candidates.len() != dispatch.kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} projection candidates {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.candidates.len(),
                    dispatch.kernel_candidate_count
                ));
            }
            let dispatch_schema_candidates = dispatch
                .candidates
                .iter()
                .filter(|candidate| candidate.semantic_schema_available)
                .count();
            let dispatch_missing_schema_candidates =
                dispatch.kernel_candidate_count - dispatch_schema_candidates;
            let dispatch_descriptor_matches = dispatch
                .candidates
                .iter()
                .filter(|candidate| candidate.semantic_descriptor_match)
                .count();
            let dispatch_ready_candidates = dispatch
                .candidates
                .iter()
                .filter(|candidate| candidate.projection_ready)
                .count();
            let dispatch_field_schema_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.field_schema_count)
                .sum::<usize>();
            let dispatch_projected_field_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.projected_field_count)
                .sum::<usize>();
            let dispatch_missing_field_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.missing_field_count)
                .sum::<usize>();
            let dispatch_kind_mismatch_field_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.kind_mismatch_field_count)
                .sum::<usize>();
            let dispatch_unsupported_encoding_field_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.unsupported_encoding_field_count)
                .sum::<usize>();
            let dispatch_scalar_narrowing_overflow_field_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.scalar_narrowing_overflow_field_count)
                .sum::<usize>();
            let dispatch_field_range_overflow_count = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.field_range_overflow_count)
                .sum::<usize>();
            let dispatch_projected_kernarg_bytes = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.projected_kernarg_bytes)
                .sum::<usize>();

            macro_rules! check_dispatch_projection_count {
                ($observed:expr, $field:ident, $label:literal) => {
                    if $observed != dispatch.$field {
                        issues.push(format!(
                            "dispatch {} {} {} != count {}",
                            dispatch.op_name, $label, $observed, dispatch.$field
                        ));
                    }
                };
            }
            check_dispatch_projection_count!(
                dispatch_schema_candidates,
                semantic_schema_candidate_count,
                "semantic schema candidates"
            );
            check_dispatch_projection_count!(
                dispatch_missing_schema_candidates,
                missing_semantic_schema_candidate_count,
                "missing semantic schema candidates"
            );
            check_dispatch_projection_count!(
                dispatch_descriptor_matches,
                semantic_descriptor_match_candidate_count,
                "semantic descriptor matches"
            );
            check_dispatch_projection_count!(
                dispatch_ready_candidates,
                projection_ready_candidate_count,
                "projection-ready candidates"
            );
            check_dispatch_projection_count!(
                dispatch_field_schema_count,
                field_schema_count,
                "field schemas"
            );
            check_dispatch_projection_count!(
                dispatch_projected_field_count,
                projected_field_count,
                "projected fields"
            );
            check_dispatch_projection_count!(
                dispatch_missing_field_count,
                missing_field_count,
                "missing fields"
            );
            check_dispatch_projection_count!(
                dispatch_kind_mismatch_field_count,
                kind_mismatch_field_count,
                "kind-mismatch fields"
            );
            check_dispatch_projection_count!(
                dispatch_unsupported_encoding_field_count,
                unsupported_encoding_field_count,
                "unsupported-encoding fields"
            );
            check_dispatch_projection_count!(
                dispatch_scalar_narrowing_overflow_field_count,
                scalar_narrowing_overflow_field_count,
                "scalar-narrowing-overflow fields"
            );
            check_dispatch_projection_count!(
                dispatch_field_range_overflow_count,
                field_range_overflow_count,
                "field-range-overflow fields"
            );
            check_dispatch_projection_count!(
                dispatch_projected_kernarg_bytes,
                projected_kernarg_bytes,
                "projected kernarg bytes"
            );
            if dispatch.has_projection_ready_candidate != (dispatch_ready_candidates > 0) {
                issues.push(format!(
                    "dispatch {} projection-ready flag does not match ready count {}",
                    dispatch.op_name, dispatch_ready_candidates
                ));
            }

            for candidate in &dispatch.candidates {
                let candidate_projected_fields = candidate
                    .fields
                    .iter()
                    .filter(|field| {
                        field.projection_status
                            == RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::Projected
                    })
                    .count();
                let candidate_missing_fields = candidate
                    .fields
                    .iter()
                    .filter(|field| {
                        field.projection_status
                            == RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::MissingModelArgument
                    })
                    .count();
                let candidate_kind_mismatches = candidate
                    .fields
                    .iter()
                    .filter(|field| {
                        field.projection_status
                            == RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::KindMismatch
                    })
                    .count();
                let candidate_unsupported_encodings = candidate
                    .fields
                    .iter()
                    .filter(|field| {
                        field.projection_status
                            == RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::UnsupportedEncoding
                    })
                    .count();
                let candidate_narrowing_overflows = candidate
                    .fields
                    .iter()
                    .filter(|field| {
                        field.projection_status
                            == RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::ScalarNarrowingOverflow
                    })
                    .count();
                let candidate_range_overflows = candidate
                    .fields
                    .iter()
                    .filter(|field| {
                        field.projection_status
                            == RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::FieldRangeOverflow
                    })
                    .count();

                if candidate.semantic_schema_available
                    != candidate.semantic_schema_kernarg_size.is_some()
                    || candidate.semantic_schema_available
                        != candidate.semantic_schema_kernarg_segment_align.is_some()
                {
                    issues.push(format!(
                        "dispatch {} candidate {} schema availability does not match schema metadata",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.semantic_descriptor_match && !candidate.semantic_schema_available {
                    issues.push(format!(
                        "dispatch {} candidate {} has descriptor match without semantic schema",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.fields.len() != candidate.field_schema_count {
                    issues.push(format!(
                        "dispatch {} candidate {} projection field entries {} != schema count {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.fields.len(),
                        candidate.field_schema_count
                    ));
                }
                if candidate_projected_fields != candidate.projected_field_count {
                    issues.push(format!(
                        "dispatch {} candidate {} projected fields {} != count {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate_projected_fields,
                        candidate.projected_field_count
                    ));
                }
                if candidate_missing_fields != candidate.missing_field_count {
                    issues.push(format!(
                        "dispatch {} candidate {} missing fields {} != count {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate_missing_fields,
                        candidate.missing_field_count
                    ));
                }
                if candidate_kind_mismatches != candidate.kind_mismatch_field_count {
                    issues.push(format!(
                        "dispatch {} candidate {} kind mismatches {} != count {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate_kind_mismatches,
                        candidate.kind_mismatch_field_count
                    ));
                }
                if candidate_unsupported_encodings != candidate.unsupported_encoding_field_count {
                    issues.push(format!(
                        "dispatch {} candidate {} unsupported encodings {} != count {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate_unsupported_encodings,
                        candidate.unsupported_encoding_field_count
                    ));
                }
                if candidate_narrowing_overflows != candidate.scalar_narrowing_overflow_field_count
                {
                    issues.push(format!(
                        "dispatch {} candidate {} scalar narrowing overflows {} != count {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate_narrowing_overflows,
                        candidate.scalar_narrowing_overflow_field_count
                    ));
                }
                if candidate_range_overflows != candidate.field_range_overflow_count {
                    issues.push(format!(
                        "dispatch {} candidate {} field range overflows {} != count {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate_range_overflows,
                        candidate.field_range_overflow_count
                    ));
                }

                let expected_ready = candidate.semantic_schema_available
                    && candidate.semantic_descriptor_match
                    && candidate.projected_field_count == candidate.field_schema_count
                    && candidate.missing_field_count == 0
                    && candidate.kind_mismatch_field_count == 0
                    && candidate.unsupported_encoding_field_count == 0
                    && candidate.scalar_narrowing_overflow_field_count == 0
                    && candidate.field_range_overflow_count == 0;
                if candidate.projection_ready != expected_ready {
                    issues.push(format!(
                        "dispatch {} candidate {} projection-ready {} != expected {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.projection_ready,
                        expected_ready
                    ));
                }
                if candidate.projection_ready && candidate.primary_projection_blocker.is_some() {
                    issues.push(format!(
                        "dispatch {} candidate {} is projection-ready but has blocker {:?}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.primary_projection_blocker
                    ));
                }
                if !candidate.projection_ready && candidate.primary_projection_blocker.is_none() {
                    issues.push(format!(
                        "dispatch {} candidate {} is not projection-ready but has no blocker",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.semantic_schema_available && candidate.semantic_descriptor_match {
                    if candidate.projected_byte_image.len() != candidate.projected_kernarg_bytes {
                        issues.push(format!(
                            "dispatch {} candidate {} projected image len {} != projected bytes {}",
                            dispatch.op_name,
                            candidate.kernel_symbol,
                            candidate.projected_byte_image.len(),
                            candidate.projected_kernarg_bytes
                        ));
                    }
                    if Some(candidate.projected_kernarg_bytes as u32)
                        != candidate.semantic_schema_kernarg_size
                    {
                        issues.push(format!(
                            "dispatch {} candidate {} projected bytes {} != schema size {:?}",
                            dispatch.op_name,
                            candidate.kernel_symbol,
                            candidate.projected_kernarg_bytes,
                            candidate.semantic_schema_kernarg_size
                        ));
                    }
                } else if candidate.projected_kernarg_bytes != 0
                    || !candidate.projected_byte_image.is_empty()
                {
                    issues.push(format!(
                        "dispatch {} candidate {} has projected bytes without usable schema",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                for field in &candidate.fields {
                    let projected = field.projection_status
                        == RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::Projected;
                    if projected {
                        if field.projected_offset != Some(field.expected_offset) {
                            issues.push(format!(
                                "dispatch {} candidate {} field {} projected offset {:?} != expected {}",
                                dispatch.op_name,
                                candidate.kernel_symbol,
                                field.kernel_argument_name,
                                field.projected_offset,
                                field.expected_offset
                            ));
                        }
                        if field.projected_size_bytes != field.expected_size_bytes {
                            issues.push(format!(
                                "dispatch {} candidate {} field {} projected size {} != expected {}",
                                dispatch.op_name,
                                candidate.kernel_symbol,
                                field.kernel_argument_name,
                                field.projected_size_bytes,
                                field.expected_size_bytes
                            ));
                        }
                        if field.projected_bytes.len() != field.expected_size_bytes {
                            issues.push(format!(
                                "dispatch {} candidate {} field {} projected byte len {} != expected {}",
                                dispatch.op_name,
                                candidate.kernel_symbol,
                                field.kernel_argument_name,
                                field.projected_bytes.len(),
                                field.expected_size_bytes
                            ));
                        }
                        if let Some(end) =
                            field.expected_offset.checked_add(field.expected_size_bytes)
                        {
                            if end <= candidate.projected_byte_image.len()
                                && candidate.projected_byte_image[field.expected_offset..end]
                                    != field.projected_bytes[..]
                            {
                                issues.push(format!(
                                    "dispatch {} candidate {} field {} projected bytes do not match image",
                                    dispatch.op_name,
                                    candidate.kernel_symbol,
                                    field.kernel_argument_name
                                ));
                            }
                        }
                    } else if field.projected_offset.is_some()
                        || field.projected_size_bytes != 0
                        || !field.projected_bytes.is_empty()
                    {
                        issues.push(format!(
                            "dispatch {} candidate {} field {} has projected data with status {}",
                            dispatch.op_name,
                            candidate.kernel_symbol,
                            field.kernel_argument_name,
                            field.projection_status.as_str()
                        ));
                    }
                }
            }

            kernel_candidate_count += dispatch.kernel_candidate_count;
            semantic_schema_candidate_count += dispatch.semantic_schema_candidate_count;
            missing_semantic_schema_candidate_count +=
                dispatch.missing_semantic_schema_candidate_count;
            semantic_descriptor_match_candidate_count +=
                dispatch.semantic_descriptor_match_candidate_count;
            projection_ready_candidate_count += dispatch.projection_ready_candidate_count;
            if dispatch.has_projection_ready_candidate {
                dispatches_with_projection_ready_candidate_count += 1;
            } else {
                dispatches_without_projection_ready_candidate_count += 1;
            }
            field_schema_count += dispatch.field_schema_count;
            projected_field_count += dispatch.projected_field_count;
            missing_field_count += dispatch.missing_field_count;
            kind_mismatch_field_count += dispatch.kind_mismatch_field_count;
            unsupported_encoding_field_count += dispatch.unsupported_encoding_field_count;
            scalar_narrowing_overflow_field_count += dispatch.scalar_narrowing_overflow_field_count;
            field_range_overflow_count += dispatch.field_range_overflow_count;
            projected_kernarg_bytes += dispatch.projected_kernarg_bytes;
        }

        macro_rules! check_projection_count {
            ($observed:ident, $field:ident, $label:literal) => {
                if $observed != self.$field {
                    issues.push(format!("{} {} != plan {}", $label, $observed, self.$field));
                }
            };
        }
        check_projection_count!(
            kernel_candidate_count,
            kernel_candidate_count,
            "semantic projection candidate count"
        );
        check_projection_count!(
            semantic_schema_candidate_count,
            semantic_schema_candidate_count,
            "semantic projection schema candidate count"
        );
        check_projection_count!(
            missing_semantic_schema_candidate_count,
            missing_semantic_schema_candidate_count,
            "semantic projection missing schema candidate count"
        );
        check_projection_count!(
            semantic_descriptor_match_candidate_count,
            semantic_descriptor_match_candidate_count,
            "semantic projection descriptor-match candidate count"
        );
        check_projection_count!(
            projection_ready_candidate_count,
            projection_ready_candidate_count,
            "semantic projection ready candidate count"
        );
        check_projection_count!(
            dispatches_with_projection_ready_candidate_count,
            dispatches_with_projection_ready_candidate_count,
            "semantic projection dispatches with ready candidate"
        );
        check_projection_count!(
            dispatches_without_projection_ready_candidate_count,
            dispatches_without_projection_ready_candidate_count,
            "semantic projection dispatches without ready candidate"
        );
        check_projection_count!(
            field_schema_count,
            field_schema_count,
            "semantic projection field schema count"
        );
        check_projection_count!(
            projected_field_count,
            projected_field_count,
            "semantic projection projected field count"
        );
        check_projection_count!(
            missing_field_count,
            missing_field_count,
            "semantic projection missing field count"
        );
        check_projection_count!(
            kind_mismatch_field_count,
            kind_mismatch_field_count,
            "semantic projection kind mismatch count"
        );
        check_projection_count!(
            unsupported_encoding_field_count,
            unsupported_encoding_field_count,
            "semantic projection unsupported encoding count"
        );
        check_projection_count!(
            scalar_narrowing_overflow_field_count,
            scalar_narrowing_overflow_field_count,
            "semantic projection scalar narrowing overflow count"
        );
        check_projection_count!(
            field_range_overflow_count,
            field_range_overflow_count,
            "semantic projection field range overflow count"
        );
        check_projection_count!(
            projected_kernarg_bytes,
            projected_kernarg_bytes,
            "semantic projection projected kernarg bytes"
        );
        if self.semantic_schema_candidate_count + self.missing_semantic_schema_candidate_count
            != self.kernel_candidate_count
        {
            issues.push(format!(
                "semantic projection schema+missing count {} != candidate count {}",
                self.semantic_schema_candidate_count + self.missing_semantic_schema_candidate_count,
                self.kernel_candidate_count
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI semantic projection plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionGapReport {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelArgumentAbiSemanticProjectionGapEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn missing_semantic_schema_kernel_symbols(&self) -> Vec<String> {
        let mut symbols = BTreeSet::new();
        for dispatch in &self.dispatches {
            for candidate in &dispatch.candidate_gaps {
                if !candidate.semantic_schema_available {
                    symbols.insert(candidate.kernel_symbol.clone());
                }
            }
        }
        symbols.into_iter().collect()
    }

    pub fn missing_model_argument_names(&self) -> Vec<String> {
        let mut names = BTreeSet::new();
        for dispatch in &self.dispatches {
            for candidate in &dispatch.candidate_gaps {
                for field in &candidate.fields {
                    if !field.model_argument_present {
                        names.insert(field.model_argument_name.to_string());
                    }
                }
            }
        }
        names.into_iter().collect()
    }

    pub fn missing_model_argument_requirements(
        &self,
    ) -> Vec<RuntimeLaunchKernelArgumentAbiMissingModelArgumentRequirement> {
        let mut requirements = Vec::new();
        for dispatch in &self.dispatches {
            for candidate in &dispatch.candidate_gaps {
                for field in &candidate.fields {
                    if field.projection_status
                        == RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::MissingModelArgument
                    {
                        requirements.push(
                            RuntimeLaunchKernelArgumentAbiMissingModelArgumentRequirement {
                                op_index: dispatch.op_index,
                                op_name: dispatch.op_name.clone(),
                                kind: dispatch.kind,
                                stage_name: dispatch.stage_name.clone(),
                                stage_kind: dispatch.stage_kind,
                                window_index: dispatch.window_index,
                                queue_packet_index: dispatch.queue_packet_index,
                                kernel_symbol: candidate.kernel_symbol.clone(),
                                field_index: field.field_index,
                                kernel_argument_name: field.kernel_argument_name,
                                model_argument_name: field.model_argument_name,
                                expected_kind: field.expected_kind,
                                expected_encoding: field.expected_encoding,
                                expected_offset: field.expected_offset,
                                expected_size_bytes: field.expected_size_bytes,
                            },
                        );
                    }
                }
            }
        }
        requirements
    }

    pub fn field_blocker_diagnostics(
        &self,
    ) -> Vec<RuntimeLaunchKernelArgumentAbiSemanticProjectionFieldBlockerDiagnostic> {
        let mut diagnostics = Vec::new();
        for dispatch in &self.dispatches {
            for candidate in &dispatch.candidate_gaps {
                for field in &candidate.fields {
                    if field.projection_status
                        != RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::Projected
                    {
                        diagnostics.push(
                            RuntimeLaunchKernelArgumentAbiSemanticProjectionFieldBlockerDiagnostic {
                                op_index: dispatch.op_index,
                                op_name: dispatch.op_name.clone(),
                                kind: dispatch.kind,
                                stage_name: dispatch.stage_name.clone(),
                                stage_kind: dispatch.stage_kind,
                                window_index: dispatch.window_index,
                                queue_packet_index: dispatch.queue_packet_index,
                                kernel_symbol: candidate.kernel_symbol.clone(),
                                field_index: field.field_index,
                                kernel_argument_name: field.kernel_argument_name,
                                model_argument_name: field.model_argument_name,
                                expected_kind: field.expected_kind,
                                expected_encoding: field.expected_encoding,
                                expected_offset: field.expected_offset,
                                expected_size_bytes: field.expected_size_bytes,
                                model_argument_present: field.model_argument_present,
                                actual_argument_index: field.actual_argument_index,
                                actual_kind: field.actual_kind,
                                actual_encoding: field.actual_encoding,
                                actual_size_bytes: field.actual_size_bytes,
                                projection_status: field.projection_status,
                                projected_offset: field.projected_offset,
                                projected_size_bytes: field.projected_size_bytes,
                            },
                        );
                    }
                }
            }
        }
        diagnostics
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_gap_count {
            issues.push(format!(
                "semantic projection gap dispatch entries {} != gap count {}",
                self.dispatches.len(),
                self.dispatch_gap_count
            ));
        }
        if self.dispatch_gap_count > self.source_dispatch_count {
            issues.push(format!(
                "semantic projection gap dispatch count {} > source dispatch count {}",
                self.dispatch_gap_count, self.source_dispatch_count
            ));
        }
        if self.all_dispatches_have_projection_ready_candidate != (self.dispatch_gap_count == 0) {
            issues.push(
                "all_dispatches_have_projection_ready_candidate does not match gap count"
                    .to_string(),
            );
        }
        if self.gap_projection_ready_candidate_count != 0 {
            issues.push(format!(
                "semantic projection gap ready candidate count {} != 0",
                self.gap_projection_ready_candidate_count
            ));
        }
        if self.semantic_schema_source != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE {
            issues.push(format!(
                "semantic projection schema source {} != {}",
                self.semantic_schema_source,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE
            ));
        }
        if self.dispatch_gap_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT)
        {
            issues.push(format!(
                "semantic projection gap report requirements missing projection blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut gap_kernel_candidate_count = 0usize;
        let mut gap_semantic_schema_candidate_count = 0usize;
        let mut gap_missing_semantic_schema_candidate_count = 0usize;
        let mut gap_semantic_descriptor_match_candidate_count = 0usize;
        let mut gap_projection_ready_candidate_count = 0usize;
        let mut gap_primary_missing_semantic_schema_candidate_count = 0usize;
        let mut gap_primary_semantic_descriptor_mismatch_candidate_count = 0usize;
        let mut gap_primary_missing_model_argument_candidate_count = 0usize;
        let mut gap_primary_kind_mismatch_candidate_count = 0usize;
        let mut gap_primary_unsupported_encoding_candidate_count = 0usize;
        let mut gap_primary_scalar_narrowing_overflow_candidate_count = 0usize;
        let mut gap_primary_field_range_overflow_candidate_count = 0usize;
        let mut gap_primary_unknown_unprojected_semantic_candidate_count = 0usize;
        let mut gap_field_schema_count = 0usize;
        let mut gap_projected_field_count = 0usize;
        let mut gap_missing_field_count = 0usize;
        let mut gap_kind_mismatch_field_count = 0usize;
        let mut gap_unsupported_encoding_field_count = 0usize;
        let mut gap_scalar_narrowing_overflow_field_count = 0usize;
        let mut gap_field_range_overflow_count = 0usize;
        let mut gap_projected_kernarg_bytes = 0usize;

        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in semantic projection gap report",
                    dispatch.op_name
                ));
            }
            if dispatch.kernel_candidate_count == 0 {
                issues.push(format!(
                    "dispatch {} has no semantic projection gap candidates",
                    dispatch.op_name
                ));
            }
            if dispatch.candidate_kernel_symbols.len() != dispatch.kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} projection gap symbols {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.candidate_kernel_symbols.len(),
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.candidate_gaps.len() != dispatch.kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} projection candidate gap rows {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.candidate_gaps.len(),
                    dispatch.kernel_candidate_count
                ));
            }
            let candidate_gap_symbols = dispatch
                .candidate_gaps
                .iter()
                .map(|candidate| candidate.kernel_symbol.as_str())
                .collect::<Vec<_>>();
            let candidate_kernel_symbols = dispatch
                .candidate_kernel_symbols
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>();
            if candidate_gap_symbols != candidate_kernel_symbols {
                issues.push(format!(
                    "dispatch {} projection gap symbols do not match candidate symbol list",
                    dispatch.op_name
                ));
            }
            if dispatch
                .candidate_kernel_symbols
                .iter()
                .any(|symbol| symbol.is_empty())
            {
                issues.push(format!(
                    "dispatch {} has an empty semantic projection gap candidate symbol",
                    dispatch.op_name
                ));
            }
            if dispatch.semantic_schema_candidate_count
                + dispatch.missing_semantic_schema_candidate_count
                != dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} semantic projection schema+missing {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.semantic_schema_candidate_count
                        + dispatch.missing_semantic_schema_candidate_count,
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.projection_ready_candidate_count != 0 {
                issues.push(format!(
                    "dispatch {} is in semantic projection gap report but has {} ready candidates",
                    dispatch.op_name, dispatch.projection_ready_candidate_count
                ));
            }

            let primary_missing_schema = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_projection_blocker
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::MissingSemanticSchema,
                        )
                })
                .count();
            let primary_descriptor_mismatch = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_projection_blocker
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::SemanticDescriptorMismatch,
                        )
                })
                .count();
            let primary_missing_model_argument = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_projection_blocker
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::MissingModelArgument,
                        )
                })
                .count();
            let primary_kind_mismatch = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_projection_blocker
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::KindMismatch,
                        )
                })
                .count();
            let primary_unsupported_encoding = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_projection_blocker
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::UnsupportedEncoding,
                        )
                })
                .count();
            let primary_scalar_narrowing_overflow = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_projection_blocker
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::ScalarNarrowingOverflow,
                        )
                })
                .count();
            let primary_field_range_overflow = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_projection_blocker
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::FieldRangeOverflow,
                        )
                })
                .count();
            let primary_unknown = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_projection_blocker
                        == Some(
                            RuntimeLaunchKernelArgumentAbiSemanticProjectionStatus::UnknownUnprojectedSemantic,
                        )
                })
                .count();

            macro_rules! check_dispatch_count {
                ($observed:expr, $field:ident, $label:literal) => {
                    if $observed != dispatch.$field {
                        issues.push(format!(
                            "dispatch {} {} {} != count {}",
                            dispatch.op_name, $label, $observed, dispatch.$field
                        ));
                    }
                };
            }
            check_dispatch_count!(
                primary_missing_schema,
                primary_missing_semantic_schema_candidate_count,
                "primary missing semantic schema candidates"
            );
            check_dispatch_count!(
                primary_descriptor_mismatch,
                primary_semantic_descriptor_mismatch_candidate_count,
                "primary semantic descriptor mismatch candidates"
            );
            check_dispatch_count!(
                primary_missing_model_argument,
                primary_missing_model_argument_candidate_count,
                "primary missing model argument candidates"
            );
            check_dispatch_count!(
                primary_kind_mismatch,
                primary_kind_mismatch_candidate_count,
                "primary kind mismatch candidates"
            );
            check_dispatch_count!(
                primary_unsupported_encoding,
                primary_unsupported_encoding_candidate_count,
                "primary unsupported encoding candidates"
            );
            check_dispatch_count!(
                primary_scalar_narrowing_overflow,
                primary_scalar_narrowing_overflow_candidate_count,
                "primary scalar narrowing overflow candidates"
            );
            check_dispatch_count!(
                primary_field_range_overflow,
                primary_field_range_overflow_candidate_count,
                "primary field range overflow candidates"
            );
            check_dispatch_count!(
                primary_unknown,
                primary_unknown_unprojected_semantic_candidate_count,
                "primary unknown unprojected candidates"
            );
            if dispatch.primary_missing_semantic_schema_candidate_count
                + dispatch.primary_semantic_descriptor_mismatch_candidate_count
                + dispatch.primary_missing_model_argument_candidate_count
                + dispatch.primary_kind_mismatch_candidate_count
                + dispatch.primary_unsupported_encoding_candidate_count
                + dispatch.primary_scalar_narrowing_overflow_candidate_count
                + dispatch.primary_field_range_overflow_candidate_count
                + dispatch.primary_unknown_unprojected_semantic_candidate_count
                != dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} primary projection gap reason counts {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.primary_missing_semantic_schema_candidate_count
                        + dispatch.primary_semantic_descriptor_mismatch_candidate_count
                        + dispatch.primary_missing_model_argument_candidate_count
                        + dispatch.primary_kind_mismatch_candidate_count
                        + dispatch.primary_unsupported_encoding_candidate_count
                        + dispatch.primary_scalar_narrowing_overflow_candidate_count
                        + dispatch.primary_field_range_overflow_candidate_count
                        + dispatch.primary_unknown_unprojected_semantic_candidate_count,
                    dispatch.kernel_candidate_count
                ));
            }

            for candidate in &dispatch.candidate_gaps {
                if candidate.kernel_symbol.is_empty() {
                    issues.push(format!(
                        "dispatch {} has an empty semantic projection gap candidate symbol",
                        dispatch.op_name
                    ));
                }
                if !dispatch
                    .candidate_kernel_symbols
                    .iter()
                    .any(|symbol| symbol == &candidate.kernel_symbol)
                {
                    issues.push(format!(
                        "dispatch {} projection gap candidate {} is missing from candidate symbol list",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.projection_ready {
                    issues.push(format!(
                        "dispatch {} candidate {} is projection-ready inside projection gap report",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                let expected_blocker =
                    runtime_launch_kernel_argument_abi_semantic_projection_primary_blocker_for(
                        candidate,
                    );
                if candidate.primary_projection_blocker != expected_blocker {
                    issues.push(format!(
                        "dispatch {} candidate {} projection primary blocker {:?} != expected {:?}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.primary_projection_blocker,
                        expected_blocker
                    ));
                }
                if candidate.semantic_schema_available
                    != (candidate.semantic_schema_kernarg_size.is_some()
                        && candidate.semantic_schema_kernarg_segment_align.is_some())
                {
                    issues.push(format!(
                        "dispatch {} candidate {} projection schema availability mismatches metadata",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.semantic_descriptor_match && !candidate.semantic_schema_available {
                    issues.push(format!(
                        "dispatch {} candidate {} projection descriptor match without schema",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
            }

            gap_kernel_candidate_count = checked_add_usize(
                gap_kernel_candidate_count,
                dispatch.kernel_candidate_count,
                "semantic projection gap candidate count",
            )?;
            gap_semantic_schema_candidate_count = checked_add_usize(
                gap_semantic_schema_candidate_count,
                dispatch.semantic_schema_candidate_count,
                "semantic projection gap schema candidate count",
            )?;
            gap_missing_semantic_schema_candidate_count = checked_add_usize(
                gap_missing_semantic_schema_candidate_count,
                dispatch.missing_semantic_schema_candidate_count,
                "semantic projection gap missing schema candidate count",
            )?;
            gap_semantic_descriptor_match_candidate_count = checked_add_usize(
                gap_semantic_descriptor_match_candidate_count,
                dispatch.semantic_descriptor_match_candidate_count,
                "semantic projection gap descriptor match candidate count",
            )?;
            gap_projection_ready_candidate_count = checked_add_usize(
                gap_projection_ready_candidate_count,
                dispatch.projection_ready_candidate_count,
                "semantic projection gap ready candidate count",
            )?;
            gap_primary_missing_semantic_schema_candidate_count = checked_add_usize(
                gap_primary_missing_semantic_schema_candidate_count,
                dispatch.primary_missing_semantic_schema_candidate_count,
                "semantic projection gap primary missing schema count",
            )?;
            gap_primary_semantic_descriptor_mismatch_candidate_count = checked_add_usize(
                gap_primary_semantic_descriptor_mismatch_candidate_count,
                dispatch.primary_semantic_descriptor_mismatch_candidate_count,
                "semantic projection gap primary descriptor mismatch count",
            )?;
            gap_primary_missing_model_argument_candidate_count = checked_add_usize(
                gap_primary_missing_model_argument_candidate_count,
                dispatch.primary_missing_model_argument_candidate_count,
                "semantic projection gap primary missing model argument count",
            )?;
            gap_primary_kind_mismatch_candidate_count = checked_add_usize(
                gap_primary_kind_mismatch_candidate_count,
                dispatch.primary_kind_mismatch_candidate_count,
                "semantic projection gap primary kind mismatch count",
            )?;
            gap_primary_unsupported_encoding_candidate_count = checked_add_usize(
                gap_primary_unsupported_encoding_candidate_count,
                dispatch.primary_unsupported_encoding_candidate_count,
                "semantic projection gap primary unsupported encoding count",
            )?;
            gap_primary_scalar_narrowing_overflow_candidate_count = checked_add_usize(
                gap_primary_scalar_narrowing_overflow_candidate_count,
                dispatch.primary_scalar_narrowing_overflow_candidate_count,
                "semantic projection gap primary scalar narrowing overflow count",
            )?;
            gap_primary_field_range_overflow_candidate_count = checked_add_usize(
                gap_primary_field_range_overflow_candidate_count,
                dispatch.primary_field_range_overflow_candidate_count,
                "semantic projection gap primary field range overflow count",
            )?;
            gap_primary_unknown_unprojected_semantic_candidate_count = checked_add_usize(
                gap_primary_unknown_unprojected_semantic_candidate_count,
                dispatch.primary_unknown_unprojected_semantic_candidate_count,
                "semantic projection gap primary unknown count",
            )?;
            gap_field_schema_count = checked_add_usize(
                gap_field_schema_count,
                dispatch.field_schema_count,
                "semantic projection gap field schema count",
            )?;
            gap_projected_field_count = checked_add_usize(
                gap_projected_field_count,
                dispatch.projected_field_count,
                "semantic projection gap projected field count",
            )?;
            gap_missing_field_count = checked_add_usize(
                gap_missing_field_count,
                dispatch.missing_field_count,
                "semantic projection gap missing field count",
            )?;
            gap_kind_mismatch_field_count = checked_add_usize(
                gap_kind_mismatch_field_count,
                dispatch.kind_mismatch_field_count,
                "semantic projection gap kind mismatch count",
            )?;
            gap_unsupported_encoding_field_count = checked_add_usize(
                gap_unsupported_encoding_field_count,
                dispatch.unsupported_encoding_field_count,
                "semantic projection gap unsupported encoding count",
            )?;
            gap_scalar_narrowing_overflow_field_count = checked_add_usize(
                gap_scalar_narrowing_overflow_field_count,
                dispatch.scalar_narrowing_overflow_field_count,
                "semantic projection gap scalar narrowing overflow count",
            )?;
            gap_field_range_overflow_count = checked_add_usize(
                gap_field_range_overflow_count,
                dispatch.field_range_overflow_count,
                "semantic projection gap field range overflow count",
            )?;
            gap_projected_kernarg_bytes = checked_add_usize(
                gap_projected_kernarg_bytes,
                dispatch.projected_kernarg_bytes,
                "semantic projection gap projected kernarg bytes",
            )?;
        }

        macro_rules! check_report_count {
            ($observed:ident, $field:ident, $label:literal) => {
                if $observed != self.$field {
                    issues.push(format!(
                        "{} {} != report {}",
                        $label, $observed, self.$field
                    ));
                }
            };
        }
        check_report_count!(
            gap_kernel_candidate_count,
            gap_kernel_candidate_count,
            "semantic projection gap candidate count"
        );
        check_report_count!(
            gap_semantic_schema_candidate_count,
            gap_semantic_schema_candidate_count,
            "semantic projection gap schema candidate count"
        );
        check_report_count!(
            gap_missing_semantic_schema_candidate_count,
            gap_missing_semantic_schema_candidate_count,
            "semantic projection gap missing schema candidate count"
        );
        check_report_count!(
            gap_semantic_descriptor_match_candidate_count,
            gap_semantic_descriptor_match_candidate_count,
            "semantic projection gap descriptor-match candidate count"
        );
        check_report_count!(
            gap_projection_ready_candidate_count,
            gap_projection_ready_candidate_count,
            "semantic projection gap ready candidate count"
        );
        check_report_count!(
            gap_primary_missing_semantic_schema_candidate_count,
            gap_primary_missing_semantic_schema_candidate_count,
            "semantic projection gap primary missing schema count"
        );
        check_report_count!(
            gap_primary_semantic_descriptor_mismatch_candidate_count,
            gap_primary_semantic_descriptor_mismatch_candidate_count,
            "semantic projection gap primary descriptor mismatch count"
        );
        check_report_count!(
            gap_primary_missing_model_argument_candidate_count,
            gap_primary_missing_model_argument_candidate_count,
            "semantic projection gap primary missing model argument count"
        );
        check_report_count!(
            gap_primary_kind_mismatch_candidate_count,
            gap_primary_kind_mismatch_candidate_count,
            "semantic projection gap primary kind mismatch count"
        );
        check_report_count!(
            gap_primary_unsupported_encoding_candidate_count,
            gap_primary_unsupported_encoding_candidate_count,
            "semantic projection gap primary unsupported encoding count"
        );
        check_report_count!(
            gap_primary_scalar_narrowing_overflow_candidate_count,
            gap_primary_scalar_narrowing_overflow_candidate_count,
            "semantic projection gap primary scalar narrowing overflow count"
        );
        check_report_count!(
            gap_primary_field_range_overflow_candidate_count,
            gap_primary_field_range_overflow_candidate_count,
            "semantic projection gap primary field range overflow count"
        );
        check_report_count!(
            gap_primary_unknown_unprojected_semantic_candidate_count,
            gap_primary_unknown_unprojected_semantic_candidate_count,
            "semantic projection gap primary unknown count"
        );
        check_report_count!(
            gap_field_schema_count,
            gap_field_schema_count,
            "semantic projection gap field schema count"
        );
        check_report_count!(
            gap_projected_field_count,
            gap_projected_field_count,
            "semantic projection gap projected field count"
        );
        check_report_count!(
            gap_missing_field_count,
            gap_missing_field_count,
            "semantic projection gap missing field count"
        );
        check_report_count!(
            gap_kind_mismatch_field_count,
            gap_kind_mismatch_field_count,
            "semantic projection gap kind mismatch count"
        );
        check_report_count!(
            gap_unsupported_encoding_field_count,
            gap_unsupported_encoding_field_count,
            "semantic projection gap unsupported encoding count"
        );
        check_report_count!(
            gap_scalar_narrowing_overflow_field_count,
            gap_scalar_narrowing_overflow_field_count,
            "semantic projection gap scalar narrowing overflow count"
        );
        check_report_count!(
            gap_field_range_overflow_count,
            gap_field_range_overflow_count,
            "semantic projection gap field range overflow count"
        );
        check_report_count!(
            gap_projected_kernarg_bytes,
            gap_projected_kernarg_bytes,
            "semantic projection gap projected kernarg bytes"
        );
        if self.gap_semantic_schema_candidate_count
            + self.gap_missing_semantic_schema_candidate_count
            != self.gap_kernel_candidate_count
        {
            issues.push(format!(
                "semantic projection gap schema+missing count {} != candidate count {}",
                self.gap_semantic_schema_candidate_count
                    + self.gap_missing_semantic_schema_candidate_count,
                self.gap_kernel_candidate_count
            ));
        }
        if self.gap_primary_missing_semantic_schema_candidate_count
            + self.gap_primary_semantic_descriptor_mismatch_candidate_count
            + self.gap_primary_missing_model_argument_candidate_count
            + self.gap_primary_kind_mismatch_candidate_count
            + self.gap_primary_unsupported_encoding_candidate_count
            + self.gap_primary_scalar_narrowing_overflow_candidate_count
            + self.gap_primary_field_range_overflow_candidate_count
            + self.gap_primary_unknown_unprojected_semantic_candidate_count
            != self.gap_kernel_candidate_count
        {
            issues.push(format!(
                "semantic projection gap primary reason counts {} != candidate count {}",
                self.gap_primary_missing_semantic_schema_candidate_count
                    + self.gap_primary_semantic_descriptor_mismatch_candidate_count
                    + self.gap_primary_missing_model_argument_candidate_count
                    + self.gap_primary_kind_mismatch_candidate_count
                    + self.gap_primary_unsupported_encoding_candidate_count
                    + self.gap_primary_scalar_narrowing_overflow_candidate_count
                    + self.gap_primary_field_range_overflow_candidate_count
                    + self.gap_primary_unknown_unprojected_semantic_candidate_count,
                self.gap_kernel_candidate_count
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI semantic projection gap report for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionCandidateRecommendationPlan {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelArgumentAbiSemanticProjectionCandidateRecommendationEntry>
    {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn kernel_argument_abi_semantic_projection_candidate_selection_request_plan(
        &self,
        projection: &ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionPlan,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionCandidateSelectionRequestPlan>
    {
        runtime_launch_kernel_argument_abi_semantic_projection_candidate_selection_request_plan_from(
            self, projection,
        )
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "semantic projection candidate recommendation dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if self.dispatch_count == 0 {
            issues.push(
                "semantic projection candidate recommendation dispatch count is zero".to_string(),
            );
        }
        if self.policy
            != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_POLICY
        {
            issues.push(format!(
                "semantic projection candidate recommendation policy {} != {}",
                self.policy,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_POLICY
            ));
        }
        if self.semantic_schema_source != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE {
            issues.push(format!(
                "semantic projection candidate recommendation schema source {} != {}",
                self.semantic_schema_source,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE
            ));
        }
        if self.recommended_dispatch_count + self.missing_recommendation_dispatch_count
            != self.dispatch_count
        {
            issues.push(format!(
                "semantic projection candidate recommendation recommended+missing dispatch count {} != dispatch count {}",
                self.recommended_dispatch_count + self.missing_recommendation_dispatch_count,
                self.dispatch_count
            ));
        }
        if self.all_dispatches_recommended != (self.missing_recommendation_dispatch_count == 0) {
            issues.push(
                "all_dispatches_recommended does not match projection candidate recommendation missing count"
                    .to_string(),
            );
        }
        if self.missing_recommendation_dispatch_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT)
        {
            issues.push(format!(
                "semantic projection candidate recommendation requirements missing projection blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        if self.missing_recommendation_dispatch_count == 0
            && self
                .unresolved_runtime_requirements
                .contains(&MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT)
        {
            issues.push(format!(
                "semantic projection candidate recommendation is complete but projection blocker remains: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        if self.source_ambiguous_dispatch_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&"kernel_candidate_selection_policy")
        {
            issues.push(format!(
                "semantic projection candidate recommendation requirements missing selection-policy blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        let mut seen_requirements = BTreeSet::new();
        for requirement in &self.unresolved_runtime_requirements {
            if requirement.is_empty() {
                issues.push(
                    "semantic projection candidate recommendation has empty requirement"
                        .to_string(),
                );
            }
            if !seen_requirements.insert(*requirement) {
                issues.push(format!(
                    "semantic projection candidate recommendation requirement {requirement} appears more than once"
                ));
            }
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut source_kernel_candidate_count = 0usize;
        let mut semantic_schema_candidate_count = 0usize;
        let mut missing_semantic_schema_candidate_count = 0usize;
        let mut semantic_descriptor_match_candidate_count = 0usize;
        let mut projection_ready_candidate_count = 0usize;
        let mut dispatches_with_projection_ready_candidate_count = 0usize;
        let mut dispatches_without_projection_ready_candidate_count = 0usize;
        let mut source_ambiguous_dispatch_count = 0usize;
        let mut recommended_dispatch_count = 0usize;
        let mut missing_recommendation_dispatch_count = 0usize;
        let mut recommended_projected_kernarg_bytes = 0usize;
        let mut selection_applied_count = 0usize;

        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in semantic projection candidate recommendation plan",
                    dispatch.op_name
                ));
            }
            if dispatch.source_kernel_candidate_count == 0 {
                issues.push(format!(
                    "dispatch {} has no source kernel candidates",
                    dispatch.op_name
                ));
            }
            if dispatch.semantic_schema_candidate_count
                + dispatch.missing_semantic_schema_candidate_count
                != dispatch.source_kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} schema+missing count {} != source candidates {}",
                    dispatch.op_name,
                    dispatch.semantic_schema_candidate_count
                        + dispatch.missing_semantic_schema_candidate_count,
                    dispatch.source_kernel_candidate_count
                ));
            }
            if dispatch.semantic_descriptor_match_candidate_count
                > dispatch.semantic_schema_candidate_count
            {
                issues.push(format!(
                    "dispatch {} descriptor matches {} > schema candidates {}",
                    dispatch.op_name,
                    dispatch.semantic_descriptor_match_candidate_count,
                    dispatch.semantic_schema_candidate_count
                ));
            }
            if dispatch.projection_ready_candidate_count > dispatch.source_kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} projection-ready candidates {} > source candidates {}",
                    dispatch.op_name,
                    dispatch.projection_ready_candidate_count,
                    dispatch.source_kernel_candidate_count
                ));
            }
            if dispatch.has_projection_ready_candidate
                != (dispatch.projection_ready_candidate_count > 0)
            {
                issues.push(format!(
                    "dispatch {} projection-ready flag does not match ready count {}",
                    dispatch.op_name, dispatch.projection_ready_candidate_count
                ));
            }
            if dispatch.has_projection_ready_candidate {
                dispatches_with_projection_ready_candidate_count += 1;
            } else {
                dispatches_without_projection_ready_candidate_count += 1;
            }
            if dispatch.source_ambiguous_candidate_set
                != (dispatch.source_kernel_candidate_count > 1)
            {
                issues.push(format!(
                    "dispatch {} ambiguous flag does not match source candidate count {}",
                    dispatch.op_name, dispatch.source_kernel_candidate_count
                ));
            }
            if dispatch.selection_applied {
                issues.push(format!(
                    "dispatch {} projection candidate recommendation selection is unexpectedly applied",
                    dispatch.op_name
                ));
                selection_applied_count += 1;
            }

            match dispatch.state {
                RuntimeLaunchKernelArgumentAbiSemanticProjectionCandidateRecommendationState::RecommendedProjectionReadyCandidate => {
                    recommended_dispatch_count += 1;
                    if dispatch.projection_ready_candidate_count == 0 {
                        issues.push(format!(
                            "dispatch {} has a projection candidate recommendation without projection-ready candidates",
                            dispatch.op_name
                        ));
                    }
                    if let Some(index) = dispatch.recommended_candidate_index {
                        if index >= dispatch.source_kernel_candidate_count {
                            issues.push(format!(
                                "dispatch {} recommended candidate index {} >= source candidate count {}",
                                dispatch.op_name, index, dispatch.source_kernel_candidate_count
                            ));
                        }
                    } else {
                        issues.push(format!(
                            "dispatch {} has no recommended candidate index",
                            dispatch.op_name
                        ));
                    }
                    if dispatch
                        .recommended_kernel_symbol
                        .as_ref()
                        .is_some_and(|symbol| symbol.is_empty())
                    {
                        issues.push(format!(
                            "dispatch {} has an empty recommended kernel symbol",
                            dispatch.op_name
                        ));
                    }
                    if dispatch.recommended_candidate_index.is_none()
                        || dispatch.recommended_kernel_symbol.is_none()
                        || dispatch.recommended_kernarg_size.is_none()
                        || dispatch.recommended_projected_kernarg_bytes.is_none()
                        || !dispatch.recommended_candidate_projection_ready
                    {
                        issues.push(format!(
                            "dispatch {} projection candidate recommendation is missing ready candidate metadata",
                            dispatch.op_name
                        ));
                    }
                    if let (Some(kernarg_size), Some(projected_bytes)) = (
                        dispatch.recommended_kernarg_size,
                        dispatch.recommended_projected_kernarg_bytes,
                    ) {
                        if kernarg_size as usize != projected_bytes {
                            issues.push(format!(
                                "dispatch {} recommended projected bytes {} != kernarg size {}",
                                dispatch.op_name, projected_bytes, kernarg_size
                            ));
                        }
                        recommended_projected_kernarg_bytes = checked_add_usize(
                            recommended_projected_kernarg_bytes,
                            projected_bytes,
                            "semantic projection candidate recommendation projected kernarg bytes",
                        )?;
                    }
                    if dispatch.recommendation_reason
                        != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_REASON_READY
                    {
                        issues.push(format!(
                            "dispatch {} projection candidate recommendation reason {} != expected {}",
                            dispatch.op_name,
                            dispatch.recommendation_reason,
                            MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_REASON_READY
                        ));
                    }
                }
                RuntimeLaunchKernelArgumentAbiSemanticProjectionCandidateRecommendationState::NoProjectionReadyCandidate => {
                    missing_recommendation_dispatch_count += 1;
                    if dispatch.projection_ready_candidate_count > 0 {
                        issues.push(format!(
                            "dispatch {} has projection-ready candidates but no projection candidate recommendation",
                            dispatch.op_name
                        ));
                    }
                    if dispatch.recommended_candidate_index.is_some()
                        || dispatch.recommended_kernel_symbol.is_some()
                        || dispatch.recommended_kernarg_size.is_some()
                        || dispatch.recommended_projected_kernarg_bytes.is_some()
                        || dispatch.recommended_candidate_projection_ready
                    {
                        issues.push(format!(
                            "dispatch {} no projection candidate recommendation row carries candidate metadata",
                            dispatch.op_name
                        ));
                    }
                    if dispatch.recommendation_reason
                        != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_REASON_NONE
                    {
                        issues.push(format!(
                            "dispatch {} projection candidate recommendation reason {} != expected {}",
                            dispatch.op_name,
                            dispatch.recommendation_reason,
                            MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_REASON_NONE
                        ));
                    }
                }
            }

            if dispatch.source_ambiguous_candidate_set {
                source_ambiguous_dispatch_count += 1;
            }
            source_kernel_candidate_count = checked_add_usize(
                source_kernel_candidate_count,
                dispatch.source_kernel_candidate_count,
                "semantic projection candidate recommendation source candidate count",
            )?;
            semantic_schema_candidate_count = checked_add_usize(
                semantic_schema_candidate_count,
                dispatch.semantic_schema_candidate_count,
                "semantic projection candidate recommendation schema candidate count",
            )?;
            missing_semantic_schema_candidate_count = checked_add_usize(
                missing_semantic_schema_candidate_count,
                dispatch.missing_semantic_schema_candidate_count,
                "semantic projection candidate recommendation missing schema candidate count",
            )?;
            semantic_descriptor_match_candidate_count = checked_add_usize(
                semantic_descriptor_match_candidate_count,
                dispatch.semantic_descriptor_match_candidate_count,
                "semantic projection candidate recommendation descriptor-match candidate count",
            )?;
            projection_ready_candidate_count = checked_add_usize(
                projection_ready_candidate_count,
                dispatch.projection_ready_candidate_count,
                "semantic projection candidate recommendation ready candidate count",
            )?;
        }

        macro_rules! check_projection_candidate_recommendation_count {
            ($observed:ident, $field:ident, $label:literal) => {
                if $observed != self.$field {
                    issues.push(format!("{} {} != plan {}", $label, $observed, self.$field));
                }
            };
        }
        check_projection_candidate_recommendation_count!(
            source_kernel_candidate_count,
            source_kernel_candidate_count,
            "semantic projection candidate recommendation source candidate count"
        );
        check_projection_candidate_recommendation_count!(
            semantic_schema_candidate_count,
            semantic_schema_candidate_count,
            "semantic projection candidate recommendation schema candidate count"
        );
        check_projection_candidate_recommendation_count!(
            missing_semantic_schema_candidate_count,
            missing_semantic_schema_candidate_count,
            "semantic projection candidate recommendation missing schema candidate count"
        );
        check_projection_candidate_recommendation_count!(
            semantic_descriptor_match_candidate_count,
            semantic_descriptor_match_candidate_count,
            "semantic projection candidate recommendation descriptor-match candidate count"
        );
        check_projection_candidate_recommendation_count!(
            projection_ready_candidate_count,
            projection_ready_candidate_count,
            "semantic projection candidate recommendation ready candidate count"
        );
        check_projection_candidate_recommendation_count!(
            source_ambiguous_dispatch_count,
            source_ambiguous_dispatch_count,
            "semantic projection candidate recommendation ambiguous dispatch count"
        );
        check_projection_candidate_recommendation_count!(
            recommended_dispatch_count,
            recommended_dispatch_count,
            "semantic projection candidate recommendation recommended dispatch count"
        );
        check_projection_candidate_recommendation_count!(
            missing_recommendation_dispatch_count,
            missing_recommendation_dispatch_count,
            "semantic projection candidate recommendation missing dispatch count"
        );
        check_projection_candidate_recommendation_count!(
            recommended_projected_kernarg_bytes,
            recommended_projected_kernarg_bytes,
            "semantic projection candidate recommendation projected kernarg bytes"
        );
        check_projection_candidate_recommendation_count!(
            selection_applied_count,
            selection_applied_count,
            "semantic projection candidate recommendation selection-applied count"
        );
        if recommended_dispatch_count != dispatches_with_projection_ready_candidate_count {
            issues.push(format!(
                "semantic projection candidate recommendation recommended dispatch count {} != dispatches with projection-ready candidates {}",
                recommended_dispatch_count, dispatches_with_projection_ready_candidate_count
            ));
        }
        if missing_recommendation_dispatch_count
            != dispatches_without_projection_ready_candidate_count
        {
            issues.push(format!(
                "semantic projection candidate recommendation missing dispatch count {} != dispatches without projection-ready candidates {}",
                missing_recommendation_dispatch_count,
                dispatches_without_projection_ready_candidate_count
            ));
        }
        if dispatches_without_projection_ready_candidate_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT)
        {
            issues.push(format!(
                "semantic projection candidate recommendation observed requirements missing projection blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        if dispatches_without_projection_ready_candidate_count == 0
            && self
                .unresolved_runtime_requirements
                .contains(&MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT)
        {
            issues.push(format!(
                "semantic projection candidate recommendation observed complete plan still carries projection blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI semantic projection candidate recommendation plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionCandidateSelectionRequestPlan {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<
        &RuntimeDispatchLaunchKernelArgumentAbiSemanticProjectionCandidateSelectionRequestEntry,
    > {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn selection_request_op_names(&self) -> Vec<String> {
        self.dispatches
            .iter()
            .filter(|dispatch| dispatch.selection_request_ready)
            .map(|dispatch| dispatch.op_name.clone())
            .collect()
    }

    /// Returns delimiter-safe launch-order `(op_name, requested_kernel_symbol)` pairs.
    pub fn selection_request_op_kernel_symbols(&self) -> Vec<(String, String)> {
        self.dispatches
            .iter()
            .filter(|dispatch| dispatch.selection_request_ready)
            .filter_map(|dispatch| {
                dispatch
                    .requested_kernel_symbol
                    .as_ref()
                    .map(|symbol| (dispatch.op_name.clone(), symbol.clone()))
            })
            .collect()
    }

    /// Returns display-oriented `op=kernel_symbol` labels for fixture output.
    ///
    /// Use `selection_request_op_kernel_symbols()` when delimiter-safe
    /// structured data is needed.
    pub fn selection_request_op_kernel_symbol_labels(&self) -> Vec<String> {
        self.dispatches
            .iter()
            .filter(|dispatch| dispatch.selection_request_ready)
            .filter_map(|dispatch| {
                dispatch
                    .requested_kernel_symbol
                    .as_ref()
                    .map(|symbol| format!("{}={}", dispatch.op_name, symbol))
            })
            .collect()
    }

    pub fn missing_selection_request_op_names(&self) -> Vec<String> {
        self.dispatches
            .iter()
            .filter(|dispatch| !dispatch.selection_request_ready)
            .map(|dispatch| dispatch.op_name.clone())
            .collect()
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "semantic projection candidate selection request dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if self.dispatch_count == 0 {
            issues.push(
                "semantic projection candidate selection request dispatch count is zero"
                    .to_string(),
            );
        }
        if self.selection_request_count + self.missing_selection_request_count
            != self.dispatch_count
        {
            issues.push(format!(
                "semantic projection candidate selection+missing request count {} != dispatch count {}",
                self.selection_request_count + self.missing_selection_request_count,
                self.dispatch_count
            ));
        }
        if self.selection_applied_count != 0 {
            issues.push(format!(
                "semantic projection candidate selection applied count {} != 0",
                self.selection_applied_count
            ));
        }
        if self.all_selection_requests_ready != (self.missing_selection_request_count == 0) {
            issues.push(
                "semantic projection candidate all_selection_requests_ready does not match missing count"
                    .to_string(),
            );
        }
        if !self.request_plan_ready {
            issues.push(
                "semantic projection candidate selection request plan is not ready".to_string(),
            );
        }
        if self.policy
            != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_POLICY
        {
            issues.push(format!(
                "semantic projection candidate selection request policy {} != {}",
                self.policy,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_POLICY
            ));
        }
        if self.semantic_schema_source != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE {
            issues.push(format!(
                "semantic projection candidate selection request schema source {} != {}",
                self.semantic_schema_source,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE
            ));
        }
        if self.missing_selection_request_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT)
        {
            issues.push(format!(
                "semantic projection candidate selection request requirements missing projection blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        if self.source_ambiguous_dispatch_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&"kernel_candidate_selection_policy")
        {
            issues.push(format!(
                "semantic projection candidate selection request requirements missing selection-policy blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        let mut seen_requirements = BTreeSet::new();
        for requirement in &self.unresolved_runtime_requirements {
            if requirement.is_empty() {
                issues.push(
                    "semantic projection candidate selection request has empty requirement"
                        .to_string(),
                );
            }
            if !seen_requirements.insert(*requirement) {
                issues.push(format!(
                    "semantic projection candidate selection request requirement {requirement} appears more than once"
                ));
            }
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut source_kernel_candidate_count = 0usize;
        let mut semantic_schema_candidate_count = 0usize;
        let mut missing_semantic_schema_candidate_count = 0usize;
        let mut semantic_descriptor_match_candidate_count = 0usize;
        let mut projection_ready_candidate_count = 0usize;
        let mut dispatches_with_projection_ready_candidate_count = 0usize;
        let mut dispatches_without_projection_ready_candidate_count = 0usize;
        let mut source_ambiguous_dispatch_count = 0usize;
        let mut selection_request_count = 0usize;
        let mut missing_selection_request_count = 0usize;
        let mut requested_projected_kernarg_bytes = 0usize;
        let mut selection_applied_count = 0usize;

        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in semantic projection candidate selection request plan",
                    dispatch.op_name
                ));
            }
            if dispatch.source_kernel_candidate_count == 0 {
                issues.push(format!(
                    "dispatch {} has no source kernel candidates",
                    dispatch.op_name
                ));
            }
            if dispatch.semantic_schema_candidate_count
                + dispatch.missing_semantic_schema_candidate_count
                != dispatch.source_kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} schema+missing count {} != source candidates {}",
                    dispatch.op_name,
                    dispatch.semantic_schema_candidate_count
                        + dispatch.missing_semantic_schema_candidate_count,
                    dispatch.source_kernel_candidate_count
                ));
            }
            if dispatch.semantic_descriptor_match_candidate_count
                > dispatch.semantic_schema_candidate_count
            {
                issues.push(format!(
                    "dispatch {} descriptor matches {} > schema candidates {}",
                    dispatch.op_name,
                    dispatch.semantic_descriptor_match_candidate_count,
                    dispatch.semantic_schema_candidate_count
                ));
            }
            if dispatch.projection_ready_candidate_count > dispatch.source_kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} projection-ready candidates {} > source candidates {}",
                    dispatch.op_name,
                    dispatch.projection_ready_candidate_count,
                    dispatch.source_kernel_candidate_count
                ));
            }
            if dispatch.has_projection_ready_candidate
                != (dispatch.projection_ready_candidate_count > 0)
            {
                issues.push(format!(
                    "dispatch {} projection-ready flag does not match ready count {}",
                    dispatch.op_name, dispatch.projection_ready_candidate_count
                ));
            }
            if dispatch.has_projection_ready_candidate {
                dispatches_with_projection_ready_candidate_count += 1;
            } else {
                dispatches_without_projection_ready_candidate_count += 1;
            }
            if dispatch.source_ambiguous_candidate_set
                != (dispatch.source_kernel_candidate_count > 1)
            {
                issues.push(format!(
                    "dispatch {} ambiguous flag does not match source candidate count {}",
                    dispatch.op_name, dispatch.source_kernel_candidate_count
                ));
            }
            if dispatch.source_ambiguous_candidate_set {
                source_ambiguous_dispatch_count += 1;
            }
            let expected_selection_ready = dispatch.recommendation_state
                == RuntimeLaunchKernelArgumentAbiSemanticProjectionCandidateRecommendationState::RecommendedProjectionReadyCandidate;
            if dispatch.selection_request_ready != expected_selection_ready {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection readiness does not match recommendation state",
                    dispatch.op_name
                ));
            }
            if dispatch.selection_request_ready {
                selection_request_count += 1;
                if dispatch.projection_ready_candidate_count == 0 {
                    issues.push(format!(
                        "dispatch {} ready projection selection request has no projection-ready candidates",
                        dispatch.op_name
                    ));
                }
                if let Some(index) = dispatch.recommended_candidate_index {
                    if index >= dispatch.source_kernel_candidate_count {
                        issues.push(format!(
                            "dispatch {} requested candidate index {} >= source candidate count {}",
                            dispatch.op_name, index, dispatch.source_kernel_candidate_count
                        ));
                    }
                } else {
                    issues.push(format!(
                        "dispatch {} has no requested candidate index",
                        dispatch.op_name
                    ));
                }
                if dispatch
                    .requested_kernel_symbol
                    .as_ref()
                    .is_some_and(|symbol| symbol.is_empty())
                {
                    issues.push(format!(
                        "dispatch {} has an empty requested kernel symbol",
                        dispatch.op_name
                    ));
                }
                if dispatch.recommended_candidate_index.is_none()
                    || dispatch.requested_kernel_symbol.is_none()
                    || dispatch.requested_kernarg_size.is_none()
                    || dispatch.requested_projected_kernarg_bytes.is_none()
                    || !dispatch.requested_candidate_projection_ready
                {
                    issues.push(format!(
                        "dispatch {} ready projection selection request is missing projected candidate metadata",
                        dispatch.op_name
                    ));
                }
                if let (Some(kernarg_size), Some(projected_bytes)) = (
                    dispatch.requested_kernarg_size,
                    dispatch.requested_projected_kernarg_bytes,
                ) {
                    if kernarg_size as usize != projected_bytes {
                        issues.push(format!(
                            "dispatch {} requested projected bytes {} != kernarg size {}",
                            dispatch.op_name, projected_bytes, kernarg_size
                        ));
                    }
                    if dispatch.requested_projected_byte_image.len() != projected_bytes {
                        issues.push(format!(
                            "dispatch {} requested projected byte image len {} != projected bytes {}",
                            dispatch.op_name,
                            dispatch.requested_projected_byte_image.len(),
                            projected_bytes
                        ));
                    }
                    requested_projected_kernarg_bytes = checked_add_usize(
                        requested_projected_kernarg_bytes,
                        projected_bytes,
                        "semantic projection candidate selection request projected kernarg bytes",
                    )?;
                }
                if dispatch.selection_request_reason
                    != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_REASON_READY
                {
                    issues.push(format!(
                        "dispatch {} ready projection selection request reason {} != expected {}",
                        dispatch.op_name,
                        dispatch.selection_request_reason,
                        MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_REASON_READY
                    ));
                }
            } else {
                missing_selection_request_count += 1;
                if dispatch.projection_ready_candidate_count != 0 {
                    issues.push(format!(
                        "dispatch {} missing projection selection request has {} projection-ready candidate(s)",
                        dispatch.op_name, dispatch.projection_ready_candidate_count
                    ));
                }
                if dispatch.recommended_candidate_index.is_some()
                    || dispatch.requested_kernel_symbol.is_some()
                    || dispatch.requested_kernarg_size.is_some()
                    || dispatch.requested_projected_kernarg_bytes.is_some()
                    || !dispatch.requested_projected_byte_image.is_empty()
                    || dispatch.requested_candidate_projection_ready
                {
                    issues.push(format!(
                        "dispatch {} missing projection selection request carries candidate metadata",
                        dispatch.op_name
                    ));
                }
                if dispatch.selection_request_reason
                    != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_REASON_NONE
                {
                    issues.push(format!(
                        "dispatch {} missing projection selection request reason {} != expected {}",
                        dispatch.op_name,
                        dispatch.selection_request_reason,
                        MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_CANDIDATE_RECOMMENDATION_REASON_NONE
                    ));
                }
            }
            if dispatch.selection_applied {
                selection_applied_count += 1;
                issues.push(format!(
                    "dispatch {} projection candidate selection is unexpectedly applied",
                    dispatch.op_name
                ));
            }
            source_kernel_candidate_count = checked_add_usize(
                source_kernel_candidate_count,
                dispatch.source_kernel_candidate_count,
                "semantic projection candidate selection request source candidate count",
            )?;
            semantic_schema_candidate_count = checked_add_usize(
                semantic_schema_candidate_count,
                dispatch.semantic_schema_candidate_count,
                "semantic projection candidate selection request schema candidate count",
            )?;
            missing_semantic_schema_candidate_count = checked_add_usize(
                missing_semantic_schema_candidate_count,
                dispatch.missing_semantic_schema_candidate_count,
                "semantic projection candidate selection request missing schema candidate count",
            )?;
            semantic_descriptor_match_candidate_count = checked_add_usize(
                semantic_descriptor_match_candidate_count,
                dispatch.semantic_descriptor_match_candidate_count,
                "semantic projection candidate selection request descriptor-match candidate count",
            )?;
            projection_ready_candidate_count = checked_add_usize(
                projection_ready_candidate_count,
                dispatch.projection_ready_candidate_count,
                "semantic projection candidate selection request ready candidate count",
            )?;
        }

        macro_rules! check_projection_candidate_selection_request_count {
            ($observed:ident, $field:ident, $label:literal) => {
                if $observed != self.$field {
                    issues.push(format!("{} {} != plan {}", $label, $observed, self.$field));
                }
            };
        }
        check_projection_candidate_selection_request_count!(
            source_kernel_candidate_count,
            source_kernel_candidate_count,
            "semantic projection candidate selection request source candidate count"
        );
        check_projection_candidate_selection_request_count!(
            semantic_schema_candidate_count,
            semantic_schema_candidate_count,
            "semantic projection candidate selection request schema candidate count"
        );
        check_projection_candidate_selection_request_count!(
            missing_semantic_schema_candidate_count,
            missing_semantic_schema_candidate_count,
            "semantic projection candidate selection request missing schema candidate count"
        );
        check_projection_candidate_selection_request_count!(
            semantic_descriptor_match_candidate_count,
            semantic_descriptor_match_candidate_count,
            "semantic projection candidate selection request descriptor-match candidate count"
        );
        check_projection_candidate_selection_request_count!(
            projection_ready_candidate_count,
            projection_ready_candidate_count,
            "semantic projection candidate selection request ready candidate count"
        );
        check_projection_candidate_selection_request_count!(
            source_ambiguous_dispatch_count,
            source_ambiguous_dispatch_count,
            "semantic projection candidate selection request ambiguous dispatch count"
        );
        check_projection_candidate_selection_request_count!(
            selection_request_count,
            selection_request_count,
            "semantic projection candidate selection request count"
        );
        check_projection_candidate_selection_request_count!(
            missing_selection_request_count,
            missing_selection_request_count,
            "semantic projection candidate selection request missing count"
        );
        check_projection_candidate_selection_request_count!(
            requested_projected_kernarg_bytes,
            requested_projected_kernarg_bytes,
            "semantic projection candidate selection request projected kernarg bytes"
        );
        check_projection_candidate_selection_request_count!(
            selection_applied_count,
            selection_applied_count,
            "semantic projection candidate selection request selection-applied count"
        );
        if selection_request_count != dispatches_with_projection_ready_candidate_count {
            issues.push(format!(
                "semantic projection candidate selection request count {} != dispatches with projection-ready candidates {}",
                selection_request_count, dispatches_with_projection_ready_candidate_count
            ));
        }
        if missing_selection_request_count != dispatches_without_projection_ready_candidate_count {
            issues.push(format!(
                "semantic projection candidate selection missing count {} != dispatches without projection-ready candidates {}",
                missing_selection_request_count,
                dispatches_without_projection_ready_candidate_count
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI semantic projection candidate selection request plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn assert_consistent_with_projection(
        &self,
        projection: &ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionPlan,
    ) -> Result<()> {
        self.assert_consistent()?;
        projection.assert_consistent()?;

        let mut issues = Vec::new();
        if self.target != projection.target {
            issues.push(format!(
                "semantic projection candidate selection request target {} != projection target {}",
                self.target, projection.target
            ));
        }
        if self.code_object_target != projection.code_object_target {
            issues.push(format!(
                "semantic projection candidate selection request code object target {} != projection target {}",
                self.code_object_target, projection.code_object_target
            ));
        }
        if self.code_object_sha256 != projection.code_object_sha256 {
            issues.push(format!(
                "semantic projection candidate selection request code object sha256 {} != projection sha256 {}",
                self.code_object_sha256, projection.code_object_sha256
            ));
        }
        if self.dispatch_count != projection.dispatch_count {
            issues.push(format!(
                "semantic projection candidate selection request dispatch count {} != projection count {}",
                self.dispatch_count, projection.dispatch_count
            ));
        }
        if self.source_kernel_candidate_count != projection.kernel_candidate_count {
            issues.push(format!(
                "semantic projection candidate selection request source candidate count {} != projection candidate count {}",
                self.source_kernel_candidate_count, projection.kernel_candidate_count
            ));
        }
        if self.semantic_schema_candidate_count != projection.semantic_schema_candidate_count {
            issues.push(format!(
                "semantic projection candidate selection request schema candidate count {} != projection schema candidate count {}",
                self.semantic_schema_candidate_count, projection.semantic_schema_candidate_count
            ));
        }
        if self.missing_semantic_schema_candidate_count
            != projection.missing_semantic_schema_candidate_count
        {
            issues.push(format!(
                "semantic projection candidate selection request missing schema candidate count {} != projection missing schema candidate count {}",
                self.missing_semantic_schema_candidate_count,
                projection.missing_semantic_schema_candidate_count
            ));
        }
        if self.semantic_descriptor_match_candidate_count
            != projection.semantic_descriptor_match_candidate_count
        {
            issues.push(format!(
                "semantic projection candidate selection request descriptor-match candidate count {} != projection descriptor-match candidate count {}",
                self.semantic_descriptor_match_candidate_count,
                projection.semantic_descriptor_match_candidate_count
            ));
        }
        if self.projection_ready_candidate_count != projection.projection_ready_candidate_count {
            issues.push(format!(
                "semantic projection candidate selection request ready candidate count {} != projection ready candidate count {}",
                self.projection_ready_candidate_count, projection.projection_ready_candidate_count
            ));
        }
        let projection_source_ambiguous_dispatch_count = projection
            .dispatches
            .iter()
            .filter(|dispatch| dispatch.kernel_candidate_count > 1)
            .count();
        if self.source_ambiguous_dispatch_count != projection_source_ambiguous_dispatch_count {
            issues.push(format!(
                "semantic projection candidate selection request ambiguous dispatch count {} != projection ambiguous dispatch count {}",
                self.source_ambiguous_dispatch_count, projection_source_ambiguous_dispatch_count
            ));
        }
        let projection_derived_requirements =
            runtime_launch_kernel_argument_abi_semantic_projection_requirements(
                &projection.unresolved_runtime_requirements,
                self.all_selection_requests_ready,
            );
        if self.unresolved_runtime_requirements != projection_derived_requirements {
            issues.push(format!(
                "semantic projection candidate selection request requirements {:?} != projection-derived {:?}",
                self.unresolved_runtime_requirements, projection_derived_requirements
            ));
        }

        for dispatch in &self.dispatches {
            let Some(projection_dispatch) = projection.dispatch_for(&dispatch.op_name) else {
                issues.push(format!(
                    "dispatch {} missing projection row for semantic projection candidate selection request",
                    dispatch.op_name
                ));
                continue;
            };
            if dispatch.op_index != projection_dispatch.op_index
                || dispatch.kind != projection_dispatch.kind
                || dispatch.stage_name != projection_dispatch.stage_name
                || dispatch.stage_kind != projection_dispatch.stage_kind
                || dispatch.window_index != projection_dispatch.window_index
                || dispatch.queue_packet_index != projection_dispatch.queue_packet_index
            {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request metadata does not match projection",
                    dispatch.op_name
                ));
            }
            if dispatch.source_kernel_candidate_count != projection_dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request source candidate count {} != projection candidate count {}",
                    dispatch.op_name,
                    dispatch.source_kernel_candidate_count,
                    projection_dispatch.kernel_candidate_count
                ));
            }
            if dispatch.semantic_schema_candidate_count
                != projection_dispatch.semantic_schema_candidate_count
            {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request schema candidate count {} != projection schema candidate count {}",
                    dispatch.op_name,
                    dispatch.semantic_schema_candidate_count,
                    projection_dispatch.semantic_schema_candidate_count
                ));
            }
            if dispatch.missing_semantic_schema_candidate_count
                != projection_dispatch.missing_semantic_schema_candidate_count
            {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request missing schema candidate count {} != projection missing schema candidate count {}",
                    dispatch.op_name,
                    dispatch.missing_semantic_schema_candidate_count,
                    projection_dispatch.missing_semantic_schema_candidate_count
                ));
            }
            if dispatch.semantic_descriptor_match_candidate_count
                != projection_dispatch.semantic_descriptor_match_candidate_count
            {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request descriptor-match candidate count {} != projection descriptor-match candidate count {}",
                    dispatch.op_name,
                    dispatch.semantic_descriptor_match_candidate_count,
                    projection_dispatch.semantic_descriptor_match_candidate_count
                ));
            }
            if dispatch.projection_ready_candidate_count
                != projection_dispatch.projection_ready_candidate_count
            {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request ready candidate count {} != projection ready candidate count {}",
                    dispatch.op_name,
                    dispatch.projection_ready_candidate_count,
                    projection_dispatch.projection_ready_candidate_count
                ));
            }
            if dispatch.has_projection_ready_candidate
                != projection_dispatch.has_projection_ready_candidate
            {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request ready flag {} != projection ready flag {}",
                    dispatch.op_name,
                    dispatch.has_projection_ready_candidate,
                    projection_dispatch.has_projection_ready_candidate
                ));
            }
            let projection_source_ambiguous_candidate_set =
                projection_dispatch.kernel_candidate_count > 1;
            if dispatch.source_ambiguous_candidate_set != projection_source_ambiguous_candidate_set
            {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request ambiguous flag {} != projection ambiguous flag {}",
                    dispatch.op_name,
                    dispatch.source_ambiguous_candidate_set,
                    projection_source_ambiguous_candidate_set
                ));
            }
            let first_ready_candidate_index = projection_dispatch
                .candidates
                .iter()
                .position(|candidate| candidate.projection_ready);
            if dispatch.recommended_candidate_index != first_ready_candidate_index {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request candidate index {:?} != first projection-ready projection candidate {:?}",
                    dispatch.op_name,
                    dispatch.recommended_candidate_index,
                    first_ready_candidate_index
                ));
            }

            if dispatch.selection_request_ready {
                let Some(index) = dispatch.recommended_candidate_index else {
                    continue;
                };
                let Some(candidate) = projection_dispatch.candidates.get(index) else {
                    issues.push(format!(
                        "dispatch {} semantic projection candidate selection request candidate index {} missing in projection",
                        dispatch.op_name, index
                    ));
                    continue;
                };
                if dispatch.requested_kernel_symbol.as_deref()
                    != Some(candidate.kernel_symbol.as_str())
                    || dispatch.requested_kernarg_size != Some(candidate.kernarg_size)
                    || dispatch.requested_projected_kernarg_bytes
                        != Some(candidate.projected_kernarg_bytes)
                    || dispatch.requested_candidate_projection_ready != candidate.projection_ready
                {
                    issues.push(format!(
                        "dispatch {} semantic projection candidate selection request metadata does not match projection candidate {}",
                        dispatch.op_name, index
                    ));
                }
                if dispatch.requested_projected_byte_image.as_slice()
                    != candidate.projected_byte_image.as_slice()
                {
                    issues.push(format!(
                        "dispatch {} requested projected byte image does not match projection candidate {}",
                        dispatch.op_name, index
                    ));
                }
            } else if projection_dispatch.has_projection_ready_candidate {
                issues.push(format!(
                    "dispatch {} semantic projection candidate selection request is missing despite a projection-ready candidate",
                    dispatch.op_name
                ));
            }
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI semantic projection candidate selection request plan for {} does not match projection plan: {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionRecommendationReport {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelArgumentAbiSemanticProjectionRecommendationEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "semantic projection recommendation dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if self.dispatch_count == 0 {
            issues.push("semantic projection recommendation dispatch count is zero".to_string());
        }
        if self.policy != MODEL_RUNTIME_KERNEL_CANDIDATE_RECOMMENDATION_POLICY {
            issues.push(format!(
                "semantic projection recommendation policy {} != {}",
                self.policy, MODEL_RUNTIME_KERNEL_CANDIDATE_RECOMMENDATION_POLICY
            ));
        }
        if self.semantic_schema_source != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE {
            issues.push(format!(
                "semantic projection recommendation schema source {} != {}",
                self.semantic_schema_source,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE
            ));
        }
        if self.recommended_dispatch_count + self.missing_recommendation_dispatch_count
            != self.dispatch_count
        {
            issues.push(format!(
                "semantic projection recommendation recommended+missing dispatch count {} != dispatch count {}",
                self.recommended_dispatch_count + self.missing_recommendation_dispatch_count,
                self.dispatch_count
            ));
        }
        if self.dispatches_with_projection_ready_candidate_count
            + self.dispatches_without_projection_ready_candidate_count
            != self.dispatch_count
        {
            issues.push(format!(
                "semantic projection recommendation dispatches with+without ready candidate {} != dispatch count {}",
                self.dispatches_with_projection_ready_candidate_count
                    + self.dispatches_without_projection_ready_candidate_count,
                self.dispatch_count
            ));
        }
        if self.recommended_projection_found_dispatch_count
            + self.recommended_missing_projection_candidate_count
            != self.recommended_dispatch_count
        {
            issues.push(format!(
                "semantic projection recommendation found+missing projection count {} != recommended dispatch count {}",
                self.recommended_projection_found_dispatch_count
                    + self.recommended_missing_projection_candidate_count,
                self.recommended_dispatch_count
            ));
        }
        if self.recommended_projection_ready_dispatch_count
            + self.recommended_without_projection_ready_dispatch_count
            != self.recommended_dispatch_count
        {
            issues.push(format!(
                "semantic projection recommendation ready+not-ready dispatch count {} != recommended dispatch count {}",
                self.recommended_projection_ready_dispatch_count
                    + self.recommended_without_projection_ready_dispatch_count,
                self.recommended_dispatch_count
            ));
        }
        if self.recommended_projection_blocked_dispatch_count
            + self.recommended_missing_projection_candidate_count
            != self.recommended_without_projection_ready_dispatch_count
        {
            issues.push(format!(
                "semantic projection recommendation blocked+missing projection count {} != not-ready recommended count {}",
                self.recommended_projection_blocked_dispatch_count
                    + self.recommended_missing_projection_candidate_count,
                self.recommended_without_projection_ready_dispatch_count
            ));
        }
        if self.all_recommended_dispatches_projection_ready
            != (self.recommended_without_projection_ready_dispatch_count == 0)
        {
            issues.push(
                "all_recommended_dispatches_projection_ready does not match not-ready count"
                    .to_string(),
            );
        }
        if self.all_dispatches_have_projection_ready_recommendation
            != (self.recommended_projection_ready_dispatch_count == self.dispatch_count)
        {
            issues.push(
                "all_dispatches_have_projection_ready_recommendation does not match ready recommendation coverage"
                    .to_string(),
            );
        }
        if self.source_ambiguous_dispatch_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&"kernel_candidate_selection_policy")
        {
            issues.push(format!(
                "semantic projection recommendation requirements missing selection-policy blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        if self.recommended_without_projection_ready_dispatch_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT)
        {
            issues.push(format!(
                "semantic projection recommendation requirements missing projection blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }
        let mut seen_requirements = BTreeSet::new();
        for requirement in &self.unresolved_runtime_requirements {
            if requirement.is_empty() {
                issues.push("semantic projection recommendation has empty requirement".to_string());
            }
            if !seen_requirements.insert(*requirement) {
                issues.push(format!(
                    "semantic projection recommendation requirement {requirement} appears more than once"
                ));
            }
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut source_kernel_candidate_count = 0usize;
        let mut projection_kernel_candidate_count = 0usize;
        let mut projection_ready_candidate_count = 0usize;
        let mut source_ambiguous_dispatch_count = 0usize;
        let mut recommended_dispatch_count = 0usize;
        let mut missing_recommendation_dispatch_count = 0usize;
        let mut dispatches_with_projection_ready_candidate_count = 0usize;
        let mut dispatches_without_projection_ready_candidate_count = 0usize;
        let mut recommended_projection_found_dispatch_count = 0usize;
        let mut recommended_missing_projection_candidate_count = 0usize;
        let mut recommended_projection_ready_dispatch_count = 0usize;
        let mut recommended_projection_blocked_dispatch_count = 0usize;
        let mut recommended_projection_ready_kernarg_bytes = 0usize;

        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in semantic projection recommendation report",
                    dispatch.op_name
                ));
            }
            if dispatch.source_kernel_candidate_count == 0 {
                issues.push(format!(
                    "dispatch {} has no source kernel candidates",
                    dispatch.op_name
                ));
            }
            if dispatch.projection_kernel_candidate_count == 0 {
                issues.push(format!(
                    "dispatch {} has no projection kernel candidates",
                    dispatch.op_name
                ));
            }
            if dispatch.source_kernel_candidate_count != dispatch.projection_kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} source candidates {} != projection candidates {}",
                    dispatch.op_name,
                    dispatch.source_kernel_candidate_count,
                    dispatch.projection_kernel_candidate_count
                ));
            }
            if dispatch.projection_ready_candidate_count
                > dispatch.projection_kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} ready projection candidates {} > projection candidates {}",
                    dispatch.op_name,
                    dispatch.projection_ready_candidate_count,
                    dispatch.projection_kernel_candidate_count
                ));
            }
            if dispatch.has_projection_ready_candidate
                != (dispatch.projection_ready_candidate_count > 0)
            {
                issues.push(format!(
                    "dispatch {} projection-ready flag does not match ready count {}",
                    dispatch.op_name, dispatch.projection_ready_candidate_count
                ));
            }
            if dispatch.source_ambiguous_candidate_set
                != (dispatch.source_kernel_candidate_count > 1)
            {
                issues.push(format!(
                    "dispatch {} ambiguous flag does not match source candidate count {}",
                    dispatch.op_name, dispatch.source_kernel_candidate_count
                ));
            }
            if dispatch.selection_applied {
                issues.push(format!(
                    "dispatch {} recommendation selection is unexpectedly applied",
                    dispatch.op_name
                ));
            }

            let expected_reason = match dispatch.recommendation_state {
                RuntimeLaunchKernelCandidateRecommendationState::RecommendedVerifiedCandidate => {
                    recommended_dispatch_count += 1;
                    if dispatch.recommended_candidate_index.is_none()
                        || dispatch.recommended_kernel_symbol.is_none()
                        || !dispatch.recommended_candidate_verified
                    {
                        issues.push(format!(
                            "dispatch {} recommended row is missing verified candidate metadata",
                            dispatch.op_name
                        ));
                    }
                    if dispatch.recommended_candidate_projection_found {
                        recommended_projection_found_dispatch_count += 1;
                        if dispatch.recommended_candidate_projection_ready {
                            recommended_projection_ready_dispatch_count += 1;
                            recommended_projection_ready_kernarg_bytes = checked_add_usize(
                                recommended_projection_ready_kernarg_bytes,
                                dispatch.recommended_candidate_projected_kernarg_bytes,
                                "semantic projection recommendation ready kernarg bytes",
                            )?;
                            MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_RECOMMENDATION_REASON_READY
                        } else {
                            recommended_projection_blocked_dispatch_count += 1;
                            MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_RECOMMENDATION_REASON_BLOCKED
                        }
                    } else {
                        recommended_missing_projection_candidate_count += 1;
                        MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_RECOMMENDATION_REASON_MISSING
                    }
                }
                RuntimeLaunchKernelCandidateRecommendationState::NoVerifiedCandidate => {
                    missing_recommendation_dispatch_count += 1;
                    if dispatch.recommended_candidate_index.is_some()
                        || dispatch.recommended_kernel_symbol.is_some()
                        || dispatch.recommended_candidate_verified
                        || dispatch.recommended_candidate_projection_found
                        || dispatch.recommended_candidate_projection_ready
                        || dispatch
                            .recommended_candidate_primary_projection_blocker
                            .is_some()
                        || dispatch.recommended_candidate_projected_kernarg_bytes != 0
                    {
                        issues.push(format!(
                            "dispatch {} no-recommendation row carries candidate projection metadata",
                            dispatch.op_name
                        ));
                    }
                    MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_RECOMMENDATION_REASON_NONE
                }
            };
            if dispatch.recommendation_projection_reason != expected_reason {
                issues.push(format!(
                    "dispatch {} projection recommendation reason {} != expected {}",
                    dispatch.op_name, dispatch.recommendation_projection_reason, expected_reason
                ));
            }
            if dispatch.recommended_candidate_projection_ready
                && dispatch
                    .recommended_candidate_primary_projection_blocker
                    .is_some()
            {
                issues.push(format!(
                    "dispatch {} recommended projection is ready but has blocker {:?}",
                    dispatch.op_name, dispatch.recommended_candidate_primary_projection_blocker
                ));
            }
            if dispatch.recommended_candidate_projection_found
                && !dispatch.recommended_candidate_projection_ready
                && dispatch
                    .recommended_candidate_primary_projection_blocker
                    .is_none()
            {
                issues.push(format!(
                    "dispatch {} recommended projection is blocked but has no primary blocker",
                    dispatch.op_name
                ));
            }
            if !dispatch.recommended_candidate_projection_found
                && (dispatch.recommended_candidate_projection_ready
                    || dispatch
                        .recommended_candidate_primary_projection_blocker
                        .is_some()
                    || dispatch.recommended_candidate_projected_kernarg_bytes != 0)
            {
                issues.push(format!(
                    "dispatch {} missing projection candidate carries projection metadata",
                    dispatch.op_name
                ));
            }

            if dispatch.source_ambiguous_candidate_set {
                source_ambiguous_dispatch_count += 1;
            }
            if dispatch.has_projection_ready_candidate {
                dispatches_with_projection_ready_candidate_count += 1;
            } else {
                dispatches_without_projection_ready_candidate_count += 1;
            }
            source_kernel_candidate_count = checked_add_usize(
                source_kernel_candidate_count,
                dispatch.source_kernel_candidate_count,
                "semantic projection recommendation source candidate count",
            )?;
            projection_kernel_candidate_count = checked_add_usize(
                projection_kernel_candidate_count,
                dispatch.projection_kernel_candidate_count,
                "semantic projection recommendation projection candidate count",
            )?;
            projection_ready_candidate_count = checked_add_usize(
                projection_ready_candidate_count,
                dispatch.projection_ready_candidate_count,
                "semantic projection recommendation ready candidate count",
            )?;
        }

        let recommended_without_projection_ready_dispatch_count =
            recommended_projection_blocked_dispatch_count
                + recommended_missing_projection_candidate_count;
        macro_rules! check_projection_recommendation_count {
            ($observed:ident, $field:ident, $label:literal) => {
                if $observed != self.$field {
                    issues.push(format!(
                        "{} {} != report {}",
                        $label, $observed, self.$field
                    ));
                }
            };
        }
        check_projection_recommendation_count!(
            source_kernel_candidate_count,
            source_kernel_candidate_count,
            "semantic projection recommendation source candidate count"
        );
        check_projection_recommendation_count!(
            projection_kernel_candidate_count,
            projection_kernel_candidate_count,
            "semantic projection recommendation projection candidate count"
        );
        check_projection_recommendation_count!(
            projection_ready_candidate_count,
            projection_ready_candidate_count,
            "semantic projection recommendation ready candidate count"
        );
        check_projection_recommendation_count!(
            source_ambiguous_dispatch_count,
            source_ambiguous_dispatch_count,
            "semantic projection recommendation ambiguous dispatch count"
        );
        check_projection_recommendation_count!(
            recommended_dispatch_count,
            recommended_dispatch_count,
            "semantic projection recommendation recommended dispatch count"
        );
        check_projection_recommendation_count!(
            missing_recommendation_dispatch_count,
            missing_recommendation_dispatch_count,
            "semantic projection recommendation missing dispatch count"
        );
        check_projection_recommendation_count!(
            dispatches_with_projection_ready_candidate_count,
            dispatches_with_projection_ready_candidate_count,
            "semantic projection recommendation dispatches with ready candidate"
        );
        check_projection_recommendation_count!(
            dispatches_without_projection_ready_candidate_count,
            dispatches_without_projection_ready_candidate_count,
            "semantic projection recommendation dispatches without ready candidate"
        );
        check_projection_recommendation_count!(
            recommended_projection_found_dispatch_count,
            recommended_projection_found_dispatch_count,
            "semantic projection recommendation found dispatch count"
        );
        check_projection_recommendation_count!(
            recommended_missing_projection_candidate_count,
            recommended_missing_projection_candidate_count,
            "semantic projection recommendation missing projection candidate count"
        );
        check_projection_recommendation_count!(
            recommended_projection_ready_dispatch_count,
            recommended_projection_ready_dispatch_count,
            "semantic projection recommendation ready dispatch count"
        );
        check_projection_recommendation_count!(
            recommended_projection_blocked_dispatch_count,
            recommended_projection_blocked_dispatch_count,
            "semantic projection recommendation blocked dispatch count"
        );
        check_projection_recommendation_count!(
            recommended_without_projection_ready_dispatch_count,
            recommended_without_projection_ready_dispatch_count,
            "semantic projection recommendation without ready dispatch count"
        );
        check_projection_recommendation_count!(
            recommended_projection_ready_kernarg_bytes,
            recommended_projection_ready_kernarg_bytes,
            "semantic projection recommendation ready kernarg bytes"
        );

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI semantic projection recommendation report for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiVerificationPlan {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelArgumentAbiVerificationEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn size_compatibility_receipt(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiSizeCompatibilityReceipt> {
        runtime_launch_kernel_argument_abi_size_compatibility_receipt_from(self)
    }

    pub fn kernel_argument_abi_verification_gap_report(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiVerificationGapReport> {
        runtime_launch_kernel_argument_abi_verification_gap_report_from(self)
    }

    pub fn kernel_argument_abi_capacity_request_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiCapacityRequestPlan> {
        self.kernel_argument_abi_verification_gap_report()?
            .kernel_argument_abi_capacity_request_plan()
    }

    pub fn kernel_candidate_recommendation_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelCandidateRecommendationPlan> {
        runtime_launch_kernel_candidate_recommendation_plan_from(self)
    }

    pub fn kernel_argument_abi_schema_request_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiSchemaRequestPlan> {
        runtime_launch_kernel_argument_abi_schema_request_plan_from(self)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if self.size_compatible_candidate_count + self.size_shortfall_candidate_count
            != self.kernel_candidate_count
        {
            issues.push(format!(
                "size-compatible+shortfall candidate count {} != candidate count {}",
                self.size_compatible_candidate_count + self.size_shortfall_candidate_count,
                self.kernel_candidate_count
            ));
        }
        if self.named_abi_schema_available_count > self.kernel_candidate_count {
            issues.push(format!(
                "named ABI schema count {} > candidate count {}",
                self.named_abi_schema_available_count, self.kernel_candidate_count
            ));
        }
        if self.verified_candidate_count > self.named_abi_schema_available_count {
            issues.push(format!(
                "verified candidate count {} > named ABI schema count {}",
                self.verified_candidate_count, self.named_abi_schema_available_count
            ));
        }
        if self.abi_verification_ready
            != (self.kernel_candidate_count > 0
                && self.verified_candidate_count == self.kernel_candidate_count)
        {
            issues.push(
                "kernel argument ABI verification readiness mismatches verified candidates"
                    .to_string(),
            );
        }
        if self.named_schema_source != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_NAMED_SCHEMA_SOURCE {
            issues.push(format!(
                "named schema source {} != {}",
                self.named_schema_source, MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_NAMED_SCHEMA_SOURCE
            ));
        }
        let has_kernel_argument_abi_verification_requirement = self
            .unresolved_runtime_requirements
            .contains(&"kernel_argument_abi_verification");
        if self.abi_verification_ready && has_kernel_argument_abi_verification_requirement {
            issues
                .push("kernel argument ABI verification is ready but still unresolved".to_string());
        }
        if !self.abi_verification_ready && !has_kernel_argument_abi_verification_requirement {
            issues.push(format!(
                "kernel argument ABI requirements missing verification blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut kernel_candidate_count = 0usize;
        let mut size_compatible_candidate_count = 0usize;
        let mut size_shortfall_candidate_count = 0usize;
        let mut verified_candidate_count = 0usize;
        let mut dispatches_with_verified_candidate_count = 0usize;
        let mut dispatches_without_verified_candidate_count = 0usize;
        let mut named_abi_schema_available_count = 0usize;
        let mut max_capacity_shortfall_bytes = 0usize;
        let mut total_capacity_shortfall_bytes = 0usize;
        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in kernel argument ABI verification plan",
                    dispatch.op_name
                ));
            }
            if dispatch.candidates.len() != dispatch.kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} candidate entries {} != count {}",
                    dispatch.op_name,
                    dispatch.candidates.len(),
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.serialized_kernarg_bytes != dispatch.argument_span_bytes {
                issues.push(format!(
                    "dispatch {} serialized bytes {} != argument span bytes {}",
                    dispatch.op_name,
                    dispatch.serialized_kernarg_bytes,
                    dispatch.argument_span_bytes
                ));
            }
            let dispatch_size_compatible = dispatch
                .candidates
                .iter()
                .filter(|candidate| candidate.size_compatible)
                .count();
            let dispatch_size_shortfall = dispatch
                .candidates
                .iter()
                .filter(|candidate| !candidate.size_compatible)
                .count();
            if dispatch_size_compatible != dispatch.size_compatible_candidate_count {
                issues.push(format!(
                    "dispatch {} size-compatible candidates {} != count {}",
                    dispatch.op_name,
                    dispatch_size_compatible,
                    dispatch.size_compatible_candidate_count
                ));
            }
            if dispatch_size_shortfall != dispatch.size_shortfall_candidate_count {
                issues.push(format!(
                    "dispatch {} size-shortfall candidates {} != count {}",
                    dispatch.op_name,
                    dispatch_size_shortfall,
                    dispatch.size_shortfall_candidate_count
                ));
            }
            let dispatch_verified = dispatch
                .candidates
                .iter()
                .filter(|candidate| candidate.verification_ready)
                .count();
            if dispatch_verified != dispatch.verified_candidate_count {
                issues.push(format!(
                    "dispatch {} verified candidates {} != count {}",
                    dispatch.op_name, dispatch_verified, dispatch.verified_candidate_count
                ));
            }
            if dispatch.has_verified_candidate != (dispatch.verified_candidate_count > 0) {
                issues.push(format!(
                    "dispatch {} verified-candidate coverage flag does not match count {}",
                    dispatch.op_name, dispatch.verified_candidate_count
                ));
            }
            if dispatch.has_verified_candidate {
                dispatches_with_verified_candidate_count += 1;
            } else {
                dispatches_without_verified_candidate_count += 1;
            }
            let dispatch_max_shortfall = dispatch
                .candidates
                .iter()
                .map(|candidate| candidate.capacity_shortfall_bytes)
                .max()
                .unwrap_or(0);
            if dispatch_max_shortfall != dispatch.max_capacity_shortfall_bytes {
                issues.push(format!(
                    "dispatch {} max shortfall {} != expected {}",
                    dispatch.op_name, dispatch.max_capacity_shortfall_bytes, dispatch_max_shortfall
                ));
            }
            let mut candidate_symbols = BTreeSet::new();
            for candidate in &dispatch.candidates {
                if !candidate_symbols.insert(candidate.kernel_symbol.as_str()) {
                    issues.push(format!(
                        "dispatch {} has duplicate ABI candidate {}",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.kernel_symbol.is_empty() {
                    issues.push(format!(
                        "dispatch {} has empty ABI candidate symbol",
                        dispatch.op_name
                    ));
                }
                if candidate.kernarg_size == 0 {
                    issues.push(format!(
                        "dispatch {} candidate {} has zero kernarg size",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                let expected_shortfall = candidate
                    .serialized_kernarg_bytes
                    .saturating_sub(candidate.kernarg_size as usize);
                if candidate.capacity_shortfall_bytes != expected_shortfall {
                    issues.push(format!(
                        "dispatch {} candidate {} shortfall {} != expected {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.capacity_shortfall_bytes,
                        expected_shortfall
                    ));
                }
                if candidate.size_compatible != (candidate.capacity_shortfall_bytes == 0) {
                    issues.push(format!(
                        "dispatch {} candidate {} size compatibility mismatches shortfall",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.named_abi_schema_available
                    != (candidate.named_abi_schema_kernarg_size.is_some()
                        && candidate.named_abi_schema_kernarg_segment_align.is_some())
                {
                    issues.push(format!(
                        "dispatch {} candidate {} named ABI schema availability mismatches schema metadata",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.named_abi_descriptor_match
                    != (candidate.named_abi_schema_kernarg_size == Some(candidate.kernarg_size)
                        && candidate.named_abi_schema_kernarg_segment_align
                            == Some(candidate.kernarg_segment_align))
                {
                    issues.push(format!(
                        "dispatch {} candidate {} named ABI descriptor match mismatches schema values",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.named_abi_verified
                    != (candidate.named_abi_schema_available
                        && candidate.named_abi_descriptor_match
                        && candidate.size_compatible)
                {
                    issues.push(format!(
                        "dispatch {} candidate {} named ABI verification mismatches schema/size compatibility",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.verification_ready != candidate.named_abi_verified {
                    issues.push(format!(
                        "dispatch {} candidate {} verification readiness mismatches named ABI verification",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.named_abi_schema_available {
                    named_abi_schema_available_count += 1;
                }
                if candidate.verification_ready {
                    verified_candidate_count += 1;
                }
                total_capacity_shortfall_bytes = checked_add_usize(
                    total_capacity_shortfall_bytes,
                    candidate.capacity_shortfall_bytes,
                    "kernel argument ABI total shortfall",
                )?;
                max_capacity_shortfall_bytes =
                    max_capacity_shortfall_bytes.max(candidate.capacity_shortfall_bytes);
            }
            kernel_candidate_count = checked_add_usize(
                kernel_candidate_count,
                dispatch.kernel_candidate_count,
                "kernel argument ABI candidate count",
            )?;
            size_compatible_candidate_count = checked_add_usize(
                size_compatible_candidate_count,
                dispatch.size_compatible_candidate_count,
                "kernel argument ABI size-compatible count",
            )?;
            size_shortfall_candidate_count = checked_add_usize(
                size_shortfall_candidate_count,
                dispatch.size_shortfall_candidate_count,
                "kernel argument ABI size-shortfall count",
            )?;
        }
        if kernel_candidate_count != self.kernel_candidate_count {
            issues.push(format!(
                "kernel candidate count {kernel_candidate_count} != plan {}",
                self.kernel_candidate_count
            ));
        }
        if size_compatible_candidate_count != self.size_compatible_candidate_count {
            issues.push(format!(
                "size-compatible candidate count {size_compatible_candidate_count} != plan {}",
                self.size_compatible_candidate_count
            ));
        }
        if size_shortfall_candidate_count != self.size_shortfall_candidate_count {
            issues.push(format!(
                "size-shortfall candidate count {size_shortfall_candidate_count} != plan {}",
                self.size_shortfall_candidate_count
            ));
        }
        if verified_candidate_count != self.verified_candidate_count {
            issues.push(format!(
                "verified candidate count {verified_candidate_count} != plan {}",
                self.verified_candidate_count
            ));
        }
        if dispatches_with_verified_candidate_count != self.dispatches_with_verified_candidate_count
        {
            issues.push(format!(
                "dispatches with verified candidates {dispatches_with_verified_candidate_count} != plan {}",
                self.dispatches_with_verified_candidate_count
            ));
        }
        if dispatches_without_verified_candidate_count
            != self.dispatches_without_verified_candidate_count
        {
            issues.push(format!(
                "dispatches without verified candidates {dispatches_without_verified_candidate_count} != plan {}",
                self.dispatches_without_verified_candidate_count
            ));
        }
        if self.dispatches_with_verified_candidate_count
            + self.dispatches_without_verified_candidate_count
            != self.dispatch_count
        {
            issues.push(format!(
                "dispatches with+without verified candidates {} != dispatch count {}",
                self.dispatches_with_verified_candidate_count
                    + self.dispatches_without_verified_candidate_count,
                self.dispatch_count
            ));
        }
        if named_abi_schema_available_count != self.named_abi_schema_available_count {
            issues.push(format!(
                "named ABI schema count {named_abi_schema_available_count} != plan {}",
                self.named_abi_schema_available_count
            ));
        }
        if max_capacity_shortfall_bytes != self.max_capacity_shortfall_bytes {
            issues.push(format!(
                "max capacity shortfall {max_capacity_shortfall_bytes} != plan {}",
                self.max_capacity_shortfall_bytes
            ));
        }
        if total_capacity_shortfall_bytes != self.total_capacity_shortfall_bytes {
            issues.push(format!(
                "total capacity shortfall {total_capacity_shortfall_bytes} != plan {}",
                self.total_capacity_shortfall_bytes
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI verification plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiSizeCompatibilityReceipt {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelArgumentAbiSizeCompatibilityReceipt> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "size compatibility dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if !self.size_compatibility_checked {
            issues.push("kernel argument ABI size compatibility was not checked".to_string());
        }
        if self.named_abi_schema_available_count > self.kernel_candidate_count {
            issues.push(format!(
                "named ABI schema count {} > candidate count {}",
                self.named_abi_schema_available_count, self.kernel_candidate_count
            ));
        }
        if self.named_abi_verified_candidate_count > self.named_abi_schema_available_count {
            issues.push(format!(
                "named ABI verified candidate count {} > schema count {}",
                self.named_abi_verified_candidate_count, self.named_abi_schema_available_count
            ));
        }
        if self.named_abi_verification_ready
            != (self.kernel_candidate_count > 0
                && self.named_abi_verified_candidate_count == self.kernel_candidate_count)
        {
            issues.push(
                "named ABI verification readiness mismatches verified candidate count".to_string(),
            );
        }
        let has_kernel_argument_abi_verification_requirement = self
            .unresolved_runtime_requirements
            .contains(&"kernel_argument_abi_verification");
        if self.named_abi_verification_ready && has_kernel_argument_abi_verification_requirement {
            issues.push("named ABI verification is ready but still unresolved".to_string());
        }
        if !self.named_abi_verification_ready && !has_kernel_argument_abi_verification_requirement {
            issues.push(format!(
                "size compatibility receipt requirements missing ABI verification blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut kernel_candidate_count = 0usize;
        let mut size_compatible_candidate_count = 0usize;
        let mut size_shortfall_candidate_count = 0usize;
        let mut dispatches_with_size_compatible_candidate_count = 0usize;
        let mut dispatches_without_size_compatible_candidate_count = 0usize;
        let mut verified_candidate_count = 0usize;
        let mut dispatches_with_verified_candidate_count = 0usize;
        let mut dispatches_without_verified_candidate_count = 0usize;
        let mut max_capacity_shortfall_bytes = 0usize;
        let mut total_capacity_shortfall_bytes = 0usize;
        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in size compatibility receipt",
                    dispatch.op_name
                ));
            }
            if dispatch.kernel_candidate_count == 0 {
                issues.push(format!(
                    "dispatch {} has no kernel candidates",
                    dispatch.op_name
                ));
            }
            if dispatch.size_compatible_candidate_count + dispatch.size_shortfall_candidate_count
                != dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} size-compatible+shortfall {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.size_compatible_candidate_count
                        + dispatch.size_shortfall_candidate_count,
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.has_size_compatible_candidate
                != (dispatch.size_compatible_candidate_count > 0)
            {
                issues.push(format!(
                    "dispatch {} size-compatible flag does not match count {}",
                    dispatch.op_name, dispatch.size_compatible_candidate_count
                ));
            }
            if dispatch.has_size_compatible_candidate {
                dispatches_with_size_compatible_candidate_count += 1;
            } else {
                dispatches_without_size_compatible_candidate_count += 1;
            }
            if dispatch.verified_candidate_count > dispatch.size_compatible_candidate_count {
                issues.push(format!(
                    "dispatch {} verified candidates {} > size-compatible candidates {}",
                    dispatch.op_name,
                    dispatch.verified_candidate_count,
                    dispatch.size_compatible_candidate_count
                ));
            }
            if dispatch.has_verified_candidate != (dispatch.verified_candidate_count > 0) {
                issues.push(format!(
                    "dispatch {} verified flag does not match count {}",
                    dispatch.op_name, dispatch.verified_candidate_count
                ));
            }
            if dispatch.has_verified_candidate {
                dispatches_with_verified_candidate_count += 1;
            } else {
                dispatches_without_verified_candidate_count += 1;
            }
            if dispatch.serialized_kernarg_bytes != dispatch.argument_span_bytes {
                issues.push(format!(
                    "dispatch {} serialized bytes {} != argument span bytes {}",
                    dispatch.op_name,
                    dispatch.serialized_kernarg_bytes,
                    dispatch.argument_span_bytes
                ));
            }
            kernel_candidate_count = checked_add_usize(
                kernel_candidate_count,
                dispatch.kernel_candidate_count,
                "kernel argument ABI size receipt candidate",
            )?;
            size_compatible_candidate_count = checked_add_usize(
                size_compatible_candidate_count,
                dispatch.size_compatible_candidate_count,
                "kernel argument ABI size receipt compatible",
            )?;
            size_shortfall_candidate_count = checked_add_usize(
                size_shortfall_candidate_count,
                dispatch.size_shortfall_candidate_count,
                "kernel argument ABI size receipt shortfall",
            )?;
            verified_candidate_count = checked_add_usize(
                verified_candidate_count,
                dispatch.verified_candidate_count,
                "kernel argument ABI size receipt verified",
            )?;
            max_capacity_shortfall_bytes =
                max_capacity_shortfall_bytes.max(dispatch.max_capacity_shortfall_bytes);
            total_capacity_shortfall_bytes = checked_add_usize(
                total_capacity_shortfall_bytes,
                dispatch.total_capacity_shortfall_bytes,
                "kernel argument ABI size receipt total shortfall",
            )?;
        }
        if kernel_candidate_count != self.kernel_candidate_count {
            issues.push(format!(
                "kernel candidate count {kernel_candidate_count} != receipt {}",
                self.kernel_candidate_count
            ));
        }
        if size_compatible_candidate_count != self.size_compatible_candidate_count {
            issues.push(format!(
                "size-compatible candidate count {size_compatible_candidate_count} != receipt {}",
                self.size_compatible_candidate_count
            ));
        }
        if size_shortfall_candidate_count != self.size_shortfall_candidate_count {
            issues.push(format!(
                "size-shortfall candidate count {size_shortfall_candidate_count} != receipt {}",
                self.size_shortfall_candidate_count
            ));
        }
        if verified_candidate_count != self.named_abi_verified_candidate_count {
            issues.push(format!(
                "verified candidate count {verified_candidate_count} != receipt {}",
                self.named_abi_verified_candidate_count
            ));
        }
        if dispatches_with_size_compatible_candidate_count
            != self.dispatches_with_size_compatible_candidate_count
        {
            issues.push(format!(
                "dispatches with size-compatible candidates {dispatches_with_size_compatible_candidate_count} != receipt {}",
                self.dispatches_with_size_compatible_candidate_count
            ));
        }
        if dispatches_without_size_compatible_candidate_count
            != self.dispatches_without_size_compatible_candidate_count
        {
            issues.push(format!(
                "dispatches without size-compatible candidates {dispatches_without_size_compatible_candidate_count} != receipt {}",
                self.dispatches_without_size_compatible_candidate_count
            ));
        }
        if self.dispatches_with_size_compatible_candidate_count
            + self.dispatches_without_size_compatible_candidate_count
            != self.dispatch_count
        {
            issues.push(format!(
                "dispatches with+without size-compatible candidates {} != dispatch count {}",
                self.dispatches_with_size_compatible_candidate_count
                    + self.dispatches_without_size_compatible_candidate_count,
                self.dispatch_count
            ));
        }
        if dispatches_with_verified_candidate_count != self.dispatches_with_verified_candidate_count
        {
            issues.push(format!(
                "dispatches with verified candidates {dispatches_with_verified_candidate_count} != receipt {}",
                self.dispatches_with_verified_candidate_count
            ));
        }
        if dispatches_without_verified_candidate_count
            != self.dispatches_without_verified_candidate_count
        {
            issues.push(format!(
                "dispatches without verified candidates {dispatches_without_verified_candidate_count} != receipt {}",
                self.dispatches_without_verified_candidate_count
            ));
        }
        if self.dispatches_with_verified_candidate_count
            + self.dispatches_without_verified_candidate_count
            != self.dispatch_count
        {
            issues.push(format!(
                "dispatches with+without verified candidates {} != dispatch count {}",
                self.dispatches_with_verified_candidate_count
                    + self.dispatches_without_verified_candidate_count,
                self.dispatch_count
            ));
        }
        if max_capacity_shortfall_bytes != self.max_capacity_shortfall_bytes {
            issues.push(format!(
                "max capacity shortfall {max_capacity_shortfall_bytes} != receipt {}",
                self.max_capacity_shortfall_bytes
            ));
        }
        if total_capacity_shortfall_bytes != self.total_capacity_shortfall_bytes {
            issues.push(format!(
                "total capacity shortfall {total_capacity_shortfall_bytes} != receipt {}",
                self.total_capacity_shortfall_bytes
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI size compatibility receipt for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiVerificationGapReport {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelArgumentAbiVerificationGapEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn kernel_argument_abi_capacity_request_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchKernelArgumentAbiCapacityRequestPlan> {
        runtime_launch_kernel_argument_abi_capacity_request_plan_from(self)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_gap_count {
            issues.push(format!(
                "ABI gap dispatch entries {} != gap count {}",
                self.dispatches.len(),
                self.dispatch_gap_count
            ));
        }
        if self.dispatch_gap_count > self.source_dispatch_count {
            issues.push(format!(
                "ABI gap dispatch count {} > source dispatch count {}",
                self.dispatch_gap_count, self.source_dispatch_count
            ));
        }
        if self.all_dispatches_have_verified_candidate != (self.dispatch_gap_count == 0) {
            issues.push(
                "all_dispatches_have_verified_candidate does not match gap count".to_string(),
            );
        }
        if self.gap_verified_candidate_count != 0 {
            issues.push(format!(
                "ABI gap verified candidate count {} != 0",
                self.gap_verified_candidate_count
            ));
        }
        if self.named_schema_source != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_NAMED_SCHEMA_SOURCE {
            issues.push(format!(
                "named schema source {} != {}",
                self.named_schema_source, MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_NAMED_SCHEMA_SOURCE
            ));
        }
        if self.dispatch_gap_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&"kernel_argument_abi_verification")
        {
            issues.push(format!(
                "ABI gap report requirements missing verification blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut gap_kernel_candidate_count = 0usize;
        let mut gap_size_compatible_candidate_count = 0usize;
        let mut gap_size_shortfall_candidate_count = 0usize;
        let mut gap_named_abi_schema_available_count = 0usize;
        let mut gap_named_abi_descriptor_match_count = 0usize;
        let mut gap_missing_named_abi_schema_count = 0usize;
        let mut gap_descriptor_mismatch_candidate_count = 0usize;
        let mut gap_verified_candidate_count = 0usize;
        let mut gap_primary_missing_named_abi_schema_candidate_count = 0usize;
        let mut gap_primary_descriptor_mismatch_candidate_count = 0usize;
        let mut gap_primary_size_shortfall_candidate_count = 0usize;
        let mut gap_primary_unknown_unverified_candidate_count = 0usize;
        let mut max_capacity_shortfall_bytes = 0usize;
        let mut total_capacity_shortfall_bytes = 0usize;
        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in ABI gap report",
                    dispatch.op_name
                ));
            }
            if dispatch.kernel_candidate_count == 0 {
                issues.push(format!(
                    "dispatch {} has no ABI gap kernel candidates",
                    dispatch.op_name
                ));
            }
            if dispatch.candidate_kernel_symbols.len() != dispatch.kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} candidate symbols {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.candidate_kernel_symbols.len(),
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.candidate_gaps.len() != dispatch.kernel_candidate_count {
                issues.push(format!(
                    "dispatch {} candidate gap rows {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.candidate_gaps.len(),
                    dispatch.kernel_candidate_count
                ));
            }
            let candidate_gap_symbols = dispatch
                .candidate_gaps
                .iter()
                .map(|candidate| candidate.kernel_symbol.as_str())
                .collect::<Vec<_>>();
            let candidate_kernel_symbols = dispatch
                .candidate_kernel_symbols
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>();
            if candidate_gap_symbols != candidate_kernel_symbols {
                issues.push(format!(
                    "dispatch {} candidate gap symbols do not match candidate symbol list",
                    dispatch.op_name
                ));
            }
            if dispatch
                .candidate_kernel_symbols
                .iter()
                .any(|symbol| symbol.is_empty())
            {
                issues.push(format!(
                    "dispatch {} has an empty ABI gap candidate symbol",
                    dispatch.op_name
                ));
            }
            if dispatch.size_compatible_candidate_count + dispatch.size_shortfall_candidate_count
                != dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} size-compatible+shortfall {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.size_compatible_candidate_count
                        + dispatch.size_shortfall_candidate_count,
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.named_abi_schema_available_count + dispatch.missing_named_abi_schema_count
                != dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} named-schema available+missing {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.named_abi_schema_available_count
                        + dispatch.missing_named_abi_schema_count,
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.named_abi_descriptor_match_count
                + dispatch.descriptor_mismatch_candidate_count
                != dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} descriptor match+mismatch {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.named_abi_descriptor_match_count
                        + dispatch.descriptor_mismatch_candidate_count,
                    dispatch.kernel_candidate_count
                ));
            }
            if dispatch.verified_candidate_count != 0 {
                issues.push(format!(
                    "dispatch {} is in ABI gap report but has {} verified candidates",
                    dispatch.op_name, dispatch.verified_candidate_count
                ));
            }
            let dispatch_primary_missing_schema = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == RuntimeLaunchKernelArgumentAbiVerificationGapReason::MissingNamedAbiSchema
                })
                .count();
            if dispatch_primary_missing_schema
                != dispatch.primary_missing_named_abi_schema_candidate_count
            {
                issues.push(format!(
                    "dispatch {} primary missing-schema candidates {} != count {}",
                    dispatch.op_name,
                    dispatch_primary_missing_schema,
                    dispatch.primary_missing_named_abi_schema_candidate_count
                ));
            }
            let dispatch_primary_descriptor_mismatch = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == RuntimeLaunchKernelArgumentAbiVerificationGapReason::NamedAbiDescriptorMismatch
                })
                .count();
            if dispatch_primary_descriptor_mismatch
                != dispatch.primary_descriptor_mismatch_candidate_count
            {
                issues.push(format!(
                    "dispatch {} primary descriptor-mismatch candidates {} != count {}",
                    dispatch.op_name,
                    dispatch_primary_descriptor_mismatch,
                    dispatch.primary_descriptor_mismatch_candidate_count
                ));
            }
            let dispatch_primary_size_shortfall = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == RuntimeLaunchKernelArgumentAbiVerificationGapReason::KernargSizeShortfall
                })
                .count();
            if dispatch_primary_size_shortfall != dispatch.primary_size_shortfall_candidate_count {
                issues.push(format!(
                    "dispatch {} primary size-shortfall candidates {} != count {}",
                    dispatch.op_name,
                    dispatch_primary_size_shortfall,
                    dispatch.primary_size_shortfall_candidate_count
                ));
            }
            let dispatch_primary_unknown = dispatch
                .candidate_gaps
                .iter()
                .filter(|candidate| {
                    candidate.primary_gap_reason
                        == RuntimeLaunchKernelArgumentAbiVerificationGapReason::UnknownUnverifiedCandidate
                })
                .count();
            if dispatch_primary_unknown != dispatch.primary_unknown_unverified_candidate_count {
                issues.push(format!(
                    "dispatch {} primary unknown candidates {} != count {}",
                    dispatch.op_name,
                    dispatch_primary_unknown,
                    dispatch.primary_unknown_unverified_candidate_count
                ));
            }
            if dispatch.primary_missing_named_abi_schema_candidate_count
                + dispatch.primary_descriptor_mismatch_candidate_count
                + dispatch.primary_size_shortfall_candidate_count
                + dispatch.primary_unknown_unverified_candidate_count
                != dispatch.kernel_candidate_count
            {
                issues.push(format!(
                    "dispatch {} primary gap reason counts {} != candidate count {}",
                    dispatch.op_name,
                    dispatch.primary_missing_named_abi_schema_candidate_count
                        + dispatch.primary_descriptor_mismatch_candidate_count
                        + dispatch.primary_size_shortfall_candidate_count
                        + dispatch.primary_unknown_unverified_candidate_count,
                    dispatch.kernel_candidate_count
                ));
            }
            for candidate in &dispatch.candidate_gaps {
                if candidate.kernel_symbol.is_empty() {
                    issues.push(format!(
                        "dispatch {} has an empty ABI gap candidate symbol",
                        dispatch.op_name
                    ));
                }
                if !dispatch
                    .candidate_kernel_symbols
                    .iter()
                    .any(|symbol| symbol == &candidate.kernel_symbol)
                {
                    issues.push(format!(
                        "dispatch {} candidate gap {} is missing from candidate symbol list",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.kernarg_size == 0 {
                    issues.push(format!(
                        "dispatch {} candidate {} has zero kernarg size",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                let expected_shortfall = candidate
                    .serialized_kernarg_bytes
                    .saturating_sub(candidate.kernarg_size as usize);
                if candidate.capacity_shortfall_bytes != expected_shortfall {
                    issues.push(format!(
                        "dispatch {} candidate {} shortfall {} != expected {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.capacity_shortfall_bytes,
                        expected_shortfall
                    ));
                }
                if candidate.size_compatible != (candidate.capacity_shortfall_bytes == 0) {
                    issues.push(format!(
                        "dispatch {} candidate {} size compatibility mismatches shortfall",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.named_abi_schema_available
                    != (candidate.named_abi_schema_kernarg_size.is_some()
                        && candidate.named_abi_schema_kernarg_segment_align.is_some())
                {
                    issues.push(format!(
                        "dispatch {} candidate {} named ABI schema availability mismatches schema metadata",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.named_abi_descriptor_match
                    != (candidate.named_abi_schema_kernarg_size == Some(candidate.kernarg_size)
                        && candidate.named_abi_schema_kernarg_segment_align
                            == Some(candidate.kernarg_segment_align))
                {
                    issues.push(format!(
                        "dispatch {} candidate {} named ABI descriptor match mismatches schema metadata",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.named_abi_verified
                    != (candidate.named_abi_schema_available
                        && candidate.named_abi_descriptor_match
                        && candidate.size_compatible)
                {
                    issues.push(format!(
                        "dispatch {} candidate {} named ABI verification mismatches schema/size compatibility",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.verification_ready != candidate.named_abi_verified {
                    issues.push(format!(
                        "dispatch {} candidate {} verification readiness mismatches named ABI verification",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.verification_ready {
                    issues.push(format!(
                        "dispatch {} candidate {} is verified inside ABI gap report",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if candidate.primary_gap_reason
                    != runtime_launch_kernel_argument_abi_verification_gap_reason_for_candidate(
                        candidate,
                    )
                {
                    issues.push(format!(
                        "dispatch {} candidate {} primary gap reason {:?} is inconsistent",
                        dispatch.op_name, candidate.kernel_symbol, candidate.primary_gap_reason
                    ));
                }
            }
            gap_kernel_candidate_count = checked_add_usize(
                gap_kernel_candidate_count,
                dispatch.kernel_candidate_count,
                "ABI gap candidate count",
            )?;
            gap_size_compatible_candidate_count = checked_add_usize(
                gap_size_compatible_candidate_count,
                dispatch.size_compatible_candidate_count,
                "ABI gap size-compatible candidate count",
            )?;
            gap_size_shortfall_candidate_count = checked_add_usize(
                gap_size_shortfall_candidate_count,
                dispatch.size_shortfall_candidate_count,
                "ABI gap size-shortfall candidate count",
            )?;
            gap_named_abi_schema_available_count = checked_add_usize(
                gap_named_abi_schema_available_count,
                dispatch.named_abi_schema_available_count,
                "ABI gap named schema count",
            )?;
            gap_named_abi_descriptor_match_count = checked_add_usize(
                gap_named_abi_descriptor_match_count,
                dispatch.named_abi_descriptor_match_count,
                "ABI gap descriptor match count",
            )?;
            gap_missing_named_abi_schema_count = checked_add_usize(
                gap_missing_named_abi_schema_count,
                dispatch.missing_named_abi_schema_count,
                "ABI gap missing named schema count",
            )?;
            gap_descriptor_mismatch_candidate_count = checked_add_usize(
                gap_descriptor_mismatch_candidate_count,
                dispatch.descriptor_mismatch_candidate_count,
                "ABI gap descriptor mismatch count",
            )?;
            gap_verified_candidate_count = checked_add_usize(
                gap_verified_candidate_count,
                dispatch.verified_candidate_count,
                "ABI gap verified candidate count",
            )?;
            gap_primary_missing_named_abi_schema_candidate_count = checked_add_usize(
                gap_primary_missing_named_abi_schema_candidate_count,
                dispatch.primary_missing_named_abi_schema_candidate_count,
                "ABI gap primary missing named schema count",
            )?;
            gap_primary_descriptor_mismatch_candidate_count = checked_add_usize(
                gap_primary_descriptor_mismatch_candidate_count,
                dispatch.primary_descriptor_mismatch_candidate_count,
                "ABI gap primary descriptor mismatch count",
            )?;
            gap_primary_size_shortfall_candidate_count = checked_add_usize(
                gap_primary_size_shortfall_candidate_count,
                dispatch.primary_size_shortfall_candidate_count,
                "ABI gap primary size shortfall count",
            )?;
            gap_primary_unknown_unverified_candidate_count = checked_add_usize(
                gap_primary_unknown_unverified_candidate_count,
                dispatch.primary_unknown_unverified_candidate_count,
                "ABI gap primary unknown unverified count",
            )?;
            max_capacity_shortfall_bytes =
                max_capacity_shortfall_bytes.max(dispatch.max_capacity_shortfall_bytes);
            total_capacity_shortfall_bytes = checked_add_usize(
                total_capacity_shortfall_bytes,
                dispatch.total_capacity_shortfall_bytes,
                "ABI gap total shortfall",
            )?;
        }
        if gap_kernel_candidate_count != self.gap_kernel_candidate_count {
            issues.push(format!(
                "gap candidate count {gap_kernel_candidate_count} != report {}",
                self.gap_kernel_candidate_count
            ));
        }
        if gap_size_compatible_candidate_count != self.gap_size_compatible_candidate_count {
            issues.push(format!(
                "gap size-compatible candidate count {gap_size_compatible_candidate_count} != report {}",
                self.gap_size_compatible_candidate_count
            ));
        }
        if gap_size_shortfall_candidate_count != self.gap_size_shortfall_candidate_count {
            issues.push(format!(
                "gap size-shortfall candidate count {gap_size_shortfall_candidate_count} != report {}",
                self.gap_size_shortfall_candidate_count
            ));
        }
        if gap_named_abi_schema_available_count != self.gap_named_abi_schema_available_count {
            issues.push(format!(
                "gap named ABI schema count {gap_named_abi_schema_available_count} != report {}",
                self.gap_named_abi_schema_available_count
            ));
        }
        if gap_named_abi_descriptor_match_count != self.gap_named_abi_descriptor_match_count {
            issues.push(format!(
                "gap named ABI descriptor match count {gap_named_abi_descriptor_match_count} != report {}",
                self.gap_named_abi_descriptor_match_count
            ));
        }
        if gap_missing_named_abi_schema_count != self.gap_missing_named_abi_schema_count {
            issues.push(format!(
                "gap missing named ABI schema count {gap_missing_named_abi_schema_count} != report {}",
                self.gap_missing_named_abi_schema_count
            ));
        }
        if gap_descriptor_mismatch_candidate_count != self.gap_descriptor_mismatch_candidate_count {
            issues.push(format!(
                "gap descriptor mismatch candidate count {gap_descriptor_mismatch_candidate_count} != report {}",
                self.gap_descriptor_mismatch_candidate_count
            ));
        }
        if gap_verified_candidate_count != self.gap_verified_candidate_count {
            issues.push(format!(
                "gap verified candidate count {gap_verified_candidate_count} != report {}",
                self.gap_verified_candidate_count
            ));
        }
        if gap_primary_missing_named_abi_schema_candidate_count
            != self.gap_primary_missing_named_abi_schema_candidate_count
        {
            issues.push(format!(
                "gap primary missing named ABI schema count {gap_primary_missing_named_abi_schema_candidate_count} != report {}",
                self.gap_primary_missing_named_abi_schema_candidate_count
            ));
        }
        if gap_primary_descriptor_mismatch_candidate_count
            != self.gap_primary_descriptor_mismatch_candidate_count
        {
            issues.push(format!(
                "gap primary descriptor mismatch count {gap_primary_descriptor_mismatch_candidate_count} != report {}",
                self.gap_primary_descriptor_mismatch_candidate_count
            ));
        }
        if gap_primary_size_shortfall_candidate_count
            != self.gap_primary_size_shortfall_candidate_count
        {
            issues.push(format!(
                "gap primary size shortfall count {gap_primary_size_shortfall_candidate_count} != report {}",
                self.gap_primary_size_shortfall_candidate_count
            ));
        }
        if gap_primary_unknown_unverified_candidate_count
            != self.gap_primary_unknown_unverified_candidate_count
        {
            issues.push(format!(
                "gap primary unknown unverified count {gap_primary_unknown_unverified_candidate_count} != report {}",
                self.gap_primary_unknown_unverified_candidate_count
            ));
        }
        if self.gap_primary_missing_named_abi_schema_candidate_count
            + self.gap_primary_descriptor_mismatch_candidate_count
            + self.gap_primary_size_shortfall_candidate_count
            + self.gap_primary_unknown_unverified_candidate_count
            != self.gap_kernel_candidate_count
        {
            issues.push(format!(
                "gap primary reason counts {} != gap candidate count {}",
                self.gap_primary_missing_named_abi_schema_candidate_count
                    + self.gap_primary_descriptor_mismatch_candidate_count
                    + self.gap_primary_size_shortfall_candidate_count
                    + self.gap_primary_unknown_unverified_candidate_count,
                self.gap_kernel_candidate_count
            ));
        }
        if max_capacity_shortfall_bytes != self.max_capacity_shortfall_bytes {
            issues.push(format!(
                "gap max capacity shortfall {max_capacity_shortfall_bytes} != report {}",
                self.max_capacity_shortfall_bytes
            ));
        }
        if total_capacity_shortfall_bytes != self.total_capacity_shortfall_bytes {
            issues.push(format!(
                "gap total capacity shortfall {total_capacity_shortfall_bytes} != report {}",
                self.total_capacity_shortfall_bytes
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI verification gap report for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

impl ModelRuntimeLaunchKernelArgumentAbiCapacityRequestPlan {
    pub fn kernel_for(
        &self,
        kernel_symbol: &str,
    ) -> Option<&RuntimeLaunchKernelArgumentAbiCapacityRequestEntry> {
        self.kernels
            .iter()
            .find(|kernel| kernel.kernel_symbol == kernel_symbol)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.kernels.len() != self.capacity_request_count {
            issues.push(format!(
                "kernel argument ABI capacity request entries {} != request count {}",
                self.kernels.len(),
                self.capacity_request_count
            ));
        }
        if self.source_primary_size_shortfall_candidate_count > self.gap_kernel_candidate_count {
            issues.push(format!(
                "primary size-shortfall candidates {} > gap candidate count {}",
                self.source_primary_size_shortfall_candidate_count, self.gap_kernel_candidate_count
            ));
        }
        if self.candidate_capacity_request_count
            != self.source_primary_size_shortfall_candidate_count
        {
            issues.push(format!(
                "candidate capacity requests {} != primary size-shortfall candidates {}",
                self.candidate_capacity_request_count,
                self.source_primary_size_shortfall_candidate_count
            ));
        }
        if self.all_capacity_requests_ready
            != self
                .kernels
                .iter()
                .all(|kernel| kernel.capacity_request_ready)
        {
            issues.push(
                "all_capacity_requests_ready does not match kernel request readiness".to_string(),
            );
        }
        if !self.request_plan_ready {
            issues.push("kernel argument ABI capacity request plan is not ready".to_string());
        }
        if self.capacity_request_reason != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_CAPACITY_REQUEST_REASON
        {
            issues.push(format!(
                "capacity request reason {} != {}",
                self.capacity_request_reason,
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_CAPACITY_REQUEST_REASON
            ));
        }
        if self.candidate_capacity_request_count > 0
            && !self
                .unresolved_runtime_requirements
                .contains(&"kernel_argument_abi_verification")
        {
            issues.push(format!(
                "kernel argument ABI capacity request requirements missing verification blocker: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_symbols = BTreeSet::new();
        let mut dispatch_reference_count = 0usize;
        let mut candidate_capacity_request_count = 0usize;
        let mut max_capacity_shortfall_bytes = 0usize;
        let mut total_capacity_shortfall_bytes = 0usize;
        for kernel in &self.kernels {
            if !seen_symbols.insert(kernel.kernel_symbol.as_str()) {
                issues.push(format!(
                    "kernel {} appears more than once in kernel argument ABI capacity request plan",
                    kernel.kernel_symbol
                ));
            }
            if kernel.kernel_symbol.is_empty() {
                issues.push("kernel argument ABI capacity request has empty symbol".to_string());
            }
            if kernel.kernarg_size == 0 {
                issues.push(format!(
                    "kernel {} has zero kernarg size",
                    kernel.kernel_symbol
                ));
            }
            if kernel.kernarg_segment_align == 0 {
                issues.push(format!(
                    "kernel {} has zero kernarg alignment",
                    kernel.kernel_symbol
                ));
            }
            if !kernel.named_abi_schema_available {
                issues.push(format!(
                    "kernel {} capacity request is missing a named ABI schema",
                    kernel.kernel_symbol
                ));
            }
            if kernel.named_abi_schema_available
                != (kernel.named_abi_schema_kernarg_size.is_some()
                    && kernel.named_abi_schema_kernarg_segment_align.is_some())
            {
                issues.push(format!(
                    "kernel {} schema availability mismatches schema metadata",
                    kernel.kernel_symbol
                ));
            }
            if kernel.named_abi_descriptor_match
                != (kernel.named_abi_schema_kernarg_size == Some(kernel.kernarg_size)
                    && kernel.named_abi_schema_kernarg_segment_align
                        == Some(kernel.kernarg_segment_align))
            {
                issues.push(format!(
                    "kernel {} descriptor match mismatches schema metadata",
                    kernel.kernel_symbol
                ));
            }
            if !kernel.named_abi_descriptor_match {
                issues.push(format!(
                    "kernel {} capacity request descriptor is not schema-matched",
                    kernel.kernel_symbol
                ));
            }
            if kernel.max_serialized_kernarg_bytes != kernel.required_kernarg_size {
                issues.push(format!(
                    "kernel {} max serialized bytes {} != required kernarg size {}",
                    kernel.kernel_symbol,
                    kernel.max_serialized_kernarg_bytes,
                    kernel.required_kernarg_size
                ));
            }
            if kernel.required_kernarg_size <= kernel.kernarg_size as usize {
                issues.push(format!(
                    "kernel {} required kernarg size {} <= descriptor kernarg size {}",
                    kernel.kernel_symbol, kernel.required_kernarg_size, kernel.kernarg_size
                ));
            }
            let expected_max_shortfall = kernel
                .required_kernarg_size
                .saturating_sub(kernel.kernarg_size as usize);
            if kernel.max_capacity_shortfall_bytes != expected_max_shortfall {
                issues.push(format!(
                    "kernel {} max capacity shortfall {} != required-size shortfall {}",
                    kernel.kernel_symbol,
                    kernel.max_capacity_shortfall_bytes,
                    expected_max_shortfall
                ));
            }
            if kernel.dispatch_reference_count == 0 {
                issues.push(format!(
                    "kernel {} has zero dispatch references",
                    kernel.kernel_symbol
                ));
            }
            if kernel.candidate_capacity_request_count == 0 {
                issues.push(format!(
                    "kernel {} has zero candidate capacity requests",
                    kernel.kernel_symbol
                ));
            }
            if kernel.total_capacity_shortfall_bytes < kernel.max_capacity_shortfall_bytes {
                issues.push(format!(
                    "kernel {} total shortfall {} < max shortfall {}",
                    kernel.kernel_symbol,
                    kernel.total_capacity_shortfall_bytes,
                    kernel.max_capacity_shortfall_bytes
                ));
            }
            if !kernel.capacity_request_ready {
                issues.push(format!(
                    "kernel {} capacity request is not ready",
                    kernel.kernel_symbol
                ));
            }
            if kernel.capacity_request_reason
                != MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_CAPACITY_REQUEST_REASON
            {
                issues.push(format!(
                    "kernel {} capacity request reason {} != {}",
                    kernel.kernel_symbol,
                    kernel.capacity_request_reason,
                    MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_CAPACITY_REQUEST_REASON
                ));
            }
            dispatch_reference_count = checked_add_usize(
                dispatch_reference_count,
                kernel.dispatch_reference_count,
                "kernel argument ABI capacity request dispatch references",
            )?;
            candidate_capacity_request_count = checked_add_usize(
                candidate_capacity_request_count,
                kernel.candidate_capacity_request_count,
                "kernel argument ABI capacity request candidates",
            )?;
            max_capacity_shortfall_bytes =
                max_capacity_shortfall_bytes.max(kernel.max_capacity_shortfall_bytes);
            total_capacity_shortfall_bytes = checked_add_usize(
                total_capacity_shortfall_bytes,
                kernel.total_capacity_shortfall_bytes,
                "kernel argument ABI capacity request total shortfall",
            )?;
        }
        if dispatch_reference_count != self.dispatch_reference_count {
            issues.push(format!(
                "dispatch reference count {dispatch_reference_count} != plan {}",
                self.dispatch_reference_count
            ));
        }
        if candidate_capacity_request_count != self.candidate_capacity_request_count {
            issues.push(format!(
                "candidate capacity request count {candidate_capacity_request_count} != plan {}",
                self.candidate_capacity_request_count
            ));
        }
        if max_capacity_shortfall_bytes != self.max_capacity_shortfall_bytes {
            issues.push(format!(
                "max capacity shortfall {max_capacity_shortfall_bytes} != plan {}",
                self.max_capacity_shortfall_bytes
            ));
        }
        if total_capacity_shortfall_bytes != self.total_capacity_shortfall_bytes {
            issues.push(format!(
                "total capacity shortfall {total_capacity_shortfall_bytes} != plan {}",
                self.total_capacity_shortfall_bytes
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch kernel argument ABI capacity request plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

fn runtime_launch_kernel_argument_abi_verification_plan_from(
    templates: &ModelRuntimeLaunchAqlPacketTemplatePlan,
) -> Result<ModelRuntimeLaunchKernelArgumentAbiVerificationPlan> {
    templates.assert_consistent()?;
    let mut dispatches = Vec::with_capacity(templates.dispatch_count);
    let mut kernel_candidate_count = 0usize;
    let mut size_compatible_candidate_count = 0usize;
    let mut size_shortfall_candidate_count = 0usize;
    let mut verified_candidate_count = 0usize;
    let mut dispatches_with_verified_candidate_count = 0usize;
    let mut dispatches_without_verified_candidate_count = 0usize;
    let mut named_abi_schema_available_count = 0usize;
    let mut max_capacity_shortfall_bytes = 0usize;
    let mut total_capacity_shortfall_bytes = 0usize;
    for template in templates
        .windows
        .iter()
        .flat_map(|window| window.dispatches.iter())
    {
        let entry = runtime_dispatch_launch_kernel_argument_abi_verification_entry_from(template)?;
        kernel_candidate_count = checked_add_usize(
            kernel_candidate_count,
            entry.kernel_candidate_count,
            "kernel argument ABI candidate count",
        )?;
        size_compatible_candidate_count = checked_add_usize(
            size_compatible_candidate_count,
            entry.size_compatible_candidate_count,
            "kernel argument ABI size-compatible candidate count",
        )?;
        size_shortfall_candidate_count = checked_add_usize(
            size_shortfall_candidate_count,
            entry.size_shortfall_candidate_count,
            "kernel argument ABI size-shortfall candidate count",
        )?;
        verified_candidate_count = checked_add_usize(
            verified_candidate_count,
            entry.verified_candidate_count,
            "kernel argument ABI verified candidate count",
        )?;
        if entry.has_verified_candidate {
            dispatches_with_verified_candidate_count += 1;
        } else {
            dispatches_without_verified_candidate_count += 1;
        }
        named_abi_schema_available_count = checked_add_usize(
            named_abi_schema_available_count,
            entry
                .candidates
                .iter()
                .filter(|candidate| candidate.named_abi_schema_available)
                .count(),
            "kernel argument ABI named schema count",
        )?;
        max_capacity_shortfall_bytes =
            max_capacity_shortfall_bytes.max(entry.max_capacity_shortfall_bytes);
        total_capacity_shortfall_bytes = checked_add_usize(
            total_capacity_shortfall_bytes,
            entry
                .candidates
                .iter()
                .map(|candidate| candidate.capacity_shortfall_bytes)
                .sum::<usize>(),
            "kernel argument ABI total capacity shortfall",
        )?;
        dispatches.push(entry);
    }
    let abi_verification_ready =
        kernel_candidate_count > 0 && verified_candidate_count == kernel_candidate_count;
    let plan = ModelRuntimeLaunchKernelArgumentAbiVerificationPlan {
        target: templates.target,
        code_object_target: templates.code_object_target.clone(),
        code_object_sha256: templates.code_object_sha256.clone(),
        dispatch_count: templates.dispatch_count,
        kernel_candidate_count,
        size_compatible_candidate_count,
        size_shortfall_candidate_count,
        verified_candidate_count,
        dispatches_with_verified_candidate_count,
        dispatches_without_verified_candidate_count,
        named_abi_schema_available_count,
        max_capacity_shortfall_bytes,
        total_capacity_shortfall_bytes,
        abi_verification_ready,
        named_schema_source: MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_NAMED_SCHEMA_SOURCE,
        unresolved_runtime_requirements: runtime_launch_kernel_argument_abi_requirements(
            &templates.unresolved_runtime_requirements,
            abi_verification_ready,
        ),
        dispatches,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

fn runtime_launch_kernel_argument_abi_semantic_plan_from(
    templates: &ModelRuntimeLaunchAqlPacketTemplatePlan,
    serialization: &ModelRuntimeLaunchKernargSerializationPlan,
) -> Result<ModelRuntimeLaunchKernelArgumentAbiSemanticPlan> {
    templates.assert_consistent()?;
    serialization.assert_consistent()?;
    if templates.target != serialization.target {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic target {} != serialization target {}",
            templates.target,
            serialization.target
        ));
    }
    if templates.code_object_target != serialization.code_object_target {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic code object target {} != serialization target {}",
            templates.code_object_target,
            serialization.code_object_target
        ));
    }
    if templates.code_object_sha256 != serialization.code_object_sha256 {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic code object sha256 {} != serialization sha256 {}",
            templates.code_object_sha256,
            serialization.code_object_sha256
        ));
    }
    if templates.dispatch_count != serialization.dispatch_count {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic dispatch count {} != serialization count {}",
            templates.dispatch_count,
            serialization.dispatch_count
        ));
    }
    if templates.window_count != serialization.window_count {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic window count {} != serialization count {}",
            templates.window_count,
            serialization.window_count
        ));
    }
    if templates.kernarg_serialized_bytes != serialization.serialized_kernarg_bytes {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic serialized bytes {} != serialization bytes {}",
            templates.kernarg_serialized_bytes,
            serialization.serialized_kernarg_bytes
        ));
    }

    let mut dispatches = Vec::with_capacity(templates.dispatch_count);
    let mut kernel_candidate_count = 0usize;
    let mut semantic_schema_candidate_count = 0usize;
    let mut missing_semantic_schema_candidate_count = 0usize;
    let mut semantic_descriptor_match_candidate_count = 0usize;
    let mut semantic_verified_candidate_count = 0usize;
    let mut dispatches_with_semantic_verified_candidate_count = 0usize;
    let mut dispatches_without_semantic_verified_candidate_count = 0usize;
    let mut field_schema_count = 0usize;
    let mut verified_field_count = 0usize;
    let mut missing_field_count = 0usize;
    let mut field_mismatch_count = 0usize;
    let mut extra_argument_count = 0usize;

    for template in templates
        .windows
        .iter()
        .flat_map(|window| window.dispatches.iter())
    {
        let serialized = serialization.dispatch_for(&template.op_name).ok_or_else(|| {
            anyhow!(
                "runtime launch kernel argument ABI semantic dispatch {} missing serialization entry",
                template.op_name
            )
        })?;
        let entry =
            runtime_dispatch_launch_kernel_argument_abi_semantic_entry_from(template, serialized)?;
        kernel_candidate_count = checked_add_usize(
            kernel_candidate_count,
            entry.kernel_candidate_count,
            "semantic ABI candidate count",
        )?;
        semantic_schema_candidate_count = checked_add_usize(
            semantic_schema_candidate_count,
            entry.semantic_schema_candidate_count,
            "semantic ABI schema candidate count",
        )?;
        missing_semantic_schema_candidate_count = checked_add_usize(
            missing_semantic_schema_candidate_count,
            entry.missing_semantic_schema_candidate_count,
            "semantic ABI missing schema candidate count",
        )?;
        semantic_descriptor_match_candidate_count = checked_add_usize(
            semantic_descriptor_match_candidate_count,
            entry.semantic_descriptor_match_candidate_count,
            "semantic ABI descriptor match candidate count",
        )?;
        semantic_verified_candidate_count = checked_add_usize(
            semantic_verified_candidate_count,
            entry.semantic_verified_candidate_count,
            "semantic ABI verified candidate count",
        )?;
        if entry.has_semantic_verified_candidate {
            dispatches_with_semantic_verified_candidate_count += 1;
        } else {
            dispatches_without_semantic_verified_candidate_count += 1;
        }
        field_schema_count = checked_add_usize(
            field_schema_count,
            entry.field_schema_count,
            "semantic ABI field schema count",
        )?;
        verified_field_count = checked_add_usize(
            verified_field_count,
            entry.verified_field_count,
            "semantic ABI verified field count",
        )?;
        missing_field_count = checked_add_usize(
            missing_field_count,
            entry.missing_field_count,
            "semantic ABI missing field count",
        )?;
        field_mismatch_count = checked_add_usize(
            field_mismatch_count,
            entry.field_mismatch_count,
            "semantic ABI field mismatch count",
        )?;
        extra_argument_count = checked_add_usize(
            extra_argument_count,
            entry.extra_argument_count,
            "semantic ABI extra argument count",
        )?;
        dispatches.push(entry);
    }

    let semantic_abi_ready =
        kernel_candidate_count > 0 && semantic_verified_candidate_count == kernel_candidate_count;
    let plan = ModelRuntimeLaunchKernelArgumentAbiSemanticPlan {
        target: templates.target,
        code_object_target: templates.code_object_target.clone(),
        code_object_sha256: templates.code_object_sha256.clone(),
        dispatch_count: templates.dispatch_count,
        kernel_candidate_count,
        semantic_schema_candidate_count,
        missing_semantic_schema_candidate_count,
        semantic_descriptor_match_candidate_count,
        semantic_verified_candidate_count,
        dispatches_with_semantic_verified_candidate_count,
        dispatches_without_semantic_verified_candidate_count,
        field_schema_count,
        verified_field_count,
        missing_field_count,
        field_mismatch_count,
        extra_argument_count,
        semantic_abi_ready,
        semantic_schema_source: MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE,
        unresolved_runtime_requirements: runtime_launch_kernel_argument_abi_requirements(
            &templates.unresolved_runtime_requirements,
            semantic_abi_ready,
        ),
        dispatches,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

fn runtime_dispatch_launch_kernel_argument_abi_semantic_entry_from(
    template: &RuntimeDispatchLaunchAqlPacketTemplateEntry,
    serialized: &RuntimeDispatchLaunchKernargSerializationEntry,
) -> Result<RuntimeDispatchLaunchKernelArgumentAbiSemanticEntry> {
    if template.op_index != serialized.op_index
        || template.op_name != serialized.op_name
        || template.kind != serialized.kind
        || template.stage_name != serialized.stage_name
        || template.stage_kind != serialized.stage_kind
    {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic dispatch {} does not match serialization dispatch {}",
            template.op_name,
            serialized.op_name
        ));
    }
    if template.argument_count != serialized.argument_count {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic dispatch {} argument count {} != serialization count {}",
            template.op_name,
            template.argument_count,
            serialized.argument_count
        ));
    }
    if template.kernarg_argument_span_bytes != serialized.argument_span_bytes {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic dispatch {} argument span {} != serialization span {}",
            template.op_name,
            template.kernarg_argument_span_bytes,
            serialized.argument_span_bytes
        ));
    }
    if template.kernarg_serialized_bytes != serialized.serialized_kernarg_bytes {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic dispatch {} serialized bytes {} != serialization bytes {}",
            template.op_name,
            template.kernarg_serialized_bytes,
            serialized.serialized_kernarg_bytes
        ));
    }

    let candidates = template
        .candidate_templates
        .iter()
        .map(|candidate| {
            runtime_launch_kernel_argument_abi_semantic_candidate_entry_from(candidate, serialized)
        })
        .collect::<Vec<_>>();
    let kernel_candidate_count = candidates.len();
    if kernel_candidate_count == 0 {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic dispatch {} has no kernel candidates",
            template.op_name
        ));
    }
    let semantic_schema_candidate_count = candidates
        .iter()
        .filter(|candidate| candidate.semantic_schema_available)
        .count();
    let missing_semantic_schema_candidate_count =
        kernel_candidate_count - semantic_schema_candidate_count;
    let semantic_descriptor_match_candidate_count = candidates
        .iter()
        .filter(|candidate| candidate.semantic_descriptor_match)
        .count();
    let semantic_verified_candidate_count = candidates
        .iter()
        .filter(|candidate| candidate.semantic_verified)
        .count();
    let field_schema_count = candidates
        .iter()
        .map(|candidate| candidate.field_schema_count)
        .sum::<usize>();
    let verified_field_count = candidates
        .iter()
        .map(|candidate| candidate.verified_field_count)
        .sum::<usize>();
    let missing_field_count = candidates
        .iter()
        .map(|candidate| candidate.missing_field_count)
        .sum::<usize>();
    let field_mismatch_count = candidates
        .iter()
        .map(|candidate| candidate.field_mismatch_count)
        .sum::<usize>();
    let extra_argument_count = candidates
        .iter()
        .map(|candidate| candidate.extra_argument_count)
        .sum::<usize>();
    Ok(RuntimeDispatchLaunchKernelArgumentAbiSemanticEntry {
        op_index: template.op_index,
        op_name: template.op_name.clone(),
        kind: template.kind,
        stage_name: template.stage_name.clone(),
        stage_kind: template.stage_kind,
        window_index: template.window_index,
        queue_packet_index: template.queue_packet_index,
        argument_count: template.argument_count,
        serialized_kernarg_bytes: template.kernarg_serialized_bytes,
        kernel_candidate_count,
        semantic_schema_candidate_count,
        missing_semantic_schema_candidate_count,
        semantic_descriptor_match_candidate_count,
        semantic_verified_candidate_count,
        has_semantic_verified_candidate: semantic_verified_candidate_count > 0,
        field_schema_count,
        verified_field_count,
        missing_field_count,
        field_mismatch_count,
        extra_argument_count,
        candidates,
    })
}

fn runtime_launch_kernel_argument_abi_semantic_candidate_entry_from(
    candidate: &RuntimeLaunchAqlPacketCandidateTemplate,
    serialized: &RuntimeDispatchLaunchKernargSerializationEntry,
) -> RuntimeLaunchKernelArgumentAbiSemanticCandidateEntry {
    let schema = runtime_launch_kernel_argument_abi_semantic_schema_for(&candidate.kernel_symbol);
    let fields = schema
        .map(|schema| {
            schema
                .fields
                .iter()
                .map(|field| {
                    runtime_launch_kernel_argument_abi_semantic_field_check_entry_from(
                        field, serialized,
                    )
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let expected_model_argument_names = schema
        .map(|schema| {
            schema
                .fields
                .iter()
                .map(|field| field.model_argument_name)
                .collect::<BTreeSet<_>>()
        })
        .unwrap_or_default();
    let extra_model_argument_names = if schema.is_some() {
        serialized
            .arguments
            .iter()
            .filter(|argument| !expected_model_argument_names.contains(argument.name))
            .map(|argument| argument.name.to_string())
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    let semantic_descriptor_match = schema
        .map(|schema| {
            schema.kernarg_size == candidate.kernarg_size
                && schema.kernarg_segment_align == candidate.kernarg_segment_align
        })
        .unwrap_or(false);
    let verified_field_count = fields.iter().filter(|field| field.field_verified).count();
    let missing_field_count = fields
        .iter()
        .filter(|field| !field.model_argument_present)
        .count();
    let field_mismatch_count = fields
        .iter()
        .filter(|field| field.model_argument_present && !field.field_verified)
        .count();
    let extra_argument_count = extra_model_argument_names.len();
    let semantic_verified = schema.is_some()
        && semantic_descriptor_match
        && candidate.kernarg_serialized_fits
        && missing_field_count == 0
        && field_mismatch_count == 0
        && extra_argument_count == 0;
    let mut entry = RuntimeLaunchKernelArgumentAbiSemanticCandidateEntry {
        kernel_symbol: candidate.kernel_symbol.clone(),
        kernarg_size: candidate.kernarg_size,
        kernarg_segment_align: candidate.kernarg_segment_align,
        serialized_kernarg_bytes: candidate.kernarg_serialized_bytes,
        kernarg_serialized_fits: candidate.kernarg_serialized_fits,
        semantic_schema_available: schema.is_some(),
        semantic_schema_kernarg_size: schema.map(|schema| schema.kernarg_size),
        semantic_schema_kernarg_segment_align: schema.map(|schema| schema.kernarg_segment_align),
        semantic_descriptor_match,
        model_argument_count: serialized.argument_count,
        field_schema_count: fields.len(),
        verified_field_count,
        missing_field_count,
        field_mismatch_count,
        extra_argument_count,
        semantic_verified,
        primary_gap_reason: None,
        extra_model_argument_names,
        fields,
    };
    entry.primary_gap_reason =
        runtime_launch_kernel_argument_abi_semantic_primary_gap_reason_for(&entry);
    entry
}

fn runtime_launch_kernel_argument_abi_semantic_field_check_entry_from(
    field: &RuntimeLaunchKernelArgumentAbiSemanticFieldSchema,
    serialized: &RuntimeDispatchLaunchKernargSerializationEntry,
) -> RuntimeLaunchKernelArgumentAbiSemanticFieldCheckEntry {
    let actual = serialized.argument_for(field.model_argument_name);
    let actual_kind = actual.map(|argument| argument.kind);
    let actual_encoding = actual.map(|argument| argument.encoding.into());
    let actual_offset = actual.map(|argument| argument.offset);
    let actual_size_bytes = actual.map(|argument| argument.size_bytes);
    let kind_matches = actual_kind == Some(field.kind);
    let encoding_matches = actual_encoding == Some(field.encoding);
    let offset_matches = actual_offset == Some(field.offset);
    let size_matches = actual_size_bytes == Some(field.size_bytes);
    let field_verified =
        actual.is_some() && kind_matches && encoding_matches && offset_matches && size_matches;
    RuntimeLaunchKernelArgumentAbiSemanticFieldCheckEntry {
        field_index: field.field_index,
        kernel_argument_name: field.kernel_argument_name,
        model_argument_name: field.model_argument_name,
        expected_kind: field.kind,
        expected_encoding: field.encoding,
        expected_offset: field.offset,
        expected_size_bytes: field.size_bytes,
        model_argument_present: actual.is_some(),
        actual_argument_index: actual.map(|argument| argument.argument_index),
        actual_kind,
        actual_encoding,
        actual_offset,
        actual_size_bytes,
        kind_matches,
        encoding_matches,
        offset_matches,
        size_matches,
        field_verified,
    }
}

fn runtime_launch_kernel_argument_abi_semantic_primary_gap_reason_for(
    candidate: &RuntimeLaunchKernelArgumentAbiSemanticCandidateEntry,
) -> Option<RuntimeLaunchKernelArgumentAbiSemanticGapReason> {
    if candidate.semantic_verified {
        None
    } else if !candidate.semantic_schema_available {
        Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::MissingSemanticSchema)
    } else if !candidate.semantic_descriptor_match {
        Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::SemanticDescriptorMismatch)
    } else if candidate.missing_field_count > 0 {
        Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::MissingModelArgument)
    } else if candidate.field_mismatch_count > 0 {
        Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::FieldShapeMismatch)
    } else if candidate.extra_argument_count > 0 {
        Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::ExtraModelArgument)
    } else if !candidate.kernarg_serialized_fits {
        Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::KernargSizeShortfall)
    } else {
        Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::UnknownUnverifiedSemantic)
    }
}

