fn runtime_dispatch_launch_kernel_argument_abi_semantic_gap_entry_from(
    dispatch: &RuntimeDispatchLaunchKernelArgumentAbiSemanticEntry,
) -> Result<RuntimeDispatchLaunchKernelArgumentAbiSemanticGapEntry> {
    if dispatch.has_semantic_verified_candidate {
        return Err(anyhow!(
            "runtime launch kernel argument ABI semantic gap dispatch {} has a verified semantic candidate",
            dispatch.op_name
        ));
    }
    let candidate_gaps = dispatch.candidates.clone();
    let primary_missing_semantic_schema_candidate_count = candidate_gaps
        .iter()
        .filter(|candidate| {
            candidate.primary_gap_reason
                == Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::MissingSemanticSchema)
        })
        .count();
    let primary_semantic_descriptor_mismatch_candidate_count = candidate_gaps
        .iter()
        .filter(|candidate| {
            candidate.primary_gap_reason
                == Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::SemanticDescriptorMismatch)
        })
        .count();
    let primary_missing_model_argument_candidate_count = candidate_gaps
        .iter()
        .filter(|candidate| {
            candidate.primary_gap_reason
                == Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::MissingModelArgument)
        })
        .count();
    let primary_field_shape_mismatch_candidate_count = candidate_gaps
        .iter()
        .filter(|candidate| {
            candidate.primary_gap_reason
                == Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::FieldShapeMismatch)
        })
        .count();
    let primary_extra_model_argument_candidate_count = candidate_gaps
        .iter()
        .filter(|candidate| {
            candidate.primary_gap_reason
                == Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::ExtraModelArgument)
        })
        .count();
    let primary_kernarg_size_shortfall_candidate_count = candidate_gaps
        .iter()
        .filter(|candidate| {
            candidate.primary_gap_reason
                == Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::KernargSizeShortfall)
        })
        .count();
    let primary_unknown_unverified_semantic_candidate_count = candidate_gaps
        .iter()
        .filter(|candidate| {
            candidate.primary_gap_reason
                == Some(RuntimeLaunchKernelArgumentAbiSemanticGapReason::UnknownUnverifiedSemantic)
        })
        .count();
    Ok(RuntimeDispatchLaunchKernelArgumentAbiSemanticGapEntry {
        op_index: dispatch.op_index,
        op_name: dispatch.op_name.clone(),
        kind: dispatch.kind,
        stage_name: dispatch.stage_name.clone(),
        stage_kind: dispatch.stage_kind,
        window_index: dispatch.window_index,
        queue_packet_index: dispatch.queue_packet_index,
        argument_count: dispatch.argument_count,
        serialized_kernarg_bytes: dispatch.serialized_kernarg_bytes,
        kernel_candidate_count: dispatch.kernel_candidate_count,
        semantic_schema_candidate_count: dispatch.semantic_schema_candidate_count,
        missing_semantic_schema_candidate_count: dispatch.missing_semantic_schema_candidate_count,
        semantic_descriptor_match_candidate_count: dispatch
            .semantic_descriptor_match_candidate_count,
        semantic_verified_candidate_count: dispatch.semantic_verified_candidate_count,
        primary_missing_semantic_schema_candidate_count,
        primary_semantic_descriptor_mismatch_candidate_count,
        primary_missing_model_argument_candidate_count,
        primary_field_shape_mismatch_candidate_count,
        primary_extra_model_argument_candidate_count,
        primary_kernarg_size_shortfall_candidate_count,
        primary_unknown_unverified_semantic_candidate_count,
        field_schema_count: dispatch.field_schema_count,
        verified_field_count: dispatch.verified_field_count,
        missing_field_count: dispatch.missing_field_count,
        field_mismatch_count: dispatch.field_mismatch_count,
        extra_argument_count: dispatch.extra_argument_count,
        candidate_kernel_symbols: dispatch
            .candidates
            .iter()
            .map(|candidate| candidate.kernel_symbol.clone())
            .collect(),
        candidate_gaps,
    })
}

fn runtime_launch_kernel_argument_abi_semantic_projection_plan_from(
    templates: &ModelRuntimeLaunchAqlPacketTemplatePlan,
    serialization: &ModelRuntimeLaunchKernargSerializationPlan,
) -> Result<ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionPlan> {
    let semantic = runtime_launch_kernel_argument_abi_semantic_plan_from(templates, serialization)?;
    semantic.assert_consistent()?;

    let mut dispatches = Vec::with_capacity(semantic.dispatch_count);
    let mut kernel_candidate_count = 0usize;
    let mut semantic_schema_candidate_count = 0usize;
    let mut missing_semantic_schema_candidate_count = 0usize;
    let mut semantic_descriptor_match_candidate_count = 0usize;
    let mut projection_ready_candidate_count = 0usize;
    let mut dispatches_with_projection_ready_candidate_count = 0usize;
    let mut dispatches_without_projection_ready_candidate_count = 0usize;
    let mut field_schema_count = 0usize;
    let mut projected_field_count = 0usize;
    let mut missing_field_count = 0usize;
    let mut kind_mismatch_field_count = 0usize;
    let mut unsupported_encoding_field_count = 0usize;
    let mut scalar_narrowing_overflow_field_count = 0usize;
    let mut field_range_overflow_count = 0usize;
    let mut projected_kernarg_bytes = 0usize;

    for dispatch in &semantic.dispatches {
        let serialized = serialization.dispatch_for(&dispatch.op_name).ok_or_else(|| {
            anyhow!(
                "runtime launch kernel argument ABI semantic projection dispatch {} missing serialization entry",
                dispatch.op_name
            )
        })?;
        let entry = runtime_dispatch_launch_kernel_argument_abi_semantic_projection_entry_from(
            dispatch, serialized,
        )?;
        kernel_candidate_count = checked_add_usize(
            kernel_candidate_count,
            entry.kernel_candidate_count,
            "semantic projection candidate count",
        )?;
        semantic_schema_candidate_count = checked_add_usize(
            semantic_schema_candidate_count,
            entry.semantic_schema_candidate_count,
            "semantic projection schema candidate count",
        )?;
        missing_semantic_schema_candidate_count = checked_add_usize(
            missing_semantic_schema_candidate_count,
            entry.missing_semantic_schema_candidate_count,
            "semantic projection missing schema candidate count",
        )?;
        semantic_descriptor_match_candidate_count = checked_add_usize(
            semantic_descriptor_match_candidate_count,
            entry.semantic_descriptor_match_candidate_count,
            "semantic projection descriptor match candidate count",
        )?;
        projection_ready_candidate_count = checked_add_usize(
            projection_ready_candidate_count,
            entry.projection_ready_candidate_count,
            "semantic projection ready candidate count",
        )?;
        if entry.has_projection_ready_candidate {
            dispatches_with_projection_ready_candidate_count += 1;
        } else {
            dispatches_without_projection_ready_candidate_count += 1;
        }
        field_schema_count = checked_add_usize(
            field_schema_count,
            entry.field_schema_count,
            "semantic projection field schema count",
        )?;
        projected_field_count = checked_add_usize(
            projected_field_count,
            entry.projected_field_count,
            "semantic projection projected field count",
        )?;
        missing_field_count = checked_add_usize(
            missing_field_count,
            entry.missing_field_count,
            "semantic projection missing field count",
        )?;
        kind_mismatch_field_count = checked_add_usize(
            kind_mismatch_field_count,
            entry.kind_mismatch_field_count,
            "semantic projection kind mismatch count",
        )?;
        unsupported_encoding_field_count = checked_add_usize(
            unsupported_encoding_field_count,
            entry.unsupported_encoding_field_count,
            "semantic projection unsupported encoding count",
        )?;
        scalar_narrowing_overflow_field_count = checked_add_usize(
            scalar_narrowing_overflow_field_count,
            entry.scalar_narrowing_overflow_field_count,
            "semantic projection scalar narrowing overflow count",
        )?;
        field_range_overflow_count = checked_add_usize(
            field_range_overflow_count,
            entry.field_range_overflow_count,
            "semantic projection field range overflow count",
        )?;
        projected_kernarg_bytes = checked_add_usize(
            projected_kernarg_bytes,
            entry.projected_kernarg_bytes,
            "semantic projection projected kernarg bytes",
        )?;
        dispatches.push(entry);
    }

    let semantic_projection_ready =
        kernel_candidate_count > 0 && projection_ready_candidate_count == kernel_candidate_count;
    let plan = ModelRuntimeLaunchKernelArgumentAbiSemanticProjectionPlan {
        target: semantic.target,
        code_object_target: semantic.code_object_target.clone(),
        code_object_sha256: semantic.code_object_sha256.clone(),
        dispatch_count: semantic.dispatch_count,
        kernel_candidate_count,
        semantic_schema_candidate_count,
        missing_semantic_schema_candidate_count,
        semantic_descriptor_match_candidate_count,
        projection_ready_candidate_count,
        dispatches_with_projection_ready_candidate_count,
        dispatches_without_projection_ready_candidate_count,
        field_schema_count,
        projected_field_count,
        missing_field_count,
        kind_mismatch_field_count,
        unsupported_encoding_field_count,
        scalar_narrowing_overflow_field_count,
        field_range_overflow_count,
        projected_kernarg_bytes,
        semantic_projection_ready,
        semantic_schema_source: MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_SCHEMA_SOURCE,
        unresolved_runtime_requirements:
            runtime_launch_kernel_argument_abi_semantic_projection_requirements(
                &templates.unresolved_runtime_requirements,
                semantic_projection_ready,
            ),
        dispatches,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

