fn runtime_launch_aql_packet_relocation_plan_from(
    templates: &ModelRuntimeLaunchAqlPacketTemplatePlan,
) -> Result<ModelRuntimeLaunchAqlPacketRelocationPlan> {
    templates.assert_consistent()?;
    let mut dispatches = Vec::with_capacity(templates.dispatch_count);
    for template in templates
        .windows
        .iter()
        .flat_map(|window| window.dispatches.iter())
    {
        dispatches.push(runtime_dispatch_launch_aql_packet_relocation_entry_from(
            template,
        )?);
    }
    let total_field_ranges = dispatches
        .iter()
        .map(|dispatch| dispatch.field_range_count)
        .sum::<usize>();
    let total_relocation_sites = dispatches
        .iter()
        .map(|dispatch| dispatch.relocation_site_count)
        .sum::<usize>();
    let plan = ModelRuntimeLaunchAqlPacketRelocationPlan {
        target: templates.target,
        code_object_target: templates.code_object_target.clone(),
        code_object_sha256: templates.code_object_sha256.clone(),
        dispatch_count: templates.dispatch_count,
        queue_packet_count: templates.queue_packet_count,
        packet_bytes: templates.packet_bytes,
        field_ranges_per_packet: MODEL_RUNTIME_AQL_PACKET_FIELD_RANGE_SPECS.len(),
        resolved_fields_per_packet: MODEL_RUNTIME_AQL_PACKET_FIELD_RANGE_SPECS
            .iter()
            .filter(|spec| {
                spec.resolution == RuntimeLaunchAqlPacketFieldResolution::ResolvedTemplateValue
            })
            .count(),
        reserved_zero_fields_per_packet: MODEL_RUNTIME_AQL_PACKET_FIELD_RANGE_SPECS
            .iter()
            .filter(|spec| spec.resolution == RuntimeLaunchAqlPacketFieldResolution::ReservedZero)
            .count(),
        relocation_sites_per_packet: MODEL_RUNTIME_AQL_PACKET_FIELD_RANGE_SPECS
            .iter()
            .filter(|spec| {
                spec.resolution == RuntimeLaunchAqlPacketFieldResolution::UnresolvedRelocation
            })
            .count(),
        total_field_ranges,
        total_relocation_sites,
        unresolved_runtime_requirements: templates.unresolved_runtime_requirements.clone(),
        dispatches,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

fn runtime_dispatch_launch_aql_packet_relocation_entry_from(
    template: &RuntimeDispatchLaunchAqlPacketTemplateEntry,
) -> Result<RuntimeDispatchLaunchAqlPacketRelocationEntry> {
    let mut field_ranges = Vec::with_capacity(MODEL_RUNTIME_AQL_PACKET_FIELD_RANGE_SPECS.len());
    let mut relocation_sites = Vec::new();
    for spec in MODEL_RUNTIME_AQL_PACKET_FIELD_RANGE_SPECS {
        let staging_offset = template
            .packet_offset
            .checked_add(spec.packet_relative_offset)
            .ok_or_else(|| {
                anyhow!(
                    "runtime launch AQL packet relocation offset overflows for dispatch {} field {}",
                    template.op_name,
                    spec.field
                )
            })?;
        field_ranges.push(RuntimeLaunchAqlPacketFieldRangeEntry {
            field: spec.field,
            packet_relative_offset: spec.packet_relative_offset,
            staging_offset,
            size_bytes: spec.size_bytes,
            resolution: spec.resolution,
            source: spec.source,
            unresolved_runtime_requirement: spec.unresolved_runtime_requirement,
        });
        if spec.resolution == RuntimeLaunchAqlPacketFieldResolution::UnresolvedRelocation {
            relocation_sites.push(RuntimeLaunchAqlPacketRelocationSite {
                field: spec.field,
                packet_relative_offset: spec.packet_relative_offset,
                staging_offset,
                size_bytes: spec.size_bytes,
                relocation_kind: spec.relocation_kind.ok_or_else(|| {
                    anyhow!(
                        "runtime launch AQL packet relocation missing relocation kind for {}",
                        spec.field
                    )
                })?,
                unresolved_runtime_requirement: spec.unresolved_runtime_requirement.ok_or_else(
                    || {
                        anyhow!(
                            "runtime launch AQL packet relocation missing requirement for {}",
                            spec.field
                        )
                    },
                )?,
            });
        }
    }
    let resolved_field_count = field_ranges
        .iter()
        .filter(|field| {
            field.resolution == RuntimeLaunchAqlPacketFieldResolution::ResolvedTemplateValue
        })
        .count();
    let reserved_zero_field_count = field_ranges
        .iter()
        .filter(|field| field.resolution == RuntimeLaunchAqlPacketFieldResolution::ReservedZero)
        .count();
    Ok(RuntimeDispatchLaunchAqlPacketRelocationEntry {
        op_index: template.op_index,
        op_name: template.op_name.clone(),
        kind: template.kind,
        stage_name: template.stage_name.clone(),
        stage_kind: template.stage_kind,
        window_index: template.window_index,
        queue_packet_index: template.queue_packet_index,
        packet_offset: template.packet_offset,
        packet_bytes: template.packet_bytes,
        field_range_count: field_ranges.len(),
        resolved_field_count,
        reserved_zero_field_count,
        relocation_site_count: relocation_sites.len(),
        field_ranges,
        relocation_sites,
    })
}

const MODEL_RUNTIME_AQL_PACKET_TYPE_KERNEL_DISPATCH: u16 = 2;
const MODEL_RUNTIME_AQL_PACKET_FENCE_SCOPE_SYSTEM: u16 = 2;
const MODEL_RUNTIME_AQL_KERNEL_DISPATCH_HEADER: u16 = MODEL_RUNTIME_AQL_PACKET_TYPE_KERNEL_DISPATCH
    | (1 << 8)
    | (MODEL_RUNTIME_AQL_PACKET_FENCE_SCOPE_SYSTEM << 9)
    | (MODEL_RUNTIME_AQL_PACKET_FENCE_SCOPE_SYSTEM << 11);

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeLaunchAqlPacketCandidateByteTemplate {
    pub kernel_symbol: String,
    pub kernarg_size: u32,
    pub private_segment_size: u32,
    pub group_segment_size: u32,
    pub packet_bytes: usize,
    pub relocation_site_count: usize,
    pub byte_image: Vec<u8>,
    pub zeroed_relocation_sites: Vec<RuntimeLaunchAqlPacketRelocationSite>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeDispatchLaunchAqlPacketByteTemplateEntry {
    pub op_index: usize,
    pub op_name: String,
    pub kind: PrimitiveKind,
    pub stage_name: String,
    pub stage_kind: ModelStageKind,
    pub window_index: usize,
    pub queue_packet_index: usize,
    pub packet_offset: usize,
    pub packet_bytes: usize,
    pub candidate_byte_template_count: usize,
    pub candidate_byte_template_bytes: usize,
    pub relocation_sites_per_candidate: usize,
    pub candidate_byte_templates: Vec<RuntimeLaunchAqlPacketCandidateByteTemplate>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchAqlPacketByteTemplatePlan {
    pub target: &'static str,
    pub code_object_target: String,
    pub code_object_sha256: String,
    pub dispatch_count: usize,
    pub queue_packet_count: usize,
    pub packet_bytes: usize,
    pub candidate_byte_template_count: usize,
    pub candidate_byte_template_bytes: usize,
    pub relocation_sites_per_candidate: usize,
    pub unresolved_runtime_requirements: Vec<&'static str>,
    pub dispatches: Vec<RuntimeDispatchLaunchAqlPacketByteTemplateEntry>,
}

impl ModelRuntimeLaunchAqlPacketByteTemplatePlan {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchAqlPacketByteTemplateEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn aql_packet_materialization_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchAqlPacketMaterializationPlan> {
        runtime_launch_aql_packet_materialization_plan_from(self)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if self.queue_packet_count != self.dispatch_count {
            issues.push(format!(
                "queue packet count {} != dispatch count {}",
                self.queue_packet_count, self.dispatch_count
            ));
        }
        match self
            .dispatch_count
            .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
        {
            Some(expected) if expected == self.packet_bytes => {}
            Some(expected) => issues.push(format!(
                "dispatch packet bytes {expected} != plan packet bytes {}",
                self.packet_bytes
            )),
            None => issues.push("AQL packet byte-template packet byte count overflows".to_string()),
        }
        match self
            .candidate_byte_template_count
            .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
        {
            Some(expected) if expected == self.candidate_byte_template_bytes => {}
            Some(expected) => issues.push(format!(
                "candidate byte-template bytes {expected} != plan candidate bytes {}",
                self.candidate_byte_template_bytes
            )),
            None => {
                issues.push("AQL packet candidate byte-template byte count overflows".to_string())
            }
        }
        if self.relocation_sites_per_candidate != 3 {
            issues.push(format!(
                "relocation sites per candidate {} != 3",
                self.relocation_sites_per_candidate
            ));
        }
        if !self
            .unresolved_runtime_requirements
            .contains(&"aql_packet_materialization")
            || !self
                .unresolved_runtime_requirements
                .contains(&"loaded_code_object_base")
            || !self
                .unresolved_runtime_requirements
                .contains(&"kernarg_allocation")
            || !self
                .unresolved_runtime_requirements
                .contains(&"completion_signal_binding")
        {
            issues.push(format!(
                "AQL packet byte-template requirements missing live packet blockers: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut candidate_byte_template_count = 0usize;
        let mut candidate_byte_template_bytes = 0usize;
        let mut expected_queue_packet_index = 0usize;
        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in AQL packet byte-template plan",
                    dispatch.op_name
                ));
            }
            if dispatch.queue_packet_index != expected_queue_packet_index {
                issues.push(format!(
                    "dispatch {} queue packet index {} != expected {}",
                    dispatch.op_name, dispatch.queue_packet_index, expected_queue_packet_index
                ));
            }
            match dispatch
                .queue_packet_index
                .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
            {
                Some(expected) if expected == dispatch.packet_offset => {}
                Some(expected) => issues.push(format!(
                    "dispatch {} packet offset {} != expected {}",
                    dispatch.op_name, dispatch.packet_offset, expected
                )),
                None => issues.push(format!(
                    "dispatch {} packet offset computation overflows",
                    dispatch.op_name
                )),
            }
            if dispatch.packet_bytes != MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES {
                issues.push(format!(
                    "dispatch {} packet bytes {} != {}",
                    dispatch.op_name,
                    dispatch.packet_bytes,
                    MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES
                ));
            }
            if dispatch.candidate_byte_templates.len() != dispatch.candidate_byte_template_count {
                issues.push(format!(
                    "dispatch {} candidate byte-template entries {} != count {}",
                    dispatch.op_name,
                    dispatch.candidate_byte_templates.len(),
                    dispatch.candidate_byte_template_count
                ));
            }
            match dispatch
                .candidate_byte_template_count
                .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
            {
                Some(expected) if expected == dispatch.candidate_byte_template_bytes => {}
                Some(expected) => issues.push(format!(
                    "dispatch {} candidate byte-template bytes {} != expected {}",
                    dispatch.op_name, dispatch.candidate_byte_template_bytes, expected
                )),
                None => issues.push(format!(
                    "dispatch {} candidate byte-template bytes overflow",
                    dispatch.op_name
                )),
            }
            if dispatch.relocation_sites_per_candidate != self.relocation_sites_per_candidate {
                issues.push(format!(
                    "dispatch {} relocation sites per candidate {} != plan {}",
                    dispatch.op_name,
                    dispatch.relocation_sites_per_candidate,
                    self.relocation_sites_per_candidate
                ));
            }

            for candidate in &dispatch.candidate_byte_templates {
                candidate_byte_template_count += 1;
                candidate_byte_template_bytes += candidate.byte_image.len();
                if candidate.packet_bytes != MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES {
                    issues.push(format!(
                        "dispatch {} candidate {} packet bytes {} != {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.packet_bytes,
                        MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES
                    ));
                }
                if candidate.byte_image.len() != MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES {
                    issues.push(format!(
                        "dispatch {} candidate {} byte image len {} != {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.byte_image.len(),
                        MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES
                    ));
                    continue;
                }
                if candidate.relocation_site_count != self.relocation_sites_per_candidate {
                    issues.push(format!(
                        "dispatch {} candidate {} relocation sites {} != {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.relocation_site_count,
                        self.relocation_sites_per_candidate
                    ));
                }
                if candidate.zeroed_relocation_sites.len() != candidate.relocation_site_count {
                    issues.push(format!(
                        "dispatch {} candidate {} zeroed relocation entries {} != count {}",
                        dispatch.op_name,
                        candidate.kernel_symbol,
                        candidate.zeroed_relocation_sites.len(),
                        candidate.relocation_site_count
                    ));
                }
                if read_le_u16(&candidate.byte_image, 0) != MODEL_RUNTIME_AQL_KERNEL_DISPATCH_HEADER
                {
                    issues.push(format!(
                        "dispatch {} candidate {} header mismatch",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if read_le_u16(&candidate.byte_image, 2) == 0 {
                    issues.push(format!(
                        "dispatch {} candidate {} setup is zero",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if read_le_u32(&candidate.byte_image, 24) != candidate.private_segment_size {
                    issues.push(format!(
                        "dispatch {} candidate {} private segment bytes mismatch",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                if read_le_u32(&candidate.byte_image, 28) != candidate.group_segment_size {
                    issues.push(format!(
                        "dispatch {} candidate {} group segment bytes mismatch",
                        dispatch.op_name, candidate.kernel_symbol
                    ));
                }
                for site in &candidate.zeroed_relocation_sites {
                    let Some(end) = site.packet_relative_offset.checked_add(site.size_bytes) else {
                        issues.push(format!(
                            "dispatch {} candidate {} relocation {} range overflows",
                            dispatch.op_name, candidate.kernel_symbol, site.field
                        ));
                        continue;
                    };
                    if end > candidate.byte_image.len() {
                        issues.push(format!(
                            "dispatch {} candidate {} relocation {} end {} exceeds byte image",
                            dispatch.op_name, candidate.kernel_symbol, site.field, end
                        ));
                        continue;
                    }
                    if candidate.byte_image[site.packet_relative_offset..end]
                        .iter()
                        .any(|byte| *byte != 0)
                    {
                        issues.push(format!(
                            "dispatch {} candidate {} relocation {} is not zero-filled",
                            dispatch.op_name, candidate.kernel_symbol, site.field
                        ));
                    }
                }
                for field in ["reserved0", "reserved2"] {
                    let spec = MODEL_RUNTIME_AQL_PACKET_FIELD_RANGE_SPECS
                        .iter()
                        .find(|spec| spec.field == field)
                        .expect("reserved field spec");
                    let end = spec.packet_relative_offset + spec.size_bytes;
                    if candidate.byte_image[spec.packet_relative_offset..end]
                        .iter()
                        .any(|byte| *byte != 0)
                    {
                        issues.push(format!(
                            "dispatch {} candidate {} reserved field {} is not zero-filled",
                            dispatch.op_name, candidate.kernel_symbol, field
                        ));
                    }
                }
            }
            expected_queue_packet_index += 1;
        }
        if candidate_byte_template_count != self.candidate_byte_template_count {
            issues.push(format!(
                "candidate byte-template count {candidate_byte_template_count} != plan {}",
                self.candidate_byte_template_count
            ));
        }
        if candidate_byte_template_bytes != self.candidate_byte_template_bytes {
            issues.push(format!(
                "candidate byte-template bytes {candidate_byte_template_bytes} != plan {}",
                self.candidate_byte_template_bytes
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch AQL packet byte-template plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

fn runtime_launch_aql_packet_byte_template_plan_from(
    templates: &ModelRuntimeLaunchAqlPacketTemplatePlan,
) -> Result<ModelRuntimeLaunchAqlPacketByteTemplatePlan> {
    templates.assert_consistent()?;
    let relocations = templates.aql_packet_relocation_plan()?;
    relocations.assert_consistent()?;
    let relocation_by_name = relocations
        .dispatches
        .iter()
        .map(|dispatch| (dispatch.op_name.as_str(), dispatch))
        .collect::<BTreeMap<_, _>>();
    let mut dispatches = Vec::with_capacity(templates.dispatch_count);
    let mut candidate_byte_template_count = 0usize;
    let mut candidate_byte_template_bytes = 0usize;
    for template in templates
        .windows
        .iter()
        .flat_map(|window| window.dispatches.iter())
    {
        let relocation = relocation_by_name
            .get(template.op_name.as_str())
            .copied()
            .ok_or_else(|| {
                anyhow!(
                    "runtime launch AQL packet byte-template missing relocation plan for {}",
                    template.op_name
                )
            })?;
        let entry =
            runtime_dispatch_launch_aql_packet_byte_template_entry_from(template, relocation)?;
        candidate_byte_template_count = checked_add_usize(
            candidate_byte_template_count,
            entry.candidate_byte_template_count,
            "AQL packet candidate byte-template count",
        )?;
        candidate_byte_template_bytes = checked_add_usize(
            candidate_byte_template_bytes,
            entry.candidate_byte_template_bytes,
            "AQL packet candidate byte-template bytes",
        )?;
        dispatches.push(entry);
    }
    let plan = ModelRuntimeLaunchAqlPacketByteTemplatePlan {
        target: templates.target,
        code_object_target: templates.code_object_target.clone(),
        code_object_sha256: templates.code_object_sha256.clone(),
        dispatch_count: templates.dispatch_count,
        queue_packet_count: templates.queue_packet_count,
        packet_bytes: templates.packet_bytes,
        candidate_byte_template_count,
        candidate_byte_template_bytes,
        relocation_sites_per_candidate: relocations.relocation_sites_per_packet,
        unresolved_runtime_requirements: templates.unresolved_runtime_requirements.clone(),
        dispatches,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

fn runtime_dispatch_launch_aql_packet_byte_template_entry_from(
    template: &RuntimeDispatchLaunchAqlPacketTemplateEntry,
    relocation: &RuntimeDispatchLaunchAqlPacketRelocationEntry,
) -> Result<RuntimeDispatchLaunchAqlPacketByteTemplateEntry> {
    if template.op_name != relocation.op_name
        || template.queue_packet_index != relocation.queue_packet_index
    {
        return Err(anyhow!(
            "runtime launch AQL packet byte-template dispatch {} does not match relocation entry {}",
            template.op_name,
            relocation.op_name
        ));
    }
    let mut candidate_byte_templates = Vec::with_capacity(template.candidate_templates.len());
    for candidate in &template.candidate_templates {
        candidate_byte_templates.push(runtime_launch_aql_packet_candidate_byte_template_from(
            template, relocation, candidate,
        )?);
    }
    let candidate_byte_template_count = candidate_byte_templates.len();
    let candidate_byte_template_bytes = candidate_byte_template_count
        .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
        .ok_or_else(|| {
            anyhow!(
                "runtime launch AQL packet byte-template bytes overflow for {}",
                template.op_name
            )
        })?;
    Ok(RuntimeDispatchLaunchAqlPacketByteTemplateEntry {
        op_index: template.op_index,
        op_name: template.op_name.clone(),
        kind: template.kind,
        stage_name: template.stage_name.clone(),
        stage_kind: template.stage_kind,
        window_index: template.window_index,
        queue_packet_index: template.queue_packet_index,
        packet_offset: template.packet_offset,
        packet_bytes: template.packet_bytes,
        candidate_byte_template_count,
        candidate_byte_template_bytes,
        relocation_sites_per_candidate: relocation.relocation_site_count,
        candidate_byte_templates,
    })
}

fn runtime_launch_aql_packet_candidate_byte_template_from(
    template: &RuntimeDispatchLaunchAqlPacketTemplateEntry,
    relocation: &RuntimeDispatchLaunchAqlPacketRelocationEntry,
    candidate: &RuntimeLaunchAqlPacketCandidateTemplate,
) -> Result<RuntimeLaunchAqlPacketCandidateByteTemplate> {
    let mut byte_image = vec![0u8; MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES];
    write_le_u16(&mut byte_image, 0, MODEL_RUNTIME_AQL_KERNEL_DISPATCH_HEADER)?;
    write_le_u16(&mut byte_image, 2, template.dimensions)?;
    write_le_u16(&mut byte_image, 4, template.workgroup_size_x)?;
    write_le_u16(&mut byte_image, 6, template.workgroup_size_y)?;
    write_le_u16(&mut byte_image, 8, template.workgroup_size_z)?;
    write_le_u32(&mut byte_image, 12, template.grid_size_x)?;
    write_le_u32(&mut byte_image, 16, template.grid_size_y)?;
    write_le_u32(&mut byte_image, 20, template.grid_size_z)?;
    write_le_u32(&mut byte_image, 24, candidate.private_segment_size)?;
    write_le_u32(&mut byte_image, 28, candidate.group_segment_size)?;
    Ok(RuntimeLaunchAqlPacketCandidateByteTemplate {
        kernel_symbol: candidate.kernel_symbol.clone(),
        kernarg_size: candidate.kernarg_size,
        private_segment_size: candidate.private_segment_size,
        group_segment_size: candidate.group_segment_size,
        packet_bytes: byte_image.len(),
        relocation_site_count: relocation.relocation_site_count,
        byte_image,
        zeroed_relocation_sites: relocation.relocation_sites.clone(),
    })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RuntimeLaunchAqlPacketMaterializationState {
    SelectedCandidateByteTemplate,
    AmbiguousCandidateByteTemplates,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeDispatchLaunchAqlPacketMaterializationEntry {
    pub op_index: usize,
    pub op_name: String,
    pub kind: PrimitiveKind,
    pub stage_name: String,
    pub stage_kind: ModelStageKind,
    pub window_index: usize,
    pub queue_packet_index: usize,
    pub packet_offset: usize,
    pub packet_bytes: usize,
    pub state: RuntimeLaunchAqlPacketMaterializationState,
    pub candidate_byte_template_count: usize,
    pub selected_candidate_kernel_symbol: Option<String>,
    pub selected_candidate_byte_image: Option<Vec<u8>>,
    pub selected_candidate_packet_bytes: usize,
    pub live_relocation_patch_site_count: usize,
    pub live_relocation_patch_bytes: usize,
    pub pending_relocation_sites: Vec<RuntimeLaunchAqlPacketRelocationSite>,
    pub dispatchable_packet_ready: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchAqlPacketMaterializationPlan {
    pub target: &'static str,
    pub code_object_target: String,
    pub code_object_sha256: String,
    pub dispatch_count: usize,
    pub queue_packet_count: usize,
    pub packet_bytes: usize,
    pub candidate_byte_template_count: usize,
    pub selected_dispatch_count: usize,
    pub ambiguous_dispatch_count: usize,
    pub selected_packet_byte_template_count: usize,
    pub selected_packet_byte_template_bytes: usize,
    pub live_relocation_patch_site_count: usize,
    pub live_relocation_patch_bytes: usize,
    pub dispatchable_packet_count: usize,
    pub dispatchable_packet_bytes: usize,
    pub packet_materialization_ready: bool,
    pub unresolved_runtime_requirements: Vec<&'static str>,
    pub dispatches: Vec<RuntimeDispatchLaunchAqlPacketMaterializationEntry>,
}

impl ModelRuntimeLaunchAqlPacketMaterializationPlan {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchAqlPacketMaterializationEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn aql_live_relocation_binding_plan(
        &self,
    ) -> Result<ModelRuntimeLaunchAqlLiveRelocationBindingPlan> {
        runtime_launch_aql_live_relocation_binding_plan_from(self)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if self.queue_packet_count != self.dispatch_count {
            issues.push(format!(
                "queue packet count {} != dispatch count {}",
                self.queue_packet_count, self.dispatch_count
            ));
        }
        match self
            .dispatch_count
            .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
        {
            Some(expected) if expected == self.packet_bytes => {}
            Some(expected) => issues.push(format!(
                "dispatch packet bytes {expected} != plan packet bytes {}",
                self.packet_bytes
            )),
            None => {
                issues.push("AQL packet materialization packet byte count overflows".to_string())
            }
        }
        if self.selected_dispatch_count + self.ambiguous_dispatch_count != self.dispatch_count {
            issues.push(format!(
                "selected+ambiguous dispatch count {} != dispatch count {}",
                self.selected_dispatch_count + self.ambiguous_dispatch_count,
                self.dispatch_count
            ));
        }
        if self.selected_packet_byte_template_count != self.selected_dispatch_count {
            issues.push(format!(
                "selected byte-template count {} != selected dispatch count {}",
                self.selected_packet_byte_template_count, self.selected_dispatch_count
            ));
        }
        match self
            .selected_packet_byte_template_count
            .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
        {
            Some(expected) if expected == self.selected_packet_byte_template_bytes => {}
            Some(expected) => issues.push(format!(
                "selected byte-template bytes {} != expected {}",
                self.selected_packet_byte_template_bytes, expected
            )),
            None => issues.push("AQL packet selected byte-template bytes overflow".to_string()),
        }
        let expected_relocation_sites = self
            .dispatch_count
            .checked_mul(3)
            .ok_or_else(|| anyhow!("AQL packet materialization relocation count overflows"))?;
        if self.live_relocation_patch_site_count != expected_relocation_sites {
            issues.push(format!(
                "live relocation patch sites {} != expected {}",
                self.live_relocation_patch_site_count, expected_relocation_sites
            ));
        }
        let expected_relocation_bytes = self
            .live_relocation_patch_site_count
            .checked_mul(8)
            .ok_or_else(|| anyhow!("AQL packet materialization relocation bytes overflow"))?;
        if self.live_relocation_patch_bytes != expected_relocation_bytes {
            issues.push(format!(
                "live relocation patch bytes {} != expected {}",
                self.live_relocation_patch_bytes, expected_relocation_bytes
            ));
        }
        if self.dispatchable_packet_count != 0 || self.dispatchable_packet_bytes != 0 {
            issues.push(format!(
                "dispatchable packets are unexpectedly present: count={} bytes={}",
                self.dispatchable_packet_count, self.dispatchable_packet_bytes
            ));
        }
        if self.packet_materialization_ready {
            issues.push("packet materialization is unexpectedly ready".to_string());
        }
        if !self
            .unresolved_runtime_requirements
            .contains(&"aql_packet_materialization")
            || !self
                .unresolved_runtime_requirements
                .contains(&"loaded_code_object_base")
            || !self
                .unresolved_runtime_requirements
                .contains(&"kernarg_allocation")
            || !self
                .unresolved_runtime_requirements
                .contains(&"completion_signal_binding")
        {
            issues.push(format!(
                "AQL packet materialization requirements missing live packet blockers: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut candidate_byte_template_count = 0usize;
        let mut selected_dispatch_count = 0usize;
        let mut ambiguous_dispatch_count = 0usize;
        let mut selected_packet_byte_template_count = 0usize;
        let mut selected_packet_byte_template_bytes = 0usize;
        let mut live_relocation_patch_site_count = 0usize;
        let mut live_relocation_patch_bytes = 0usize;
        let mut expected_queue_packet_index = 0usize;
        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in AQL packet materialization plan",
                    dispatch.op_name
                ));
            }
            if dispatch.queue_packet_index != expected_queue_packet_index {
                issues.push(format!(
                    "dispatch {} queue packet index {} != expected {}",
                    dispatch.op_name, dispatch.queue_packet_index, expected_queue_packet_index
                ));
            }
            match dispatch
                .queue_packet_index
                .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
            {
                Some(expected) if expected == dispatch.packet_offset => {}
                Some(expected) => issues.push(format!(
                    "dispatch {} packet offset {} != expected {}",
                    dispatch.op_name, dispatch.packet_offset, expected
                )),
                None => issues.push(format!(
                    "dispatch {} packet offset computation overflows",
                    dispatch.op_name
                )),
            }
            if dispatch.packet_bytes != MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES {
                issues.push(format!(
                    "dispatch {} packet bytes {} != {}",
                    dispatch.op_name,
                    dispatch.packet_bytes,
                    MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES
                ));
            }
            if dispatch.candidate_byte_template_count == 0 {
                issues.push(format!(
                    "dispatch {} has no candidate byte templates",
                    dispatch.op_name
                ));
            }
            candidate_byte_template_count += dispatch.candidate_byte_template_count;
            match dispatch.state {
                RuntimeLaunchAqlPacketMaterializationState::SelectedCandidateByteTemplate => {
                    selected_dispatch_count += 1;
                    selected_packet_byte_template_count += 1;
                    if dispatch.candidate_byte_template_count != 1 {
                        issues.push(format!(
                            "dispatch {} selected state has {} candidates",
                            dispatch.op_name, dispatch.candidate_byte_template_count
                        ));
                    }
                    if dispatch.selected_candidate_kernel_symbol.is_none() {
                        issues.push(format!(
                            "dispatch {} selected state has no selected symbol",
                            dispatch.op_name
                        ));
                    }
                    if let Some(byte_image) = &dispatch.selected_candidate_byte_image {
                        if byte_image.len() != MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES {
                            issues.push(format!(
                                "dispatch {} selected byte image len {} != {}",
                                dispatch.op_name,
                                byte_image.len(),
                                MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES
                            ));
                        }
                        selected_packet_byte_template_bytes += byte_image.len();
                        if dispatch.selected_candidate_packet_bytes != byte_image.len() {
                            issues.push(format!(
                                "dispatch {} selected packet bytes {} != byte image len {}",
                                dispatch.op_name,
                                dispatch.selected_candidate_packet_bytes,
                                byte_image.len()
                            ));
                        }
                        for site in &dispatch.pending_relocation_sites {
                            let Some(end) =
                                site.packet_relative_offset.checked_add(site.size_bytes)
                            else {
                                issues.push(format!(
                                    "dispatch {} relocation {} range overflows",
                                    dispatch.op_name, site.field
                                ));
                                continue;
                            };
                            if end > byte_image.len() {
                                issues.push(format!(
                                    "dispatch {} relocation {} end {} exceeds selected byte image",
                                    dispatch.op_name, site.field, end
                                ));
                                continue;
                            }
                            if byte_image[site.packet_relative_offset..end]
                                .iter()
                                .any(|byte| *byte != 0)
                            {
                                issues.push(format!(
                                    "dispatch {} relocation {} is already patched",
                                    dispatch.op_name, site.field
                                ));
                            }
                        }
                    } else {
                        issues.push(format!(
                            "dispatch {} selected state has no byte image",
                            dispatch.op_name
                        ));
                    }
                }
                RuntimeLaunchAqlPacketMaterializationState::AmbiguousCandidateByteTemplates => {
                    ambiguous_dispatch_count += 1;
                    if dispatch.candidate_byte_template_count <= 1 {
                        issues.push(format!(
                            "dispatch {} ambiguous state has {} candidates",
                            dispatch.op_name, dispatch.candidate_byte_template_count
                        ));
                    }
                    if dispatch.selected_candidate_kernel_symbol.is_some()
                        || dispatch.selected_candidate_byte_image.is_some()
                        || dispatch.selected_candidate_packet_bytes != 0
                    {
                        issues.push(format!(
                            "dispatch {} ambiguous state unexpectedly carries selected bytes",
                            dispatch.op_name
                        ));
                    }
                }
            }
            if dispatch.live_relocation_patch_site_count != dispatch.pending_relocation_sites.len()
            {
                issues.push(format!(
                    "dispatch {} relocation patch site count {} != entries {}",
                    dispatch.op_name,
                    dispatch.live_relocation_patch_site_count,
                    dispatch.pending_relocation_sites.len()
                ));
            }
            let dispatch_relocation_patch_bytes = dispatch
                .pending_relocation_sites
                .iter()
                .map(|site| site.size_bytes)
                .sum::<usize>();
            if dispatch.live_relocation_patch_bytes != dispatch_relocation_patch_bytes {
                issues.push(format!(
                    "dispatch {} relocation patch bytes {} != expected {}",
                    dispatch.op_name,
                    dispatch.live_relocation_patch_bytes,
                    dispatch_relocation_patch_bytes
                ));
            }
            if dispatch.dispatchable_packet_ready {
                issues.push(format!(
                    "dispatch {} is unexpectedly dispatchable",
                    dispatch.op_name
                ));
            }
            for site in &dispatch.pending_relocation_sites {
                if !self
                    .unresolved_runtime_requirements
                    .contains(&site.unresolved_runtime_requirement)
                {
                    issues.push(format!(
                        "dispatch {} relocation {} requirement {} not present in plan requirements",
                        dispatch.op_name, site.field, site.unresolved_runtime_requirement
                    ));
                }
            }
            live_relocation_patch_site_count += dispatch.live_relocation_patch_site_count;
            live_relocation_patch_bytes += dispatch.live_relocation_patch_bytes;
            expected_queue_packet_index += 1;
        }
        if candidate_byte_template_count != self.candidate_byte_template_count {
            issues.push(format!(
                "candidate byte-template count {candidate_byte_template_count} != plan {}",
                self.candidate_byte_template_count
            ));
        }
        if selected_dispatch_count != self.selected_dispatch_count {
            issues.push(format!(
                "selected dispatch count {selected_dispatch_count} != plan {}",
                self.selected_dispatch_count
            ));
        }
        if ambiguous_dispatch_count != self.ambiguous_dispatch_count {
            issues.push(format!(
                "ambiguous dispatch count {ambiguous_dispatch_count} != plan {}",
                self.ambiguous_dispatch_count
            ));
        }
        if selected_packet_byte_template_count != self.selected_packet_byte_template_count {
            issues.push(format!(
                "selected byte-template count {selected_packet_byte_template_count} != plan {}",
                self.selected_packet_byte_template_count
            ));
        }
        if selected_packet_byte_template_bytes != self.selected_packet_byte_template_bytes {
            issues.push(format!(
                "selected byte-template bytes {selected_packet_byte_template_bytes} != plan {}",
                self.selected_packet_byte_template_bytes
            ));
        }
        if live_relocation_patch_site_count != self.live_relocation_patch_site_count {
            issues.push(format!(
                "live relocation patch sites {live_relocation_patch_site_count} != plan {}",
                self.live_relocation_patch_site_count
            ));
        }
        if live_relocation_patch_bytes != self.live_relocation_patch_bytes {
            issues.push(format!(
                "live relocation patch bytes {live_relocation_patch_bytes} != plan {}",
                self.live_relocation_patch_bytes
            ));
        }
        if expected_queue_packet_index != self.queue_packet_count {
            issues.push(format!(
                "assigned queue packet count {expected_queue_packet_index} != plan queue packet count {}",
                self.queue_packet_count
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch AQL packet materialization plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RuntimeLaunchAqlLiveRelocationBindingKind {
    LoadedCodeObjectBase,
    KernargAllocation,
    CompletionSignal,
}

impl RuntimeLaunchAqlLiveRelocationBindingKind {
    fn for_requirement(requirement: &str) -> Option<Self> {
        match requirement {
            "loaded_code_object_base" => Some(Self::LoadedCodeObjectBase),
            "kernarg_allocation" => Some(Self::KernargAllocation),
            "completion_signal_binding" => Some(Self::CompletionSignal),
            _ => None,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeLaunchAqlLiveRelocationBindingRequest {
    pub field: &'static str,
    pub binding_kind: RuntimeLaunchAqlLiveRelocationBindingKind,
    pub packet_relative_offset: usize,
    pub staging_offset: usize,
    pub size_bytes: usize,
    pub relocation_kind: &'static str,
    pub unresolved_runtime_requirement: &'static str,
    pub runtime_value_bound: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeDispatchLaunchAqlLiveRelocationBindingEntry {
    pub op_index: usize,
    pub op_name: String,
    pub kind: PrimitiveKind,
    pub stage_name: String,
    pub stage_kind: ModelStageKind,
    pub window_index: usize,
    pub queue_packet_index: usize,
    pub packet_offset: usize,
    pub packet_bytes: usize,
    pub materialization_state: RuntimeLaunchAqlPacketMaterializationState,
    pub candidate_byte_template_count: usize,
    pub binding_request_count: usize,
    pub binding_request_bytes: usize,
    pub code_object_base_request_count: usize,
    pub kernarg_allocation_request_count: usize,
    pub completion_signal_request_count: usize,
    pub bound_relocation_count: usize,
    pub unbound_relocation_count: usize,
    pub all_relocations_bound: bool,
    pub binding_requests: Vec<RuntimeLaunchAqlLiveRelocationBindingRequest>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchAqlLiveRelocationBindingPlan {
    pub target: &'static str,
    pub code_object_target: String,
    pub code_object_sha256: String,
    pub dispatch_count: usize,
    pub queue_packet_count: usize,
    pub packet_bytes: usize,
    pub binding_request_count: usize,
    pub binding_request_bytes: usize,
    pub code_object_base_request_count: usize,
    pub kernarg_allocation_request_count: usize,
    pub completion_signal_request_count: usize,
    pub bound_relocation_count: usize,
    pub unbound_relocation_count: usize,
    pub dispatches_fully_bound_count: usize,
    pub all_relocations_bound: bool,
    pub binding_request_plan_ready: bool,
    pub unresolved_runtime_requirements: Vec<&'static str>,
    pub dispatches: Vec<RuntimeDispatchLaunchAqlLiveRelocationBindingEntry>,
}

impl ModelRuntimeLaunchAqlLiveRelocationBindingPlan {
    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchAqlLiveRelocationBindingEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.dispatches.len() != self.dispatch_count {
            issues.push(format!(
                "dispatch entries {} != dispatch count {}",
                self.dispatches.len(),
                self.dispatch_count
            ));
        }
        if self.queue_packet_count != self.dispatch_count {
            issues.push(format!(
                "queue packet count {} != dispatch count {}",
                self.queue_packet_count, self.dispatch_count
            ));
        }
        match self
            .dispatch_count
            .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
        {
            Some(expected) if expected == self.packet_bytes => {}
            Some(expected) => issues.push(format!(
                "dispatch packet bytes {expected} != plan packet bytes {}",
                self.packet_bytes
            )),
            None => issues.push("AQL live relocation packet byte count overflows".to_string()),
        }
        if self.binding_request_count
            != self.code_object_base_request_count
                + self.kernarg_allocation_request_count
                + self.completion_signal_request_count
        {
            issues.push(format!(
                "live relocation request count {} != code_object+kernarg+signal {}",
                self.binding_request_count,
                self.code_object_base_request_count
                    + self.kernarg_allocation_request_count
                    + self.completion_signal_request_count
            ));
        }
        if self.bound_relocation_count + self.unbound_relocation_count != self.binding_request_count
        {
            issues.push(format!(
                "bound+unbound live relocation count {} != request count {}",
                self.bound_relocation_count + self.unbound_relocation_count,
                self.binding_request_count
            ));
        }
        if self.bound_relocation_count != 0 {
            issues.push(format!(
                "bound relocation count {} != 0",
                self.bound_relocation_count
            ));
        }
        if self.dispatches_fully_bound_count != 0 {
            issues.push(format!(
                "dispatches fully bound count {} != 0",
                self.dispatches_fully_bound_count
            ));
        }
        if self.all_relocations_bound {
            issues.push("live relocations are unexpectedly all bound".to_string());
        }
        if !self.binding_request_plan_ready {
            issues.push("live relocation binding request plan is not ready".to_string());
        }
        if !self
            .unresolved_runtime_requirements
            .contains(&"loaded_code_object_base")
            || !self
                .unresolved_runtime_requirements
                .contains(&"kernarg_allocation")
            || !self
                .unresolved_runtime_requirements
                .contains(&"completion_signal_binding")
            || !self
                .unresolved_runtime_requirements
                .contains(&"aql_packet_materialization")
        {
            issues.push(format!(
                "AQL live relocation binding requirements missing live packet blockers: {:?}",
                self.unresolved_runtime_requirements
            ));
        }

        let mut seen_dispatches = BTreeSet::new();
        let mut binding_request_count = 0usize;
        let mut binding_request_bytes = 0usize;
        let mut code_object_base_request_count = 0usize;
        let mut kernarg_allocation_request_count = 0usize;
        let mut completion_signal_request_count = 0usize;
        let mut bound_relocation_count = 0usize;
        let mut unbound_relocation_count = 0usize;
        let mut dispatches_fully_bound_count = 0usize;
        let mut expected_queue_packet_index = 0usize;
        for dispatch in &self.dispatches {
            if !seen_dispatches.insert(dispatch.op_name.as_str()) {
                issues.push(format!(
                    "dispatch {} appears more than once in AQL live relocation binding plan",
                    dispatch.op_name
                ));
            }
            if dispatch.queue_packet_index != expected_queue_packet_index {
                issues.push(format!(
                    "dispatch {} queue packet index {} != expected {}",
                    dispatch.op_name, dispatch.queue_packet_index, expected_queue_packet_index
                ));
            }
            match dispatch
                .queue_packet_index
                .checked_mul(MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES)
            {
                Some(expected) if expected == dispatch.packet_offset => {}
                Some(expected) => issues.push(format!(
                    "dispatch {} packet offset {} != expected {}",
                    dispatch.op_name, dispatch.packet_offset, expected
                )),
                None => issues.push(format!(
                    "dispatch {} packet offset computation overflows",
                    dispatch.op_name
                )),
            }
            if dispatch.packet_bytes != MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES {
                issues.push(format!(
                    "dispatch {} packet bytes {} != {}",
                    dispatch.op_name,
                    dispatch.packet_bytes,
                    MODEL_RUNTIME_AQL_PACKET_TEMPLATE_PACKET_BYTES
                ));
            }
            if dispatch.binding_requests.len() != dispatch.binding_request_count {
                issues.push(format!(
                    "dispatch {} binding request entries {} != count {}",
                    dispatch.op_name,
                    dispatch.binding_requests.len(),
                    dispatch.binding_request_count
                ));
            }
            if dispatch.binding_request_count
                != dispatch.code_object_base_request_count
                    + dispatch.kernarg_allocation_request_count
                    + dispatch.completion_signal_request_count
            {
                issues.push(format!(
                    "dispatch {} live relocation request count {} != code_object+kernarg+signal {}",
                    dispatch.op_name,
                    dispatch.binding_request_count,
                    dispatch.code_object_base_request_count
                        + dispatch.kernarg_allocation_request_count
                        + dispatch.completion_signal_request_count
                ));
            }
            if dispatch.bound_relocation_count + dispatch.unbound_relocation_count
                != dispatch.binding_request_count
            {
                issues.push(format!(
                    "dispatch {} bound+unbound live relocations {} != request count {}",
                    dispatch.op_name,
                    dispatch.bound_relocation_count + dispatch.unbound_relocation_count,
                    dispatch.binding_request_count
                ));
            }
            if dispatch.bound_relocation_count != 0 {
                issues.push(format!(
                    "dispatch {} bound relocation count {} != 0",
                    dispatch.op_name, dispatch.bound_relocation_count
                ));
            }
            if dispatch.all_relocations_bound {
                issues.push(format!(
                    "dispatch {} live relocations are unexpectedly all bound",
                    dispatch.op_name
                ));
            }

            let mut dispatch_request_bytes = 0usize;
            let mut dispatch_code_object_requests = 0usize;
            let mut dispatch_kernarg_requests = 0usize;
            let mut dispatch_signal_requests = 0usize;
            let mut dispatch_bound_requests = 0usize;
            let mut dispatch_unbound_requests = 0usize;
            for request in &dispatch.binding_requests {
                if request.size_bytes != 8 {
                    issues.push(format!(
                        "dispatch {} live relocation {} size {} != 8",
                        dispatch.op_name, request.field, request.size_bytes
                    ));
                }
                if request.relocation_kind.is_empty() {
                    issues.push(format!(
                        "dispatch {} live relocation {} has empty relocation kind",
                        dispatch.op_name, request.field
                    ));
                }
                match RuntimeLaunchAqlLiveRelocationBindingKind::for_requirement(
                    request.unresolved_runtime_requirement,
                ) {
                    Some(kind) if kind == request.binding_kind => {}
                    Some(kind) => issues.push(format!(
                        "dispatch {} live relocation {} kind {:?} != expected {:?}",
                        dispatch.op_name, request.field, request.binding_kind, kind
                    )),
                    None => issues.push(format!(
                        "dispatch {} live relocation {} has unknown requirement {}",
                        dispatch.op_name, request.field, request.unresolved_runtime_requirement
                    )),
                }
                if !self
                    .unresolved_runtime_requirements
                    .contains(&request.unresolved_runtime_requirement)
                {
                    issues.push(format!(
                        "dispatch {} live relocation {} requirement {} not present in plan requirements",
                        dispatch.op_name, request.field, request.unresolved_runtime_requirement
                    ));
                }
                if request.runtime_value_bound {
                    dispatch_bound_requests += 1;
                } else {
                    dispatch_unbound_requests += 1;
                }
                dispatch_request_bytes += request.size_bytes;
                match request.binding_kind {
                    RuntimeLaunchAqlLiveRelocationBindingKind::LoadedCodeObjectBase => {
                        dispatch_code_object_requests += 1;
                    }
                    RuntimeLaunchAqlLiveRelocationBindingKind::KernargAllocation => {
                        dispatch_kernarg_requests += 1;
                    }
                    RuntimeLaunchAqlLiveRelocationBindingKind::CompletionSignal => {
                        dispatch_signal_requests += 1;
                    }
                }
            }
            if dispatch_request_bytes != dispatch.binding_request_bytes {
                issues.push(format!(
                    "dispatch {} binding request bytes {} != expected {}",
                    dispatch.op_name, dispatch.binding_request_bytes, dispatch_request_bytes
                ));
            }
            if dispatch_code_object_requests != dispatch.code_object_base_request_count {
                issues.push(format!(
                    "dispatch {} code-object request count {} != expected {}",
                    dispatch.op_name,
                    dispatch.code_object_base_request_count,
                    dispatch_code_object_requests
                ));
            }
            if dispatch_kernarg_requests != dispatch.kernarg_allocation_request_count {
                issues.push(format!(
                    "dispatch {} kernarg request count {} != expected {}",
                    dispatch.op_name,
                    dispatch.kernarg_allocation_request_count,
                    dispatch_kernarg_requests
                ));
            }
            if dispatch_signal_requests != dispatch.completion_signal_request_count {
                issues.push(format!(
                    "dispatch {} completion-signal request count {} != expected {}",
                    dispatch.op_name,
                    dispatch.completion_signal_request_count,
                    dispatch_signal_requests
                ));
            }
            if dispatch_bound_requests != dispatch.bound_relocation_count {
                issues.push(format!(
                    "dispatch {} bound request count {} != expected {}",
                    dispatch.op_name, dispatch.bound_relocation_count, dispatch_bound_requests
                ));
            }
            if dispatch_unbound_requests != dispatch.unbound_relocation_count {
                issues.push(format!(
                    "dispatch {} unbound request count {} != expected {}",
                    dispatch.op_name, dispatch.unbound_relocation_count, dispatch_unbound_requests
                ));
            }
            if dispatch.all_relocations_bound {
                dispatches_fully_bound_count += 1;
            }
            binding_request_count += dispatch.binding_request_count;
            binding_request_bytes += dispatch.binding_request_bytes;
            code_object_base_request_count += dispatch.code_object_base_request_count;
            kernarg_allocation_request_count += dispatch.kernarg_allocation_request_count;
            completion_signal_request_count += dispatch.completion_signal_request_count;
            bound_relocation_count += dispatch.bound_relocation_count;
            unbound_relocation_count += dispatch.unbound_relocation_count;
            expected_queue_packet_index += 1;
        }
        if binding_request_count != self.binding_request_count {
            issues.push(format!(
                "binding request count {binding_request_count} != plan {}",
                self.binding_request_count
            ));
        }
        if binding_request_bytes != self.binding_request_bytes {
            issues.push(format!(
                "binding request bytes {binding_request_bytes} != plan {}",
                self.binding_request_bytes
            ));
        }
        if code_object_base_request_count != self.code_object_base_request_count {
            issues.push(format!(
                "code-object request count {code_object_base_request_count} != plan {}",
                self.code_object_base_request_count
            ));
        }
        if kernarg_allocation_request_count != self.kernarg_allocation_request_count {
            issues.push(format!(
                "kernarg request count {kernarg_allocation_request_count} != plan {}",
                self.kernarg_allocation_request_count
            ));
        }
        if completion_signal_request_count != self.completion_signal_request_count {
            issues.push(format!(
                "completion-signal request count {completion_signal_request_count} != plan {}",
                self.completion_signal_request_count
            ));
        }
        if bound_relocation_count != self.bound_relocation_count {
            issues.push(format!(
                "bound relocation count {bound_relocation_count} != plan {}",
                self.bound_relocation_count
            ));
        }
        if unbound_relocation_count != self.unbound_relocation_count {
            issues.push(format!(
                "unbound relocation count {unbound_relocation_count} != plan {}",
                self.unbound_relocation_count
            ));
        }
        if dispatches_fully_bound_count != self.dispatches_fully_bound_count {
            issues.push(format!(
                "dispatches fully bound count {dispatches_fully_bound_count} != plan {}",
                self.dispatches_fully_bound_count
            ));
        }
        if expected_queue_packet_index != self.queue_packet_count {
            issues.push(format!(
                "assigned queue packet count {expected_queue_packet_index} != plan queue packet count {}",
                self.queue_packet_count
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch AQL live relocation binding plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

fn runtime_launch_aql_live_relocation_binding_plan_from(
    materialization: &ModelRuntimeLaunchAqlPacketMaterializationPlan,
) -> Result<ModelRuntimeLaunchAqlLiveRelocationBindingPlan> {
    materialization.assert_consistent()?;
    let mut dispatches = Vec::with_capacity(materialization.dispatch_count);
    let mut binding_request_count = 0usize;
    let mut binding_request_bytes = 0usize;
    let mut code_object_base_request_count = 0usize;
    let mut kernarg_allocation_request_count = 0usize;
    let mut completion_signal_request_count = 0usize;
    for dispatch in &materialization.dispatches {
        let entry = runtime_dispatch_launch_aql_live_relocation_binding_entry_from(dispatch)?;
        binding_request_count = checked_add_usize(
            binding_request_count,
            entry.binding_request_count,
            "AQL live relocation binding request count",
        )?;
        binding_request_bytes = checked_add_usize(
            binding_request_bytes,
            entry.binding_request_bytes,
            "AQL live relocation binding request bytes",
        )?;
        code_object_base_request_count = checked_add_usize(
            code_object_base_request_count,
            entry.code_object_base_request_count,
            "AQL live relocation code-object request count",
        )?;
        kernarg_allocation_request_count = checked_add_usize(
            kernarg_allocation_request_count,
            entry.kernarg_allocation_request_count,
            "AQL live relocation kernarg request count",
        )?;
        completion_signal_request_count = checked_add_usize(
            completion_signal_request_count,
            entry.completion_signal_request_count,
            "AQL live relocation completion-signal request count",
        )?;
        dispatches.push(entry);
    }
    let plan = ModelRuntimeLaunchAqlLiveRelocationBindingPlan {
        target: materialization.target,
        code_object_target: materialization.code_object_target.clone(),
        code_object_sha256: materialization.code_object_sha256.clone(),
        dispatch_count: materialization.dispatch_count,
        queue_packet_count: materialization.queue_packet_count,
        packet_bytes: materialization.packet_bytes,
        binding_request_count,
        binding_request_bytes,
        code_object_base_request_count,
        kernarg_allocation_request_count,
        completion_signal_request_count,
        bound_relocation_count: 0,
        unbound_relocation_count: binding_request_count,
        dispatches_fully_bound_count: 0,
        all_relocations_bound: false,
        binding_request_plan_ready: true,
        unresolved_runtime_requirements: materialization.unresolved_runtime_requirements.clone(),
        dispatches,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

fn runtime_dispatch_launch_aql_live_relocation_binding_entry_from(
    dispatch: &RuntimeDispatchLaunchAqlPacketMaterializationEntry,
) -> Result<RuntimeDispatchLaunchAqlLiveRelocationBindingEntry> {
    let mut binding_requests = Vec::with_capacity(dispatch.pending_relocation_sites.len());
    let mut code_object_base_request_count = 0usize;
    let mut kernarg_allocation_request_count = 0usize;
    let mut completion_signal_request_count = 0usize;
    let mut binding_request_bytes = 0usize;
    for site in &dispatch.pending_relocation_sites {
        let binding_kind = RuntimeLaunchAqlLiveRelocationBindingKind::for_requirement(
            site.unresolved_runtime_requirement,
        )
        .ok_or_else(|| {
            anyhow!(
                "runtime launch AQL live relocation binding has unknown requirement {} for {}",
                site.unresolved_runtime_requirement,
                dispatch.op_name
            )
        })?;
        match binding_kind {
            RuntimeLaunchAqlLiveRelocationBindingKind::LoadedCodeObjectBase => {
                code_object_base_request_count += 1;
            }
            RuntimeLaunchAqlLiveRelocationBindingKind::KernargAllocation => {
                kernarg_allocation_request_count += 1;
            }
            RuntimeLaunchAqlLiveRelocationBindingKind::CompletionSignal => {
                completion_signal_request_count += 1;
            }
        }
        binding_request_bytes = checked_add_usize(
            binding_request_bytes,
            site.size_bytes,
            "AQL live relocation binding request bytes",
        )?;
        binding_requests.push(RuntimeLaunchAqlLiveRelocationBindingRequest {
            field: site.field,
            binding_kind,
            packet_relative_offset: site.packet_relative_offset,
            staging_offset: site.staging_offset,
            size_bytes: site.size_bytes,
            relocation_kind: site.relocation_kind,
            unresolved_runtime_requirement: site.unresolved_runtime_requirement,
            runtime_value_bound: false,
        });
    }
    let binding_request_count = binding_requests.len();
    Ok(RuntimeDispatchLaunchAqlLiveRelocationBindingEntry {
        op_index: dispatch.op_index,
        op_name: dispatch.op_name.clone(),
        kind: dispatch.kind,
        stage_name: dispatch.stage_name.clone(),
        stage_kind: dispatch.stage_kind,
        window_index: dispatch.window_index,
        queue_packet_index: dispatch.queue_packet_index,
        packet_offset: dispatch.packet_offset,
        packet_bytes: dispatch.packet_bytes,
        materialization_state: dispatch.state,
        candidate_byte_template_count: dispatch.candidate_byte_template_count,
        binding_request_count,
        binding_request_bytes,
        code_object_base_request_count,
        kernarg_allocation_request_count,
        completion_signal_request_count,
        bound_relocation_count: 0,
        unbound_relocation_count: binding_request_count,
        all_relocations_bound: false,
        binding_requests,
    })
}

fn runtime_launch_aql_packet_materialization_plan_from(
    byte_templates: &ModelRuntimeLaunchAqlPacketByteTemplatePlan,
) -> Result<ModelRuntimeLaunchAqlPacketMaterializationPlan> {
    byte_templates.assert_consistent()?;
    let mut dispatches = Vec::with_capacity(byte_templates.dispatch_count);
    let mut candidate_byte_template_count = 0usize;
    let mut selected_dispatch_count = 0usize;
    let mut ambiguous_dispatch_count = 0usize;
    let mut selected_packet_byte_template_count = 0usize;
    let mut selected_packet_byte_template_bytes = 0usize;
    let mut live_relocation_patch_site_count = 0usize;
    let mut live_relocation_patch_bytes = 0usize;
    for dispatch in &byte_templates.dispatches {
        let entry = runtime_dispatch_launch_aql_packet_materialization_entry_from(dispatch)?;
        candidate_byte_template_count = checked_add_usize(
            candidate_byte_template_count,
            entry.candidate_byte_template_count,
            "AQL packet materialization candidate byte-template count",
        )?;
        match entry.state {
            RuntimeLaunchAqlPacketMaterializationState::SelectedCandidateByteTemplate => {
                selected_dispatch_count += 1;
                selected_packet_byte_template_count += 1;
                selected_packet_byte_template_bytes = checked_add_usize(
                    selected_packet_byte_template_bytes,
                    entry.selected_candidate_packet_bytes,
                    "AQL packet materialization selected byte-template bytes",
                )?;
            }
            RuntimeLaunchAqlPacketMaterializationState::AmbiguousCandidateByteTemplates => {
                ambiguous_dispatch_count += 1;
            }
        }
        live_relocation_patch_site_count = checked_add_usize(
            live_relocation_patch_site_count,
            entry.live_relocation_patch_site_count,
            "AQL packet materialization relocation patch sites",
        )?;
        live_relocation_patch_bytes = checked_add_usize(
            live_relocation_patch_bytes,
            entry.live_relocation_patch_bytes,
            "AQL packet materialization relocation patch bytes",
        )?;
        dispatches.push(entry);
    }
    let plan = ModelRuntimeLaunchAqlPacketMaterializationPlan {
        target: byte_templates.target,
        code_object_target: byte_templates.code_object_target.clone(),
        code_object_sha256: byte_templates.code_object_sha256.clone(),
        dispatch_count: byte_templates.dispatch_count,
        queue_packet_count: byte_templates.queue_packet_count,
        packet_bytes: byte_templates.packet_bytes,
        candidate_byte_template_count,
        selected_dispatch_count,
        ambiguous_dispatch_count,
        selected_packet_byte_template_count,
        selected_packet_byte_template_bytes,
        live_relocation_patch_site_count,
        live_relocation_patch_bytes,
        dispatchable_packet_count: 0,
        dispatchable_packet_bytes: 0,
        packet_materialization_ready: false,
        unresolved_runtime_requirements: byte_templates.unresolved_runtime_requirements.clone(),
        dispatches,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

fn runtime_dispatch_launch_aql_packet_materialization_entry_from(
    dispatch: &RuntimeDispatchLaunchAqlPacketByteTemplateEntry,
) -> Result<RuntimeDispatchLaunchAqlPacketMaterializationEntry> {
    if dispatch.candidate_byte_templates.is_empty() {
        return Err(anyhow!(
            "runtime launch AQL packet materialization missing byte template for {}",
            dispatch.op_name
        ));
    }
    let state = if dispatch.candidate_byte_template_count == 1 {
        RuntimeLaunchAqlPacketMaterializationState::SelectedCandidateByteTemplate
    } else {
        RuntimeLaunchAqlPacketMaterializationState::AmbiguousCandidateByteTemplates
    };
    let selected_candidate =
        if state == RuntimeLaunchAqlPacketMaterializationState::SelectedCandidateByteTemplate {
            dispatch.candidate_byte_templates.first()
        } else {
            None
        };
    let pending_relocation_sites = dispatch.candidate_byte_templates[0]
        .zeroed_relocation_sites
        .clone();
    let live_relocation_patch_bytes = pending_relocation_sites
        .iter()
        .map(|site| site.size_bytes)
        .sum::<usize>();
    Ok(RuntimeDispatchLaunchAqlPacketMaterializationEntry {
        op_index: dispatch.op_index,
        op_name: dispatch.op_name.clone(),
        kind: dispatch.kind,
        stage_name: dispatch.stage_name.clone(),
        stage_kind: dispatch.stage_kind,
        window_index: dispatch.window_index,
        queue_packet_index: dispatch.queue_packet_index,
        packet_offset: dispatch.packet_offset,
        packet_bytes: dispatch.packet_bytes,
        state,
        candidate_byte_template_count: dispatch.candidate_byte_template_count,
        selected_candidate_kernel_symbol: selected_candidate
            .map(|candidate| candidate.kernel_symbol.clone()),
        selected_candidate_byte_image: selected_candidate
            .map(|candidate| candidate.byte_image.clone()),
        selected_candidate_packet_bytes: selected_candidate
            .map(|candidate| candidate.packet_bytes)
            .unwrap_or(0),
        live_relocation_patch_site_count: pending_relocation_sites.len(),
        live_relocation_patch_bytes,
        pending_relocation_sites,
        dispatchable_packet_ready: false,
    })
}

fn write_le_u16(bytes: &mut [u8], offset: usize, value: u16) -> Result<()> {
    let end = offset
        .checked_add(2)
        .ok_or_else(|| anyhow!("u16 packet write offset overflows"))?;
    if end > bytes.len() {
        return Err(anyhow!(
            "u16 packet write range {offset}..{end} exceeds {}",
            bytes.len()
        ));
    }
    bytes[offset..end].copy_from_slice(&value.to_le_bytes());
    Ok(())
}

fn write_le_u32(bytes: &mut [u8], offset: usize, value: u32) -> Result<()> {
    let end = offset
        .checked_add(4)
        .ok_or_else(|| anyhow!("u32 packet write offset overflows"))?;
    if end > bytes.len() {
        return Err(anyhow!(
            "u32 packet write range {offset}..{end} exceeds {}",
            bytes.len()
        ));
    }
    bytes[offset..end].copy_from_slice(&value.to_le_bytes());
    Ok(())
}

fn read_le_u16(bytes: &[u8], offset: usize) -> u16 {
    u16::from_le_bytes([bytes[offset], bytes[offset + 1]])
}

fn read_le_u32(bytes: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes([
        bytes[offset],
        bytes[offset + 1],
        bytes[offset + 2],
        bytes[offset + 3],
    ])
}

fn runtime_launch_kernarg_value_bytes(
    value: &RuntimeLaunchDeviceArgumentValue,
    encoding: RuntimeLaunchKernargArgumentEncoding,
) -> Result<Vec<u8>> {
    match (value, encoding) {
        (
            RuntimeLaunchDeviceArgumentValue::Pointer(pointer),
            RuntimeLaunchKernargArgumentEncoding::DevicePointerU64,
        ) => Ok(pointer.device_pointer.device_va.to_le_bytes().to_vec()),
        (
            RuntimeLaunchDeviceArgumentValue::Scalar(RuntimeDispatchScalarValue::Usize(value)),
            RuntimeLaunchKernargArgumentEncoding::UsizeU64,
        ) => {
            let value = u64::try_from(*value)
                .map_err(|_| anyhow!("usize scalar does not fit canonical u64 kernarg"))?;
            Ok(value.to_le_bytes().to_vec())
        }
        (
            RuntimeLaunchDeviceArgumentValue::Scalar(RuntimeDispatchScalarValue::F32Bits(value)),
            RuntimeLaunchKernargArgumentEncoding::F32BitsU32,
        ) => Ok(value.to_le_bytes().to_vec()),
        (
            RuntimeLaunchDeviceArgumentValue::Scalar(RuntimeDispatchScalarValue::DType(value)),
            RuntimeLaunchKernargArgumentEncoding::DTypeU32,
        ) => Ok(runtime_launch_dtype_code(*value).to_le_bytes().to_vec()),
        (
            RuntimeLaunchDeviceArgumentValue::Scalar(RuntimeDispatchScalarValue::WeightFormat(
                value,
            )),
            RuntimeLaunchKernargArgumentEncoding::WeightFormatU32,
        ) => Ok(runtime_launch_weight_format_code(*value)
            .to_le_bytes()
            .to_vec()),
        (
            RuntimeLaunchDeviceArgumentValue::Scalar(
                RuntimeDispatchScalarValue::LinearParallelism(value),
            ),
            RuntimeLaunchKernargArgumentEncoding::LinearParallelismTagShardsU32Pair,
        ) => {
            let (tag, shards) = runtime_launch_linear_parallelism_code(*value)?;
            let mut bytes = Vec::with_capacity(8);
            bytes.extend_from_slice(&tag.to_le_bytes());
            bytes.extend_from_slice(&shards.to_le_bytes());
            Ok(bytes)
        }
        (
            RuntimeLaunchDeviceArgumentValue::Scalar(RuntimeDispatchScalarValue::RopeMode(value)),
            RuntimeLaunchKernargArgumentEncoding::RopeModeU32,
        ) => Ok(runtime_launch_rope_mode_code(*value).to_le_bytes().to_vec()),
        (
            RuntimeLaunchDeviceArgumentValue::Scalar(RuntimeDispatchScalarValue::KvCacheFormat(
                value,
            )),
            RuntimeLaunchKernargArgumentEncoding::KvCacheFormatU32,
        ) => Ok(runtime_launch_kv_cache_format_code(value)?
            .to_le_bytes()
            .to_vec()),
        (
            RuntimeLaunchDeviceArgumentValue::Scalar(RuntimeDispatchScalarValue::CollectiveKind(
                value,
            )),
            RuntimeLaunchKernargArgumentEncoding::CollectiveKindU32,
        ) => Ok(runtime_launch_collective_kind_code(*value)
            .to_le_bytes()
            .to_vec()),
        (
            RuntimeLaunchDeviceArgumentValue::Scalar(RuntimeDispatchScalarValue::MoeActivation(
                value,
            )),
            RuntimeLaunchKernargArgumentEncoding::MoeActivationU32,
        ) => Ok(runtime_launch_moe_activation_code(*value)
            .to_le_bytes()
            .to_vec()),
        _ => Err(anyhow!(
            "runtime launch kernarg serialization value does not match encoding {:?}",
            encoding
        )),
    }
}

fn runtime_launch_dtype_code(value: DType) -> u32 {
    match value {
        DType::F32 => 0,
        DType::F16 => 1,
        DType::Bf16 => 2,
        DType::Fp8E4M3 => 3,
        DType::Fp4E2M1 => 4,
        DType::U32 => 5,
    }
}

fn runtime_launch_weight_format_code(value: WeightFormat) -> u32 {
    match value {
        WeightFormat::F16 => 0,
        WeightFormat::Fp8E4M3PerOutputChannel => 1,
    }
}

fn runtime_launch_linear_parallelism_code(value: LinearParallelism) -> Result<(u32, u32)> {
    match value {
        LinearParallelism::Replicated => Ok((0, 1)),
        LinearParallelism::TensorParallelColumn { shards } => {
            let shards = u32::try_from(shards)
                .map_err(|_| anyhow!("linear parallelism shard count exceeds u32"))?;
            Ok((1, shards))
        }
        LinearParallelism::TensorParallelRow { shards } => {
            let shards = u32::try_from(shards)
                .map_err(|_| anyhow!("linear parallelism shard count exceeds u32"))?;
            Ok((2, shards))
        }
    }
}

fn runtime_launch_rope_mode_code(value: RopeMode) -> u32 {
    match value {
        RopeMode::StandardGqa => 0,
        RopeMode::DecoupledMla => 1,
    }
}

fn runtime_launch_kv_cache_format_code(value: &KvCacheFormat) -> Result<u32> {
    match value {
        KvCacheFormat::PagedGqa => Ok(0),
        KvCacheFormat::PagedMla => Ok(1),
        KvCacheFormat::Named(name) => Err(anyhow!(
            "named KV cache format {name} has no canonical u32 kernarg encoding"
        )),
    }
}

fn runtime_launch_collective_kind_code(value: CollectiveKind) -> u32 {
    match value {
        CollectiveKind::AllReduce => 0,
        CollectiveKind::AllToAll => 1,
        CollectiveKind::ReduceScatter => 2,
        CollectiveKind::AllGather => 3,
    }
}

fn runtime_launch_moe_activation_code(value: MoeActivation) -> u32 {
    match value {
        MoeActivation::SwiGlu => 0,
    }
}

