#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum RuntimeLaunchLiveAqlProofKind {
    BatchReservationPlan,
    MaterializedPacketPlan,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RuntimeLaunchLiveAqlProofKindDescriptor {
    pub kind: RuntimeLaunchLiveAqlProofKind,
    pub proof_input: &'static str,
    pub proof_type: &'static str,
    pub validation_type: &'static str,
    pub validation_method: &'static str,
    pub ready_field: &'static str,
    pub no_live_queue_mutation_contract_field: &'static str,
    pub submits_work: bool,
    pub mutates_live_queue: bool,
}

impl RuntimeLaunchLiveAqlProofKind {
    pub const ALL: [Self; MODEL_RUNTIME_LAUNCH_LIVE_AQL_PROOF_STEP_COUNT] =
        [Self::BatchReservationPlan, Self::MaterializedPacketPlan];

    pub const DESCRIPTORS: [RuntimeLaunchLiveAqlProofKindDescriptor;
        MODEL_RUNTIME_LAUNCH_LIVE_AQL_PROOF_STEP_COUNT] = [
        Self::BatchReservationPlan.descriptor(),
        Self::MaterializedPacketPlan.descriptor(),
    ];

    pub const fn as_str(self) -> &'static str {
        match self {
            Self::BatchReservationPlan => "batch_reservation_plan",
            Self::MaterializedPacketPlan => "materialized_packet_plan",
        }
    }

    pub const fn proof_input(self) -> &'static str {
        match self {
            Self::BatchReservationPlan => "KfdQueueLiveAqlBatchReservationPlanInput",
            Self::MaterializedPacketPlan => "KfdQueueLiveAqlMaterializedPacketPlanInput",
        }
    }

    pub const fn proof_type(self) -> &'static str {
        match self {
            Self::BatchReservationPlan => "KfdQueueLiveAqlBatchReservationPlanProof",
            Self::MaterializedPacketPlan => "KfdQueueLiveAqlMaterializedPacketPlanProof",
        }
    }

    pub const fn validation_type(self) -> &'static str {
        match self {
            Self::BatchReservationPlan => "KfdQueueLiveAqlBatchReservationPlanValidation",
            Self::MaterializedPacketPlan => "KfdQueueLiveAqlMaterializedPacketPlanValidation",
        }
    }

    pub const fn validation_method(self) -> &'static str {
        match self {
            Self::BatchReservationPlan => {
                "KfdQueueLiveAqlBatchReservationPlanProof::validate_ready"
            }
            Self::MaterializedPacketPlan => {
                "KfdQueueLiveAqlMaterializedPacketPlanProof::validate_ready"
            }
        }
    }

    pub const fn ready_field(self) -> &'static str {
        "ready"
    }

    pub const fn no_live_queue_mutation_contract_field(self) -> &'static str {
        "no_live_queue_mutation_contract"
    }

    pub const fn submits_work(self) -> bool {
        false
    }

    pub const fn mutates_live_queue(self) -> bool {
        false
    }

    pub const fn descriptor(self) -> RuntimeLaunchLiveAqlProofKindDescriptor {
        RuntimeLaunchLiveAqlProofKindDescriptor {
            kind: self,
            proof_input: self.proof_input(),
            proof_type: self.proof_type(),
            validation_type: self.validation_type(),
            validation_method: self.validation_method(),
            ready_field: self.ready_field(),
            no_live_queue_mutation_contract_field: self.no_live_queue_mutation_contract_field(),
            submits_work: self.submits_work(),
            mutates_live_queue: self.mutates_live_queue(),
        }
    }

    pub fn validate_batch_reservation_plan_proof(
        self,
        proof: KfdQueueLiveAqlBatchReservationPlanProof,
    ) -> Result<RuntimeLaunchLiveAqlProofValidation> {
        if self != Self::BatchReservationPlan {
            return Err(anyhow!(
                "live-AQL proof kind {} cannot validate {}; expected {}",
                self,
                Self::BatchReservationPlan.proof_type(),
                Self::BatchReservationPlan
            ));
        }
        Ok(RuntimeLaunchLiveAqlProofValidation::batch_reservation_plan(
            proof,
        ))
    }

    pub fn validate_materialized_packet_plan_proof(
        self,
        proof: KfdQueueLiveAqlMaterializedPacketPlanProof,
    ) -> Result<RuntimeLaunchLiveAqlProofValidation> {
        if self != Self::MaterializedPacketPlan {
            return Err(anyhow!(
                "live-AQL proof kind {} cannot validate {}; expected {}",
                self,
                Self::MaterializedPacketPlan.proof_type(),
                Self::MaterializedPacketPlan
            ));
        }
        Ok(RuntimeLaunchLiveAqlProofValidation::materialized_packet_plan(proof))
    }

    pub fn from_proof_input(proof_input: &str) -> Option<Self> {
        Self::ALL
            .iter()
            .copied()
            .find(|kind| kind.proof_input() == proof_input)
    }

    pub fn from_validation_method(validation_method: &str) -> Option<Self> {
        Self::ALL
            .iter()
            .copied()
            .find(|kind| kind.validation_method() == validation_method)
    }
}

impl fmt::Display for RuntimeLaunchLiveAqlProofKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

#[derive(Clone, Copy, Debug)]
pub enum RuntimeLaunchLiveAqlProofValidation {
    BatchReservationPlan(KfdQueueLiveAqlBatchReservationPlanValidation),
    MaterializedPacketPlan(KfdQueueLiveAqlMaterializedPacketPlanValidation),
}

impl RuntimeLaunchLiveAqlProofValidation {
    pub fn batch_reservation_plan(proof: KfdQueueLiveAqlBatchReservationPlanProof) -> Self {
        Self::BatchReservationPlan(proof.validate_ready())
    }

    pub fn materialized_packet_plan(proof: KfdQueueLiveAqlMaterializedPacketPlanProof) -> Self {
        Self::MaterializedPacketPlan(proof.validate_ready())
    }

    pub fn kind(&self) -> RuntimeLaunchLiveAqlProofKind {
        match self {
            Self::BatchReservationPlan(_) => RuntimeLaunchLiveAqlProofKind::BatchReservationPlan,
            Self::MaterializedPacketPlan(_) => {
                RuntimeLaunchLiveAqlProofKind::MaterializedPacketPlan
            }
        }
    }

    pub fn descriptor(&self) -> RuntimeLaunchLiveAqlProofKindDescriptor {
        self.kind().descriptor()
    }

    pub fn proof_input(&self) -> &'static str {
        self.kind().proof_input()
    }

    pub fn proof_type(&self) -> &'static str {
        self.kind().proof_type()
    }

    pub fn validation_type(&self) -> &'static str {
        self.kind().validation_type()
    }

    pub fn validation_method(&self) -> &'static str {
        self.kind().validation_method()
    }

    pub fn validation_ready_field(&self) -> &'static str {
        self.kind().ready_field()
    }

    pub fn no_live_queue_mutation_contract_field(&self) -> &'static str {
        self.kind().no_live_queue_mutation_contract_field()
    }

    pub fn printed_ready(&self) -> bool {
        match self {
            Self::BatchReservationPlan(validation) => validation.printed_plan_ready,
            Self::MaterializedPacketPlan(validation) => validation.printed_packet_plan_ready,
        }
    }

    pub fn ready(&self) -> bool {
        match self {
            Self::BatchReservationPlan(validation) => validation.ready,
            Self::MaterializedPacketPlan(validation) => validation.ready,
        }
    }

    pub fn no_live_queue_mutation_contract(&self) -> bool {
        match self {
            Self::BatchReservationPlan(validation) => validation.no_live_queue_mutation_contract,
            Self::MaterializedPacketPlan(validation) => validation.no_live_queue_mutation_contract,
        }
    }

    pub fn passed(&self) -> bool {
        match self {
            Self::BatchReservationPlan(validation) => validation.passed,
            Self::MaterializedPacketPlan(validation) => validation.passed,
        }
    }

    pub fn submits_work(&self) -> bool {
        self.kind().submits_work()
    }

    pub fn mutates_live_queue(&self) -> bool {
        self.kind().mutates_live_queue()
    }

    pub fn receipt_lines(&self) -> Vec<String> {
        let descriptor = self.descriptor();
        let mut lines = Vec::new();
        push_receipt_line(
            &mut lines,
            "receipt.kind",
            "model_runtime_launch_live_aql_proof_validation",
        );
        push_receipt_line(&mut lines, "receipt.version", 1usize);
        push_receipt_line(&mut lines, "proof_kind", descriptor.kind.as_str());
        push_receipt_line(&mut lines, "proof_input", descriptor.proof_input);
        push_receipt_line(&mut lines, "proof_type", descriptor.proof_type);
        push_receipt_line(&mut lines, "validation_type", descriptor.validation_type);
        push_receipt_line(
            &mut lines,
            "validation_method",
            descriptor.validation_method,
        );
        push_receipt_line(&mut lines, "validation_ready_field", descriptor.ready_field);
        push_receipt_line(
            &mut lines,
            "no_live_queue_mutation_contract_field",
            descriptor.no_live_queue_mutation_contract_field,
        );
        push_receipt_line(
            &mut lines,
            "printed_ready",
            bool_label(self.printed_ready()),
        );
        push_receipt_line(&mut lines, "ready", bool_label(self.ready()));
        push_receipt_line(
            &mut lines,
            "no_live_queue_mutation_contract",
            bool_label(self.no_live_queue_mutation_contract()),
        );
        push_receipt_line(&mut lines, "passed", bool_label(self.passed()));
        push_receipt_line(&mut lines, "submits_work", bool_label(self.submits_work()));
        push_receipt_line(
            &mut lines,
            "mutates_live_queue",
            bool_label(self.mutates_live_queue()),
        );
        lines
    }

    pub fn receipt_text(&self) -> String {
        receipt_text_from_lines(&self.receipt_lines())
    }

    pub fn receipt_fingerprint(&self) -> String {
        receipt_fingerprint_from_lines(&self.receipt_lines())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RuntimeLaunchExecutionRequestStepDescriptor {
    pub step: RuntimeLaunchExecutionRequestStep,
    pub step_index: usize,
    pub request_plan: &'static str,
    pub requirement: &'static str,
    pub live_aql_proof_kind: Option<RuntimeLaunchLiveAqlProofKind>,
    pub live_aql_proof_input: Option<&'static str>,
    pub live_aql_validation_method: Option<&'static str>,
    pub mutates_live_queue: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum RuntimeLaunchExecutionRequestStep {
    CodeObjectLoad,
    CodeObjectBaseBinding,
    CompletionSignalBinding,
    QueueReservation,
    KernargAllocation,
    KernelArgumentAbiSchema,
    KernelCandidateSelection,
    KernelArgumentAbiSemanticProjectionCandidateSelection,
    HostLauncherBranchResolution,
    AqlLiveRelocationBinding,
}

impl RuntimeLaunchExecutionRequestStep {
    pub const ALL: [Self; MODEL_RUNTIME_LAUNCH_EXECUTION_REQUEST_PLAN_COUNT] = [
        Self::CodeObjectLoad,
        Self::CodeObjectBaseBinding,
        Self::CompletionSignalBinding,
        Self::QueueReservation,
        Self::KernargAllocation,
        Self::KernelArgumentAbiSchema,
        Self::KernelCandidateSelection,
        Self::KernelArgumentAbiSemanticProjectionCandidateSelection,
        Self::HostLauncherBranchResolution,
        Self::AqlLiveRelocationBinding,
    ];

    pub const DESCRIPTORS: [RuntimeLaunchExecutionRequestStepDescriptor;
        MODEL_RUNTIME_LAUNCH_EXECUTION_REQUEST_PLAN_COUNT] = [
        Self::CodeObjectLoad.descriptor(),
        Self::CodeObjectBaseBinding.descriptor(),
        Self::CompletionSignalBinding.descriptor(),
        Self::QueueReservation.descriptor(),
        Self::KernargAllocation.descriptor(),
        Self::KernelArgumentAbiSchema.descriptor(),
        Self::KernelCandidateSelection.descriptor(),
        Self::KernelArgumentAbiSemanticProjectionCandidateSelection.descriptor(),
        Self::HostLauncherBranchResolution.descriptor(),
        Self::AqlLiveRelocationBinding.descriptor(),
    ];

    pub const LIVE_AQL_PROOF_STEPS: [Self; MODEL_RUNTIME_LAUNCH_LIVE_AQL_PROOF_STEP_COUNT] =
        [Self::QueueReservation, Self::AqlLiveRelocationBinding];

    pub const LIVE_AQL_PROOF_DESCRIPTORS: [RuntimeLaunchExecutionRequestStepDescriptor;
        MODEL_RUNTIME_LAUNCH_LIVE_AQL_PROOF_STEP_COUNT] = [
        Self::QueueReservation.descriptor(),
        Self::AqlLiveRelocationBinding.descriptor(),
    ];

    pub const fn step_index(self) -> usize {
        match self {
            Self::CodeObjectLoad => 0,
            Self::CodeObjectBaseBinding => 1,
            Self::CompletionSignalBinding => 2,
            Self::QueueReservation => 3,
            Self::KernargAllocation => 4,
            Self::KernelArgumentAbiSchema => 5,
            Self::KernelCandidateSelection => 6,
            Self::KernelArgumentAbiSemanticProjectionCandidateSelection => 7,
            Self::HostLauncherBranchResolution => 8,
            Self::AqlLiveRelocationBinding => 9,
        }
    }

    pub const fn request_plan(self) -> &'static str {
        match self {
            Self::CodeObjectLoad => "code_object_load_request_plan",
            Self::CodeObjectBaseBinding => "code_object_base_binding_request_plan",
            Self::CompletionSignalBinding => "completion_signal_binding_request_plan",
            Self::QueueReservation => "queue_reservation_request_plan",
            Self::KernargAllocation => "kernarg_allocation_request_plan",
            Self::KernelArgumentAbiSchema => "kernel_argument_abi_schema_request_plan",
            Self::KernelCandidateSelection => "kernel_candidate_selection_request_plan",
            Self::KernelArgumentAbiSemanticProjectionCandidateSelection => {
                "kernel_argument_abi_semantic_projection_candidate_selection_request_plan"
            }
            Self::HostLauncherBranchResolution => "host_launcher_branch_resolution_request_plan",
            Self::AqlLiveRelocationBinding => "aql_live_relocation_binding_request_plan",
        }
    }

    pub fn from_request_plan(request_plan: &str) -> Option<Self> {
        Self::ALL
            .iter()
            .copied()
            .find(|step| step.request_plan() == request_plan)
    }

    pub fn descriptor_for_request_plan(
        request_plan: &str,
    ) -> Option<RuntimeLaunchExecutionRequestStepDescriptor> {
        Self::from_request_plan(request_plan).map(Self::descriptor)
    }

    pub const fn requirement(self) -> &'static str {
        match self {
            Self::CodeObjectLoad | Self::CodeObjectBaseBinding => "loaded_code_object_base",
            Self::CompletionSignalBinding => "completion_signal_binding",
            Self::QueueReservation => "queue_reservation",
            Self::KernargAllocation => "kernarg_allocation",
            Self::KernelArgumentAbiSchema => "kernel_argument_abi_verification",
            Self::KernelCandidateSelection => "kernel_candidate_selection_policy",
            Self::KernelArgumentAbiSemanticProjectionCandidateSelection => {
                MODEL_RUNTIME_KERNEL_ARGUMENT_ABI_SEMANTIC_PROJECTION_REQUIREMENT
            }
            Self::HostLauncherBranchResolution => "host_launcher_runtime_branch_resolution",
            Self::AqlLiveRelocationBinding => "aql_packet_materialization",
        }
    }

    pub const fn live_aql_proof_kind(self) -> Option<RuntimeLaunchLiveAqlProofKind> {
        match self {
            Self::QueueReservation => Some(RuntimeLaunchLiveAqlProofKind::BatchReservationPlan),
            Self::AqlLiveRelocationBinding => {
                Some(RuntimeLaunchLiveAqlProofKind::MaterializedPacketPlan)
            }
            Self::CodeObjectLoad
            | Self::CodeObjectBaseBinding
            | Self::CompletionSignalBinding
            | Self::KernargAllocation
            | Self::KernelArgumentAbiSchema
            | Self::KernelCandidateSelection
            | Self::KernelArgumentAbiSemanticProjectionCandidateSelection
            | Self::HostLauncherBranchResolution => None,
        }
    }

    pub const fn live_aql_proof_input(self) -> Option<&'static str> {
        match self {
            Self::QueueReservation => {
                Some(RuntimeLaunchLiveAqlProofKind::BatchReservationPlan.proof_input())
            }
            Self::AqlLiveRelocationBinding => {
                Some(RuntimeLaunchLiveAqlProofKind::MaterializedPacketPlan.proof_input())
            }
            Self::CodeObjectLoad
            | Self::CodeObjectBaseBinding
            | Self::CompletionSignalBinding
            | Self::KernargAllocation
            | Self::KernelArgumentAbiSchema
            | Self::KernelCandidateSelection
            | Self::KernelArgumentAbiSemanticProjectionCandidateSelection
            | Self::HostLauncherBranchResolution => None,
        }
    }

    pub const fn live_aql_validation_method(self) -> Option<&'static str> {
        match self {
            Self::QueueReservation => {
                Some(RuntimeLaunchLiveAqlProofKind::BatchReservationPlan.validation_method())
            }
            Self::AqlLiveRelocationBinding => {
                Some(RuntimeLaunchLiveAqlProofKind::MaterializedPacketPlan.validation_method())
            }
            Self::CodeObjectLoad
            | Self::CodeObjectBaseBinding
            | Self::CompletionSignalBinding
            | Self::KernargAllocation
            | Self::KernelArgumentAbiSchema
            | Self::KernelCandidateSelection
            | Self::KernelArgumentAbiSemanticProjectionCandidateSelection
            | Self::HostLauncherBranchResolution => None,
        }
    }

    pub const fn requires_live_aql_proof(self) -> bool {
        matches!(
            self,
            Self::QueueReservation | Self::AqlLiveRelocationBinding
        )
    }

    pub const fn mutates_live_queue(self) -> bool {
        false
    }

    pub const fn permits_zero_actionable_requests(self) -> bool {
        matches!(
            self,
            Self::KernelArgumentAbiSemanticProjectionCandidateSelection
        )
    }

    pub const fn descriptor(self) -> RuntimeLaunchExecutionRequestStepDescriptor {
        RuntimeLaunchExecutionRequestStepDescriptor {
            step: self,
            step_index: self.step_index(),
            request_plan: self.request_plan(),
            requirement: self.requirement(),
            live_aql_proof_kind: self.live_aql_proof_kind(),
            live_aql_proof_input: self.live_aql_proof_input(),
            live_aql_validation_method: self.live_aql_validation_method(),
            mutates_live_queue: self.mutates_live_queue(),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum RuntimeLaunchSubmissionPrerequisiteNextAction {
    None,
    CompleteRequestPlan,
    ValidateLiveAqlProof,
    ApplyRuntimeRequestComponent,
    ResolveExecutionReadinessBlocker,
    RejectLiveAqlSubmissionSideEffect,
    RejectLiveQueueMutation,
}

impl RuntimeLaunchSubmissionPrerequisiteNextAction {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::None => "none",
            Self::CompleteRequestPlan => "complete_request_plan",
            Self::ValidateLiveAqlProof => "validate_live_aql_proof",
            Self::ApplyRuntimeRequestComponent => "apply_runtime_request_component",
            Self::ResolveExecutionReadinessBlocker => "resolve_execution_readiness_blocker",
            Self::RejectLiveAqlSubmissionSideEffect => "reject_live_aql_submission_side_effect",
            Self::RejectLiveQueueMutation => "reject_live_queue_mutation",
        }
    }

    pub const fn uses_live_aql_proof(self) -> bool {
        matches!(self, Self::ValidateLiveAqlProof)
    }
}

impl fmt::Display for RuntimeLaunchSubmissionPrerequisiteNextAction {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

