    fn non_submitting_boundary_issues(&self) -> Vec<String> {
        let mut issues = Vec::new();
        if self.live_aql_submission_side_effect_next_action_count != 0 {
            issues.push(format!(
                "live AQL submission side-effect next actions {} != 0",
                self.live_aql_submission_side_effect_next_action_count
            ));
        }
        if self.live_aql_submitting_prerequisite_count != 0 {
            issues.push(format!(
                "live AQL submitting prerequisites {} != 0",
                self.live_aql_submitting_prerequisite_count
            ));
        }
        let live_aql_submitting_prerequisites =
            self.live_aql_submitting_prerequisite_request_plan_names();
        if !live_aql_submitting_prerequisites.is_empty() {
            issues.push(format!(
                "live AQL submitting prerequisite rows {}",
                live_aql_submitting_prerequisites.join(",")
            ));
        }
        if self.live_queue_mutation_next_action_count != 0 {
            issues.push(format!(
                "live queue mutation next actions {} != 0",
                self.live_queue_mutation_next_action_count
            ));
        }
        if self.live_queue_mutating_prerequisite_count != 0 {
            issues.push(format!(
                "live queue mutating prerequisites {} != 0",
                self.live_queue_mutating_prerequisite_count
            ));
        }
        let live_queue_mutating_prerequisites =
            self.live_queue_mutating_prerequisite_request_plan_names();
        if !live_queue_mutating_prerequisites.is_empty() {
            issues.push(format!(
                "live queue mutating prerequisite rows {}",
                live_queue_mutating_prerequisites.join(",")
            ));
        }
        issues
    }

    pub fn is_non_submitting_boundary(&self) -> bool {
        self.assert_non_submitting_boundary().is_ok()
    }

    pub fn assert_non_submitting_boundary(&self) -> Result<()> {
        let mut issues = Vec::new();
        if let Err(err) = self.assert_consistent() {
            issues.push(format!("consistency: {err}"));
        }
        issues.extend(self.non_submitting_boundary_issues());
        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch submission prerequisite plan for {} is not a non-submitting boundary: {}",
                self.target,
                issues.join("; ")
            ))
        }
    }

