#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchKernelRequirementPlan {
    pub target: &'static str,
    pub stages: Vec<RuntimeStageLaunchKernelRequirementEntry>,
    pub dispatch_count: usize,
    pub required_kernel_symbols: Vec<String>,
    pub unmapped_host_launchers: Vec<String>,
}

impl ModelRuntimeLaunchKernelRequirementPlan {
    pub fn stage_for(&self, stage_name: &str) -> Option<&RuntimeStageLaunchKernelRequirementEntry> {
        self.stages
            .iter()
            .find(|stage| stage.stage_name == stage_name)
    }

    pub fn dispatch_for(
        &self,
        op_name: &str,
    ) -> Option<&RuntimeDispatchLaunchKernelRequirementEntry> {
        self.stages
            .iter()
            .flat_map(|stage| stage.dispatches.iter())
            .find(|dispatch| dispatch.op_name == op_name)
    }

    pub fn assert_all_host_launchers_mapped(&self) -> Result<()> {
        if self.unmapped_host_launchers.is_empty() {
            return Ok(());
        }
        Err(anyhow!(
            "runtime launch kernel requirement plan for {} has {} unmapped host launcher(s): {}",
            self.target,
            self.unmapped_host_launchers.len(),
            self.unmapped_host_launchers.join(", ")
        ))
    }

    pub fn validate_code_object(
        &self,
        code_object: &CodeObjectInfo,
    ) -> Result<CodeObjectKernelSetValidation> {
        self.assert_all_host_launchers_mapped()?;
        Ok(self.validate_mapped_code_object_kernels(code_object))
    }

    pub fn kernel_metadata_plan(
        &self,
        code_object: &CodeObjectInfo,
    ) -> Result<ModelRuntimeLaunchKernelMetadataPlan> {
        self.validate_code_object(code_object)?.assert_complete()?;
        runtime_launch_kernel_metadata_plan_from(self, code_object)
    }

    pub fn validate_mapped_code_object_kernels(
        &self,
        code_object: &CodeObjectInfo,
    ) -> CodeObjectKernelSetValidation {
        let required = self
            .required_kernel_symbols
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>();
        code_object.validate_required_kernels(&required)
    }
}

