const MODEL_RUNTIME_CODE_OBJECT_LOAD_REQUEST_UNRESOLVED_RUNTIME_REQUIREMENTS: &[&str] =
    &["loaded_code_object_base", "aql_packet_materialization"];

#[derive(Clone, Debug, PartialEq, Eq)]
