#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchCodeObjectLoadRequestPlan {
    pub target: &'static str,
    pub code_object_target: String,
    pub code_object_sha256: String,
    pub code_object_size: usize,
    pub required_kernel_count: usize,
    pub code_object_load_request_count: usize,
    pub loaded_code_object_count: usize,
    pub code_object_base_bound: bool,
    pub kernel_descriptor_binding_request_count: usize,
    pub kernel_descriptor_bound_count: usize,
    pub all_kernel_descriptors_bound: bool,
    pub request_plan_ready: bool,
    pub unresolved_runtime_requirements: Vec<&'static str>,
    pub kernels: Vec<RuntimeLaunchCodeObjectKernelDescriptorRequest>,
}

impl ModelRuntimeLaunchCodeObjectLoadRequestPlan {
    pub fn kernel_for(
        &self,
        symbol: &str,
    ) -> Option<&RuntimeLaunchCodeObjectKernelDescriptorRequest> {
        self.kernels.iter().find(|kernel| kernel.symbol == symbol)
    }

    pub fn code_object_base_binding_request_plan(
        &self,
        live_relocation_bindings: &ModelRuntimeLaunchAqlLiveRelocationBindingPlan,
    ) -> Result<ModelRuntimeLaunchCodeObjectBaseBindingRequestPlan> {
        runtime_launch_code_object_base_binding_request_plan_from(self, live_relocation_bindings)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.kernels.len() != self.required_kernel_count {
            issues.push(format!(
                "kernel entries {} != required kernel count {}",
                self.kernels.len(),
                self.required_kernel_count
            ));
        }
        if self.code_object_load_request_count != 1 {
            issues.push(format!(
                "code object load request count {} != 1",
                self.code_object_load_request_count
            ));
        }
        if self.loaded_code_object_count != 0 {
            issues.push(format!(
                "loaded code object count {} != 0",
                self.loaded_code_object_count
            ));
        }
        if self.code_object_base_bound {
            issues.push("code object base is unexpectedly bound".to_string());
        }
        if self.kernel_descriptor_binding_request_count != self.required_kernel_count {
            issues.push(format!(
                "kernel descriptor binding request count {} != required kernel count {}",
                self.kernel_descriptor_binding_request_count, self.required_kernel_count
            ));
        }
        if self.kernel_descriptor_bound_count != 0 {
            issues.push(format!(
                "kernel descriptor bound count {} != 0",
                self.kernel_descriptor_bound_count
            ));
        }
        if self.all_kernel_descriptors_bound {
            issues.push("kernel descriptors are unexpectedly all bound".to_string());
        }
        if !self.request_plan_ready {
            issues.push("code object load request plan is not ready".to_string());
        }
        if self.unresolved_runtime_requirements
            != MODEL_RUNTIME_CODE_OBJECT_LOAD_REQUEST_UNRESOLVED_RUNTIME_REQUIREMENTS
        {
            issues.push(format!(
                "unresolved runtime requirements changed: {}",
                self.unresolved_runtime_requirements.join(", ")
            ));
        }

        let mut seen_symbols = BTreeSet::new();
        let mut descriptor_bound_count = 0usize;
        for kernel in &self.kernels {
            if kernel.symbol.is_empty() {
                issues.push("kernel descriptor request has empty symbol".to_string());
            }
            if !seen_symbols.insert(kernel.symbol.as_str()) {
                issues.push(format!(
                    "kernel descriptor request {} appears more than once",
                    kernel.symbol
                ));
            }
            if kernel.kernel_descriptor_vaddr == 0 {
                issues.push(format!(
                    "kernel descriptor request {} has zero code-object descriptor offset",
                    kernel.symbol
                ));
            }
            if kernel.kernarg_segment_align == 0 {
                issues.push(format!(
                    "kernel descriptor request {} has zero kernarg alignment",
                    kernel.symbol
                ));
            }
            if kernel.descriptor_binding_bound {
                descriptor_bound_count += 1;
                issues.push(format!(
                    "kernel descriptor request {} is unexpectedly bound",
                    kernel.symbol
                ));
            }
        }
        if descriptor_bound_count != self.kernel_descriptor_bound_count {
            issues.push(format!(
                "descriptor bound count {descriptor_bound_count} != plan {}",
                self.kernel_descriptor_bound_count
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "runtime launch code object load request plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }
}

fn runtime_launch_code_object_load_request_plan_from(
    metadata: &ModelRuntimeLaunchKernelMetadataPlan,
) -> Result<ModelRuntimeLaunchCodeObjectLoadRequestPlan> {
    let kernels = metadata
        .kernels
        .iter()
        .map(|kernel| RuntimeLaunchCodeObjectKernelDescriptorRequest {
            symbol: kernel.symbol.clone(),
            kernel_descriptor_vaddr: kernel.kernel_descriptor_vaddr,
            group_segment_size: kernel.group_segment_size,
            private_segment_size: kernel.private_segment_size,
            kernarg_size: kernel.kernarg_size,
            kernarg_segment_align: kernel.kernarg_segment_align,
            wavefront_size: kernel.wavefront_size,
            max_flat_workgroup_size: kernel.max_flat_workgroup_size,
            descriptor_binding_bound: false,
        })
        .collect::<Vec<_>>();
    let plan = ModelRuntimeLaunchCodeObjectLoadRequestPlan {
        target: metadata.target,
        code_object_target: metadata.code_object_target.clone(),
        code_object_sha256: metadata.code_object_sha256.clone(),
        code_object_size: metadata.code_object_size,
        required_kernel_count: metadata.required_kernel_count,
        code_object_load_request_count: 1,
        loaded_code_object_count: 0,
        code_object_base_bound: false,
        kernel_descriptor_binding_request_count: kernels.len(),
        kernel_descriptor_bound_count: 0,
        all_kernel_descriptors_bound: false,
        request_plan_ready: true,
        unresolved_runtime_requirements:
            MODEL_RUNTIME_CODE_OBJECT_LOAD_REQUEST_UNRESOLVED_RUNTIME_REQUIREMENTS.to_vec(),
        kernels,
    };
    plan.assert_consistent()?;
    Ok(plan)
}

