fn extend_unique_strings(out: &mut Vec<String>, values: &[String]) {
    for value in values {
        if !out.contains(value) {
            out.push(value.clone());
        }
    }
}

fn extend_unique_static_strs(out: &mut Vec<&'static str>, values: &[&'static str]) {
    for value in values {
        if !out.contains(value) {
            out.push(*value);
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeLaunchSlotArgumentBinding {
    pub slot: usize,
    pub argument_access: RuntimeDispatchSlotArgumentAccess,
    pub handle: RuntimeLaunchSlotHandle,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RuntimeLaunchArgumentValue {
    Slot(RuntimeLaunchSlotArgumentBinding),
    Scalar(RuntimeDispatchScalarValue),
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeLaunchArgumentBinding {
    pub name: &'static str,
    pub value: RuntimeLaunchArgumentValue,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeDispatchLaunchArgumentEntry {
    pub op_index: usize,
    pub op_name: String,
    pub kind: PrimitiveKind,
    pub stage_name: String,
    pub stage_kind: ModelStageKind,
    pub entrypoint_symbols: Vec<String>,
    pub arguments: Vec<RuntimeLaunchArgumentBinding>,
}

impl RuntimeDispatchLaunchArgumentEntry {
    pub fn argument_for(&self, name: &str) -> Option<&RuntimeLaunchArgumentBinding> {
        self.arguments.iter().find(|argument| argument.name == name)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeStageLaunchArgumentEntry {
    pub stage_index: usize,
    pub stage_name: String,
    pub kind: ModelStageKind,
    pub dispatches: Vec<RuntimeDispatchLaunchArgumentEntry>,
    pub argument_count: usize,
}

impl RuntimeStageLaunchArgumentEntry {
    pub fn dispatch_for(&self, op_name: &str) -> Option<&RuntimeDispatchLaunchArgumentEntry> {
        self.dispatches
            .iter()
            .find(|dispatch| dispatch.op_name == op_name)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchArgumentPlan {
    pub target: &'static str,
    pub stages: Vec<RuntimeStageLaunchArgumentEntry>,
    pub dispatch_count: usize,
    pub argument_count: usize,
}

impl ModelRuntimeLaunchArgumentPlan {
    pub fn stage_for(&self, stage_name: &str) -> Option<&RuntimeStageLaunchArgumentEntry> {
        self.stages
            .iter()
            .find(|stage| stage.stage_name == stage_name)
    }

    pub fn dispatch_for(&self, op_name: &str) -> Option<&RuntimeDispatchLaunchArgumentEntry> {
        self.stages
            .iter()
            .flat_map(|stage| stage.dispatches.iter())
            .find(|dispatch| dispatch.op_name == op_name)
    }
}

fn runtime_launch_argument_plan_from(
    candidates: &ModelRuntimeStageLaunchCandidatePlan,
) -> Result<ModelRuntimeLaunchArgumentPlan> {
    let mut dispatch_count = 0usize;
    let mut argument_count = 0usize;
    let stages = candidates
        .stages
        .iter()
        .map(|stage| {
            let entry = runtime_stage_launch_argument_entry_from(stage)?;
            dispatch_count += entry.dispatches.len();
            argument_count += entry.argument_count;
            Ok(entry)
        })
        .collect::<Result<Vec<_>>>()?;

    Ok(ModelRuntimeLaunchArgumentPlan {
        target: candidates.target,
        stages,
        dispatch_count,
        argument_count,
    })
}

fn runtime_stage_launch_argument_entry_from(
    stage: &RuntimeStageLaunchCandidateEntry,
) -> Result<RuntimeStageLaunchArgumentEntry> {
    let dispatches = stage
        .dispatches
        .iter()
        .map(runtime_dispatch_launch_argument_entry_from)
        .collect::<Result<Vec<_>>>()?;
    let argument_count = dispatches
        .iter()
        .map(|dispatch| dispatch.arguments.len())
        .sum();
    Ok(RuntimeStageLaunchArgumentEntry {
        stage_index: stage.stage_index,
        stage_name: stage.stage_name.clone(),
        kind: stage.kind,
        dispatches,
        argument_count,
    })
}

fn runtime_dispatch_launch_argument_entry_from(
    dispatch: &RuntimeDispatchLaunchCandidate,
) -> Result<RuntimeDispatchLaunchArgumentEntry> {
    let mut seen_argument_names = BTreeSet::new();
    let mut arguments = Vec::new();

    for argument in &dispatch.slot_arguments {
        if !seen_argument_names.insert(argument.name) {
            return Err(anyhow!(
                "runtime launch argument plan dispatch {} has duplicate argument name {}",
                dispatch.op_name,
                argument.name
            ));
        }
        let handle = match argument.access {
            RuntimeDispatchSlotArgumentAccess::Read => dispatch.read_handle_for(argument.slot),
            RuntimeDispatchSlotArgumentAccess::Write => dispatch.write_handle_for(argument.slot),
        }
        .cloned()
        .ok_or_else(|| {
            anyhow!(
                "runtime launch argument plan dispatch {} argument {} slot {} has no {:?} handle",
                dispatch.op_name,
                argument.name,
                argument.slot,
                argument.access
            )
        })?;
        arguments.push(RuntimeLaunchArgumentBinding {
            name: argument.name,
            value: RuntimeLaunchArgumentValue::Slot(RuntimeLaunchSlotArgumentBinding {
                slot: argument.slot,
                argument_access: argument.access,
                handle,
            }),
        });
    }

    for argument in &dispatch.scalar_arguments {
        if !seen_argument_names.insert(argument.name) {
            return Err(anyhow!(
                "runtime launch argument plan dispatch {} has duplicate argument name {}",
                dispatch.op_name,
                argument.name
            ));
        }
        arguments.push(RuntimeLaunchArgumentBinding {
            name: argument.name,
            value: RuntimeLaunchArgumentValue::Scalar(argument.value.clone()),
        });
    }

    Ok(RuntimeDispatchLaunchArgumentEntry {
        op_index: dispatch.op_index,
        op_name: dispatch.op_name.clone(),
        kind: dispatch.kind,
        stage_name: dispatch.stage_name.clone(),
        stage_kind: dispatch.stage_kind,
        entrypoint_symbols: dispatch.entrypoint_symbols.clone(),
        arguments,
    })
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeLaunchWindowEntry {
    pub window_index: usize,
    pub stage_index: usize,
    pub stage_name: String,
    pub stage_kind: ModelStageKind,
    pub stage_window_index: usize,
    pub first_op_index: usize,
    pub dispatch_count: usize,
    pub dispatch_names: Vec<String>,
    pub entrypoint_symbols: Vec<String>,
    pub required_slots: Vec<usize>,
    pub resource_handles: Vec<RuntimeLaunchSlotHandle>,
    pub chain_barrier_count: usize,
    pub terminal_signal_required: bool,
}

impl RuntimeLaunchWindowEntry {
    pub fn resource_handle_for(&self, slot: usize) -> Option<&RuntimeLaunchSlotHandle> {
        self.resource_handles
            .iter()
            .find(|handle| handle.slot == slot)
    }

    pub fn contains_dispatch(&self, op_name: &str) -> bool {
        self.dispatch_names.iter().any(|name| name == op_name)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuntimeStageLaunchWindowSummary {
    pub stage_index: usize,
    pub stage_name: String,
    pub kind: ModelStageKind,
    pub dispatch_count: usize,
    pub window_indices: Vec<usize>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ModelRuntimeLaunchWindowPlan {
    pub target: &'static str,
    pub max_dispatches_per_window: usize,
    pub dispatch_count: usize,
    pub window_count: usize,
    pub stages: Vec<RuntimeStageLaunchWindowSummary>,
    pub windows: Vec<RuntimeLaunchWindowEntry>,
}

impl ModelRuntimeLaunchWindowPlan {
    pub fn stage_for(&self, stage_name: &str) -> Option<&RuntimeStageLaunchWindowSummary> {
        self.stages
            .iter()
            .find(|stage| stage.stage_name == stage_name)
    }

    pub fn window_for(&self, window_index: usize) -> Option<&RuntimeLaunchWindowEntry> {
        self.windows
            .iter()
            .find(|window| window.window_index == window_index)
    }

    pub fn windows_for_stage(&self, stage_name: &str) -> Vec<&RuntimeLaunchWindowEntry> {
        self.windows
            .iter()
            .filter(|window| window.stage_name == stage_name)
            .collect()
    }
}

fn runtime_launch_window_plan_from(
    candidates: &ModelRuntimeStageLaunchCandidatePlan,
    max_dispatches_per_window: usize,
) -> Result<ModelRuntimeLaunchWindowPlan> {
    if max_dispatches_per_window == 0 {
        return Err(anyhow!(
            "runtime launch window plan for {} requires non-zero max dispatches per window",
            candidates.target
        ));
    }

    let mut windows = Vec::new();
    let mut stages = Vec::new();
    let mut dispatch_count = 0usize;

    for stage in &candidates.stages {
        let mut window_indices = Vec::new();
        let mut stage_window_index = 0usize;
        let mut offset = 0usize;
        while offset < stage.dispatches.len() {
            let end = (offset + max_dispatches_per_window).min(stage.dispatches.len());
            let dispatches = &stage.dispatches[offset..end];
            let window_index = windows.len();
            let first = dispatches.first().ok_or_else(|| {
                anyhow!(
                    "runtime launch window plan stage {} has an empty dispatch window",
                    stage.stage_name
                )
            })?;
            let dispatch_names = dispatches
                .iter()
                .map(|dispatch| dispatch.op_name.clone())
                .collect::<Vec<_>>();
            let mut entrypoint_symbols = Vec::new();
            let mut used_slots = BTreeSet::new();
            for dispatch in dispatches {
                for symbol in &dispatch.entrypoint_symbols {
                    if !entrypoint_symbols.contains(symbol) {
                        entrypoint_symbols.push(symbol.clone());
                    }
                }
                for handle in dispatch
                    .read_handles
                    .iter()
                    .chain(dispatch.write_handles.iter())
                {
                    used_slots.insert(handle.slot);
                }
            }
            let required_slots = used_slots.iter().copied().collect::<Vec<_>>();
            let resource_handles = required_slots
                .iter()
                .map(|slot| {
                    stage.resource_handle_for(*slot).cloned().ok_or_else(|| {
                        anyhow!(
                            "runtime launch window plan stage {} window {} missing resource handle for slot {}",
                            stage.stage_name,
                            stage_window_index,
                            slot
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            let dispatch_len = dispatches.len();

            windows.push(RuntimeLaunchWindowEntry {
                window_index,
                stage_index: stage.stage_index,
                stage_name: stage.stage_name.clone(),
                stage_kind: stage.kind,
                stage_window_index,
                first_op_index: first.op_index,
                dispatch_count: dispatch_len,
                dispatch_names,
                entrypoint_symbols,
                required_slots,
                resource_handles,
                chain_barrier_count: dispatch_len.saturating_sub(1),
                terminal_signal_required: true,
            });
            window_indices.push(window_index);
            dispatch_count += dispatch_len;
            stage_window_index += 1;
            offset = end;
        }

        stages.push(RuntimeStageLaunchWindowSummary {
            stage_index: stage.stage_index,
            stage_name: stage.stage_name.clone(),
            kind: stage.kind,
            dispatch_count: stage.dispatches.len(),
            window_indices,
        });
    }

    Ok(ModelRuntimeLaunchWindowPlan {
        target: candidates.target,
        max_dispatches_per_window,
        dispatch_count,
        window_count: windows.len(),
        stages,
        windows,
    })
}

fn runtime_stage_launch_candidate_plan_from(
    stage_dispatch_bindings: &ModelRuntimeStageDispatchBindingValidation,
) -> Result<ModelRuntimeStageLaunchCandidatePlan> {
    stage_dispatch_bindings.assert_complete()?;

    let gap_dispatches = stage_dispatch_bindings
        .stages
        .iter()
        .flat_map(|stage| {
            stage
                .dispatch_bindings
                .iter()
                .filter(|dispatch| dispatch.route.status.is_gap())
                .map(move |dispatch| format!("{}:{}", stage.stage_name, dispatch.op_name))
        })
        .collect::<Vec<_>>();
    if !gap_dispatches.is_empty() {
        return Err(anyhow!(
            "runtime stage launch candidate plan for {} contains lowering gap dispatch(es): {}",
            stage_dispatch_bindings.target,
            gap_dispatches.join(", ")
        ));
    }

    let missing_entrypoints = stage_dispatch_bindings
        .stages
        .iter()
        .flat_map(|stage| {
            stage.dispatch_bindings.iter().filter_map(move |dispatch| {
                if dispatch.entrypoint_symbols.is_empty() {
                    Some(format!("{}:{}", stage.stage_name, dispatch.op_name))
                } else {
                    None
                }
            })
        })
        .collect::<Vec<_>>();
    if !missing_entrypoints.is_empty() {
        return Err(anyhow!(
            "runtime stage launch candidate plan for {} is missing entrypoint symbols: {}",
            stage_dispatch_bindings.target,
            missing_entrypoints.join(", ")
        ));
    }

    let mut dispatch_count = 0usize;
    let stages = stage_dispatch_bindings
        .stages
        .iter()
        .map(|stage| {
            let dispatches = stage
                .dispatch_bindings
                .iter()
                .map(runtime_dispatch_launch_candidate_from)
                .collect::<Result<Vec<_>>>()?;
            dispatch_count += dispatches.len();

            let op_names = dispatches
                .iter()
                .map(|dispatch| dispatch.op_name.clone())
                .collect::<Vec<_>>();
            let mut entrypoint_symbols = Vec::new();
            let mut handle_by_slot = BTreeMap::new();
            for dispatch in &dispatches {
                for symbol in &dispatch.entrypoint_symbols {
                    if !entrypoint_symbols.contains(symbol) {
                        entrypoint_symbols.push(symbol.clone());
                    }
                }
                for handle in dispatch
                    .read_handles
                    .iter()
                    .chain(dispatch.write_handles.iter())
                {
                    handle_by_slot
                        .entry(handle.slot)
                        .or_insert_with(|| handle.clone());
                }
            }
            let resource_handles = stage
                .required_slots
                .iter()
                .map(|slot| {
                    handle_by_slot.get(slot).cloned().ok_or_else(|| {
                        anyhow!(
                            "runtime stage launch candidate plan stage {} missing resource handle for slot {}",
                            stage.stage_name,
                            slot
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?;

            Ok(RuntimeStageLaunchCandidateEntry {
                stage_index: stage.stage_index,
                stage_name: stage.stage_name.clone(),
                kind: stage.kind,
                required_slots: stage.required_slots.clone(),
                resource_handles,
                op_names,
                entrypoint_symbols,
                dispatches,
            })
        })
        .collect::<Result<Vec<_>>>()?;

    Ok(ModelRuntimeStageLaunchCandidatePlan {
        target: stage_dispatch_bindings.target,
        stages,
        dispatch_count,
    })
}

fn runtime_dispatch_launch_candidate_from(
    dispatch: &RuntimeDispatchBindingValidationEntry,
) -> Result<RuntimeDispatchLaunchCandidate> {
    let stage_name = dispatch.stage_name.clone().ok_or_else(|| {
        anyhow!(
            "runtime launch candidate dispatch {} is not assigned to a stage",
            dispatch.op_name
        )
    })?;
    let stage_kind = dispatch.stage_kind.ok_or_else(|| {
        anyhow!(
            "runtime launch candidate dispatch {} has no stage kind",
            dispatch.op_name
        )
    })?;
    Ok(RuntimeDispatchLaunchCandidate {
        op_index: dispatch.op_index,
        op_name: dispatch.op_name.clone(),
        kind: dispatch.kind,
        stage_name,
        stage_kind,
        route: dispatch.route.clone(),
        entrypoint_symbols: dispatch.entrypoint_symbols.clone(),
        slot_arguments: dispatch.slot_arguments.clone(),
        scalar_arguments: dispatch.scalar_arguments.clone(),
        read_handles: runtime_launch_slot_handles(
            &dispatch.op_name,
            "read",
            &dispatch.read_bindings,
        )?,
        write_handles: runtime_launch_slot_handles(
            &dispatch.op_name,
            "write",
            &dispatch.write_bindings,
        )?,
    })
}

fn runtime_launch_slot_handles(
    op_name: &str,
    direction: &str,
    bindings: &[RuntimeDispatchSlotBindingRef],
) -> Result<Vec<RuntimeLaunchSlotHandle>> {
    bindings
        .iter()
        .map(|binding_ref| {
            let binding = binding_ref.binding.as_ref().ok_or_else(|| {
                anyhow!(
                    "runtime launch candidate dispatch {} has unbound {} slot {}",
                    op_name,
                    direction,
                    binding_ref.slot
                )
            })?;
            let tensor = binding_ref.tensor.clone().ok_or_else(|| {
                anyhow!(
                    "runtime launch candidate dispatch {} {} slot {} has no tensor metadata",
                    op_name,
                    direction,
                    binding_ref.slot
                )
            })?;
            let class = binding_ref.class.ok_or_else(|| {
                anyhow!(
                    "runtime launch candidate dispatch {} {} slot {} has no binding class metadata",
                    op_name,
                    direction,
                    binding_ref.slot
                )
            })?;
            let lifetime_access = binding_ref.lifetime_access.ok_or_else(|| {
                anyhow!(
                    "runtime launch candidate dispatch {} {} slot {} has no lifetime access metadata",
                    op_name,
                    direction,
                    binding_ref.slot
                )
            })?;
            Ok(RuntimeLaunchSlotHandle {
                slot: binding_ref.slot,
                tensor,
                class,
                lifetime_access,
                bytes: binding.bytes,
                access: binding.access,
                handle: binding.handle.clone(),
            })
        })
        .collect()
}

