    pub fn runtime_kfd_alloc_memory_result_binding_plan(
        &self,
        device_pointers: &ModelRuntimeSlotDevicePointerValidation,
        resident_gpu_ids: &[u32],
        result_bindings: &[RuntimeKfdAllocMemoryResultBinding],
    ) -> ModelRuntimeKfdAllocMemoryResultBindingPlan {
        self.runtime_kfd_alloc_memory_request_plan(device_pointers, resident_gpu_ids)
            .kfd_alloc_memory_result_binding_plan(result_bindings)
    }

    pub fn runtime_kfd_map_memory_argument_binding_plan(
        &self,
        device_pointers: &ModelRuntimeSlotDevicePointerValidation,
        resident_gpu_ids: &[u32],
        alloc_memory_result_bindings: &[RuntimeKfdAllocMemoryResultBinding],
        device_ids_array_bindings: &[RuntimeKfdMapMemoryDeviceIdsArrayBinding],
    ) -> ModelRuntimeKfdMapMemoryArgumentBindingPlan {
        let alloc_memory_requests =
            self.runtime_kfd_alloc_memory_request_plan(device_pointers, resident_gpu_ids);
        let map_memory_requests = alloc_memory_requests.kfd_map_memory_request_plan();
        let alloc_memory_results = alloc_memory_requests
            .kfd_alloc_memory_result_binding_plan(alloc_memory_result_bindings);
        map_memory_requests
            .kfd_map_memory_argument_binding_plan(&alloc_memory_results, device_ids_array_bindings)
    }

    pub fn runtime_kfd_map_memory_result_binding_plan(
        &self,
        device_pointers: &ModelRuntimeSlotDevicePointerValidation,
        resident_gpu_ids: &[u32],
        alloc_memory_result_bindings: &[RuntimeKfdAllocMemoryResultBinding],
        device_ids_array_bindings: &[RuntimeKfdMapMemoryDeviceIdsArrayBinding],
        map_memory_result_bindings: &[RuntimeKfdMapMemoryResultBinding],
    ) -> ModelRuntimeKfdMapMemoryResultBindingPlan {
        self.runtime_kfd_map_memory_argument_binding_plan(
            device_pointers,
            resident_gpu_ids,
            alloc_memory_result_bindings,
            device_ids_array_bindings,
        )
        .kfd_map_memory_result_binding_plan(map_memory_result_bindings)
    }

    pub fn runtime_slot_kfd_residency_binding_plan(
        &self,
        device_pointers: &ModelRuntimeSlotDevicePointerValidation,
        resident_gpu_ids: &[u32],
        alloc_memory_result_bindings: &[RuntimeKfdAllocMemoryResultBinding],
        device_ids_array_bindings: &[RuntimeKfdMapMemoryDeviceIdsArrayBinding],
        map_memory_result_bindings: &[RuntimeKfdMapMemoryResultBinding],
    ) -> ModelRuntimeSlotKfdResidencyBindingPlan {
        let allocation_requests = self
            .runtime_slot_kfd_allocation_residency_request_plan(device_pointers, resident_gpu_ids);
        let map_memory_results = self.runtime_kfd_map_memory_result_binding_plan(
            device_pointers,
            resident_gpu_ids,
            alloc_memory_result_bindings,
            device_ids_array_bindings,
            map_memory_result_bindings,
        );
        allocation_requests.kfd_residency_binding_plan(&map_memory_results)
    }

    pub fn runtime_checkpoint_payload_binding_plan(
        &self,
        device_pointers: &ModelRuntimeSlotDevicePointerValidation,
        resident_gpu_ids: &[u32],
        alloc_memory_result_bindings: &[RuntimeKfdAllocMemoryResultBinding],
        device_ids_array_bindings: &[RuntimeKfdMapMemoryDeviceIdsArrayBinding],
        map_memory_result_bindings: &[RuntimeKfdMapMemoryResultBinding],
        key_resolution: &ModelCheckpointKeyResolution,
        payload_bindings: &[RuntimeCheckpointPayloadBinding],
    ) -> ModelRuntimeCheckpointPayloadBindingPlan {
        let kfd_residency = self.runtime_slot_kfd_residency_binding_plan(
            device_pointers,
            resident_gpu_ids,
            alloc_memory_result_bindings,
            device_ids_array_bindings,
            map_memory_result_bindings,
        );
        self.checkpoint.runtime_checkpoint_payload_binding_plan(
            &self.slots,
            key_resolution,
            &kfd_residency,
            payload_bindings,
        )
    }

    pub fn synthetic_cpu_runtime_checkpoint_payload_binding_plan<I, S>(
        &self,
        available_checkpoint_keys: I,
        payload_source: &str,
        resident_gpu_ids: &[u32],
        device_pointer_base_va: u64,
        device_pointer_alignment: u64,
    ) -> Result<ModelRuntimeCheckpointPayloadBindingPlan>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let device_pointer_bindings = self
            .slots
            .device_pointer_binding_template(device_pointer_base_va, device_pointer_alignment)?;
        let device_pointer_validation = self
            .slots
            .validate_complete_device_pointer_bindings(&device_pointer_bindings);
        device_pointer_validation.assert_complete()?;

        let allocation_requests = self.runtime_slot_kfd_allocation_residency_request_plan(
            &device_pointer_validation,
            resident_gpu_ids,
        );
        let vm_acquire_requests = allocation_requests.kfd_vm_acquire_request_plan();
        let alloc_memory_requests =
            allocation_requests.kfd_alloc_memory_request_plan(&vm_acquire_requests);
        let alloc_memory_result_bindings =
            synthetic_cpu_kfd_alloc_memory_result_bindings(&alloc_memory_requests)?;
        let alloc_memory_result_plan = alloc_memory_requests
            .kfd_alloc_memory_result_binding_plan(&alloc_memory_result_bindings);
        alloc_memory_result_plan.assert_kfd_alloc_memory_result_bound()?;

        let map_memory_requests = alloc_memory_requests.kfd_map_memory_request_plan();
        let device_ids_array_bindings =
            synthetic_cpu_kfd_map_memory_device_ids_array_bindings(&map_memory_requests)?;
        let map_memory_argument_plan = map_memory_requests.kfd_map_memory_argument_binding_plan(
            &alloc_memory_result_plan,
            &device_ids_array_bindings,
        );
        map_memory_argument_plan.assert_kfd_map_memory_arguments_bound()?;

        let map_memory_result_bindings =
            synthetic_cpu_kfd_map_memory_result_bindings(&map_memory_argument_plan)?;
        let map_memory_result_plan = map_memory_argument_plan
            .kfd_map_memory_result_binding_plan(&map_memory_result_bindings);
        map_memory_result_plan.assert_kfd_map_memory_result_bound()?;

        let checkpoint_resolution = self
            .checkpoint
            .resolve_against_available_keys(available_checkpoint_keys)?;
        let payload_bindings = synthetic_cpu_checkpoint_payload_bindings_for_resolution(
            &checkpoint_resolution,
            payload_source,
        )?;
        Ok(self.runtime_checkpoint_payload_binding_plan(
            &device_pointer_validation,
            resident_gpu_ids,
            &alloc_memory_result_bindings,
            &device_ids_array_bindings,
            &map_memory_result_bindings,
            &checkpoint_resolution,
            &payload_bindings,
        ))
    }

