    pub fn synthetic_cpu_runtime_checkpoint_payload_binding_plan<I, S>(
        &self,
        available_checkpoint_keys: I,
        payload_source: &str,
        resident_gpu_ids: &[u32],
    ) -> Result<ModelRuntimeCheckpointPayloadBindingPlan>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        self.assert_static_handoff_ready()?;
        let plan = self
            .readiness
            .synthetic_cpu_runtime_checkpoint_payload_binding_plan(
                available_checkpoint_keys,
                payload_source,
                resident_gpu_ids,
                DEFAULT_RUNTIME_SYNTHETIC_DEVICE_POINTER_BASE,
                DEFAULT_RUNTIME_DEVICE_POINTER_ALIGNMENT,
            )?;
        plan.assert_consistent()?;
        Ok(plan)
    }

    pub fn synthetic_cpu_runtime_launch_execution_request_plan(
        &self,
        receipt_namespace: &str,
    ) -> Result<ModelRuntimeLaunchExecutionRequestPlan> {
        validate_name("synthetic CPU runtime launch namespace", receipt_namespace)?;
        self.assert_static_handoff_ready()?;

        let code_object = CodeObjectInfo::inspect(MAINARCH_KERNELS_GFX950)?;
        let slot_bindings = self
            .readiness
            .slots
            .metadata_binding_template(receipt_namespace)?;
        let device_pointer_bindings = self.readiness.slots.device_pointer_binding_template(
            DEFAULT_RUNTIME_SYNTHETIC_DEVICE_POINTER_BASE,
            DEFAULT_RUNTIME_DEVICE_POINTER_ALIGNMENT,
        )?;
        let device_pointer_validation = self
            .readiness
            .slots
            .validate_complete_device_pointer_bindings(&device_pointer_bindings);
        device_pointer_validation.assert_complete()?;

        let execution_requests = self.readiness.runtime_launch_execution_request_plan(
            &slot_bindings,
            &code_object,
            DEFAULT_RUNTIME_LAUNCH_WINDOW_DISPATCHES,
            &device_pointer_validation,
        )?;
        execution_requests.assert_non_submitting_boundary()?;
        Ok(execution_requests)
    }

