    #[test]
    fn reference_moe_tensor_storage_plan_reports_role_footprint() {
        let graph = reference_graph_with_layers(1);
        let plan = graph.tensor_storage_plan().unwrap();
        assert_eq!(plan.entries.len(), graph.tensors.len());

        let summed = plan
            .entries
            .iter()
            .map(|entry| entry.storage_bytes)
            .sum::<usize>();
        assert_eq!(plan.footprint.total_bytes, summed);
        assert_eq!(
            plan.footprint.bytes_for_role(TensorRole::KvCache),
            2 * (128 * 4 * 128 / 2)
        );

        let embed = plan.entry_for("embed_tokens.weight").unwrap();
        assert_eq!(embed.role, TensorRole::Weight);
        assert_eq!(embed.elements, 1024 * 4096);
        assert_eq!(embed.storage_bytes, 1024 * 4096 * 2);

        let k_cache = plan.entry_for("layers.0.kv_cache.k").unwrap();
        assert_eq!(k_cache.dtype, DType::Fp4E2M1);
        assert_eq!(k_cache.elements, 128 * 4 * 128);
        assert_eq!(k_cache.storage_bytes, 128 * 4 * 128 / 2);
        assert!(plan.footprint.weight_bytes > plan.footprint.kv_cache_bytes);
        assert!(plan.footprint.activation_bytes > 0);
        assert!(plan.footprint.metadata_bytes > 0);
        assert!(plan.footprint.routing_bytes > 0);
    }

    #[test]
    fn reference_moe_tensor_access_plan_reports_runtime_bindings() {
        let graph = reference_graph_with_layers(1);
        let plan = graph.tensor_access_plan().unwrap();
        assert_eq!(plan.entries.len(), graph.ops.len());

        let embed = plan.entry_for("embed_tokens").unwrap();
        assert_eq!(embed.kind, PrimitiveKind::EmbeddingLookup);
        assert_eq!(
            embed.reads,
            refs(&["tokens.current", "embed_tokens.weight"])
        );
        assert_eq!(embed.writes, refs(&["hidden.0"]));
        assert_eq!(plan.writers_for("hidden.0").len(), 1);

        let cache_append = plan.entry_for("layers.0.kv_cache_append").unwrap();
        assert_eq!(
            cache_append.reads,
            refs(&["layers.0.k_rope", "layers.0.v", "block_table", "position"])
        );
        assert_eq!(
            cache_append.writes,
            refs(&["layers.0.kv_cache.k", "layers.0.kv_cache.v"])
        );

        let attention = plan.entry_for("layers.0.paged_gqa_attention").unwrap();
        assert_eq!(
            attention.reads,
            refs(&[
                "layers.0.q_rope",
                "block_table",
                "seq_len",
                "layers.0.kv_cache.k",
                "layers.0.kv_cache.v"
            ])
        );
        assert_eq!(attention.writes, refs(&["layers.0.attn_out"]));
        assert_eq!(plan.readers_for("layers.0.kv_cache.k").len(), 1);

        let router = plan.entry_for("layers.0.router_topk").unwrap();
        assert_eq!(
            router.reads,
            refs(&["layers.0.post_norm", "layers.0.router.weight"])
        );
        assert_eq!(
            router.writes,
            refs(&["layers.0.expert_ids", "layers.0.expert_weights"])
        );

        let moe = plan.entry_for("layers.0.moe_local_ffn").unwrap();
        assert!(moe.reads_tensor("layers.0.expert_ids"));
        assert!(moe.reads_tensor("layers.0.expert_weights"));
        assert!(moe.writes_tensor("layers.0.moe_partial"));
    }

    #[test]
    fn reference_moe_tensor_lifetime_plan_reports_static_ranges() {
        let graph = reference_graph_with_layers(1);
        let storage = graph.tensor_storage_plan().unwrap();
        let plan = graph.tensor_lifetime_plan().unwrap();
        assert_eq!(plan.entries.len(), graph.tensors.len());
        assert_eq!(plan.total_storage_bytes, storage.footprint.total_bytes);
        assert!(plan.unused_tensors.is_empty());

        let hidden0 = plan.entry_for("hidden.0").unwrap();
        assert_eq!(hidden0.write_count, 1);
        assert_eq!(hidden0.read_count, 2);
        assert_eq!(hidden0.first_op_name.as_deref(), Some("embed_tokens"));
        assert_eq!(
            hidden0.last_op_name.as_deref(),
            Some("layers.0.attention_residual_rmsnorm")
        );
        assert!(hidden0.first_op_index < hidden0.last_op_index);

        let k_cache = plan.entry_for("layers.0.kv_cache.k").unwrap();
        assert_eq!(k_cache.role, TensorRole::KvCache);
        assert_eq!(k_cache.write_count, 1);
        assert_eq!(k_cache.read_count, 1);
        assert_eq!(
            k_cache.first_op_name.as_deref(),
            Some("layers.0.kv_cache_append")
        );
        assert_eq!(
            k_cache.last_op_name.as_deref(),
            Some("layers.0.paged_gqa_attention")
        );

        let router_weight = plan.entry_for("layers.0.router.weight").unwrap();
        assert_eq!(router_weight.role, TensorRole::Weight);
        assert_eq!(router_weight.write_count, 0);
        assert_eq!(router_weight.read_count, 1);
        assert_eq!(
            router_weight.first_op_name.as_deref(),
            Some("layers.0.router_topk")
        );

        let next_token = plan.entry_for("tokens.next").unwrap();
        assert_eq!(next_token.role, TensorRole::Token);
        assert_eq!(next_token.write_count, 1);
        assert_eq!(next_token.read_count, 0);
        assert_eq!(next_token.last_op_name.as_deref(), Some("greedy_argmax"));
    }

    #[test]
    fn reference_moe_tensor_binding_plan_classifies_runtime_contract() {
        let graph = reference_graph_with_layers(1);
        let storage = graph.tensor_storage_plan().unwrap();
        let plan = graph.tensor_binding_plan().unwrap();
        assert_eq!(plan.entries.len(), graph.tensors.len());
        assert_eq!(plan.footprint.total_bytes, storage.footprint.total_bytes);
        assert!(plan.issues.is_empty());
        plan.assert_no_binding_issues().unwrap();

        assert!(plan
            .external_inputs
            .contains(&TensorRef::from("tokens.current")));
        assert!(plan.external_inputs.contains(&TensorRef::from("position")));
        assert!(plan
            .external_inputs
            .contains(&TensorRef::from("block_table")));
        assert!(plan.external_inputs.contains(&TensorRef::from("seq_len")));
        assert!(plan
            .external_outputs
            .contains(&TensorRef::from("tokens.next")));
        assert!(plan
            .checkpoint_weights
            .contains(&TensorRef::from("embed_tokens.weight")));
        assert!(plan
            .persistent_state
            .contains(&TensorRef::from("layers.0.kv_cache.k")));
        assert!(plan.scratch_tensors.contains(&TensorRef::from("hidden.0")));
        assert!(plan
            .scratch_tensors
            .contains(&TensorRef::from("layers.0.expert_ids")));

        let current_token = plan.entry_for("tokens.current").unwrap();
        assert_eq!(current_token.class, TensorBindingClass::ExternalInput);
        assert_eq!(current_token.access, TensorBindingAccess::ReadOnly);

        let next_token = plan.entry_for("tokens.next").unwrap();
        assert_eq!(next_token.class, TensorBindingClass::ExternalOutput);
        assert_eq!(next_token.access, TensorBindingAccess::WriteOnly);

        let embed_weight = plan.entry_for("embed_tokens.weight").unwrap();
        assert_eq!(embed_weight.class, TensorBindingClass::CheckpointWeight);
        assert_eq!(embed_weight.access, TensorBindingAccess::ReadOnly);
        assert_eq!(
            embed_weight.checkpoint_key.as_deref(),
            Some("model.embed_tokens.weight")
        );

        let k_cache = plan.entry_for("layers.0.kv_cache.k").unwrap();
        assert_eq!(k_cache.class, TensorBindingClass::PersistentState);
        assert_eq!(k_cache.access, TensorBindingAccess::ReadWrite);

        let logits = plan.entry_for("logits").unwrap();
        assert_eq!(logits.class, TensorBindingClass::Scratch);
        assert_eq!(logits.access, TensorBindingAccess::ReadWrite);
    }

    #[test]
    fn tensor_binding_plan_reports_role_access_issues() {
        let mut builder = ModelPrimitiveGraphBuilder::new("bad-binding-role");
        for spec in [
            TensorSpec::new(
                "scratch_logits",
                DType::F16,
                vec![4],
                TensorRole::Activation,
            ),
            TensorSpec::new("next", DType::U32, vec![1], TensorRole::Token),
        ] {
            builder.declare_tensor(spec).unwrap();
        }
        builder
            .begin_stage("sampled", ModelStageKind::Sampling)
            .unwrap();
        builder
            .emit(PrimitiveOp::ArgmaxSample(ArgmaxSample {
                name: "sample".to_string(),
                logits: "scratch_logits".into(),
                output_token: "next".into(),
                vocab: 4,
            }))
            .unwrap();
        builder.end_stage().unwrap();
        let graph = builder.build().unwrap();
        let plan = graph.tensor_binding_plan().unwrap();
        let scratch = plan.entry_for("scratch_logits").unwrap();
        assert_eq!(scratch.class, TensorBindingClass::Scratch);
        assert_eq!(scratch.access, TensorBindingAccess::ReadOnly);
        assert_eq!(plan.issues.len(), 1);
        assert_eq!(plan.issues[0].tensor, TensorRef::from("scratch_logits"));
        assert!(plan
            .assert_no_binding_issues()
            .unwrap_err()
            .to_string()
            .contains("scratch tensor is read but never produced"));
        let readiness = graph
            .readiness_report(&MainarchPrimitiveLoweringCatalog::default())
            .unwrap();
        let issues = readiness.static_readiness_issues();
        let binding_issues = issues.issues_for_kind(ModelReadinessIssueKind::TensorBinding);
        assert_eq!(binding_issues.len(), 1);
        assert_eq!(binding_issues[0].surface, "tensor_binding");
        assert_eq!(binding_issues[0].subject, "scratch_logits");
        assert!(binding_issues[0]
            .message
            .contains("scratch tensor is read but never produced"));
        assert!(!issues.is_ready());
        assert!(issues
            .assert_ready()
            .unwrap_err()
            .to_string()
            .contains("scratch_logits"));
        assert!(readiness
            .assert_static_runtime_ready()
            .unwrap_err()
            .to_string()
            .contains("scratch tensor is read but never produced"));
    }

