    #[test]
    fn checkpoint_key_resolution_matches_exact_and_wildcard_keys() {
        let exact = checkpoint_binding("exact", "model.exact.weight", vec![4]);
        let packed = checkpoint_binding(
            "packed_experts",
            "model.layers.0.mlp.experts.*.gate_proj.weight",
            vec![2, 4],
        );
        let missing = checkpoint_binding("missing", "model.missing.weight", vec![4]);
        let total_checkpoint_bytes =
            exact.storage_bytes + packed.storage_bytes + missing.storage_bytes;
        let plan = ModelCheckpointBindingPlan {
            entries: vec![exact, packed, missing],
            missing_weight_tensors: Vec::new(),
            total_checkpoint_bytes,
        };

        let resolution = plan
            .resolve_against_available_keys([
                "model.exact.weight",
                "model.layers.0.mlp.experts.0.gate_proj.weight",
                "model.layers.0.mlp.experts.1.gate_proj.weight",
                "model.extra.weight",
            ])
            .unwrap();

        assert_eq!(resolution.resolved_entries.len(), 2);
        assert_eq!(
            resolution
                .resolved_entry_for("exact")
                .unwrap()
                .matched_checkpoint_keys,
            vec!["model.exact.weight".to_string()]
        );
        assert_eq!(
            resolution
                .resolved_entry_for("packed_experts")
                .unwrap()
                .matched_checkpoint_keys,
            vec![
                "model.layers.0.mlp.experts.0.gate_proj.weight".to_string(),
                "model.layers.0.mlp.experts.1.gate_proj.weight".to_string()
            ]
        );
        assert_eq!(
            resolution.missing_checkpoint_entries,
            vec![MissingCheckpointEntry {
                tensor: TensorRef::from("missing"),
                checkpoint_key: "model.missing.weight".to_string(),
            }]
        );
        assert_eq!(
            resolution.unmatched_checkpoint_keys,
            vec!["model.extra.weight".to_string()]
        );
        assert!(resolution
            .assert_fully_resolved()
            .unwrap_err()
            .to_string()
            .contains("model.missing.weight"));
    }

