    #[test]
    fn stage_coverage_reports_unstaged_ops() {
        let mut builder = ModelPrimitiveGraphBuilder::new("partial-stage");
        for spec in [
            TensorSpec::new("logits", DType::F16, vec![4], TensorRole::Logits),
            TensorSpec::new("next", DType::U32, vec![1], TensorRole::Token),
        ] {
            builder.declare_tensor(spec).unwrap();
        }
        builder
            .begin_stage("sampled", ModelStageKind::Sampling)
            .unwrap();
        builder
            .emit(PrimitiveOp::ArgmaxSample(ArgmaxSample {
                name: "sample0".to_string(),
                logits: "logits".into(),
                output_token: "next".into(),
                vocab: 4,
            }))
            .unwrap();
        builder.end_stage().unwrap();
        builder
            .emit(PrimitiveOp::ArgmaxSample(ArgmaxSample {
                name: "sample1".to_string(),
                logits: "logits".into(),
                output_token: "next".into(),
                vocab: 4,
            }))
            .unwrap();
        let graph = builder.build().unwrap();
        let report = graph.validate().unwrap();
        assert_eq!(report.stages, 1);
        assert_eq!(report.staged_ops, 1);
        assert_eq!(report.unstaged_ops, 1);
        assert!(graph
            .assert_all_ops_staged()
            .unwrap_err()
            .to_string()
            .contains("sample1"));
    }

