        assert_eq!(plan.gap_ops, 0);
        assert_eq!(plan.fused_native_gpu_ops, 1);
        assert_eq!(
            plan.native_gpu_ops + plan.fused_native_gpu_ops,
            graph.ops.len()
        );
        plan.assert_fully_staged_no_gaps().unwrap();

        let embedding = plan.stage_for("embedding").unwrap();
        assert_eq!(embedding.kind, ModelStageKind::Embedding);
        assert_eq!(embedding.op_count, 1);
        assert_eq!(embedding.fused_native_gpu_ops, 1);

        let attention = plan.stage_for("layers.0.attention").unwrap();
        assert_eq!(attention.kind, ModelStageKind::Attention);
