        assert!(!missing_gpu_alloc_memory_requests.allocation_residency_request_ready);
        assert!(!missing_gpu_alloc_memory_requests.vm_acquire_request_metadata_ready);
        assert!(!missing_gpu_alloc_memory_requests.all_request_metadata_ready);
        let err = missing_gpu_alloc_memory_requests
            .assert_kfd_alloc_memory_request_ready()
            .unwrap_err()
            .to_string();
        assert!(err.contains("slot KFD allocation/residency request plan is not ready"));
        assert!(err.contains("KFD VM-acquire request metadata is not ready"));
        assert!(err.contains("no allocation GPU ID available"));

        let allocation_requests = lifetimes.kfd_allocation_residency_request_plan(&[1001, 1002]);
        let mismatched_vm_requests = lifetimes
            .kfd_allocation_residency_request_plan(&[1003])
            .kfd_vm_acquire_request_plan();
        let mismatched_alloc_memory_requests =
            allocation_requests.kfd_alloc_memory_request_plan(&mismatched_vm_requests);
        mismatched_alloc_memory_requests
            .assert_consistent()
            .unwrap();
        assert!(!mismatched_alloc_memory_requests.is_kfd_alloc_memory_request_ready());
